/*
 * EPSON Scan (rebuild) — app skeleton.
 *
 * Builds Epson Scan 3.9's Professional Mode window from professional.json,
 * which holds the exact control positions, labels and artwork references
 * taken from the original installer's resources.
 *
 * Two looks, switchable from the View menu:
 *   - Classic Aqua: controls custom-drawn to match Mac OS X 10.5/10.6
 *   - Native: current macOS controls in the same positions
 */
#import <Cocoa/Cocoa.h>
#import <ApplicationServices/ApplicationServices.h>
#include "core/es_scanner.h"
#include "core/es_output.h"
#include "core/film_post.h"
#include "core/ice_film.h"
#include "core/fit.h"
#include "core/es_adjust.h"
#include "core/es_target.h"
#include "core/es_levels.h"
#include "core/es_tonefile.h"
#include "core/es_save.h"
#include "core/es_dde.h"
#include "core/es_pict.h"
#include "core/pim.h"
#include "core/es_pdf.h"
#include "core/ic.h"
#include "core/dtr.h"
#include "core/apo.h"
#include "es_strings.h"     /* generated by the builder */

static NSString *const kThemeDefault = @"UseNativeControls";

/* Configuration > Color: 0 Color Control, 1 ColorSync, 2 No Color Correction */
static int ESColorMgr(void)
{
    NSUserDefaults *d = NSUserDefaults.standardUserDefaults;
    return [d objectForKey:@"CfgColorMgrType"] ? (int)[d integerForKey:@"CfgColorMgrType"] : 0;
}

/* The screen gamma Epson's processing aims at: Display Gamma for Color Control; ColorSync
 * works on gamma 1.8 data (what PERV550R/F.ICC are built for) */
static int ESScreenGamma10(void)
{
    if (ESColorMgr() == 1) return 18;
    NSUserDefaults *d = NSUserDefaults.standardUserDefaults;
    return [d objectForKey:@"DisplayGamma"] ? (int)[d integerForKey:@"DisplayGamma"] : 22;
}
static void ESLog(NSString *fmt, ...) NS_FORMAT_FUNCTION(1, 2);   /* ~/Library/Logs/EPSON Scan.log */

/* ------------------------------------------------------------------------ */
#pragma mark - Fonts and artwork

static NSFont *ESFont(CGFloat size, BOOL bold)
{
    NSFont *f = [NSFont fontWithName:(bold ? @"LucidaGrande-Bold" : @"LucidaGrande") size:size];
    if (!f) f = bold ? [NSFont boldSystemFontOfSize:size] : [NSFont systemFontOfSize:size];
    return f;
}

static NSImage *ESArt(NSString *name)
{
    NSString *path = [[NSBundle mainBundle] pathForResource:name ofType:nil inDirectory:@"art"];
    return path ? [[NSImage alloc] initWithContentsOfFile:path] : nil;
}

static NSImage *ESIcon(id iconId)
{
    if (![iconId isKindOfClass:[NSNumber class]]) return nil;
    return ESArt([NSString stringWithFormat:@"cicn_%@.png", iconId]);
}

/* JSON rect [left, top, right, bottom] -> frame in a flipped view */
static NSRect ESRect(NSArray *r)
{
    CGFloat l = [r[0] doubleValue], t = [r[1] doubleValue], rr = [r[2] doubleValue], b = [r[3] doubleValue];
    return NSMakeRect(l, t, rr - l, b - t);
}

/* ------------------------------------------------------------------------ */
#pragma mark - Flipped container

@interface ESFlippedView : NSView
@end
@implementation ESFlippedView
- (BOOL)isFlipped { return YES; }
@end

/* ------------------------------------------------------------------------ */
#pragma mark - Classic Aqua controls (custom drawn)

typedef NS_ENUM(NSInteger, AQKind) {
    AQPopup, AQButton, AQBevel, AQCheck, AQRadio, AQDisclosure, AQSeparator, AQStepper, AQTabs, AQPlacard
};

@interface AQControl : NSView <NSMenuDelegate>
@property (nonatomic) AQKind kind;
@property (nonatomic, copy) NSString *text;
@property (nonatomic, strong) NSImage *icon;
@property (nonatomic) BOOL on;
@property (nonatomic) BOOL isDefault;
@property (nonatomic, copy) NSArray<NSString *> *menuItems;
@property (nonatomic) BOOL pressed;
@property (nonatomic, copy) NSArray<NSString *> *tabs;
@property (nonatomic) NSInteger selectedTab;
@property (nonatomic, copy) void (^onChange)(AQControl *);
@property (nonatomic, copy) void (^onHold)(BOOL down);     /* press-and-hold buttons */
@property (nonatomic) BOOL disabled;                        /* deactivated (ActivateControl false) */
@property (nonatomic, copy) NSIndexSet *disabledItems;      /* popup items shown dimmed (DisableMenuItem) */
@property (nonatomic) BOOL arrowOnly;                       /* menu button with no title (picks fill a field) */
@property (nonatomic, copy) NSString *picked;               /* last item chosen from an arrowOnly menu */
@property (nonatomic, strong) NSMenuItem *highlighted;       /* popup menu: the item under the pointer */
@property (nonatomic) BOOL pickedNow;
@property (nonatomic) int stepDirection;                    /* stepper: +1 upper half, -1 lower half */
@end

@implementation AQControl

- (BOOL)isFlipped { return YES; }
- (void)setFrameSize:(NSSize)size { [super setFrameSize:size]; [self setNeedsDisplay:YES]; }

static NSGradient *Grad(CGFloat top, CGFloat bottom)
{
    return [[NSGradient alloc] initWithStartingColor:[NSColor colorWithWhite:top alpha:1]
                                         endingColor:[NSColor colorWithWhite:bottom alpha:1]];
}

static NSGradient *AquaBlue(BOOL pressed)
{
    CGFloat k = pressed ? 0.8 : 1.0;
    return [[NSGradient alloc] initWithColorsAndLocations:
            [NSColor colorWithCalibratedRed:0.62 * k green:0.80 * k blue:0.99 * k alpha:1], 0.0,
            [NSColor colorWithCalibratedRed:0.36 * k green:0.60 * k blue:0.94 * k alpha:1], 0.49,
            [NSColor colorWithCalibratedRed:0.20 * k green:0.47 * k blue:0.90 * k alpha:1], 0.51,
            [NSColor colorWithCalibratedRed:0.45 * k green:0.75 * k blue:1.00 * k alpha:1], 1.0, nil];
}

static NSGradient *AquaWhite(BOOL pressed)
{
    CGFloat k = pressed ? 0.85 : 1.0;
    return [[NSGradient alloc] initWithColorsAndLocations:
            [NSColor colorWithWhite:1.00 * k alpha:1], 0.0,
            [NSColor colorWithWhite:0.95 * k alpha:1], 0.49,
            [NSColor colorWithWhite:0.89 * k alpha:1], 0.51,
            [NSColor colorWithWhite:0.97 * k alpha:1], 1.0, nil];
}

- (void)drawText:(NSString *)s at:(NSPoint)p size:(CGFloat)size center:(BOOL)center inRect:(NSRect)r
{
    if (!s.length) return;
    NSDictionary *a = @{ NSFontAttributeName: ESFont(size, NO), NSForegroundColorAttributeName: NSColor.blackColor };
    NSSize sz = [s sizeWithAttributes:a];
    CGFloat x = center ? NSMidX(r) - sz.width / 2 : p.x;
    [s drawAtPoint:NSMakePoint(x, NSMidY(r) - sz.height / 2) withAttributes:a];
}

- (void)drawUpDownArrowsIn:(NSRect)r color:(NSColor *)c
{
    CGFloat cx = NSMidX(r), cy = NSMidY(r);
    NSBezierPath *p = [NSBezierPath bezierPath];
    [p moveToPoint:NSMakePoint(cx - 3, cy - 1)]; [p lineToPoint:NSMakePoint(cx + 3, cy - 1)];
    [p lineToPoint:NSMakePoint(cx, cy - 5)]; [p closePath];
    [p moveToPoint:NSMakePoint(cx - 3, cy + 1)]; [p lineToPoint:NSMakePoint(cx + 3, cy + 1)];
    [p lineToPoint:NSMakePoint(cx, cy + 5)]; [p closePath];
    [c setFill]; [p fill];
}

- (void)drawRect:(NSRect)dirty
{
    NSRect b = NSInsetRect(self.bounds, 0.5, 0.5);
    NSColor *edge = [NSColor colorWithWhite:0.55 alpha:1];
    switch (self.kind) {
    case AQPopup: {
        NSBezierPath *body = [NSBezierPath bezierPathWithRoundedRect:b xRadius:4 yRadius:4];
        BOOL arrowOnly = self.arrowOnly || (self.text.length == 0 && b.size.width < 30);
        if (!arrowOnly) {
            [AquaWhite(self.pressed) drawInBezierPath:body angle:90];
        }
        NSRect cap = arrowOnly ? b : NSMakeRect(NSMaxX(b) - 17, b.origin.y, 17, b.size.height);
        NSBezierPath *capPath = [NSBezierPath bezierPathWithRoundedRect:cap xRadius:4 yRadius:4];
        [AquaBlue(self.pressed) drawInBezierPath:capPath angle:90];
        [edge setStroke]; [body stroke];
        [self drawUpDownArrowsIn:cap color:NSColor.whiteColor];
        if (!arrowOnly) [self drawText:self.text at:NSMakePoint(b.origin.x + 8, 0) size:11 center:NO inRect:b];
        break;
    }
    case AQButton: {
        CGFloat r = MIN(b.size.height / 2, 11);
        NSBezierPath *p = [NSBezierPath bezierPathWithRoundedRect:b xRadius:r yRadius:r];
        [(self.isDefault ? AquaBlue(self.pressed) : AquaWhite(self.pressed)) drawInBezierPath:p angle:90];
        [edge setStroke]; [p stroke];
        if (self.icon) {
            NSDictionary *a = @{ NSFontAttributeName: ESFont(13, NO) };
            NSSize ts = [self.text sizeWithAttributes:a];
            NSSize is = self.icon.size;
            CGFloat x = NSMidX(b) - (is.width + 6 + ts.width) / 2;
            [self.icon drawInRect:NSMakeRect(x, NSMidY(b) - is.height / 2, is.width, is.height)
                         fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1
                   respectFlipped:YES hints:nil];
            [self drawText:self.text at:NSMakePoint(x + is.width + 6, 0) size:13 center:NO inRect:b];
        } else {
            [self drawText:self.text at:NSZeroPoint size:11 center:YES inRect:b];
        }
        break;
    }
    case AQBevel: {
        NSBezierPath *p = [NSBezierPath bezierPathWithRect:b];
        [Grad(self.pressed ? 0.80 : 0.99, self.pressed ? 0.72 : 0.88) drawInBezierPath:p angle:90];
        [edge setStroke]; [p stroke];
        if (self.icon) {
            NSSize is = self.icon.size;
            if (is.width > b.size.width - 4 || is.height > b.size.height - 4) {
                CGFloat k = MIN((b.size.width - 6) / is.width, (b.size.height - 6) / is.height);
                is = NSMakeSize(is.width * k, is.height * k);
            }
            CGFloat x = NSMidX(b) - is.width / 2;
            if (self.text.length) {
                NSDictionary *a = @{ NSFontAttributeName: ESFont(11, NO) };
                CGFloat tw = [self.text sizeWithAttributes:a].width;
                x = NSMidX(b) - (is.width + 4 + tw) / 2;
                [self drawText:self.text at:NSMakePoint(x + is.width + 4, 0) size:11 center:NO inRect:b];
            }
            [self.icon drawInRect:NSMakeRect(x, NSMidY(b) - is.height / 2, is.width, is.height)
                         fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1
                   respectFlipped:YES hints:nil];
        } else if (self.text.length) {
            [self drawText:self.text at:NSZeroPoint size:11 center:YES inRect:b];
        }
        break;
    }
    case AQTabs: {
        /* Aqua tab control: a panel with the tab buttons straddling its top edge */
        NSRect panel = NSMakeRect(b.origin.x, b.origin.y + 11, b.size.width, b.size.height - 11);
        NSBezierPath *pp = [NSBezierPath bezierPathWithRoundedRect:panel xRadius:5 yRadius:5];
        [[NSColor colorWithWhite:0.94 alpha:1] setFill]; [pp fill];
        [[NSColor colorWithWhite:0.62 alpha:1] setStroke]; [pp stroke];
        NSDictionary *a = @{ NSFontAttributeName: ESFont(11, NO) };
        CGFloat total = 0;
        NSMutableArray *widths = [NSMutableArray array];
        for (NSString *t in self.tabs) {
            CGFloat w = MAX(64, [t sizeWithAttributes:a].width + 24);
            [widths addObject:@(w)];
            total += w;
        }
        CGFloat x = NSMidX(b) - total / 2;
        for (NSUInteger k = 0; k < self.tabs.count; k++) {
            CGFloat w = [widths[k] doubleValue];
            NSRect tr = NSMakeRect(x, b.origin.y, w, 22);
            NSBezierPath *tp = [NSBezierPath bezierPathWithRoundedRect:tr xRadius:(k == 0 || k == self.tabs.count - 1) ? 5 : 0
                                                               yRadius:(k == 0 || k == self.tabs.count - 1) ? 5 : 0];
            [((NSInteger)k == self.selectedTab ? AquaBlue(NO) : AquaWhite(NO)) drawInBezierPath:tp angle:90];
            [edge setStroke]; [tp stroke];
            [self drawText:self.tabs[k] at:NSZeroPoint size:11 center:YES inRect:tr];
            x += w;
        }
        break;
    }
    case AQPlacard: {
        NSBezierPath *p = [NSBezierPath bezierPathWithRect:b];
        [Grad(0.97, 0.86) drawInBezierPath:p angle:90];
        [[NSColor colorWithWhite:0.6 alpha:1] setStroke]; [p stroke];
        break;
    }
    case AQCheck:
    case AQRadio: {
        CGFloat cy = NSMidY(b);
        NSRect box = NSMakeRect(b.origin.x + 0.5, cy - 6.5, 13, 13);
        NSBezierPath *p = self.kind == AQCheck ? [NSBezierPath bezierPathWithRoundedRect:box xRadius:2.5 yRadius:2.5]
                                               : [NSBezierPath bezierPathWithOvalInRect:box];
        [(self.on ? AquaBlue(self.pressed) : AquaWhite(self.pressed)) drawInBezierPath:p angle:90];
        [edge setStroke]; [p stroke];
        if (self.on) {
            if (self.kind == AQCheck) {
                NSBezierPath *m = [NSBezierPath bezierPath];
                m.lineWidth = 2; m.lineCapStyle = NSLineCapStyleRound; m.lineJoinStyle = NSLineJoinStyleRound;
                [m moveToPoint:NSMakePoint(box.origin.x + 3, cy)];
                [m lineToPoint:NSMakePoint(box.origin.x + 5.5, cy + 3.5)];
                [m lineToPoint:NSMakePoint(box.origin.x + 10.5, cy - 4)];
                [[NSColor colorWithWhite:0.1 alpha:1] setStroke]; [m stroke];
            } else {
                [[NSColor colorWithWhite:0.1 alpha:1] setFill];
                [[NSBezierPath bezierPathWithOvalInRect:NSInsetRect(box, 4, 4)] fill];
            }
        }
        [self drawText:self.text at:NSMakePoint(b.origin.x + 18, 0) size:11 center:NO inRect:b];
        break;
    }
    case AQDisclosure: {
        CGFloat cx = NSMidX(b), cy = NSMidY(b);
        NSBezierPath *t = [NSBezierPath bezierPath];
        if (self.on) {
            [t moveToPoint:NSMakePoint(cx - 4, cy - 2)]; [t lineToPoint:NSMakePoint(cx + 4, cy - 2)];
            [t lineToPoint:NSMakePoint(cx, cy + 3)];
        } else {
            [t moveToPoint:NSMakePoint(cx - 2, cy - 4)]; [t lineToPoint:NSMakePoint(cx - 2, cy + 4)];
            [t lineToPoint:NSMakePoint(cx + 3, cy)];
        }
        [t closePath];
        [[NSColor colorWithWhite:0.32 alpha:1] setFill]; [t fill];
        break;
    }
    case AQSeparator: {
        [[NSColor colorWithWhite:0.64 alpha:1] setFill];
        NSRectFill(NSMakeRect(0, 0, self.bounds.size.width, 1));
        [[NSColor colorWithWhite:1 alpha:0.8] setFill];
        NSRectFill(NSMakeRect(0, 1, self.bounds.size.width, 1));
        break;
    }
    case AQStepper: {
        NSBezierPath *p = [NSBezierPath bezierPathWithRoundedRect:b xRadius:3 yRadius:3];
        [AquaWhite(NO) drawInBezierPath:p angle:90];
        [edge setStroke]; [p stroke];
        [edge setFill];
        NSRectFill(NSMakeRect(b.origin.x, NSMidY(b), b.size.width, 1));
        CGFloat cx = NSMidX(b), my = NSMidY(b);
        NSBezierPath *a = [NSBezierPath bezierPath];
        [a moveToPoint:NSMakePoint(cx - 3, my - 3)]; [a lineToPoint:NSMakePoint(cx + 3, my - 3)];
        [a lineToPoint:NSMakePoint(cx, my - 7)]; [a closePath];
        [a moveToPoint:NSMakePoint(cx - 3, my + 3)]; [a lineToPoint:NSMakePoint(cx + 3, my + 3)];
        [a lineToPoint:NSMakePoint(cx, my + 7)]; [a closePath];
        [NSColor.blackColor setFill]; [a fill];
        break;
    }
    }
}

- (void)mouseDown:(NSEvent *)e
{
    if (self.kind == AQSeparator || self.kind == AQPlacard || self.disabled) return;
    if (self.kind == AQStepper) {
        NSPoint sp = [self convertPoint:e.locationInWindow fromView:nil];
        self.stepDirection = sp.y < NSMidY(self.bounds) ? 1 : -1;     /* flipped: top half is up */
    }
    if (self.kind == AQTabs) {
        NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
        if (p.y > 22) return;
        NSDictionary *a = @{ NSFontAttributeName: ESFont(11, NO) };
        CGFloat total = 0;
        for (NSString *t in self.tabs) total += MAX(64, [t sizeWithAttributes:a].width + 24);
        CGFloat x = NSMidX(self.bounds) - total / 2;
        for (NSUInteger k = 0; k < self.tabs.count; k++) {
            CGFloat w = MAX(64, [self.tabs[k] sizeWithAttributes:a].width + 24);
            if (p.x >= x && p.x < x + w) {
                self.selectedTab = (NSInteger)k;
                [self setNeedsDisplay:YES];
                if (self.onChange) self.onChange(self);
                return;
            }
            x += w;
        }
        return;
    }
    if (self.kind == AQPopup && self.menuItems.count) {
        NSMenu *m = [[NSMenu alloc] init];
        m.font = ESFont(11, NO);
        m.autoenablesItems = NO;
        for (NSUInteger i = 0; i < self.menuItems.count; i++) {
            NSString *s = self.menuItems[i];
            NSMenuItem *it = [m addItemWithTitle:s action:@selector(pick:) keyEquivalent:@""];
            it.target = self;
            it.enabled = ![self.disabledItems containsIndex:i];
            if ([s isEqualToString:self.text]) it.state = NSControlStateValueOn;
        }
        self.pressed = YES; [self setNeedsDisplay:YES];
        /* in a modal dialog AppKit may not deliver the item's action: track the highlighted item and
         * apply it ourselves when the menu closes on a choice */
        m.delegate = self;
        self.highlighted = nil;
        self.pickedNow = NO;
        BOOL chose = [m popUpMenuPositioningItem:nil atLocation:NSMakePoint(0, self.bounds.size.height + 2) inView:self];
        self.pressed = NO; [self setNeedsDisplay:YES];
        if (chose && !self.pickedNow && self.highlighted.enabled) [self pick:self.highlighted];
        self.highlighted = nil;
        return;
    }
    self.pressed = YES; [self setNeedsDisplay:YES];
    if (self.onHold) { [self displayIfNeeded]; self.onHold(YES); }
    NSEvent *ev;
    while ((ev = [self.window nextEventMatchingMask:NSEventMaskLeftMouseUp | NSEventMaskLeftMouseDragged])) {
        NSPoint p = [self convertPoint:ev.locationInWindow fromView:nil];
        BOOL inside = NSPointInRect(p, self.bounds);
        if (ev.type == NSEventTypeLeftMouseUp) {
            self.pressed = NO;
            if (inside) {
                if (self.kind == AQCheck || self.kind == AQDisclosure) self.on = !self.on;
                if (self.kind == AQRadio) self.on = YES;
                if (self.onChange) self.onChange(self);
            }
            break;
        }
        if (self.pressed != inside) { self.pressed = inside; [self setNeedsDisplay:YES]; }
    }
    [self setNeedsDisplay:YES];
    if (self.onHold) self.onHold(NO);
}

- (void)menu:(NSMenu *)menu willHighlightItem:(NSMenuItem *)item { self.highlighted = item; }
- (BOOL)worksWhenModal { return YES; }

- (void)pick:(NSMenuItem *)it
{
    self.pickedNow = YES;
    self.picked = it.title;
    if (!self.arrowOnly) self.text = it.title;
    [self setNeedsDisplay:YES];
    if (self.onChange) self.onChange(self);
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark - Preview canvas

@interface ESPreviewCanvas : NSView
@property (nonatomic, strong) NSImage *image;
@property (nonatomic, copy) NSArray<NSValue *> *frames;   /* marquees, in image pixels */
@property (nonatomic) NSInteger selected;
@property (nonatomic, copy) NSString *message;
@property (nonatomic, copy) void (^onSelect)(NSInteger index);
/* a marquee was moved/resized/added (index) or deleted (index, deleted = YES) */
@property (nonatomic, copy) void (^onEdit)(NSInteger index, BOOL deleted);
@property (nonatomic) BOOL editable;
/* pipette: the next click in the image is reported (image pixels) instead of editing marquees */
@property (nonatomic, copy) void (^onPick)(NSPoint imagePoint);
/* height / width a marquee must keep while it's resized (CMarqDraw::SetMarqueeConstraint when the
 * marquee's target size is fixed); 0 = free */
@property (nonatomic, copy) double (^aspectFor)(NSInteger index);
/* All button (CPreviewWnd "All"): every marquee is selected; the next click ends it */
@property (nonatomic) BOOL allSelected;
/* Densitometer: the pointer's image position while it's over the image (NO = left it) */
@property (nonatomic, copy) void (^onHover)(NSPoint imagePoint, BOOL inside);
@property (nonatomic, strong) NSTrackingArea *hoverArea;
- (void)deleteSelected;
@end

@implementation ESPreviewCanvas
- (BOOL)isFlipped { return YES; }
- (void)setFrameSize:(NSSize)size { [super setFrameSize:size]; [self setNeedsDisplay:YES]; }
- (NSRect)imageRect
{
    NSSize is = self.image.size;
    if (!self.image || is.width <= 0) return NSZeroRect;
    CGFloat k = MIN(self.bounds.size.width / is.width, self.bounds.size.height / is.height);
    NSRect r = NSMakeRect(0, 0, is.width * k, is.height * k);
    r.origin = NSMakePoint(NSMidX(self.bounds) - r.size.width / 2, NSMidY(self.bounds) - r.size.height / 2);
    return r;
}

- (NSRect)viewRectForFrame:(NSRect)f
{
    NSRect ir = [self imageRect];
    CGFloat k = ir.size.width / self.image.size.width;
    return NSMakeRect(ir.origin.x + f.origin.x * k, ir.origin.y + f.origin.y * k, f.size.width * k, f.size.height * k);
}

- (BOOL)acceptsFirstResponder { return YES; }

/* view point -> image pixels */
- (NSPoint)imagePoint:(NSPoint)p
{
    NSRect ir = [self imageRect];
    CGFloat k = ir.size.width / self.image.size.width;
    return NSMakePoint((p.x - ir.origin.x) / k, (p.y - ir.origin.y) / k);
}

/* which part of a marquee is under the point: bit 1 left, 2 right, 4 top, 8 bottom, 16 inside */
- (int)hitPart:(NSPoint)p frame:(NSRect)vr
{
    const CGFloat g = 5;
    if (!NSPointInRect(p, NSInsetRect(vr, -g, -g))) return 0;
    int part = 0;
    if (fabs(p.x - NSMinX(vr)) <= g) part |= 1;
    else if (fabs(p.x - NSMaxX(vr)) <= g) part |= 2;
    if (fabs(p.y - NSMinY(vr)) <= g) part |= 4;
    else if (fabs(p.y - NSMaxY(vr)) <= g) part |= 8;
    return part ? part : (NSPointInRect(p, vr) ? 16 : 0);
}

- (void)mouseDown:(NSEvent *)e
{
    [self.window makeFirstResponder:self];
    if (!self.image) return;
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    if (self.onPick) {
        void (^pick)(NSPoint) = self.onPick;
        self.onPick = nil;
        [self.window invalidateCursorRectsForView:self];
        if (NSPointInRect(p, [self imageRect])) pick([self imagePoint:p]);
        return;
    }
    if (self.allSelected) { self.allSelected = NO; [self setNeedsDisplay:YES]; }
    NSMutableArray *fr = [self.frames mutableCopy] ?: [NSMutableArray array];
    NSInteger hit = -1; int part = 0;
    /* the selected marquee's handles win, then any marquee under the point */
    if (self.selected >= 0 && self.selected < (NSInteger)fr.count) {
        part = [self hitPart:p frame:[self viewRectForFrame:[fr[self.selected] rectValue]]];
        if (part) hit = self.selected;
    }
    for (NSUInteger i = 0; hit < 0 && i < fr.count; i++)
        if (NSPointInRect(p, [self viewRectForFrame:[fr[i] rectValue]])) { hit = (NSInteger)i; part = 16; }
    if (hit >= 0 && hit != self.selected) {
        self.selected = hit;
        if (self.onSelect) self.onSelect(hit);
    }
    if (!self.editable) { [self setNeedsDisplay:YES]; return; }

    NSSize is = self.image.size;
    NSPoint start = [self imagePoint:p];
    BOOL creating = NO;
    if (hit < 0) {                                   /* draw a new marquee */
        if (start.x < 0 || start.y < 0 || start.x > is.width || start.y > is.height) return;
        [fr addObject:[NSValue valueWithRect:NSMakeRect(start.x, start.y, 0, 0)]];
        hit = (NSInteger)fr.count - 1;
        self.selected = hit;
        part = 2 | 8;
        creating = YES;
    }
    NSRect orig = [fr[hit] rectValue];
    BOOL changed = NO;
    double aspect = !creating && self.aspectFor ? self.aspectFor(hit) : 0;
    while (1) {
        NSEvent *ev = [self.window nextEventMatchingMask:NSEventMaskLeftMouseDragged | NSEventMaskLeftMouseUp];
        if (ev.type == NSEventTypeLeftMouseUp) break;
        NSPoint q = [self imagePoint:[self convertPoint:ev.locationInWindow fromView:nil]];
        CGFloat dx = q.x - start.x, dy = q.y - start.y;
        NSRect r = orig;
        if (part == 16) {                            /* move, kept inside the image */
            r.origin.x = MIN(MAX(0, orig.origin.x + dx), is.width - r.size.width);
            r.origin.y = MIN(MAX(0, orig.origin.y + dy), is.height - r.size.height);
        } else {
            CGFloat x0 = NSMinX(orig), x1 = NSMaxX(orig), y0 = NSMinY(orig), y1 = NSMaxY(orig);
            if (part & 1) x0 += dx;
            if (part & 2) x1 += dx;
            if (part & 4) y0 += dy;
            if (part & 8) y1 += dy;
            x0 = MIN(MAX(0, x0), is.width); x1 = MIN(MAX(0, x1), is.width);
            y0 = MIN(MAX(0, y0), is.height); y1 = MIN(MAX(0, y1), is.height);
            r = NSMakeRect(MIN(x0, x1), MIN(y0, y1), fabs(x1 - x0), fabs(y1 - y0));
            if (aspect > 0) {
                /* CMarqDraw::GetConstrainMouseMoved: the corner opposite the handle stays, the size
                 * follows whichever way the mouse moved further, at the fixed shape */
                CGFloat ax = (part & 1) ? NSMaxX(orig) : NSMinX(orig), ay = (part & 4) ? NSMaxY(orig) : NSMinY(orig);
                CGFloat w = r.size.width, h = r.size.height;
                if (!(part & 3)) w = h / aspect;
                else if (!(part & 12)) h = w * aspect;
                else if (h < w * aspect) h = w * aspect; else w = h / aspect;
                CGFloat maxW = (part & 1) ? ax : is.width - ax, maxH = (part & 4) ? ay : is.height - ay;
                if (w > maxW) { w = maxW; h = w * aspect; }
                if (h > maxH) { h = maxH; w = h / aspect; }
                r = NSMakeRect((part & 1) ? ax - w : ax, (part & 4) ? ay - h : ay, w, h);
            }
        }
        fr[hit] = [NSValue valueWithRect:NSIntegralRect(r)];
        self.frames = fr;
        changed = YES;
        [self setNeedsDisplay:YES];
    }
    NSRect r = [fr[hit] rectValue];
    if (creating && (r.size.width < 8 || r.size.height < 8)) {     /* a click, not a drag */
        [fr removeObjectAtIndex:(NSUInteger)hit];
        self.frames = fr;
        self.selected = fr.count ? 0 : -1;
        [self setNeedsDisplay:YES];
        return;
    }
    if (changed && self.onEdit) self.onEdit(hit, NO);
    [self setNeedsDisplay:YES];
}

- (void)keyDown:(NSEvent *)e
{
    unichar ch = e.charactersIgnoringModifiers.length ? [e.charactersIgnoringModifiers characterAtIndex:0] : 0;
    if (self.editable && (ch == NSDeleteCharacter || ch == NSBackspaceCharacter || ch == NSDeleteFunctionKey) &&
        self.selected >= 0 && self.selected < (NSInteger)self.frames.count) {
        [self deleteSelected];
        return;
    }
    [super keyDown:e];
}

- (void)deleteSelected
{
    if (!self.editable || self.selected < 0 || self.selected >= (NSInteger)self.frames.count) return;
    NSInteger i = self.selected;
    NSMutableArray *fr = [self.frames mutableCopy];
    [fr removeObjectAtIndex:(NSUInteger)i];
    self.allSelected = NO;
    self.frames = fr;
    self.selected = fr.count ? MIN(i, (NSInteger)fr.count - 1) : -1;
    if (self.onEdit) self.onEdit(i, YES);
    [self setNeedsDisplay:YES];
}

- (void)updateTrackingAreas
{
    [super updateTrackingAreas];
    if (self.hoverArea) [self removeTrackingArea:self.hoverArea];
    self.hoverArea = [[NSTrackingArea alloc] initWithRect:self.bounds
                                                  options:NSTrackingMouseMoved | NSTrackingMouseEnteredAndExited |
                                                          NSTrackingActiveAlways | NSTrackingInVisibleRect
                                                    owner:self userInfo:nil];
    [self addTrackingArea:self.hoverArea];
}

- (void)mouseMoved:(NSEvent *)e
{
    if (!self.onHover || !self.image) return;
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    BOOL in = NSPointInRect(p, [self imageRect]);
    self.onHover(in ? [self imagePoint:p] : NSZeroPoint, in);
}

- (void)mouseExited:(NSEvent *)e { if (self.onHover) self.onHover(NSZeroPoint, NO); }

- (void)resetCursorRects
{
    if (self.onPick && self.image) { [self addCursorRect:[self imageRect] cursor:NSCursor.crosshairCursor]; return; }
    if (!self.editable || !self.image) return;
    for (NSUInteger i = 0; i < self.frames.count; i++) {
        NSRect vr = [self viewRectForFrame:self.frames[i].rectValue];
        [self addCursorRect:vr cursor:NSCursor.openHandCursor];
        [self addCursorRect:NSMakeRect(NSMinX(vr) - 5, NSMinY(vr), 10, vr.size.height) cursor:NSCursor.resizeLeftRightCursor];
        [self addCursorRect:NSMakeRect(NSMaxX(vr) - 5, NSMinY(vr), 10, vr.size.height) cursor:NSCursor.resizeLeftRightCursor];
        [self addCursorRect:NSMakeRect(NSMinX(vr), NSMinY(vr) - 5, vr.size.width, 10) cursor:NSCursor.resizeUpDownCursor];
        [self addCursorRect:NSMakeRect(NSMinX(vr), NSMaxY(vr) - 5, vr.size.width, 10) cursor:NSCursor.resizeUpDownCursor];
    }
    [self addCursorRect:[self imageRect] cursor:NSCursor.crosshairCursor];
}

- (void)drawRect:(NSRect)dirty
{
    [self.window invalidateCursorRectsForView:self];
    [NSColor.whiteColor setFill];
    NSRectFill(self.bounds);
    if (self.image) {
        [self.image drawInRect:[self imageRect] fromRect:NSZeroRect operation:NSCompositingOperationSourceOver
                      fraction:1 respectFlipped:YES hints:nil];
        /* marquees: dashed outline, the selected one solid with handles, numbered like Epson Scan */
        for (NSUInteger i = 0; i < self.frames.count; i++) {
            NSRect r = NSInsetRect([self viewRectForFrame:self.frames[i].rectValue], 0.5, 0.5);
            BOOL sel = (NSInteger)i == self.selected || self.allSelected;
            NSBezierPath *p = [NSBezierPath bezierPathWithRect:r];
            p.lineWidth = sel ? 2 : 1;
            CGFloat dash[2] = { 4, 3 };
            if (!sel) [p setLineDash:dash count:2 phase:0];
            [(sel ? NSColor.systemBlueColor : [NSColor colorWithWhite:0.15 alpha:1]) setStroke];
            [p stroke];
            if (sel) {
                [NSColor.systemBlueColor setFill];
                NSPoint corners[4] = { r.origin, NSMakePoint(NSMaxX(r), r.origin.y),
                                       NSMakePoint(r.origin.x, NSMaxY(r)), NSMakePoint(NSMaxX(r), NSMaxY(r)) };
                for (int k = 0; k < 4; k++)
                    NSRectFill(NSMakeRect(corners[k].x - 3, corners[k].y - 3, 6, 6));
            }
            NSString *n = [NSString stringWithFormat:@"%lu", (unsigned long)i + 1];
            NSDictionary *a = @{ NSFontAttributeName: ESFont(11, YES), NSForegroundColorAttributeName: NSColor.whiteColor,
                                 NSBackgroundColorAttributeName: sel ? NSColor.systemBlueColor : [NSColor colorWithWhite:0.15 alpha:1] };
            [[NSString stringWithFormat:@" %@ ", n] drawAtPoint:NSMakePoint(r.origin.x + 3, r.origin.y + 3) withAttributes:a];
        }
    }
    if (self.message.length) {
        NSDictionary *a = @{ NSFontAttributeName: ESFont(12, NO), NSForegroundColorAttributeName: [NSColor colorWithWhite:0.35 alpha:1] };
        NSSize sz = [self.message sizeWithAttributes:a];
        NSRect box = NSInsetRect(NSMakeRect(NSMidX(self.bounds) - sz.width / 2, NSMaxY(self.bounds) - sz.height - 16,
                                            sz.width, sz.height), -8, -4);
        [[NSColor colorWithWhite:1 alpha:0.85] setFill];
        [[NSBezierPath bezierPathWithRoundedRect:box xRadius:6 yRadius:6] fill];
        [self.message drawAtPoint:NSMakePoint(box.origin.x + 8, box.origin.y + 4) withAttributes:a];
    }
    [[NSColor colorWithWhite:0.55 alpha:1] setStroke];
    [[NSBezierPath bezierPathWithRect:NSInsetRect(self.bounds, 0.5, 0.5)] stroke];
}
@end

/* ------------------------------------------------------------------------ */
/* ------------------------------------------------------------------------ */
#pragma mark - Slider and tick marks (Image Adjustment)

/* Classic Aqua slider: recessed track, glass pointer aiming at the tick marks above it */
@interface AQSlider : NSView
@property (nonatomic) double minValue, maxValue, value;
@property (nonatomic) BOOL pressed;
@property (nonatomic, copy) void (^onChange)(AQSlider *);
@end

@implementation AQSlider
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }
- (CGFloat)thumbX
{
    CGFloat lo = 7, hi = self.bounds.size.width - 7;
    double f = self.maxValue > self.minValue ? (self.value - self.minValue) / (self.maxValue - self.minValue) : 0;
    return round(lo + (hi - lo) * f);
}
- (void)drawRect:(NSRect)dirty
{
    NSRect b = self.bounds;
    CGFloat cy = 8;
    NSRect track = NSMakeRect(5, cy - 2, b.size.width - 10, 5);
    NSBezierPath *tp = [NSBezierPath bezierPathWithRoundedRect:track xRadius:2.5 yRadius:2.5];
    [Grad(0.62, 0.86) drawInBezierPath:tp angle:90];
    [[NSColor colorWithWhite:0.45 alpha:1] setStroke];
    tp.lineWidth = 0.75;
    [tp stroke];
    /* pointer: pentagon, tip up */
    CGFloat x = [self thumbX], top = 1, w = 6.5, sh = 6, bot = 15;
    NSBezierPath *p = [NSBezierPath bezierPath];
    [p moveToPoint:NSMakePoint(x, top)];
    [p lineToPoint:NSMakePoint(x + w, top + sh)];
    [p lineToPoint:NSMakePoint(x + w, bot - 1.5)];
    [p curveToPoint:NSMakePoint(x + w - 1.5, bot) controlPoint1:NSMakePoint(x + w, bot) controlPoint2:NSMakePoint(x + w, bot)];
    [p lineToPoint:NSMakePoint(x - w + 1.5, bot)];
    [p curveToPoint:NSMakePoint(x - w, bot - 1.5) controlPoint1:NSMakePoint(x - w, bot) controlPoint2:NSMakePoint(x - w, bot)];
    [p lineToPoint:NSMakePoint(x - w, top + sh)];
    [p closePath];
    NSShadow *sd = [NSShadow new];
    sd.shadowOffset = NSMakeSize(0, -1);
    sd.shadowBlurRadius = 1.5;
    sd.shadowColor = [NSColor colorWithWhite:0 alpha:0.35];
    [NSGraphicsContext saveGraphicsState];
    [sd set];
    [[NSColor whiteColor] setFill];
    [p fill];
    [NSGraphicsContext restoreGraphicsState];
    [(self.pressed ? AquaBlue(NO) : AquaWhite(NO)) drawInBezierPath:p angle:0];
    [[NSColor colorWithWhite:self.pressed ? 0.25 : 0.42 alpha:1] setStroke];
    p.lineWidth = 0.75;
    [p stroke];
}
- (void)trackTo:(NSEvent *)e
{
    CGFloat x = [self convertPoint:e.locationInWindow fromView:nil].x;
    CGFloat lo = 7, hi = self.bounds.size.width - 7;
    double f = MAX(0, MIN(1, (x - lo) / (hi - lo)));
    double v = round(self.minValue + f * (self.maxValue - self.minValue));
    if (v != self.value) {
        self.value = v;
        [self setNeedsDisplay:YES];
        if (self.onChange) self.onChange(self);
    }
}
- (void)mouseDown:(NSEvent *)e { self.pressed = YES; [self trackTo:e]; [self setNeedsDisplay:YES]; }
- (void)mouseDragged:(NSEvent *)e { [self trackTo:e]; }
- (void)mouseUp:(NSEvent *)e { self.pressed = NO; [self setNeedsDisplay:YES]; }
@end

@interface ESTicks : NSView
@property (nonatomic) NSInteger count;
@end

@implementation ESTicks
- (BOOL)isFlipped { return YES; }
- (void)drawRect:(NSRect)dirty
{
    if (self.count < 2) return;
    NSRect b = self.bounds;
    [[NSColor colorWithWhite:0.35 alpha:1] setFill];
    CGFloat lo = 4, hi = b.size.width - 4;          /* matches the slider's travel (inset 7 vs 3) */
    for (NSInteger i = 0; i < self.count; i++) {
        CGFloat x = round(lo + (hi - lo) * i / (self.count - 1));
        BOOL major = i == 0 || i == self.count - 1 || i == self.count / 2;
        NSRectFill(NSMakeRect(x, major ? 1 : 3, 1, b.size.height - (major ? 1 : 3)));
    }
}
@end

/* ------------------------------------------------------------------------ */
#pragma mark - Histogram Adjustment views (CHistogramTable, CIndicatorArrow3/2, CLockupTable)

/* the histogram: one bar per value, like CHistogramTable::DrawHistogram (white, 1 px edge) */
@interface ESHistogramView : NSView
@property (nonatomic, strong) NSData *histogram;   /* EsHistogram */
@property (nonatomic) int channel;                 /* 0 master, 1 R, 2 G, 3 B */
@end

@implementation ESHistogramView
- (BOOL)isFlipped { return YES; }
- (void)drawRect:(NSRect)dirty
{
    [NSColor.whiteColor setFill];
    NSRectFill(self.bounds);
    const EsHistogram *hg = self.histogram.bytes;
    if (hg && hg->valid) {
        NSColor *c = self.channel == 1 ? NSColor.redColor : self.channel == 2 ? [NSColor colorWithCalibratedRed:0 green:0.8 blue:0 alpha:1]
                   : self.channel == 3 ? NSColor.blueColor : NSColor.blackColor;
        [c setFill];
        for (int i = 0; i < 256; i++) {
            int x = hg->x[self.channel][i] + 1, h = hg->h[self.channel][i];
            if (h <= 0) continue;
            CGFloat top = MAX(1, 0x6a - h);
            NSRectFill(NSMakeRect(x, top, 1, 0x6a - top + 1));
        }
    }
    [[NSColor colorWithWhite:0.45 alpha:1] setStroke];
    NSBezierPath *b = [NSBezierPath bezierPathWithRect:NSInsetRect(self.bounds, 0.5, 0.5)];
    b.lineWidth = 1;
    [b stroke];
}
@end

/* arrow bar under the histogram: shadow (black), gamma (gray, input only), highlight (white).
 * Positions are CIndicatorArrow coordinates 0..235; the view is 5 px wider on each side. */
@interface ESLevelArrows : NSView
@property (nonatomic) int count;
@property (nonatomic) int left, center, right;
@property (nonatomic) int dragging;                  /* -1 none, 0 left, 1 centre, 2 right */
@property (nonatomic, copy) void (^onMove)(int arrow, int pos, BOOL done);
@end

@implementation ESLevelArrows
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }
- (void)drawArrowAt:(int)pos fill:(NSColor *)fill
{
    CGFloat x = pos + 5.5, h = self.bounds.size.height;
    NSBezierPath *p = [NSBezierPath bezierPath];
    [p moveToPoint:NSMakePoint(x, 0.5)];
    [p lineToPoint:NSMakePoint(x + 5, h - 1)];
    [p lineToPoint:NSMakePoint(x - 5, h - 1)];
    [p closePath];
    [fill setFill];
    [p fill];
    [NSColor.blackColor setStroke];
    p.lineWidth = 1;
    [p stroke];
}
- (void)drawRect:(NSRect)dirty
{
    [self drawArrowAt:self.left fill:NSColor.blackColor];
    if (self.count == 3) [self drawArrowAt:self.center fill:[NSColor colorWithWhite:0.55 alpha:1]];
    [self drawArrowAt:self.right fill:NSColor.whiteColor];
}
- (int)posFor:(NSEvent *)e
{
    CGFloat x = [self convertPoint:e.locationInWindow fromView:nil].x - 5;
    return (int)lround(MAX(0, MIN(235, x)));
}
- (void)mouseDown:(NSEvent *)e
{
    int x = [self posFor:e];
    int d[3] = { abs(x - self.left), self.count == 3 ? abs(x - self.center) : 9999, abs(x - self.right) };
    int best = d[1] <= d[0] && d[1] <= d[2] ? 1 : d[0] <= d[2] ? 0 : 2;
    if (self.left == self.right) best = x < self.left ? 0 : 2;
    if (d[best] > 7) { self.dragging = -1; return; }
    self.dragging = best;
}
- (void)mouseDragged:(NSEvent *)e
{
    if (self.dragging < 0) return;
    if (self.onMove) self.onMove(self.dragging, [self posFor:e], NO);
}
- (void)mouseUp:(NSEvent *)e
{
    if (self.dragging >= 0 && self.onMove) self.onMove(self.dragging, [self posFor:e], YES);
    self.dragging = -1;
}
@end

/* Tone Curve Viewer (CLockupTable::DrawLookupTable): the table for R, G and B over the
 * display axis, the selected channel on top, with the level line dotted behind. */
@interface ESCurveView : NSView
@property (nonatomic, strong) NSData *lut;           /* 3 x 256 */
@property (nonatomic) int channel, screenGamma10;
@property (nonatomic) BOOL negative, hideDots;
@property (nonatomic, strong) NSData *levels;        /* EsLevels */
@end

@implementation ESCurveView
- (BOOL)isFlipped { return YES; }
- (void)drawChannel:(int)c
{
    const uint8_t *L = self.lut.bytes;
    NSColor *col = c == 0 ? NSColor.redColor : c == 1 ? [NSColor colorWithCalibratedRed:0 green:0.75 blue:0 alpha:1] : NSColor.blueColor;
    if (!self.hideDots && self.levels.length == sizeof(EsLevels)) {
        const EsLevels *lv = self.levels.bytes;
        const int *v = lv->ch[c];
        NSBezierPath *d = [NSBezierPath bezierPath];
        [d moveToPoint:NSMakePoint(v[LV_SD] / 257 / 2.0 + 1, 127 - v[LV_OSD] / 257 / 2.0 + 1)];
        [d lineToPoint:NSMakePoint(v[LV_HL] / 257 / 2.0 + 1, 127 - v[LV_OHL] / 257 / 2.0 + 1)];
        CGFloat dash[2] = { 1, 2 };
        [d setLineDash:dash count:2 phase:0];
        [[col blendedColorWithFraction:0.75 ofColor:NSColor.whiteColor] setStroke];
        [d stroke];
    }
    NSBezierPath *p = [NSBezierPath bezierPath];
    for (int i = 0; i < 256; i++) {
        NSPoint q = NSMakePoint(floor(lv_axis_x(i, self.screenGamma10, self.negative) / 2.0) + 1.5,
                                0x7f - (L[c * 256 + i] >> 1) + 1.5);
        if (i) [p lineToPoint:q]; else [p moveToPoint:q];
    }
    [col setStroke];
    p.lineWidth = 1;
    [p stroke];
}
- (void)drawRect:(NSRect)dirty
{
    [NSColor.whiteColor setFill];
    NSRectFill(self.bounds);
    if (self.lut.length == 768) {
        int top = self.channel == 0 ? 0 : self.channel - 1;   /* master: red drawn last, as Epson does */
        for (int c = 2; c >= 0; c--) if (c != top) [self drawChannel:c];
        [self drawChannel:top];
    }
    [[NSColor colorWithWhite:0.45 alpha:1] setStroke];
    [[NSBezierPath bezierPathWithRect:NSInsetRect(self.bounds, 0.5, 0.5)] stroke];
}
@end

/* shadow / highlight curve form buttons (CToneCurveButton): icon shows the form, click pops
 * Boost / Normal / Soft */
@interface ESCurveButton : NSView
@property (nonatomic, copy) NSArray<NSString *> *menuItems;
@property (nonatomic) NSInteger selected;
@property (nonatomic, copy) NSArray<NSImage *> *icons;   /* one per item */
@property (nonatomic) BOOL native, pressed;
@property (nonatomic, copy) void (^onChange)(NSInteger index);
@end

@implementation ESCurveButton
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }
- (void)drawRect:(NSRect)dirty
{
    NSRect b = NSInsetRect(self.bounds, 2.5, 2.5);
    NSBezierPath *p = [NSBezierPath bezierPathWithRoundedRect:b xRadius:4 yRadius:4];
    if (self.native) {
        [(self.pressed ? NSColor.selectedControlColor : NSColor.controlColor) setFill];
        [p fill];
        [NSColor.separatorColor setStroke];
    } else {
        [AquaWhite(self.pressed) drawInBezierPath:p angle:90];
        [[NSColor colorWithWhite:0.55 alpha:1] setStroke];
    }
    p.lineWidth = 1;
    [p stroke];
    NSImage *ic = self.selected >= 0 && self.selected < (NSInteger)self.icons.count ? self.icons[self.selected] : nil;
    if (ic) {
        NSSize sz = ic.size;
        [ic drawInRect:NSMakeRect(round(NSMidX(self.bounds) - sz.width / 2), round(NSMidY(self.bounds) - sz.height / 2),
                                  sz.width, sz.height)
              fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1 respectFlipped:YES hints:nil];
    }
}
- (void)mouseDown:(NSEvent *)e
{
    NSMenu *m = [[NSMenu alloc] init];
    m.font = self.native ? [NSFont menuFontOfSize:11] : ESFont(11, NO);
    for (NSUInteger i = 0; i < self.menuItems.count; i++) {
        NSMenuItem *it = [m addItemWithTitle:self.menuItems[i] action:@selector(pick:) keyEquivalent:@""];
        it.target = self;
        it.tag = (NSInteger)i;
        if ((NSInteger)i == self.selected) it.state = NSControlStateValueOn;
    }
    self.pressed = YES; [self setNeedsDisplay:YES];
    [m popUpMenuPositioningItem:nil atLocation:NSMakePoint(0, self.bounds.size.height + 2) inView:self];
    self.pressed = NO; [self setNeedsDisplay:YES];
}
- (void)pick:(NSMenuItem *)it
{
    self.selected = it.tag;
    [self setNeedsDisplay:YES];
    if (self.onChange) self.onChange(it.tag);
}
@end

/* Tone Correction curve (CToneCurve / CToneCurvePaintCtrl): dotted net at the quarters, the
 * other channels' curves plain, the current one on top with its points. Control coordinates
 * are Epson's: x = v * 171 / 255 - 1, y = 171 - (v * 171 / 255 - 1). */
@interface ESToneView : NSView
@property (nonatomic, strong) NSData *curves;     /* 4 x TC_SIZE: master, R, G, B */
@property (nonatomic) int channel, selected;
@property (nonatomic, copy) void (^onMouse)(int phase, int ctrlX, int x, int y);   /* 0 down, 1 drag, 2 up */
@end

@implementation ESToneView
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }
static NSPoint tc_ctrl(double x, double y)
{
    if (x > 255) x = 255;
    if (y > 255) y = 255;
    return NSMakePoint((int)(x * 171.0 / 255.0 - 1.0) + 1.5, (0xab - (int)(y * 171.0 / 255.0 - 1.0)) + 1.5);
}
- (NSColor *)colorFor:(int)c
{
    return c == 1 ? NSColor.redColor : c == 2 ? [NSColor colorWithCalibratedRed:0 green:0.75 blue:0 alpha:1]
         : c == 3 ? NSColor.blueColor : NSColor.blackColor;
}
- (void)drawCurve:(int)c points:(BOOL)points
{
    const uint8_t *ic = (const uint8_t *)self.curves.bytes + c * TC_SIZE;
    double out[256];
    tc_curve(ic, out);
    NSBezierPath *p = [NSBezierPath bezierPath];
    for (int i = 0; i < 256; i++) {
        NSPoint q = tc_ctrl(i, out[i]);
        if (i) [p lineToPoint:q]; else [p moveToPoint:q];
    }
    NSColor *col = [self colorFor:c];
    [col setStroke];
    p.lineWidth = 1;
    [p stroke];
    if (!points) return;
    for (int k = 0; k < tc_count(ic); k++) {
        int x, y;
        tc_point(ic, k, &x, &y);
        NSPoint q = tc_ctrl(x, y);
        NSRect r = NSMakeRect(q.x - 2.5, q.y - 2.5, 6, 6);
        [(k == self.selected ? col : NSColor.whiteColor) setFill];
        NSRectFill(r);
        [col setStroke];
        [NSBezierPath strokeRect:r];
    }
}
- (void)drawRect:(NSRect)dirty
{
    [NSColor.whiteColor setFill];
    NSRectFill(self.bounds);
    NSBezierPath *net = [NSBezierPath bezierPath];
    for (int v = 0x2a; v <= 0x80; v += 0x2b) {      /* CToneCurve::DrawNet: 42, 85, 128 */
        [net moveToPoint:NSMakePoint(v + 1.5, 1)]; [net lineToPoint:NSMakePoint(v + 1.5, self.bounds.size.height - 1)];
        [net moveToPoint:NSMakePoint(1, v + 1.5)]; [net lineToPoint:NSMakePoint(self.bounds.size.width - 1, v + 1.5)];
    }
    CGFloat dash[2] = { 1, 2 };
    [net setLineDash:dash count:2 phase:0];
    [[NSColor colorWithWhite:0.6 alpha:1] setStroke];
    [net stroke];
    if (self.curves.length == 4 * TC_SIZE) {
        for (int c = 3; c >= 0; c--) if (c != self.channel) [self drawCurve:c points:NO];
        [self drawCurve:self.channel points:YES];
    }
    [[NSColor colorWithWhite:0.45 alpha:1] setStroke];
    [[NSBezierPath bezierPathWithRect:NSInsetRect(self.bounds, 0.5, 0.5)] stroke];
}
/* CToneCurve::ConvertToOriginCoordinates */
- (void)report:(NSEvent *)e phase:(int)phase
{
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    int cx = (int)floor(p.x) - 1, cy = (int)floor(p.y) - 1;
    int w = (int)self.bounds.size.width - 2, h = (int)self.bounds.size.height - 2;
    cx = MAX(0, MIN(w - 1, cx)); cy = MAX(0, MIN(h - 1, cy));
    int ox = MIN(cx, 0xac), oy = MIN(cy, 0xac);
    int x = (int)ceil(ox * 255.0 / 171.0), y = 0xff - (int)ceil(oy * 255.0 / 171.0);
    if (self.onMouse) self.onMouse(phase, cx, MIN(255, x), MAX(0, y));
}
- (void)mouseDown:(NSEvent *)e { [self report:e phase:0]; }
- (void)mouseDragged:(NSEvent *)e { [self report:e phase:1]; }
- (void)mouseUp:(NSEvent *)e { [self report:e phase:2]; }
@end

/* ------------------------------------------------------------------------ */
#pragma mark - Color Palette views (CColorPalette, CColorStore)

static NSString *ESImageControlEngine(void) { return [[NSBundle mainBundle] pathForResource:@"ImageControl_i386" ofType:nil]; }

/* a cell as CHexagonCell::Draw paints it: filled, darker edge on the lower right, white on the upper left */
static void ESDrawCell(NSPoint *v, int n, const int rgb[3])
{
    NSBezierPath *p = [NSBezierPath bezierPath];
    [p moveToPoint:v[0]];
    for (int k = 1; k < n; k++) [p lineToPoint:v[k]];
    [p closePath];
    [[NSColor colorWithCalibratedRed:rgb[0] / 255.0 green:rgb[1] / 255.0 blue:rgb[2] / 255.0 alpha:1] setFill];
    [p fill];
    if (n != 6) return;
    NSBezierPath *dark = [NSBezierPath bezierPath], *light = [NSBezierPath bezierPath];
    [dark moveToPoint:v[2]]; [dark lineToPoint:v[3]]; [dark lineToPoint:v[4]]; [dark lineToPoint:v[5]];
    [light moveToPoint:v[5]]; [light lineToPoint:v[0]]; [light lineToPoint:v[1]]; [light lineToPoint:v[2]];
    [[NSColor colorWithCalibratedWhite:0xa0 / 255.0 alpha:1] setStroke];
    [dark stroke];
    [NSColor.whiteColor setStroke];
    [light stroke];
}

/* the hexagon palette: 44 cells around the current colour (Epson's own SetColor), the eight
 * fixed hue triangles, cells 0 and 1 framed in orange */
@interface ESPaletteView : NSView
@property (nonatomic) NSPoint origin;                 /* dialog coordinates of the view */
@property (nonatomic, copy) void (^onPick)(const int rgb[3]);
- (void)setColor:(const int[3])rgb;
- (void)getColor:(int[3])rgb;
@end

@implementation ESPaletteView {
    IcPaletteShape _shape;
    BOOL _haveShape;
    int _cells[IC_HEXAGONS][3];
}
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }
- (instancetype)initWithFrame:(NSRect)r
{
    if ((self = [super initWithFrame:r])) {
        char err[256];
        NSString *eng = ESImageControlEngine();
        _haveShape = eng && ic_palette_shape(eng.fileSystemRepresentation, &_shape, err, sizeof err) == 0;
        if (!_haveShape) NSLog(@"Color Palette: %s", err);
        int gray[3] = { 192, 192, 192 };
        [self setColor:gray];
    }
    return self;
}
- (void)setColor:(const int[3])rgb
{
    char err[256];
    int sg = ESScreenGamma10();
    NSString *eng = ESImageControlEngine();
    if (!eng || ic_palette_colors(eng.fileSystemRepresentation, sg, rgb, _cells, err, sizeof err)) {
        NSLog(@"Color Palette: %s", err);
        for (int i = 0; i < IC_HEXAGONS; i++) memcpy(_cells[i], rgb, sizeof _cells[i]);
    }
    for (int i = 0; i < IC_HEXAGONS; i++)
        for (int c = 0; c < 3; c++) _cells[i][c] = MAX(0, MIN(255, _cells[i][c]));
    [self setNeedsDisplay:YES];
}
- (void)getColor:(int[3])rgb { memcpy(rgb, _cells[0], 3 * sizeof(int)); }
- (NSPoint)pt:(const int *)xy { return NSMakePoint(xy[0] - self.origin.x + 0.5, xy[1] - self.origin.y + 0.5); }
- (NSBezierPath *)hexPath:(int)i
{
    NSBezierPath *p = [NSBezierPath bezierPath];
    for (int k = 0; k < 6; k++) {
        NSPoint q = [self pt:_shape.hex[i][k]];
        if (k) [p lineToPoint:q]; else [p moveToPoint:q];
    }
    [p closePath];
    return p;
}
- (void)drawRect:(NSRect)dirty
{
    if (!_haveShape) return;
    for (int i = 0; i < IC_HEXAGONS; i++) {
        NSPoint v[6];
        for (int k = 0; k < 6; k++) v[k] = [self pt:_shape.hex[i][k]];
        ESDrawCell(v, 6, _cells[i]);
    }
    for (int i = 0; i < IC_TRIANGLES; i++) {
        NSPoint v[3];
        for (int k = 0; k < 3; k++) v[k] = [self pt:_shape.tri[i][k]];
        ESDrawCell(v, 3, _shape.tri_rgb[i]);
    }
    [[NSColor colorWithCalibratedRed:0xfa / 255.0 green:0x50 / 255.0 blue:0 alpha:1] setStroke];   /* DrawFrame(250, 80, 0) */
    for (int i = 0; i < 2; i++) {
        NSBezierPath *f = [self hexPath:i];
        f.lineWidth = 3;
        [f stroke];
    }
    NSRect b = self.bounds;                                   /* DrawColorPaletteFrame */
    [[NSColor colorWithCalibratedWhite:0x99 / 255.0 alpha:1] setStroke];
    [NSBezierPath strokeRect:NSInsetRect(b, 0.5, 0.5)];
    [NSColor.whiteColor setStroke];
    [NSBezierPath strokeRect:NSInsetRect(b, 1.5, 1.5)];
}
/* CColorPalette::OnMouseUp: the clicked cell becomes the colour */
- (void)mouseUp:(NSEvent *)e
{
    if (!_haveShape) return;
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    for (int i = 0; i < IC_HEXAGONS; i++)
        if ([[self hexPath:i] containsPoint:p]) {
            int rgb[3];
            memcpy(rgb, _cells[i], sizeof rgb);
            [self setColor:rgb];
            if (self.onPick) self.onPick(rgb);
            return;
        }
}
@end

/* the nine saved colours (CColorStore): click to select, the selection framed in orange */
@interface ESColorStoreView : NSView
@property (nonatomic, copy) NSArray<NSValue *> *cells;   /* rects in view coordinates */
@property (nonatomic) NSInteger selected;
@property (nonatomic, copy) void (^onSelect)(NSInteger i);
- (void)setColor:(const int[3])rgb at:(NSInteger)i;
- (void)getColor:(int[3])rgb at:(NSInteger)i;
@end

@implementation ESColorStoreView {
    int _rgb[9][3];
}
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)e { return YES; }
- (instancetype)initWithFrame:(NSRect)r
{
    if ((self = [super initWithFrame:r]))
        for (int i = 0; i < 9; i++) _rgb[i][0] = _rgb[i][1] = _rgb[i][2] = 0xc0;
    return self;
}
- (void)setColor:(const int[3])rgb at:(NSInteger)i { if (i >= 0 && i < 9) { memcpy(_rgb[i], rgb, sizeof _rgb[i]); [self setNeedsDisplay:YES]; } }
- (void)getColor:(int[3])rgb at:(NSInteger)i { if (i >= 0 && i < 9) memcpy(rgb, _rgb[i], sizeof _rgb[i]); }
- (void)drawRect:(NSRect)dirty
{
    for (NSUInteger i = 0; i < self.cells.count && i < 9; i++) {
        NSRect r = self.cells[i].rectValue;
        NSPoint v[6] = { NSMakePoint(NSMinX(r), NSMaxY(r)), NSMakePoint(NSMinX(r), NSMinY(r)), NSMakePoint(NSMaxX(r), NSMinY(r)),
                         NSMakePoint(NSMaxX(r), NSMinY(r)), NSMakePoint(NSMaxX(r), NSMaxY(r)), NSMakePoint(NSMinX(r), NSMaxY(r)) };
        [[NSColor colorWithCalibratedRed:_rgb[i][0] / 255.0 green:_rgb[i][1] / 255.0 blue:_rgb[i][2] / 255.0 alpha:1] setFill];
        NSRectFill(r);
        NSBezierPath *dark = [NSBezierPath bezierPath], *light = [NSBezierPath bezierPath];
        [dark moveToPoint:v[2]]; [dark lineToPoint:v[4]]; [dark lineToPoint:v[5]];
        [light moveToPoint:v[0]]; [light lineToPoint:v[1]]; [light lineToPoint:v[2]];
        [[NSColor colorWithCalibratedWhite:0xa0 / 255.0 alpha:1] setStroke]; [dark stroke];
        [NSColor.whiteColor setStroke]; [light stroke];
        if ((NSInteger)i == self.selected) {
            [[NSColor colorWithCalibratedRed:0xfa / 255.0 green:0x50 / 255.0 blue:0 alpha:1] setStroke];
            NSBezierPath *f = [NSBezierPath bezierPathWithRect:NSInsetRect(r, 1.5, 1.5)];
            f.lineWidth = 3;
            [f stroke];
        }
    }
}
- (void)mouseUp:(NSEvent *)e
{
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    for (NSUInteger i = 0; i < self.cells.count; i++)
        if (NSPointInRect(p, self.cells[i].rectValue)) {
            self.selected = (NSInteger)i;
            [self setNeedsDisplay:YES];
            if (self.onSelect) self.onSelect((NSInteger)i);
            return;
        }
}
@end

/* native push button that reports press and release (Show Output) */
@interface ESHoldButton : NSButton
@property (nonatomic, copy) void (^onHold)(BOOL down);
@end

@implementation ESHoldButton
- (void)mouseDown:(NSEvent *)e
{
    if (self.onHold) self.onHold(YES);
    [super mouseDown:e];          /* tracks until the mouse goes up */
    if (self.onHold) self.onHold(NO);
}
@end

static void ESSetSliderValue(NSView *v, double x)
{
    if ([v isKindOfClass:[AQSlider class]]) { ((AQSlider *)v).value = x; [v setNeedsDisplay:YES]; }
    else if ([v isKindOfClass:[NSSlider class]]) ((NSSlider *)v).doubleValue = x;
}

#pragma mark - Building a view from the layout

/* The Preview button's menu (Epson's CDEF 382 bevel with a menu): a small triangle in the
 * button's lower-right corner; a click there opens Normal / Thumbnail */
@interface ESMenuArrow : NSView
@property (nonatomic, copy) NSArray<NSString *> *items;
@property (nonatomic, copy) NSString *current;
@property (nonatomic, copy) void (^onPick)(NSString *title);
@end

@implementation ESMenuArrow
- (BOOL)isFlipped { return YES; }
- (void)drawRect:(NSRect)dirty
{
    NSRect b = self.bounds;
    NSBezierPath *p = [NSBezierPath bezierPath];
    CGFloat w = 7, h = 4, cx = NSMidX(b), cy = NSMidY(b);
    [p moveToPoint:NSMakePoint(cx - w / 2, cy - h / 2)];
    [p lineToPoint:NSMakePoint(cx + w / 2, cy - h / 2)];
    [p lineToPoint:NSMakePoint(cx, cy + h / 2)];
    [p closePath];
    [[NSColor colorWithWhite:0.15 alpha:1] setFill];
    [p fill];
}
- (void)mouseDown:(NSEvent *)e
{
    NSMenu *m = [[NSMenu alloc] initWithTitle:@""];
    m.font = [NSFont systemFontOfSize:12];
    for (NSString *t in self.items) {
        NSMenuItem *mi = [m addItemWithTitle:t action:@selector(picked:) keyEquivalent:@""];
        mi.target = self;
        mi.state = [t isEqualToString:self.current] ? NSControlStateValueOn : NSControlStateValueOff;
    }
    [m popUpMenuPositioningItem:nil atLocation:NSMakePoint(0, NSMaxY(self.bounds) + 2) inView:self];
}
- (void)picked:(NSMenuItem *)mi { if (self.onPick) self.onPick(mi.title); }
- (BOOL)worksWhenModal { return YES; }
@end

/* Help buttons: Epson's own help pages (the V550 driver's English help, by context ID) */
static BOOL ESShowHelp(NSString *action)
{
    static NSDictionary *pages;
    if (!pages)
        pages = @{ @"help": @"0x0100", @"cfg": @"0x0600", @"pvHelp": @"0x0800", @"ha": @"0x0900",
                   @"ia": @"0x1000", @"tc": @"0x1100", @"cp": @"0x1300", @"fs": @"0x2100", @"edit": @"0x2800",
                   @"j": @"0x3100", @"t": @"0x3200", @"p": @"0x3400",
                   @"home": @"0x2300", @"office": @"0x2400", @"fa": @"0x2200", @"fac": @"0x2250" };
    NSString *key = [action hasSuffix:@":help"] ? [action substringToIndex:action.length - 5] : action;
    NSString *page = pages[key];
    if (!page) return NO;
    NSString *path = [[NSBundle mainBundle] pathForResource:page ofType:@"htm" inDirectory:@"Help"];
    if (path) [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:path]];
    else NSBeep();
    return YES;
}

/* Home Mode's Document Type list (CNTL 10105, proc 401 = Epson's icon menu button, MIWI 15024): the
 * chosen type's 48-pixel icon and name in a bevel box; a click opens the list with the icons */
@interface ESIconPopup : NSView
@property (nonatomic, copy) NSArray<NSString *> *items;
@property (nonatomic, copy) NSArray<NSImage *> *images;
@property (nonatomic) NSInteger selected;
@property (nonatomic) BOOL native, enabled;
@property (nonatomic, copy) void (^onChange)(ESIconPopup *me);
@end

@implementation ESIconPopup
- (BOOL)isFlipped { return YES; }
- (NSString *)picked { return self.selected >= 0 && self.selected < (NSInteger)self.items.count ? self.items[self.selected] : @""; }
- (void)drawRect:(NSRect)dirty
{
    NSRect b = NSInsetRect(self.bounds, 0.5, 0.5);
    NSBezierPath *box = [NSBezierPath bezierPathWithRoundedRect:b xRadius:self.native ? 6 : 3 yRadius:self.native ? 6 : 3];
    if (self.native) {
        [NSColor.controlBackgroundColor setFill];
        [box fill];
        [NSColor.separatorColor setStroke];
    } else {
        NSGradient *g = [[NSGradient alloc] initWithStartingColor:[NSColor colorWithWhite:0.99 alpha:1]
                                                      endingColor:[NSColor colorWithWhite:0.86 alpha:1]];
        [g drawInBezierPath:box angle:90];
        [[NSColor colorWithWhite:0.55 alpha:1] setStroke];
    }
    [box stroke];
    CGFloat alpha = self.enabled ? 1 : 0.45;
    NSImage *ic = self.selected >= 0 && self.selected < (NSInteger)self.images.count ? self.images[self.selected] : nil;
    CGFloat h = self.bounds.size.height;
    if (ic) [ic drawInRect:NSMakeRect(8, (h - 40) / 2, 40, 40) fromRect:NSZeroRect operation:NSCompositingOperationSourceOver
                  fraction:alpha respectFlipped:YES hints:nil];
    NSFont *f = self.native ? [NSFont systemFontOfSize:13] : ESFont(13, NO);
    NSDictionary *a = @{ NSFontAttributeName: f,
                         NSForegroundColorAttributeName: [(self.native ? NSColor.labelColor : NSColor.blackColor)
                                                          colorWithAlphaComponent:alpha] };
    NSString *t = [self picked];
    NSSize ts = [t sizeWithAttributes:a];
    [t drawAtPoint:NSMakePoint(60, (h - ts.height) / 2) withAttributes:a];
    /* the menu triangle */
    CGFloat x = self.bounds.size.width - 20, y = h / 2;
    NSBezierPath *tri = [NSBezierPath bezierPath];
    [tri moveToPoint:NSMakePoint(x, y - 3)];
    [tri lineToPoint:NSMakePoint(x + 9, y - 3)];
    [tri lineToPoint:NSMakePoint(x + 4.5, y + 3)];
    [tri closePath];
    [[(self.native ? NSColor.secondaryLabelColor : NSColor.blackColor) colorWithAlphaComponent:alpha] setFill];
    [tri fill];
}
- (void)mouseDown:(NSEvent *)e
{
    if (!self.enabled) return;
    NSMenu *m = [NSMenu new];
    m.autoenablesItems = NO;
    for (NSUInteger i = 0; i < self.items.count; i++) {
        NSMenuItem *mi = [m addItemWithTitle:self.items[i] action:@selector(picked:) keyEquivalent:@""];
        mi.target = self; mi.tag = (NSInteger)i;
        if (i < self.images.count) {
            NSImage *small = [self.images[i] copy];
            small.size = NSMakeSize(32, 32);
            mi.image = small;
        }
        mi.state = (NSInteger)i == self.selected ? NSControlStateValueOn : NSControlStateValueOff;
    }
    NSMenuItem *cur = self.selected >= 0 && self.selected < m.numberOfItems ? [m itemAtIndex:self.selected] : nil;
    [m popUpMenuPositioningItem:cur atLocation:NSMakePoint(0, 4) inView:self];
}
- (void)picked:(NSMenuItem *)mi
{
    if (mi.tag == self.selected) return;
    self.selected = mi.tag;
    [self setNeedsDisplay:YES];
    if (self.onChange) self.onChange(self);
}
@end

@interface ESBuilder : NSObject
@property (nonatomic) BOOL native;
@property (nonatomic, copy) void (^onToggle)(NSString *group, BOOL open);
@property (nonatomic, copy) void (^onAction)(NSString *action);
@property (nonatomic, copy) void (^onValue)(NSString *key, double value);   /* sliders, curve buttons */
@property (nonatomic, copy) void (^onHold)(NSString *key, BOOL down);       /* press-and-hold buttons */
@property (nonatomic, strong) NSMutableDictionary<NSString *, NSView *> *controls;   /* by "key"/"tag" */
@property (nonatomic, strong) NSMutableDictionary<NSString *, NSMutableArray<NSView *> *> *groups;   /* by "group" */
@property (nonatomic, strong) NSMutableDictionary<NSString *, NSString *> *fillActions;   /* native pull-downs: field -> action */
@property (nonatomic) int lastStep;                        /* native stepper direction */
- (void)build:(NSArray *)items into:(NSView *)parent;
@end

static void ESSetField(NSView *v, NSString *str);
static void ESSetEnabled(NSView *v, BOOL en);

@implementation ESBuilder

/* every Help button goes to Epson's help page for its dialog */
- (void)setOnAction:(void (^)(NSString *))onAction
{
    void (^inner)(NSString *) = [onAction copy];
    _onAction = inner ? [^(NSString *a) { if (!ESShowHelp(a)) inner(a); } copy] : nil;
}

- (NSTextField *)labelWith:(NSDictionary *)it
{
    NSTextField *l = [NSTextField labelWithString:it[@"text"] ?: @""];
    l.font = self.native ? (([it[@"bold"] boolValue]) ? [NSFont boldSystemFontOfSize:11] : [NSFont systemFontOfSize:11])
                         : ESFont(11, [it[@"bold"] boolValue]);
    [l sizeToFit];
    NSRect r = ESRect(it[@"rect"]);
    NSRect f = l.frame;
    BOOL right = [it[@"align"] isEqualToString:@"right"];
    f.origin = NSMakePoint(right ? NSMaxX(r) - f.size.width : r.origin.x, NSMidY(r) - f.size.height / 2);
    l.frame = f;
    return l;
}

- (NSView *)control:(NSDictionary *)it
{
    NSString *kind = it[@"kind"];
    /* drawn by the dialog itself (File Save's folder path and Details box) */
    if ([kind isEqualToString:@"path"] || [kind isEqualToString:@"details"]) return nil;
    NSRect r = ESRect(it[@"rect"]);
    NSString *text = it[@"text"] ?: @"";

    if ([kind isEqualToString:@"image"]) {
        NSImageView *iv = [[NSImageView alloc] initWithFrame:r];
        iv.image = ESArt(it[@"image"]);
        iv.imageScaling = NSImageScaleAxesIndependently;
        return iv;
    }
    if ([kind isEqualToString:@"label"]) return [self labelWith:it];
    if ([kind isEqualToString:@"canvas"]) return [[ESPreviewCanvas alloc] initWithFrame:r];
    if ([kind isEqualToString:@"wrap"]) {          /* a paragraph of text (Full Auto's notes) */
        NSTextField *t = [NSTextField wrappingLabelWithString:text];
        t.frame = r;
        t.font = self.native ? [NSFont systemFontOfSize:11] : ESFont(11, NO);
        if ([it[@"align"] isEqualToString:@"center"]) t.alignment = NSTextAlignmentCenter;
        return t;
    }
    if ([kind isEqualToString:@"progress"]) {
        NSProgressIndicator *pi = [[NSProgressIndicator alloc] initWithFrame:NSInsetRect(r, 0, -2)];
        pi.indeterminate = NO; pi.minValue = 0; pi.maxValue = 100;
        return pi;
    }
    if ([kind isEqualToString:@"iconpopup"]) {
        ESIconPopup *ip = [[ESIconPopup alloc] initWithFrame:r];
        ip.native = self.native; ip.enabled = YES;
        ip.items = it[@"menu"];
        NSMutableArray *ims = [NSMutableArray array];
        for (NSString *n in it[@"images"]) [ims addObject:ESArt(n) ?: [NSImage new]];
        ip.images = ims;
        NSString *action = it[@"action"];
        __weak ESBuilder *weakSelf = self;
        ip.onChange = ^(ESIconPopup *me) { if (action && weakSelf.onAction) weakSelf.onAction(action); };
        return ip;
    }
    if ([kind isEqualToString:@"icon"]) {
        NSImageView *iv = [[NSImageView alloc] initWithFrame:r];
        iv.image = it[@"image"] ? ESArt(it[@"image"]) : ESIcon(it[@"icon"]);
        iv.imageScaling = NSImageScaleProportionallyDown;
        return iv;
    }
    if ([kind isEqualToString:@"histogram"]) return [[ESHistogramView alloc] initWithFrame:r];
    if ([kind isEqualToString:@"curveview"]) return [[ESCurveView alloc] initWithFrame:r];
    if ([kind isEqualToString:@"toneview"]) return [[ESToneView alloc] initWithFrame:r];
    if ([kind isEqualToString:@"palette"]) {
        ESPaletteView *pv = [[ESPaletteView alloc] initWithFrame:r];
        pv.origin = NSMakePoint([it[@"rect"][0] doubleValue], [it[@"rect"][1] doubleValue]);
        return pv;
    }
    if ([kind isEqualToString:@"colorstore"]) {
        ESColorStoreView *sv = [[ESColorStoreView alloc] initWithFrame:r];
        double ox = [it[@"rect"][0] doubleValue], oy = [it[@"rect"][1] doubleValue];
        NSMutableArray *cells = [NSMutableArray array];
        for (NSArray *c in it[@"cells"])
            [cells addObject:[NSValue valueWithRect:NSMakeRect([c[0] doubleValue] - ox, [c[1] doubleValue] - oy,
                                                               [c[2] doubleValue] - [c[0] doubleValue],
                                                               [c[3] doubleValue] - [c[1] doubleValue])]];
        sv.cells = cells;
        return sv;
    }
    if ([kind isEqualToString:@"levelarrows"]) {
        ESLevelArrows *a = [[ESLevelArrows alloc] initWithFrame:r];
        a.count = [it[@"count"] intValue];
        a.right = 235; a.center = 117; a.dragging = -1;
        return a;
    }
    if ([kind isEqualToString:@"curvebutton"]) {
        ESCurveButton *cb = [[ESCurveButton alloc] initWithFrame:r];
        cb.native = self.native;
        cb.menuItems = it[@"menu"];
        /* CToneCurveButton::SetCurrentCurve: icon 262 - n for curve n (0..2 highlight, 3..5 shadow) */
        int first = [it[@"icon"] intValue] >= 260 ? 262 : 259;
        cb.icons = @[ ESIcon(@(first)) ?: [NSImage new], ESIcon(@(first - 1)) ?: [NSImage new], ESIcon(@(first - 2)) ?: [NSImage new] ];
        cb.selected = 1;
        NSString *key = it[@"key"];
        __weak ESBuilder *weakSelf = self;
        cb.onChange = ^(NSInteger i) { if (weakSelf.onValue) weakSelf.onValue(key, (double)i); };
        return cb;
    }
    if ([kind isEqualToString:@"ticks"]) {
        ESTicks *t = [[ESTicks alloc] initWithFrame:r];
        t.count = [it[@"count"] integerValue];
        return t;
    }
    if ([kind isEqualToString:@"slider"]) {
        NSString *key = it[@"key"];
        if (!self.native) {
            AQSlider *sl = [[AQSlider alloc] initWithFrame:NSMakeRect(r.origin.x, r.origin.y - 3, r.size.width, 17)];
            sl.minValue = [it[@"min"] doubleValue]; sl.maxValue = [it[@"max"] doubleValue];
            sl.value = [it[@"value"] doubleValue];
            __weak ESBuilder *weakSelf = self;
            sl.onChange = ^(AQSlider *me) { if (weakSelf.onValue) weakSelf.onValue(key, me.value); };
            return sl;
        }
        NSSlider *sl = [[NSSlider alloc] initWithFrame:NSMakeRect(r.origin.x, r.origin.y - 4, r.size.width, 19)];
        sl.controlSize = NSControlSizeSmall;
        sl.minValue = [it[@"min"] doubleValue]; sl.maxValue = [it[@"max"] doubleValue];
        sl.doubleValue = [it[@"value"] doubleValue];
        sl.continuous = YES;
        sl.identifier = key;
        sl.target = self;
        sl.action = @selector(sliderMoved:);
        return sl;
    }
    if ([kind isEqualToString:@"edit"]) {
        NSTextField *t = [[NSTextField alloc] initWithFrame:NSInsetRect(r, 0, -2)];
        t.stringValue = text;
        t.font = self.native ? [NSFont systemFontOfSize:11] : ESFont(11, NO);
        t.bezelStyle = NSTextFieldSquareBezel;
        return t;
    }

    if (!self.native) {
        AQControl *c = [[AQControl alloc] initWithFrame:r];
        c.text = text;
        c.icon = ESIcon(it[@"icon"]);
        c.on = [it[@"on"] boolValue];
        c.isDefault = [it[@"default"] boolValue];
        c.menuItems = it[@"menu"];
        c.tabs = it[@"tabs"];
        c.selectedTab = [it[@"value"] integerValue];
        if (!c.icon && it[@"symbol"]) {
            if (@available(macOS 11.0, *))
                c.icon = [NSImage imageWithSystemSymbolName:it[@"symbol"] accessibilityDescription:nil];
        }
        if ([kind isEqualToString:@"popup"]) c.kind = AQPopup;
        else if ([kind isEqualToString:@"button"]) c.kind = AQButton;
        else if ([kind isEqualToString:@"bevel"]) c.kind = AQBevel;
        else if ([kind isEqualToString:@"check"]) c.kind = AQCheck;
        else if ([kind isEqualToString:@"radio"]) c.kind = AQRadio;
        else if ([kind isEqualToString:@"disclosure"]) c.kind = AQDisclosure;
        else if ([kind isEqualToString:@"separator"]) c.kind = AQSeparator;
        else if ([kind isEqualToString:@"stepper"]) c.kind = AQStepper;
        else if ([kind isEqualToString:@"tabs"]) c.kind = AQTabs;
        else if ([kind isEqualToString:@"placard"]) c.kind = AQPlacard;
        if (c.kind == AQPopup && [it[@"text"] length] == 0) {
            /* Epson's menu buttons next to an edit field (Resolution): the choice goes into the field */
            c.arrowOnly = YES;
            NSString *fills = it[@"fills"], *action = it[@"action"];
            __weak ESBuilder *weakSelf = self;
            c.onChange = ^(AQControl *me) {
                if (fills) ESSetField(weakSelf.controls[fills], me.picked);
                if (action && weakSelf.onAction) weakSelf.onAction(action);
            };
        } else
        if (it[@"action"] && (c.kind == AQButton || c.kind == AQBevel || c.kind == AQCheck || c.kind == AQPopup ||
                               c.kind == AQStepper || c.kind == AQTabs)) {
            NSString *action = it[@"action"];
            __weak ESBuilder *weakSelf = self;
            c.onChange = ^(AQControl *me) { if (weakSelf.onAction) weakSelf.onAction(action); };
        }
        if ([it[@"hold"] boolValue]) {
            NSString *key = it[@"key"];
            __weak ESBuilder *weakSelf = self;
            c.onHold = ^(BOOL down) { if (weakSelf.onHold) weakSelf.onHold(key, down); };
        }
        if (c.kind == AQDisclosure && it[@"toggles"]) {
            NSString *group = it[@"toggles"];
            __weak ESBuilder *weakSelf = self;
            c.onChange = ^(AQControl *me) { if (weakSelf.onToggle) weakSelf.onToggle(group, me.on); };
        }
        if (c.kind == AQRadio && it[@"action"]) {     /* radio group by action: the dialog keeps the state */
            NSString *action = it[@"action"];
            __weak ESBuilder *weakSelf = self;
            c.onChange = ^(AQControl *me) { if (weakSelf.onAction) weakSelf.onAction(action); };
        } else if (c.kind == AQRadio) {
            c.onChange = ^(AQControl *me) {     /* radio group: siblings on the same row */
                for (NSView *v in me.superview.subviews)
                    if (v != me && [v isKindOfClass:[AQControl class]] && ((AQControl *)v).kind == AQRadio &&
                        fabs(NSMidY(v.frame) - NSMidY(me.frame)) < 4) {
                        ((AQControl *)v).on = NO;
                        [v setNeedsDisplay:YES];
                    }
            };
        }
        return c;
    }

    /* native controls */
    if ([kind isEqualToString:@"tabs"]) {
        NSTabView *tv = [[NSTabView alloc] initWithFrame:NSInsetRect(r, -6, -4)];
        for (NSString *t in it[@"tabs"]) {
            NSTabViewItem *ti = [[NSTabViewItem alloc] initWithIdentifier:t];
            ti.label = t;
            [tv addTabViewItem:ti];
        }
        tv.font = [NSFont systemFontOfSize:11];
        return tv;
    }
    if ([kind isEqualToString:@"placard"]) {
        NSBox *box = [[NSBox alloc] initWithFrame:r];
        box.boxType = NSBoxCustom;
        box.borderColor = NSColor.separatorColor;
        box.fillColor = NSColor.controlBackgroundColor;
        box.borderWidth = 1;
        return box;
    }
    if ([kind isEqualToString:@"popup"]) {
        NSArray *menu = it[@"menu"];
        BOOL arrowOnly = text.length == 0 && r.size.width < 30;
        NSPopUpButton *p = [[NSPopUpButton alloc] initWithFrame:NSInsetRect(r, 0, -3) pullsDown:arrowOnly];
        p.font = [NSFont systemFontOfSize:11];
        p.controlSize = NSControlSizeSmall;
        /* items stay enabled in modal dialogs too (validation there disables items whose target
         * isn't in the modal window); ESSetItemEnabled dims single items */
        p.autoenablesItems = NO;
        if (arrowOnly) [p addItemWithTitle:@""];
        [p addItemsWithTitles:menu.count ? menu : @[text]];
        if (!arrowOnly) [p selectItemWithTitle:text];
        if (arrowOnly && it[@"fills"]) {
            p.identifier = it[@"fills"]; p.target = self; p.action = @selector(fillPicked:);
            if (it[@"action"]) {
                if (!self.fillActions) self.fillActions = [NSMutableDictionary dictionary];
                self.fillActions[it[@"fills"]] = it[@"action"];
            }
        } else if (it[@"action"]) { p.identifier = it[@"action"]; p.target = self; p.action = @selector(actionClicked:); }
        return p;
    }
    if ([kind isEqualToString:@"button"] && [it[@"hold"] boolValue]) {
        ESHoldButton *b = [[ESHoldButton alloc] initWithFrame:r];
        b.title = text;
        b.bezelStyle = NSBezelStyleRounded;
        b.font = [NSFont systemFontOfSize:11];
        NSString *key = it[@"key"];
        __weak ESBuilder *weakSelf = self;
        b.onHold = ^(BOOL down) { if (weakSelf.onHold) weakSelf.onHold(key, down); };
        return b;
    }
    if ([kind isEqualToString:@"button"]) {
        NSButton *b = [NSButton buttonWithTitle:text target:nil action:nil];
        b.frame = r;
        b.bezelStyle = r.size.height > 30 ? NSBezelStyleRegularSquare : NSBezelStyleRounded;
        b.font = [NSFont systemFontOfSize:r.size.height > 30 ? 13 : 11];
        NSImage *ic = ESIcon(it[@"icon"]);
        if (ic) { b.image = ic; b.imagePosition = NSImageLeft; }
        if ([it[@"default"] boolValue]) b.keyEquivalent = @"\r";
        if (it[@"action"]) { b.identifier = it[@"action"]; b.target = self; b.action = @selector(actionClicked:); }
        return b;
    }
    if ([kind isEqualToString:@"bevel"]) {
        NSButton *b = [[NSButton alloc] initWithFrame:r];
        b.bezelStyle = NSBezelStyleShadowlessSquare;
        b.image = ESIcon(it[@"icon"]);
        if (!b.image && it[@"symbol"]) {
            if (@available(macOS 11.0, *))
                b.image = [NSImage imageWithSystemSymbolName:it[@"symbol"] accessibilityDescription:nil];
        }
        NSString *t = it[@"text"] ?: @"";
        b.title = t;
        b.font = [NSFont systemFontOfSize:11];
        b.imagePosition = t.length ? NSImageLeft : NSImageOnly;
        b.imageScaling = NSImageScaleProportionallyDown;
        if (it[@"action"]) { b.identifier = it[@"action"]; b.target = self; b.action = @selector(actionClicked:); }
        return b;
    }
    if ([kind isEqualToString:@"check"] || [kind isEqualToString:@"radio"]) {
        NSButton *b = [kind isEqualToString:@"check"] ? [NSButton checkboxWithTitle:text target:nil action:nil]
                                                      : [NSButton radioButtonWithTitle:text target:nil action:nil];
        b.frame = NSInsetRect(r, 0, -2);
        b.font = [NSFont systemFontOfSize:11];
        b.state = [it[@"on"] boolValue] ? NSControlStateValueOn : NSControlStateValueOff;
        [b sizeToFit];
        if (it[@"action"]) { b.identifier = it[@"action"]; b.target = self; b.action = @selector(actionClicked:); }
        return b;
    }
    if ([kind isEqualToString:@"disclosure"]) {
        NSButton *b = [[NSButton alloc] initWithFrame:NSInsetRect(r, -2, -2)];
        b.bezelStyle = NSBezelStyleDisclosure;
        [b setButtonType:NSButtonTypeOnOff];
        b.title = @"";
        b.state = [it[@"on"] boolValue] ? NSControlStateValueOn : NSControlStateValueOff;
        if (it[@"toggles"]) {
            b.identifier = it[@"toggles"];
            b.target = self;
            b.action = @selector(disclosureClicked:);
        }
        return b;
    }
    if ([kind isEqualToString:@"separator"]) {
        NSBox *box = [[NSBox alloc] initWithFrame:NSMakeRect(r.origin.x, r.origin.y, r.size.width, 1)];
        box.boxType = NSBoxSeparator;
        return box;
    }
    if ([kind isEqualToString:@"stepper"]) {
        NSStepper *s = [[NSStepper alloc] initWithFrame:r];
        s.controlSize = NSControlSizeSmall;
        s.minValue = -1000000; s.maxValue = 1000000; s.valueWraps = NO; s.increment = 1; s.integerValue = 0;
        if (it[@"action"]) { s.identifier = it[@"action"]; s.target = self; s.action = @selector(stepped:); }
        return s;
    }
    return nil;
}

- (void)sliderMoved:(NSSlider *)s
{
    double v = round(s.doubleValue);
    if (self.onValue) self.onValue(s.identifier, v);
}

/* native stepper: report the direction, then re-centre */
- (void)stepped:(NSStepper *)s
{
    self.lastStep = s.integerValue > 0 ? 1 : -1;
    s.integerValue = 0;
    if (self.onAction) self.onAction(s.identifier);
}

/* a pull-down next to an edit field: put the chosen item in the field, keep the blank title */
- (void)fillPicked:(NSPopUpButton *)p
{
    NSString *t = p.titleOfSelectedItem;
    ESSetField(self.controls[p.identifier], t ?: @"");
    [p selectItemAtIndex:0];
    NSString *action = self.fillActions[p.identifier];
    if (action && self.onAction) self.onAction(action);
}

/* the builder is the target of every control: its actions must also work in modal dialogs */
- (BOOL)worksWhenModal { return YES; }

- (void)actionClicked:(NSControl *)b
{
    if (self.onAction) self.onAction(b.identifier);
}

- (void)disclosureClicked:(NSButton *)b
{
    if (self.onToggle) self.onToggle(b.identifier, b.state == NSControlStateValueOn);
}

- (void)build:(NSArray *)items into:(NSView *)parent
{
    NSView *lastBold = nil;
    for (NSDictionary *it in items) {
        NSView *v = [self control:it];
        if (!v) continue;
        if ([it[@"kind"] isEqualToString:@"label"] && [it[@"bold"] boolValue]) lastBold = v;
        if (it[@"tip"]) v.toolTip = it[@"tip"];
        NSString *key = it[@"key"] ?: it[@"tag"];
        if (key) {
            if (!self.controls) self.controls = [NSMutableDictionary dictionary];
            self.controls[key] = v;
        }
        if (it[@"group"]) {
            if (!self.groups) self.groups = [NSMutableDictionary dictionary];
            if (!self.groups[it[@"group"]]) self.groups[it[@"group"]] = [NSMutableArray array];
            [self.groups[it[@"group"]] addObject:v];
        }
        if ([it[@"kind"] isEqualToString:@"separator"] && lastBold) {
            /* section rule: from just after the section title to the right edge */
            NSRect f = v.frame;
            CGFloat x0 = NSMaxX(lastBold.frame) + 8;
            f.size.width = MAX(10, NSMaxX(f) - x0);
            f.origin.x = x0;
            f.origin.y = round(NSMidY(lastBold.frame));
            v.frame = f;
        }
        /* Resizing (in a flipped view, MinY is the top margin):
         *   pin=bottom  keep the distance to the bottom edge
         *   right=true  keep the distance to the right edge
         *   grow=width|height|both  stretch with the window */
        NSString *grow = it[@"grow"] ?: @"";
        BOOL gw = [grow isEqualToString:@"width"] || [grow isEqualToString:@"both"];
        BOOL gh = [grow isEqualToString:@"height"] || [grow isEqualToString:@"both"];
        NSAutoresizingMaskOptions m = 0;
        if (gh) m |= NSViewHeightSizable;
        else m |= [it[@"pin"] isEqualToString:@"bottom"] ? NSViewMinYMargin : NSViewMaxYMargin;
        if (gw) m |= NSViewWidthSizable;
        else m |= [it[@"right"] boolValue] ? NSViewMinXMargin : NSViewMaxXMargin;
        v.autoresizingMask = m;
        [parent addSubview:v];
    }
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark - Control values (either look)

static NSString *ESValue(NSView *v)
{
    if ([v isKindOfClass:[AQControl class]]) return ((AQControl *)v).text ?: @"";
    if ([v isKindOfClass:[NSPopUpButton class]]) return ((NSPopUpButton *)v).titleOfSelectedItem ?: @"";
    if ([v isKindOfClass:[NSTextField class]]) return ((NSTextField *)v).stringValue;
    return @"";
}

static BOOL ESIsOn(NSView *v)
{
    if ([v isKindOfClass:[AQControl class]]) return ((AQControl *)v).on;
    if ([v isKindOfClass:[NSButton class]]) return ((NSButton *)v).state == NSControlStateValueOn;
    return NO;
}

static void ESSetText(NSView *v, NSString *s)
{
    if ([v isKindOfClass:[NSTextField class]]) {
        NSTextField *t = (NSTextField *)v;
        CGFloat x = t.frame.origin.x, mid = NSMidY(t.frame);
        t.stringValue = s;
        [t sizeToFit];
        NSRect f = t.frame;
        f.origin = NSMakePoint(x, mid - f.size.height / 2);
        t.frame = f;
    }
}

/* ------------------------------------------------------------------------ */
#pragma mark - Preview scanning helpers

/* Linear 8-bit scanner data -> display image. Negatives are inverted with
 * per-channel levels; everything gets a display gamma (the data is linear). */
static NSImage *ESDisplayImage(const uint8_t *rgb, int w, int rows, BOOL negative, const int lo[3], const int hi[3],
                               double gamma)
{
    if (w <= 0 || rows <= 0) return nil;
    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:w pixelsHigh:rows
                                                                 bitsPerSample:8 samplesPerPixel:3 hasAlpha:NO
                                                                      isPlanar:NO colorSpaceName:NSDeviceRGBColorSpace
                                                                   bytesPerRow:w * 3 bitsPerPixel:24];
    uint8_t lut[3][256];
    for (int c = 0; c < 3; c++)
        for (int v = 0; v < 256; v++) {
            double t = (double)(v - lo[c]) / (double)MAX(1, hi[c] - lo[c]);
            t = t < 0 ? 0 : t > 1 ? 1 : t;
            if (negative) t = 1 - t;
            lut[c][v] = (uint8_t)lround(255.0 * pow(t, 1 / gamma));
        }
    uint8_t *dst = rep.bitmapData;
    size_t n = (size_t)w * rows;
    for (size_t i = 0; i < n; i++) {
        dst[i * 3 + 0] = lut[0][rgb[i * 3 + 0]];
        dst[i * 3 + 1] = lut[1][rgb[i * 3 + 1]];
        dst[i * 3 + 2] = lut[2][rgb[i * 3 + 2]];
    }
    NSImage *im = [[NSImage alloc] initWithSize:NSMakeSize(w, rows)];
    [im addRepresentation:rep];
    return im;
}

/* Film frames in a film-holder preview: light comes through film and empty
 * slots; holder bars are black. Empty slots are skipped (mostly saturated). */
/* Trim unexposed film (the rebate along a frame's edges) out of a detected frame, like
 * Epson's frame detection: on a negative the rebate is clear film base (the brightest,
 * flattest part of the frame in the raw data); on a slide it is opaque (near black).
 * Plain C so it can be tested on its own. */
typedef struct { int x0, y0, x1, y1, base, cut[4]; char prof[4][96]; } ESTrim;

/* fraction (0..100) of a line that is film base (edge printing aside) */
static int es_line_base(const uint8_t *rgb, int w, int ax, int ay, int dx, int dy, int len, int p98, int negative)
{
    int k = 0, base = 0;
    for (int i = 0; i < len; i += 2, k++) {
        int g = rgb[((size_t)(ay + dy * i) * w + (ax + dx * i)) * 3 + 1];
        if (g >= 250 || (negative ? g >= p98 * 85 / 100 : g <= p98 * 12 / 100)) base++;
    }
    return k ? base * 100 / k : 0;
}

/* how many lines to cut from one side: the outer band (max 10%) up to the last line that is
 * mostly film base, tolerating short soft transitions at the holder edge */
static int es_cut(const uint8_t *rgb, int w, int ax, int ay, int dx, int dy, int sx, int sy, int len, int maxn,
                  int p98, int negative, char *prof, size_t plen)
{
    int last = -1, gap = 0;
    size_t used = 0;
    for (int t = 0; t < maxn; t++) {
        int f = es_line_base(rgb, w, ax + sx * t, ay + sy * t, dx, dy, len, p98, negative);
        if (t < 12 && used + 4 < plen) used += (size_t)snprintf(prof + used, plen - used, "%d ", f);
        if (f >= 60) { last = t; gap = 0; }
        else if (++gap > 6) break;
    }
    return last + 1;
}

static ESTrim ESTrimRebateC(const uint8_t *rgb, int w, int x0, int y0, int x1, int y1, int negative)
{
    ESTrim r = { x0, y0, x1, y1, 0, { 0, 0, 0, 0 }, { "", "", "", "" } };
    if (x1 - x0 < 20 || y1 - y0 < 20) return r;
    /* film-base level: ignore light leaking past the film edges (blown out) */
    long hist[256] = { 0 }, n = 0;
    for (int y = y0; y < y1; y += 2)
        for (int x = x0; x < x1; x += 2) {
            int g = rgb[((size_t)y * w + x) * 3 + 1];
            if (g < 250) { hist[g]++; n++; }
        }
    long acc = 0; int p98 = 255;
    for (int v = 255; v >= 0; v--) { acc += hist[v]; if (acc > n / 50) { p98 = v; break; } }
    r.base = p98;
    if (p98 < 8) return r;
    int maxv = (y1 - y0) / 10, maxh = (x1 - x0) / 10;
    r.cut[0] = es_cut(rgb, w, x0, y0, 1, 0, 0, 1, x1 - x0, maxv, p98, negative, r.prof[0], sizeof r.prof[0]);
    r.cut[1] = es_cut(rgb, w, x0, y1 - 1, 1, 0, 0, -1, x1 - x0, maxv, p98, negative, r.prof[1], sizeof r.prof[1]);
    r.cut[2] = es_cut(rgb, w, x0, y0, 0, 1, 1, 0, y1 - y0, maxh, p98, negative, r.prof[2], sizeof r.prof[2]);
    r.cut[3] = es_cut(rgb, w, x1 - 1, y0, 0, 1, -1, 0, y1 - y0, maxh, p98, negative, r.prof[3], sizeof r.prof[3]);
    r.y0 += r.cut[0]; r.y1 -= r.cut[1]; r.x0 += r.cut[2]; r.x1 -= r.cut[3];
    return r;
}

static NSRect ESTrimRebate(const uint8_t *rgb, int w, NSRect f, BOOL negative)
{
    ESTrim t = ESTrimRebateC(rgb, w, (int)f.origin.x, (int)f.origin.y, (int)NSMaxX(f), (int)NSMaxY(f), negative);
    NSRect r = NSMakeRect(t.x0, t.y0, t.x1 - t.x0, t.y1 - t.y0);
    NSString *path = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Logs/EPSON Scan.log"];
    NSDateFormatter *df = [NSDateFormatter new];
    df.dateFormat = @"yyyy-MM-dd HH:mm:ss";
    NSString *line = [NSString stringWithFormat:@"%@  Preview frame: found %@, film edge trimmed to %@ (film base %d, %@; "
                      "cut top %d bottom %d left %d right %d; edge %% top [%s] bottom [%s] left [%s] right [%s])\n",
                      [df stringFromDate:NSDate.date], NSStringFromRect(f), NSStringFromRect(r), t.base,
                      negative ? @"negative" : @"positive", t.cut[0], t.cut[1], t.cut[2], t.cut[3],
                      t.prof[0], t.prof[1], t.prof[2], t.prof[3]];
    FILE *fp = fopen(path.fileSystemRepresentation, "a");
    if (fp) { fputs(line.UTF8String, fp); fclose(fp); }
    return r;
}

static NSArray<NSValue *> *ESDetectFrames(const uint8_t *rgb, int w, int h, int dpi, BOOL negative)
{
    NSMutableArray *out = [NSMutableArray array];
    const int open_level = 4, min_len = dpi * 35 / 100, inset = dpi / 200 + 2;
    uint8_t *open = calloc((size_t)h, 1);
    for (int y = 0; y < h; y++) {
        long sum = 0; int cnt = 0;
        for (int x = 0; x < w; x += 4, cnt++) sum += rgb[((size_t)y * w + x) * 3 + 1];
        open[y] = cnt && sum / cnt > open_level;
    }
    for (int y = 0; y < h;) {
        if (!open[y]) { y++; continue; }
        int y0 = y;
        while (y < h && open[y]) y++;
        int y1 = y;
        if (y1 - y0 < min_len) continue;
        long *col = calloc((size_t)w, sizeof(long));
        long sat = 0, tot = 0;
        for (int yy = y0; yy < y1; yy += 2)
            for (int x = 0; x < w; x++) {
                uint8_t g = rgb[((size_t)yy * w + x) * 3 + 1];
                col[x] += g;
                if (!(x & 3)) { tot++; if (g >= 250) sat++; }
            }
        int rows = (y1 - y0 + 1) / 2, x0 = 0, x1 = w;
        while (x0 < w && col[x0] / rows <= open_level) x0++;
        while (x1 > x0 && col[x1 - 1] / rows <= open_level) x1--;
        free(col);
        if (x1 - x0 < min_len || sat * 2 > tot) continue;
        NSRect fr = ESTrimRebate(rgb, w, NSMakeRect(x0, y0, x1 - x0, y1 - y0), negative);
        [out addObject:[NSValue valueWithRect:NSInsetRect(fr, inset, inset)]];
    }
    free(open);
    return out;
}

/* per-channel 0.5% / 99.5% levels over the given areas (or the whole image) */
static void ESLevels(const uint8_t *rgb, int w, int h, NSArray<NSValue *> *areas, int lo[3], int hi[3])
{
    long hist[3][256] = { { 0 } };
    long n = 0;
    NSArray *rs = areas.count ? areas : @[ [NSValue valueWithRect:NSMakeRect(0, 0, w, h)] ];
    for (NSValue *v in rs) {
        NSRect r = v.rectValue;
        for (int y = (int)r.origin.y; y < (int)NSMaxY(r) && y < h; y += 2)
            for (int x = (int)r.origin.x; x < (int)NSMaxX(r) && x < w; x += 2, n++)
                for (int c = 0; c < 3; c++) hist[c][rgb[((size_t)y * w + x) * 3 + c]]++;
    }
    for (int c = 0; c < 3; c++) {
        long acc = 0; lo[c] = 0; hi[c] = 255;
        for (int v = 0; v < 256; v++) { acc += hist[c][v]; if (acc > n / 200) { lo[c] = v; break; } }
        acc = 0;
        for (int v = 255; v >= 0; v--) { acc += hist[c][v]; if (acc > n / 200) { hi[c] = v; break; } }
        if (hi[c] <= lo[c]) hi[c] = lo[c] + 1;
    }
}

/* ------------------------------------------------------------------------ */
#pragma mark - Professional Mode window


/* ------------------------------------------------------------------------ */
#pragma mark - Epson FIT (auto exposure / film color)

/* Red-correction matrices from the V550's hardware data file
 * (EPSON Scan ES00EB HRD, "red profile matrix" records, x10000 integers).
 * Scan Control picks: negative film -> 3rd, positive film -> 2nd, flatbed -> 1st. */
static const double kRedMatrix[3][9] = {
    { 0.974, 0, 0,  0, 1.020, 0,  0, 0, 1.006 },   /* flatbed (reflective) */
    { 0.987, 0, 0,  0, 1.007, 0,  0, 0, 1.006 },   /* positive film        */
    { 0.834, 0, 0,  0, 0.911, 0,  0, 0, 1.008 },   /* negative film        */
};

/* Epson Scan's defaults (ESPR preference record): display gamma 2.2, exposure level 4 */
static FitParams ESFitParams(BOOL film, BOOL negative, BOOL restoration, int backlight, BOOL document)
{
    FitParams p = { 0 };
    p.type = film ? (negative ? FIT_NEGA : FIT_POSI) : FIT_REFLECTIVE;
    /* CFitIF::SetFIT3_PARA: Reflective with Auto Exposure Type Document = 1, else 0;
     * Color Restoration turns a 0 into 2 */
    p.sub = !film && document ? 1 : restoration ? 2 : 0;
    p.backlight = backlight;                 /* Backlight Correction: 0 off, 1 Low, 2 Medium, 3 High */
    p.cmd_type = 1;
    NSUserDefaults *d = NSUserDefaults.standardUserDefaults;
    p.screen_gamma10 = ESScreenGamma10();
    p.exposure_level = [d objectForKey:@"ExposureLevel"] ? (int)[d integerForKey:@"ExposureLevel"] : 4;
    const double *m = kRedMatrix[film ? (negative ? 2 : 1) : 0];
    memcpy(p.matrix, m, sizeof p.matrix);
    return p;
}

/* 16-bit linear -> 8-bit gamma 1.8 (what Epson's scanner hands FIT for previews) */
static const uint8_t *ESGamma18(void)
{
    static uint8_t t[65536];
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        for (int v = 0; v < 65536; v++) t[v] = (uint8_t)lround(255.0 * pow(v / 65535.0, 1 / 1.8));
    });
    return t;
}

/* Colour-correction matrices from the HRD file ("profile matrix" records, x10000):
 * the same three choices as the red matrices above. */
static const double kProfileMatrix[3][9] = {
    { 1.2377, -0.1952, -0.0425,  -0.1693, 1.2682, -0.0989,  -0.0456, -0.2368, 1.2824 },   /* flatbed  */
    { 1.3849, -0.3563, -0.0286,  -0.0832, 1.1432, -0.0600,  -0.0213, -0.2304, 1.2517 },   /* positive */
    { 0.9912,  0.0059,  0.0029,  -0.2607, 1.1295,  0.1312,  -0.0909, -0.0986, 1.1895 },   /* negative */
};

static NSString *ESFitEngine(void) { return [[NSBundle mainBundle] pathForResource:@"FIT_i386" ofType:nil]; }

/* ---- Epson DTR2 (recompiled): frame detection and Auto Locate, as CDTR / CEsExtDTR2 call it ---- */

/* the preview resampled to DTR's resolution (film 300 dpi, documents 150), 32-bit xRGB at gamma 1.8
 * like the FIT3_BmpInfo Epson's UI hands to DTR */
static NSMutableData *ESDTRPreview(const uint16_t *raw, int w, int h, int dpi, int toDPI, int *ow, int *oh)
{
    const uint8_t *g = ESGamma18();
    int W = (int)lround((double)w * toDPI / dpi), H = (int)lround((double)h * toDPI / dpi);
    if (W < 8 || H < 8) return nil;
    NSMutableData *d = [NSMutableData dataWithLength:(size_t)W * H * 4];
    uint8_t *o = d.mutableBytes;
    double k = (double)dpi / toDPI;
    for (int y = 0; y < H; y++) {
        int y0 = (int)(y * k), y1 = MAX(y0 + 1, MIN(h, (int)((y + 1) * k)));
        for (int x = 0; x < W; x++) {
            int x0 = (int)(x * k), x1 = MAX(x0 + 1, MIN(w, (int)((x + 1) * k)));
            uint32_t s[3] = { 0, 0, 0 }, n = 0;
            for (int yy = y0; yy < y1 && yy < h; yy++)
                for (int xx = x0; xx < x1 && xx < w; xx++) {
                    const uint16_t *p = raw + ((size_t)yy * w + xx) * 3;
                    s[0] += p[0]; s[1] += p[1]; s[2] += p[2]; n++;
                }
            uint8_t *q = o + ((size_t)y * W + x) * 4;
            q[0] = 0;
            for (int c = 0; c < 3; c++) q[1 + c] = n ? g[s[c] / n] : 0;
        }
    }
    *ow = W; *oh = H;
    return d;
}

static NSString *ESDTREngine(void) { return [[NSBundle mainBundle] pathForResource:@"DTR2_i386" ofType:nil]; }

static DtrImage ESDTRImage(const uint8_t *xrgb, int w, int h, int dpi, BOOL film, BOOL negative, int filmType)
{
    /* CDTR::InitDetectImgInfo with the V550's TWEP_DTRPREVIEWINFO: model 0xEB (ES00EB.dti),
     * the built-in transparency unit (unit type 3), light path from the film type; the red correction
     * matrix is the scanner's for that film (CImgTriplet22::DetectImageInfo) */
    DtrImage im = { 0 };
    im.xrgb = xrgb; im.width = w; im.height = h; im.dpi = dpi;
    im.model_id = 0xEB;
    im.connected_unit = 3;
    im.scanned_unit = film ? 3 : 0;
    im.doc_source = film ? (negative ? 1 : 2) : 0;
    im.holder = 0;
    im.film = film;
    im.film_size = 0;
    im.film_type = filmType;
    const double nega[3] = { 0.834, 0.911, 1.008 }, posi[3] = { 0.987, 1.007, 1.006 }, fb[3] = { 0.974, 1.02, 1.006 };
    const double *m = film ? (negative ? nega : posi) : fb;
    for (int i = 0; i < 3; i++) im.red_matrix[i * 4] = m[i];
    return im;
}

/* Professional Mode's Preview kind, kept for film and for the glass apart (CAdvancedDialog +0x1af0 /
 * +0x1af4, SetDefaultPreviewMode): Thumbnail for film, Normal for the glass to begin with */
static BOOL ESThumbnailPreview(BOOL film)
{
    NSUserDefaults *ud = NSUserDefaults.standardUserDefaults;
    NSString *key = film ? @"PreviewThumbnail" : @"PreviewThumbnailReflective";
    return [ud objectForKey:key] ? [ud boolForKey:key] : film;
}

static void ESSetThumbnailPreview(BOOL film, BOOL on)
{
    [NSUserDefaults.standardUserDefaults setBool:on forKey:film ? @"PreviewThumbnail" : @"PreviewThumbnailReflective"];
}

/* the film type DTR found in the last detection (TWEP_TFT, -1 none): Full Auto Mode reads it */
static int gDTRFoundFilmType = -1;

/* Film frames by Epson's DTR (CDTR::DoDetectImage + AdjustMargin): marquees in preview pixels;
 * nil when DTR can't tell (the caller then uses its own frame finder) */
static NSArray<NSValue *> *ESDetectFramesDTR(const uint16_t *raw, int w, int h, int dpi, BOOL negative, int filmType,
                                             int marginID)
{
    NSString *engine = ESDTREngine();
    if (!engine || !raw) return nil;
    int W = 0, H = 0;
    NSMutableData *px = ESDTRPreview(raw, w, h, dpi, 300, &W, &H);
    if (!px) return nil;
    DtrImage im = ESDTRImage(px.bytes, W, H, 300, YES, negative, filmType);
    im.margin_id = marginID;
    DtrFrame fr[64];
    int n = 0;
    char err[256] = "";
    NSString *dir = engine.stringByDeletingLastPathComponent;
    int rc = dtr_detect(engine.fileSystemRepresentation, dir.fileSystemRepresentation, &im, fr, 64, &n, err, sizeof err);
    if (rc) { ESLog(@"DTR frame detection: %s", err); return nil; }
    double k = (double)dpi / 300.0;
    NSMutableArray *out = [NSMutableArray array];
    for (int i = 0; i < n; i++) {
        /* TWEP_LOCATIONDATA: top, left, width and height in DTR pixels */
        NSRect r = NSMakeRect(fr[i].pt[1] * k, fr[i].pt[0] * k, fr[i].pt[2] * k, fr[i].pt[3] * k);
        r = NSIntersectionRect(NSIntegralRect(r), NSMakeRect(0, 0, w, h));
        if (r.size.width >= 8 && r.size.height >= 8) [out addObject:[NSValue valueWithRect:r]];
    }
    gDTRFoundFilmType = n ? fr[0].film_type : -1;
    ESLog(@"DTR frame detection: %d frame(s), holder %d, film type %d, cropping area %d", (int)out.count,
          n ? fr[0].holder : -1, n ? fr[0].film_type : -1, marginID);
    return out.count ? out : nil;
}

/* Auto Locate on the flatbed (CDTR::DoAutoLocation): the original inside the preview */
static NSArray<NSValue *> *ESAutoLocateDTR(const uint16_t *raw, int w, int h, int dpi)
{
    NSString *engine = ESDTREngine();
    if (!engine || !raw) return nil;
    int W = 0, H = 0;
    NSMutableData *px = ESDTRPreview(raw, w, h, dpi, 150, &W, &H);
    if (!px) return nil;
    DtrImage im = ESDTRImage(px.bytes, W, H, 150, NO, NO, -1);
    int area[4] = { 0, 0, W - 1, H - 1 }, out[4] = { 0 };
    char err[256] = "";
    NSString *dir = engine.stringByDeletingLastPathComponent;
    int rc = dtr_autolocate(engine.fileSystemRepresentation, dir.fileSystemRepresentation, &im, area, out, err, sizeof err);
    if (rc) { ESLog(@"DTR Auto Locate: %s", rc < 0 ? err : "nothing found"); return nil; }
    double k = (double)dpi / 150.0;
    NSRect r = NSIntegralRect(NSMakeRect(out[0] * k, out[1] * k, (out[2] - out[0] + 1) * k, (out[3] - out[1] + 1) * k));
    r = NSIntersectionRect(r, NSMakeRect(0, 0, w, h));
    ESLog(@"DTR Auto Locate: %@", NSStringFromRect(r));
    return r.size.width >= 8 && r.size.height >= 8 ? @[ [NSValue valueWithRect:r] ] : nil;
}

static NSArray<NSValue *> *ESDetectDocumentsDTR(const uint16_t *raw, int w, int h, int dpi, NSArray<NSNumber *> **types);

/* One marquee's auto exposure + image adjustments (CFitIF's per-marquee data), with the
 * tone table and colour matrix made from them. */
@interface ESAdjust : NSObject <NSCopying>
@property (nonatomic, strong) NSMutableData *state;   /* FitState */
@property (nonatomic, strong) NSData *lut;            /* 3 x 256, gamma-1.8 domain */
@property (nonatomic, strong) NSData *coef;           /* 9 doubles, applied after the table */
@property (nonatomic) int profile;                    /* 0 flatbed, 1 positive, 2 negative */
@property (nonatomic, strong) NSData *autoPara;       /* FIT3_PARA right after auto exposure (Reset) */
@property (nonatomic, strong) NSData *baseLevels;     /* 12 ints: levels when a pipette was used (marquee +0x328) */
@property (nonatomic) int grayIntensity;              /* -1 = no gray balance (plug-in data +0x68) */
@property (nonatomic) int grayR, grayG, grayB;        /* gray point, 0..255 display values */
@property (nonatomic, copy) NSString *toneName;       /* Tone Correction entry (marquee +0xd4) */
@property (nonatomic) EsTarget target;                /* Target Size / Scale / Trimming of the marquee */
- (FitState *)st;
- (int)field:(int)off;
- (void)setField:(int)off value:(int)v;
- (BOOL)update;
@end

@implementation ESAdjust
- (id)copyWithZone:(NSZone *)z
{
    ESAdjust *a = [ESAdjust new];
    a.state = [self.state mutableCopy]; a.lut = self.lut; a.coef = self.coef; a.profile = self.profile;
    a.autoPara = self.autoPara; a.baseLevels = self.baseLevels; a.grayIntensity = self.grayIntensity;
    a.grayR = self.grayR; a.grayG = self.grayG; a.grayB = self.grayB;
    a.toneName = self.toneName;
    a.target = self.target;
    return a;
}
- (FitState *)st { return (FitState *)self.state.mutableBytes; }
- (int)field:(int)off { int v; memcpy(&v, [self st]->para + off, 4); return v; }
- (void)setField:(int)off value:(int)v { memcpy([self st]->para + off, &v, 4); }
/* CFitIF::MakeLUT + CScanBase::SaturationColorCoef(ColorMatrixConv(GetColorCorrection)) */
- (BOOL)update
{
    uint8_t lut[768];
    double coef[9];
    char err[256];
    const char *eng = ESFitEngine().fileSystemRepresentation;
    if (fit_state_lut(eng, [self st], lut, err, sizeof err)) { NSLog(@"FIT LUT: %s", err); return NO; }
    if (fit_state_matrix(eng, [self st], kProfileMatrix[self.profile], coef, err, sizeof err)) {
        NSLog(@"FIT matrix: %s", err);
        return NO;
    }
    self.lut = [NSData dataWithBytes:lut length:sizeof lut];
    self.coef = [NSData dataWithBytes:coef length:sizeof coef];
    return YES;
}
@end

/* Run FIT auto exposure on one area of a 16-bit linear RGB preview. */
static ESAdjust *ESFitAdjust(const uint16_t *raw, int w, int h, NSRect area, FitParams p, int profile)
{
    const uint8_t *g = ESGamma18();
    int rb = w * 4;
    uint8_t *px = calloc((size_t)rb * h, 1);
    if (!px) return nil;
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++) {
            const uint16_t *s = raw + ((size_t)y * w + x) * 3;
            uint8_t *d = px + (size_t)y * rb + (size_t)x * 4;
            d[1] = g[s[0]]; d[2] = g[s[1]]; d[3] = g[s[2]];
        }
    int x0 = MAX(0, (int)area.origin.x), y0 = MAX(0, (int)area.origin.y);
    int x1 = MIN(w, (int)NSMaxX(area)), y1 = MIN(h, (int)NSMaxY(area));
    char err[256];
    NSString *engine = ESFitEngine();
    ESAdjust *a = [ESAdjust new];
    a.state = [NSMutableData dataWithLength:sizeof(FitState)];
    a.profile = profile;
    int rc = engine ? fit_auto_state(engine.fileSystemRepresentation, px, w, h, rb, x0, y0, x1, y1, &p,
                                     a.state.mutableBytes, err, sizeof err) : -1;
    free(px);
    if (rc) { NSLog(@"FIT: %@", engine ? [NSString stringWithUTF8String:err] : @"engine missing"); return nil; }
    a.autoPara = [NSData dataWithBytes:a.state.bytes length:0x80];
    a.grayIntensity = -1;
    /* the curve auto exposure left: a preset if it is one, otherwise Epson's "Auto" entry */
    a.toneName = @"Auto";
    for (int i = 0; i < TC_PRESETS; i++) {
        uint8_t pc[4][TC_SIZE];
        tc_preset(i, pc);
        FitState *st = a.st;
        if (tc_equal(pc[0], st->tone_master) && tc_equal(pc[1], st->tone_rgb) &&
            tc_equal(pc[2], st->tone_rgb + TC_SIZE) && tc_equal(pc[3], st->tone_rgb + 2 * TC_SIZE)) {
            a.toneName = @(tc_preset_name(i));
            break;
        }
    }
    return [a update] ? a : nil;
}

/* Preview through FIT: each marquee with its own table and colour matrix, the rest with `fallback`. */
static NSImage *ESDisplayImageFIT(const uint16_t *raw, int w, int rows, NSArray<NSValue *> *areas,
                                  NSArray<ESAdjust *> *adjusts, ESAdjust *fallback)
{
    if (w <= 0 || rows <= 0 || fallback.lut.length != 768 || fallback.coef.length != 72) return nil;
    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:w pixelsHigh:rows
                                                                 bitsPerSample:8 samplesPerPixel:3 hasAlpha:NO
                                                                      isPlanar:NO colorSpaceName:NSDeviceRGBColorSpace
                                                                   bytesPerRow:w * 3 bitsPerPixel:24];
    const uint8_t *g = ESGamma18();
    uint8_t *dst = rep.bitmapData;
    NSUInteger n = MIN(areas.count, adjusts.count);
    NSRect *rects = calloc(n + 1, sizeof(NSRect));
    const uint8_t **luts = calloc(n + 1, sizeof *luts);
    const double **mats = calloc(n + 1, sizeof *mats);
    for (NSUInteger i = 0; i < n; i++) {
        rects[i] = areas[i].rectValue;
        luts[i] = adjusts[i].lut.length == 768 ? adjusts[i].lut.bytes : fallback.lut.bytes;
        mats[i] = adjusts[i].coef.length == 72 ? adjusts[i].coef.bytes : fallback.coef.bytes;
    }
    const uint8_t *L0 = fallback.lut.bytes;
    const double *M0 = fallback.coef.bytes;
    for (int y = 0; y < rows; y++)
        for (int x = 0; x < w; x++) {
            const uint8_t *L = L0;
            const double *M = M0;
            for (NSUInteger i = 0; i < n; i++)
                if (NSPointInRect(NSMakePoint(x + 0.5, y + 0.5), rects[i])) { L = luts[i]; M = mats[i]; break; }
            const uint16_t *s = raw + ((size_t)y * w + x) * 3;
            uint8_t *d = dst + ((size_t)y * w + x) * 3;
            double v[3] = { L[g[s[0]]], L[256 + g[s[1]]], L[512 + g[s[2]]] };
            for (int c = 0; c < 3; c++) {
                double r = M[c * 3] * v[0] + M[c * 3 + 1] * v[1] + M[c * 3 + 2] * v[2] + 0.5;
                d[c] = (uint8_t)(r < 0 ? 0 : r > 255 ? 255 : r);
            }
        }
    free(rects); free(luts); free(mats);
    NSImage *im = [[NSImage alloc] initWithSize:NSMakeSize(w, rows)];
    [im addRepresentation:rep];
    return im;
}

static NSString *const ESSelectionChanged = @"ESPreviewSelectionChanged";
/* a Mode list was changed (object: the mode's name) */
static NSString *const ESModeChangeRequest = @"ESModeChangeRequest";
/* Image Adjustment fields, in the dialog's order (CFitIF::SetFIT3_PARA, marquee +0x310..+0x324) */
static const int kAdjustFields[6] = { FIT_BRIGHTNESS, FIT_CONTRAST, FIT_SATURATION, FIT_BAL_CR, FIT_BAL_MG, FIT_BAL_YB };

/* Thumbnail preview (DITL 10302, CThumbnailWnd): each film frame as a thumbnail with a check
 * box and its number; checked frames are scanned. Small / Large thumbnails, or one frame full size. */
@interface ESThumbGrid : NSView
@property (nonatomic, strong) NSImage *image;               /* the adjusted preview */
@property (nonatomic, copy) NSArray<NSValue *> *frames;     /* in image pixels */
@property (nonatomic, copy) NSArray<NSNumber *> *turns, *mirror, *checked;
@property (nonatomic) NSInteger selected, fullIndex;
@property (nonatomic) int mode;                             /* 0 small, 1 large, 2 one frame */
@property (nonatomic, copy) void (^onSelect)(NSInteger i);
@property (nonatomic, copy) void (^onToggle)(NSInteger i);
@property (nonatomic, copy) void (^onOpen)(NSInteger i);
- (void)tile;
@end

@implementation ESThumbGrid
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstResponder { return YES; }
- (CGFloat)box { return self.mode == 0 ? 96 : 160; }
- (NSSize)visible
{
    NSScrollView *sv = self.enclosingScrollView;
    return sv ? sv.contentSize : self.bounds.size;
}
- (int)columns
{
    CGFloat b = [self box], g = 14;
    return MAX(1, (int)((self.visible.width - g) / (b + g)));
}
- (void)tile
{
    NSSize v = self.visible;
    CGFloat h = v.height;
    if (self.mode != 2) {
        int cols = [self columns], rows = ((int)self.frames.count + cols - 1) / cols;
        h = MAX(h, 14 + rows * ([self box] + 22 + 14));
    }
    if (fabs(self.frame.size.width - v.width) > 0.5 || fabs(self.frame.size.height - h) > 0.5)
        [self setFrameSize:NSMakeSize(v.width, h)];
    [self setNeedsDisplay:YES];
}
/* cell i: the image box and the check box under it */
- (NSRect)boxFor:(NSInteger)i check:(NSRect *)check
{
    if (self.mode == 2) {
        NSSize v = self.visible;
        NSRect r = NSMakeRect(14, 14, MAX(10, v.width - 28), MAX(10, v.height - 50));
        if (check) *check = NSMakeRect(14, NSMaxY(r) + 6, 120, 18);
        return r;
    }
    CGFloat b = [self box], g = 14;
    int cols = [self columns];
    CGFloat x = g + (i % cols) * (b + g), y = g + (i / cols) * (b + 22 + g);
    if (check) *check = NSMakeRect(x, y + b + 3, b, 18);
    return NSMakeRect(x, y, b, b);
}
- (void)drawFrame:(NSInteger)i inBox:(NSRect)box
{
    NSRect f = self.frames[(NSUInteger)i].rectValue;
    int q = i < (NSInteger)self.turns.count ? self.turns[(NSUInteger)i].intValue & 3 : 0;
    BOOL m = i < (NSInteger)self.mirror.count && self.mirror[(NSUInteger)i].boolValue;
    CGFloat fw = q & 1 ? f.size.height : f.size.width, fh = q & 1 ? f.size.width : f.size.height;
    if (fw <= 0 || fh <= 0 || !self.image) return;
    CGFloat k = MIN(box.size.width / fw, box.size.height / fh);
    CGFloat dw = fw * k, dh = fh * k;
    NSRect src = NSMakeRect(f.origin.x, self.image.size.height - NSMaxY(f), f.size.width, f.size.height);
    [NSGraphicsContext saveGraphicsState];
    NSAffineTransform *t = [NSAffineTransform transform];
    [t translateXBy:NSMidX(box) yBy:NSMidY(box)];
    [t rotateByDegrees:90 * q];               /* flipped view: clockwise */
    if (m) [t scaleXBy:-1 yBy:1];
    [t concat];
    CGFloat uw = q & 1 ? dh : dw, uh = q & 1 ? dw : dh;
    [self.image drawInRect:NSMakeRect(-uw / 2, -uh / 2, uw, uh) fromRect:src
                 operation:NSCompositingOperationSourceOver fraction:1 respectFlipped:YES hints:nil];
    [NSGraphicsContext restoreGraphicsState];
}
- (void)drawRect:(NSRect)dirty
{
    [NSColor.whiteColor setFill];
    NSRectFill(self.bounds);
    NSButtonCell *cb = [[NSButtonCell alloc] initTextCell:@""];
    [cb setButtonType:NSButtonTypeSwitch];
    cb.font = [NSFont systemFontOfSize:11];
    for (NSInteger i = 0; i < (NSInteger)self.frames.count; i++) {
        if (self.mode == 2 && i != self.fullIndex) continue;
        NSRect check, box = [self boxFor:i check:&check];
        if (!NSIntersectsRect(NSInsetRect(box, -6, -30), dirty)) continue;
        [[NSColor colorWithWhite:0.93 alpha:1] setFill];
        NSRectFill(box);
        [self drawFrame:i inBox:box];
        if (i == self.selected) {
            NSBezierPath *p = [NSBezierPath bezierPathWithRect:NSInsetRect(box, -2.5, -2.5)];
            p.lineWidth = 3;
            [NSColor.selectedContentBackgroundColor setStroke];
            [p stroke];
        }
        cb.title = [NSString stringWithFormat:@"%ld", (long)i + 1];
        cb.state = i < (NSInteger)self.checked.count && self.checked[(NSUInteger)i].boolValue
                 ? NSControlStateValueOn : NSControlStateValueOff;
        [cb drawWithFrame:check inView:self];
    }
}
- (void)mouseDown:(NSEvent *)e
{
    [self.window makeFirstResponder:self];
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    for (NSInteger i = 0; i < (NSInteger)self.frames.count; i++) {
        if (self.mode == 2 && i != self.fullIndex) continue;
        NSRect check, box = [self boxFor:i check:&check];
        if (NSPointInRect(p, NSMakeRect(check.origin.x, check.origin.y, 22 + 30, check.size.height))) {
            if (self.onToggle) self.onToggle(i);
            return;
        }
        if (NSPointInRect(p, box)) {
            if (self.onSelect) self.onSelect(i);
            if (e.clickCount == 2 && self.onOpen) self.onOpen(i);
            return;
        }
    }
}
- (void)keyDown:(NSEvent *)e
{
    unichar ch = e.charactersIgnoringModifiers.length ? [e.charactersIgnoringModifiers characterAtIndex:0] : 0;
    NSInteger n = (NSInteger)self.frames.count, i = self.selected;
    if (!n) { [super keyDown:e]; return; }
    if (ch == NSRightArrowFunctionKey) i = MIN(n - 1, i + 1);
    else if (ch == NSLeftArrowFunctionKey) i = MAX(0, i - 1);
    else if (ch == ' ' && i >= 0) { if (self.onToggle) self.onToggle(i); return; }
    else { [super keyDown:e]; return; }
    if (i != self.selected && self.onSelect) self.onSelect(i);
}
@end

/* Preview rotation: a rect in a W x H image after a quarter turn clockwise (the image is then H x W) */
static NSRect ESRotateRect(NSRect r, int W, int H)
{
    (void)W;
    return NSMakeRect(H - NSMaxY(r), r.origin.x, r.size.height, r.size.width);
}

/* a quarter turn clockwise of an interleaved 3-sample image with `size`-byte samples */
static NSMutableData *ESRotateBuffer(NSData *in, int w, int h, int size)
{
    size_t px = (size_t)3 * size;
    if (in.length < (size_t)w * h * px) return [NSMutableData data];
    NSMutableData *out = [NSMutableData dataWithLength:(size_t)w * h * px];
    const uint8_t *s = in.bytes;
    uint8_t *d = out.mutableBytes;
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)          /* (x, y) -> (h - 1 - y, x) in an h-wide image */
            memcpy(d + ((size_t)x * h + (h - 1 - y)) * px, s + ((size_t)y * w + x) * px, px);
    return out;
}

/* Auto Locate on the flatbed (CPreviewWnd auto-locate for reflective documents): the
 * originals are what isn't the white document mat. 1 mm cells that are mostly darker than
 * the mat, joined across small gaps, each group at least 0.4 in square is one marquee. */
static NSArray<NSValue *> *ESLocateReflective(const uint8_t *rgb, int w, int h, int dpi)
{
    int cell = MAX(2, dpi / 25), gw = (w + cell - 1) / cell, gh = (h + cell - 1) / cell;
    if (gw < 2 || gh < 2) return @[];
    uint8_t *g = calloc((size_t)gw * gh, 1), *seen = calloc((size_t)gw * gh, 1);
    int *stack = malloc(sizeof(int) * (size_t)gw * gh);
    /* the mat's level: the bright end of the histogram */
    long hist[256] = { 0 };
    for (int y = 0; y < h; y += 2)
        for (int x = 0; x < w; x += 2) {
            const uint8_t *p = rgb + ((size_t)y * w + x) * 3;
            hist[MIN(p[0], MIN(p[1], p[2]))]++;
        }
    long total = 0, acc = 0;
    for (int i = 0; i < 256; i++) total += hist[i];
    int mat = 255;
    for (int i = 255; i >= 0; i--) { acc += hist[i]; if (acc * 20 >= total) { mat = i; break; } }
    int level = mat * 80 / 100;                  /* linear data: ~90% on a gamma 1.8 screen */
    for (int gy = 0; gy < gh; gy++)
        for (int gx = 0; gx < gw; gx++) {
            int dark = 0, n = 0;
            for (int y = gy * cell; y < MIN(h, (gy + 1) * cell); y++)
                for (int x = gx * cell; x < MIN(w, (gx + 1) * cell); x++) {
                    const uint8_t *p = rgb + ((size_t)y * w + x) * 3;
                    dark += MIN(p[0], MIN(p[1], p[2])) < level;
                    n++;
                }
            g[gy * gw + gx] = n && dark * 10 >= n * 3;
        }
    NSMutableArray *out = [NSMutableArray array];
    const int gap = 2, minCells = (int)(dpi * 0.4 / cell);
    for (int i = 0; i < gw * gh; i++) {
        if (!g[i] || seen[i]) continue;
        int sp = 0, x0 = gw, y0 = gh, x1 = -1, y1 = -1;
        stack[sp++] = i; seen[i] = 1;
        while (sp) {
            int c = stack[--sp], cx = c % gw, cy = c / gw;
            x0 = MIN(x0, cx); x1 = MAX(x1, cx); y0 = MIN(y0, cy); y1 = MAX(y1, cy);
            for (int dy = -gap; dy <= gap; dy++)
                for (int dx = -gap; dx <= gap; dx++) {
                    int nx = cx + dx, ny = cy + dy;
                    if (nx < 0 || ny < 0 || nx >= gw || ny >= gh) continue;
                    int j = ny * gw + nx;
                    if (g[j] && !seen[j]) { seen[j] = 1; stack[sp++] = j; }
                }
        }
        if (x1 - x0 + 1 < minCells || y1 - y0 + 1 < minCells) continue;
        NSRect r = NSMakeRect(x0 * cell, y0 * cell, (x1 - x0 + 1) * cell, (y1 - y0 + 1) * cell);
        r = NSIntersectionRect(r, NSMakeRect(0, 0, w, h));
        [out addObject:[NSValue valueWithRect:r]];
    }
    free(g); free(seen); free(stack);
    /* Epson numbers them top to bottom, then left to right */
    [out sortUsingComparator:^NSComparisonResult(NSValue *a, NSValue *b) {
        NSRect ra = a.rectValue, rb = b.rectValue;
        if (fabs(ra.origin.y - rb.origin.y) > MIN(ra.size.height, rb.size.height) / 2)
            return ra.origin.y < rb.origin.y ? NSOrderedAscending : NSOrderedDescending;
        return ra.origin.x < rb.origin.x ? NSOrderedAscending : ra.origin.x > rb.origin.x ? NSOrderedDescending : NSOrderedSame;
    }];
    return out;
}

@interface ESPreviewWindow : NSObject <NSTabViewDelegate>
@property (nonatomic, strong) NSWindow *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic, strong) NSMutableData *pixels;       /* 8-bit RGB preview (linear, for frame finding) */
@property (nonatomic, strong) NSMutableData *raw16;        /* 16-bit linear RGB preview (for FIT) */
@property (nonatomic, strong) NSMutableData *carry;        /* partial pixel between data blocks */
@property (nonatomic, copy) NSArray<ESAdjust *> *adjusts; /* auto exposure + adjustments per marquee */
@property (nonatomic, strong) ESAdjust *areaAdjust;        /* the same for the whole area */
@property (nonatomic) int pw, ph, pdpi;
@property (nonatomic) BOOL negative, scanning, film, restoration;
@property (nonatomic) BOOL documentAE;                      /* Reflective: Auto Exposure Type Document */
@property (nonatomic) int bwThreshold;                      /* Black & White: 0..255, -1 = not B&W */
@property (nonatomic) int dropout;                          /* Dropout channel 0 R, 1 G, 2 B, -1 none */
@property (nonatomic) int backlight;
@property (nonatomic, copy) NSArray<NSValue *> *frames;
- (BOOL)selectedAreaForFilm:(BOOL)film x:(double *)x y:(double *)y w:(double *)w h:(double *)h;
- (NSArray<NSNumber *> *)skewForAreaX:(double)ax y:(double)ay w:(double)aw h:(double)ah;
- (ESAdjust *)selectedAdjust;
- (void)adjustmentsChanged;
- (BOOL)histogram:(EsHistogram *)hg output:(BOOL)output;
- (BOOL)sampleAt:(NSPoint)pt rgb:(int *)rgb;
- (void)pickWith:(void (^)(NSPoint imagePoint))handler;
- (void)rerunAutoExposureRestoration:(BOOL)restoration backlight:(int)backlight;
- (void)rerunAutoExposureDocument:(BOOL)document;
- (void)reapplyConfiguration;
- (void)showCurrent;
@property (nonatomic) int targetDPI, bytesPerPixel;
@property (nonatomic) int defaultTrimming;                 /* for new marquees */
@property (nonatomic) BOOL keepTarget;                     /* a marquee change made by the target itself */
@property (nonatomic) EsTarget pendingTarget;              /* ... and the target that goes with it */
- (BOOL)hasArea;
- (void)areaInches:(double *)w h:(double *)h;
- (EsTarget)currentTarget;
/* store the selected marquee's target; when `moved`, the marquee takes its new place and size */
- (void)setCurrentTarget:(EsTarget)t moved:(BOOL)moved;
- (int)activeMarquees;
/* preview toolbar state: quarter turns clockwise of the preview (and so of the scan), the
 * zoom preview's origin in the scan area (mm) and whether the Zoom tab is showing */
@property (nonatomic) int quarters;
@property (nonatomic) double originX, originY;
@property (nonatomic) BOOL zoomed;
@property (nonatomic, strong) NSDictionary *otherState;   /* the tab that isn't showing */
@property (nonatomic, strong) NSPanel *densiPanel;
- (BOOL)allMarqueesSelected;
- (void)selectMarquee:(NSInteger)i;
/* Thumbnail preview: per-frame Rotation, Mirroring and check box (parallel to the marquees) */
@property (nonatomic) BOOL thumbnailMode;
@property (nonatomic) int filmTFT;            /* TWEP_TFT for DTR: 0 colour negative, 1 B&W negative, 2 positive */
@property (nonatomic, strong) NSMutableArray<NSNumber *> *frameTurns, *frameMirror, *frameChecked;
@property (nonatomic) int thumbSize;
@property (nonatomic, strong) NSScrollView *gridScroll;
/* the marquees the next Scan goes through, in order (nil: just the selected one) */
- (NSArray<NSNumber *> *)marqueesToScan;
- (void)updateMode;
- (int)selectedQuarters;
- (BOOL)selectedMirrored;
- (void)rebuild;
- (void)startPreviewFilm:(BOOL)film negative:(BOOL)neg targetDPI:(int)dpi bytesPerPixel:(int)bpp;
/* Home / Office / Full Auto: told when a preview has finished (YES) or failed */
@property (nonatomic, copy) void (^onPreviewDone)(BOOL ok);
- (void)autoLocate;
- (void)placeMarqueeMM:(NSSize)size;
- (void)selectAllMarquees;
- (void)adoptFrames:(NSArray<NSValue *> *)frames;
- (void)autoOrientFrames;
- (void)refreshGrid;
- (void)checkAllFrames;
@end

@implementation ESPreviewWindow

- (NSDictionary *)layout
{
    NSString *path = [[NSBundle mainBundle] pathForResource:@"preview" ofType:@"json"];
    NSData *d = [NSData dataWithContentsOfFile:path];
    return d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : @{};
}

- (instancetype)init
{
    if ((self = [super init])) {
        _bwThreshold = -1;
        _dropout = -1;
        NSDictionary *w = [self layout][@"window"];
        self.window = [[NSWindow alloc] initWithContentRect:NSMakeRect(0, 0, [w[@"width"] doubleValue],
                                                                       [w[@"height"] doubleValue])
                                                  styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                            NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable
                                                    backing:NSBackingStoreBuffered defer:NO];
        self.window.title = w[@"title"];
        self.window.releasedWhenClosed = NO;
        self.window.contentMinSize = NSMakeSize([w[@"width"] doubleValue], [w[@"height"] doubleValue]);
        [self rebuild];
    }
    return self;
}

- (void)rebuild
{
    NSDictionary *L = [self layout];
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    self.builder = [ESBuilder new];
    self.builder.native = native;
    NSDictionary *w = L[@"window"];
    /* build at the original size; the window then resizes it and the masks place everything */
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, [w[@"width"] doubleValue],
                                                                          [w[@"height"] doubleValue])];
    root.wantsLayer = YES;
    root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor
                                        : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    [self.builder build:L[@"items"] into:root];
    root.autoresizesSubviews = YES;
    self.window.contentView = root;
    ESPreviewCanvas *c = [self canvas];
    __weak ESPreviewWindow *weakSelf = self;
    c.onSelect = ^(NSInteger i) {
        [weakSelf updateStatus];
        [weakSelf updateToolbar];
        [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:weakSelf];
    };
    c.onEdit = ^(NSInteger i, BOOL deleted) { [weakSelf marqueeEdited:i deleted:deleted]; };
    self.builder.onAction = ^(NSString *a) { [weakSelf perform:a]; };
    /* the V550 has no focus mechanism: Epson hides Auto/Manual Focus and the position */
    for (NSString *key in @[ @"pvAF", @"pvMF", @"pvFocusText" ]) [self.builder.controls[key] setHidden:YES];
    NSTabView *tv = (NSTabView *)self.builder.controls[@"pvTabs"];
    if ([tv isKindOfClass:[NSTabView class]]) tv.delegate = self;
    /* the thumbnail grid takes the preview area's place in Thumbnail mode */
    NSScrollView *sv = [[NSScrollView alloc] initWithFrame:c.frame];
    sv.autoresizingMask = c.autoresizingMask;
    sv.hasVerticalScroller = YES;
    sv.borderType = NSBezelBorder;
    ESThumbGrid *g = [[ESThumbGrid alloc] initWithFrame:NSMakeRect(0, 0, c.frame.size.width, c.frame.size.height)];
    g.autoresizingMask = NSViewWidthSizable;
    sv.documentView = g;
    [c.superview addSubview:sv positioned:NSWindowAbove relativeTo:c];
    self.gridScroll = sv;
    g.onSelect = ^(NSInteger i) {
        ESThumbGrid *gr = (ESThumbGrid *)weakSelf.gridScroll.documentView;
        if (gr.mode == 2) gr.fullIndex = i;
        [weakSelf selectMarquee:i];
    };
    g.onToggle = ^(NSInteger i) { [weakSelf toggleFrame:i]; };
    g.onOpen = ^(NSInteger i) { [weakSelf showFrameFull:i]; };
    [NSNotificationCenter.defaultCenter addObserverForName:NSViewFrameDidChangeNotification object:sv.contentView
                                                     queue:nil usingBlock:^(NSNotification *n) {
        [(ESThumbGrid *)weakSelf.gridScroll.documentView tile];
    }];
    sv.contentView.postsFrameChangedNotifications = YES;
    [self updateMode];
    [self updateToolbar];
    c.aspectFor = ^double(NSInteger i) {
        ESPreviewWindow *me = weakSelf;
        if (!me || i < 0 || i >= (NSInteger)me.adjusts.count) return 0;
        EsTarget t = me.adjusts[(NSUInteger)i].target;
        return t.active && t.sw > 0 ? t.sh / t.sw : 0;
    };
    [self showCurrent];
}

- (ESPreviewCanvas *)canvas
{
    for (NSView *v in self.window.contentView.subviews)
        if ([v isKindOfClass:[ESPreviewCanvas class]]) return (ESPreviewCanvas *)v;
    return nil;
}

- (void)showCurrent
{
    ESPreviewCanvas *c = [self canvas];
    if (!self.pixels.length || !self.pw) return;
    int rows = (int)(self.pixels.length / ((size_t)self.pw * 3));
    int lo[3] = { 0, 0, 0 }, hi[3] = { 255, 255, 255 };
    int mgr = ESColorMgr();
    if (!self.scanning && (self.bwThreshold >= 0 || self.dropout >= 0)) {
        /* Dropout / Black & White (CAdvancedDialog::UpdatePreview, ESCalcThreshold): one channel
         * (or the gray), at the screen gamma, then the threshold */
        double g = ESScreenGamma10() / 10.0;
        uint8_t lut[256];
        for (int v = 0; v < 256; v++) {
            double t = v / 255.0; if (self.negative) t = 1 - t;
            lut[v] = (uint8_t)lround(255 * pow(t, 1 / g));
        }
        int ch = self.dropout >= 0 ? self.dropout : -1;
        NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:self.pw pixelsHigh:rows
                                   bitsPerSample:8 samplesPerPixel:3 hasAlpha:NO isPlanar:NO
                                  colorSpaceName:NSDeviceRGBColorSpace bytesPerRow:self.pw * 3 bitsPerPixel:24];
        const uint8_t *src = self.pixels.bytes;
        uint8_t *dst = rep.bitmapData;
        for (size_t i = 0, n = (size_t)self.pw * rows; i < n; i++) {
            int v = ch >= 0 ? lut[src[i * 3 + ch]]
                            : lut[(src[i * 3] * 299 + src[i * 3 + 1] * 587 + src[i * 3 + 2] * 114) / 1000];
            if (self.bwThreshold >= 0) v = v >= self.bwThreshold ? 255 : 0;
            dst[i * 3] = dst[i * 3 + 1] = dst[i * 3 + 2] = (uint8_t)v;
        }
        NSImage *im = [[NSImage alloc] initWithSize:NSMakeSize(self.pw, rows)];
        [im addRepresentation:rep];
        c.image = im;
        c.frames = self.frames;
        [c setNeedsDisplay:YES];
        return;
    }
    if (!self.scanning && self.areaAdjust && self.raw16.length >= (size_t)self.pw * rows * 6)
        c.image = ESDisplayImageFIT(self.raw16.bytes, self.pw, rows, self.frames, self.adjusts, self.areaAdjust);
    else if (mgr == 2)          /* No Color Correction: the scanner's data at gamma 1.8, no levels */
        c.image = ESDisplayImage(self.pixels.bytes, self.pw, rows, self.negative, lo, hi, 1.8);
    else {
        if (!self.scanning) ESLevels(self.pixels.bytes, self.pw, rows, self.frames, lo, hi);
        c.image = ESDisplayImage(self.pixels.bytes, self.pw, rows, self.negative, lo, hi, 2.2);
    }
    /* ColorSync with "Display preview using monitor compensation": the preview is the scanner's
     * colour (EPSON Standard profile), matched to the display */
    if (mgr == 1 && [NSUserDefaults.standardUserDefaults boolForKey:@"CfgUseMonitor"] && c.image) {
        NSString *icc = [[NSBundle mainBundle] pathForResource:self.film ? @"PERV550F" : @"PERV550R" ofType:@"ICC"];
        NSData *d = icc ? [NSData dataWithContentsOfFile:icc] : nil;
        NSColorSpace *cs = d ? [[NSColorSpace alloc] initWithICCProfileData:d] : nil;
        NSBitmapImageRep *rep = (NSBitmapImageRep *)c.image.representations.firstObject;
        if (cs && [rep isKindOfClass:[NSBitmapImageRep class]]) {
            NSBitmapImageRep *tagged = [rep bitmapImageRepByRetaggingWithColorSpace:cs];
            if (tagged) {
                NSImage *im = [[NSImage alloc] initWithSize:c.image.size];
                [im addRepresentation:tagged];
                c.image = im;
            }
        }
    }
    c.frames = self.scanning ? @[] : self.frames;
    [c setNeedsDisplay:YES];
    [self refreshGrid];
}

- (void)updateStatus
{
    ESPreviewCanvas *c = [self canvas];
    NSRect f = NSZeroRect;
    if (c.frames.count && c.selected >= 0 && c.selected < (NSInteger)c.frames.count) f = c.frames[c.selected].rectValue;
    else if (self.pw) f = NSMakeRect(0, 0, self.pw, self.ph);
    if (!self.pdpi || f.size.width <= 0) return;
    double win = f.size.width / self.pdpi, hin = f.size.height / self.pdpi;
    EsTarget t = [self currentTarget];
    if (t.sw > 0) est_target_inches(&t, self.targetDPI ?: 300, &win, &hin);
    long px = (long)(win * self.targetDPI), py = (long)(hin * self.targetDPI);
    double mb = (double)px * py * self.bytesPerPixel / (1024.0 * 1024.0);
    NSDictionary *k = self.builder.controls;
    ESSetText(k[@"statusW"], [NSString stringWithFormat:@"%.2f in", win]);
    ESSetText(k[@"statusH"], [NSString stringWithFormat:@"%.2f in", hin]);
    ESSetText(k[@"statusSize"], [NSString stringWithFormat:@"%ld x %ld pixels  %.1f MB", px, py, mb]);
    [self updateToolbar];
}

/* The selected marquee in millimetres from the scan-area origin. NO if there's no
 * finished preview for this document source (then the whole area is scanned). */
- (BOOL)selectedAreaForFilm:(BOOL)film x:(double *)x y:(double *)y w:(double *)w h:(double *)h
{
    if (self.scanning || !self.pdpi || !self.pw || self.film != film) return NO;
    ESPreviewCanvas *c = [self canvas];
    NSRect f;
    if (c.frames.count && c.selected >= 0 && c.selected < (NSInteger)c.frames.count) f = c.frames[c.selected].rectValue;
    else if (film && !self.zoomed) return NO;
    else f = NSMakeRect(0, 0, self.pw, self.ph);
    /* undo the preview rotation: the scanner reads in its own orientation */
    int W = self.pw, H = self.ph;
    for (int q = self.quarters & 3; q && q < 4; q++) {
        f = ESRotateRect(f, W, H);
        int t = W; W = H; H = t;
    }
    double k = 25.4 / self.pdpi;
    *x = f.origin.x * k + self.originX; *y = f.origin.y * k + self.originY;
    *w = f.size.width * k; *h = f.size.height * k;
    return YES;
}

/* Correct Document Skew (Configuration): DTR finds the document in the preview with its skew
 * (TWEP_LOCATIONDATA + angle, as CDTR::DoDetectImage gets it) and Scan Control straightens the
 * scan with it (CScanner::IPInitSkew -> IPC_SKInit). Returns theta and the eight location words
 * in inches, top / left relative to the scan area, or nil when the document isn't skewed. */
- (NSArray<NSNumber *> *)skewForAreaX:(double)ax y:(double)ay w:(double)aw h:(double)ah
{
    if (self.film || !self.raw16 || !self.pdpi || (self.quarters & 3)) return nil;
    NSString *engine = ESDTREngine();
    if (!engine) return nil;
    int W = 0, H = 0;
    NSMutableData *px = ESDTRPreview(self.raw16.bytes, self.pw, self.ph, self.pdpi, 150, &W, &H);
    if (!px) return nil;
    DtrImage im = ESDTRImage(px.bytes, W, H, 150, NO, NO, -1);
    DtrFrame fr[16];
    int n = 0;
    char err[256] = "";
    NSString *dir = engine.stringByDeletingLastPathComponent;
    if (dtr_detect(engine.fileSystemRepresentation, dir.fileSystemRepresentation, &im, fr, 16, &n, err, sizeof err)) {
        ESLog(@"Correct Document Skew: %s", err);
        return nil;
    }
    /* the document under the scan area (inches on the glass) */
    NSRect area = NSMakeRect(ax / 25.4, ay / 25.4, aw / 25.4, ah / 25.4);
    double ox = self.originX / 25.4, oy = self.originY / 25.4, best = 0;
    int pick = -1;
    for (int i = 0; i < n; i++) {
        NSRect r = NSMakeRect(fr[i].pt[1] / 150.0 + ox, fr[i].pt[0] / 150.0 + oy, fr[i].pt[2] / 150.0, fr[i].pt[3] / 150.0);
        NSRect x = NSIntersectionRect(r, area);
        double a = x.size.width * x.size.height;
        if (a > best) { best = a; pick = i; }
    }
    if (pick < 0) { ESLog(@"Correct Document Skew: no document found under the scan area"); return nil; }
    DtrFrame *f = &fr[pick];
    ESLog(@"Correct Document Skew: angle %.2f degrees, location %d %d %d %d %d %d %d %d (150 dpi)", f->angle * 180 / M_PI,
          f->pt[0], f->pt[1], f->pt[2], f->pt[3], f->pt[4], f->pt[5], f->pt[6], f->pt[7]);
    if (fabs(f->angle) < 0.0005) return nil;
    NSMutableArray *out = [NSMutableArray arrayWithObject:@(f->angle)];
    [out addObject:@(f->pt[0] / 150.0 + oy - area.origin.y)];
    [out addObject:@(f->pt[1] / 150.0 + ox - area.origin.x)];
    for (int k = 2; k < 8; k++) [out addObject:@(f->pt[k] / 150.0)];
    return out;
}

/* a marquee was drawn, moved, resized or deleted: Epson re-runs auto exposure for it
 * (the image-adjustment settings the user made for it are kept) */
- (void)marqueeEdited:(NSInteger)i deleted:(BOOL)deleted
{
    ESPreviewCanvas *c = [self canvas];
    NSMutableArray<ESAdjust *> *adj = [self.adjusts mutableCopy] ?: [NSMutableArray array];
    self.frames = c.frames;
    if (deleted) {
        if (i < (NSInteger)adj.count) [adj removeObjectAtIndex:(NSUInteger)i];
        for (NSMutableArray *a in @[ self.frameTurns ?: @[].mutableCopy, self.frameMirror ?: @[].mutableCopy,
                                     self.frameChecked ?: @[].mutableCopy ])
            if (i < (NSInteger)a.count) [a removeObjectAtIndex:(NSUInteger)i];
    } else if (self.raw16.length >= (size_t)self.pw * self.ph * 6) {
        /* Configuration > Continuous auto exposure (ESPR +0x1a, on): each marquee gets its own
         * auto exposure; off, a marquee keeps (or a new one takes) the settings it had */
        NSUserDefaults *cfg = NSUserDefaults.standardUserDefaults;
        BOOL continuous = [cfg objectForKey:@"CfgAutoExpose"] ? [cfg boolForKey:@"CfgAutoExpose"] : YES;
        ESAdjust *old = i < (NSInteger)adj.count ? adj[(NSUInteger)i] : nil;
        ESAdjust *a = nil;
        if (continuous || (!old && !self.areaAdjust)) {
            FitParams p = ESFitParams(self.film, self.negative, self.restoration, self.backlight, self.documentAE);
            a = ESFitAdjust(self.raw16.bytes, self.pw, self.ph, self.frames[(NSUInteger)i].rectValue, p,
                            [self profileIndex]);
        } else {
            ESAdjust *from = old ?: (c.selected >= 0 && c.selected < (NSInteger)adj.count && c.selected != i
                                     ? adj[(NSUInteger)c.selected] : self.areaAdjust);
            a = [from copy];                   /* carries the adjustments and the target */
        }
        if (a && old && continuous) {
            for (int k = 0; k < 6; k++) [a setField:kAdjustFields[k] value:[old field:kAdjustFields[k]]];
            [a update];
        }
        /* the marquee's Target Size goes with it: a fixed target changes the scale, else the
         * target follows the marquee (CMarqCtl::ChangeTargetSize); a new marquee starts at Original */
        if (a) {
            NSRect fr = self.frames[(NSUInteger)i].rectValue;
            double k = self.pdpi ? 1.0 / self.pdpi : 0;
            EsTarget t = old ? old.target : (EsTarget){ .trimming = self.defaultTrimming };
            if (self.keepTarget) t = self.pendingTarget;
            if (old && t.sw > 0 && !self.keepTarget)
                est_marquee_changed(&t, fr.size.width * k, fr.size.height * k, fr.origin.x * k, fr.origin.y * k,
                                    self.targetDPI ?: 300);
            else if (!self.keepTarget && (!old || t.sw <= 0))
                est_init(&t, fr.size.width * k, fr.size.height * k, fr.origin.x * k, fr.origin.y * k);
            else { t.sw = fr.size.width * k; t.sh = fr.size.height * k; t.ox = fr.origin.x * k; t.oy = fr.origin.y * k; }
            a.target = t;
        }
        while ((NSInteger)adj.count <= i) [adj addObject:a ?: [self.areaAdjust copy] ?: [ESAdjust new]];
        if (a) adj[(NSUInteger)i] = a;
    }
    self.adjusts = adj;
    [self showCurrent];
    [self updateStatus];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

- (int)profileIndex { return self.film ? (self.negative ? 2 : 1) : 0; }

- (BOOL)hasArea { return self.pdpi > 0 && self.pw > 0 && !self.scanning; }

- (void)areaInches:(double *)w h:(double *)h
{
    *w = self.pdpi ? (double)self.pw / self.pdpi : 0;
    *h = self.pdpi ? (double)self.ph / self.pdpi : 0;
}

- (int)activeMarquees { return (int)[self canvas].frames.count; }

/* the selected marquee's target (or the whole area's when there's no marquee) */
- (EsTarget)currentTarget
{
    ESAdjust *a = [self selectedAdjust];
    EsTarget t = a ? a.target : (EsTarget){ 0 };
    if (t.sw <= 0 && self.pdpi) {
        NSRect f = [self selectedArea];
        double k = 1.0 / self.pdpi;
        t.trimming = self.defaultTrimming;
        est_init(&t, f.size.width * k, f.size.height * k, f.origin.x * k, f.origin.y * k);
        a.target = t;
    }
    return t;
}

- (void)setCurrentTarget:(EsTarget)t moved:(BOOL)moved
{
    ESAdjust *a = [self selectedAdjust];
    if (!a) return;
    a.target = t;
    ESPreviewCanvas *c = [self canvas];
    if (moved && self.pdpi && !c.frames.count) {
        /* no marquee yet: the trimmed area becomes one (CNormalPreview::ChangeMarqueeInfo) */
        c.frames = @[ [NSValue valueWithRect:NSMakeRect(0, 0, self.pw, self.ph)] ];
        c.selected = 0;
    }
    if (moved && self.pdpi && c.selected >= 0 && c.selected < (NSInteger)c.frames.count) {
        NSMutableArray *fr = [c.frames mutableCopy];
        NSRect r = NSMakeRect(t.ox * self.pdpi, t.oy * self.pdpi, t.sw * self.pdpi, t.sh * self.pdpi);
        fr[(NSUInteger)c.selected] = [NSValue valueWithRect:NSIntersectionRect(r, NSMakeRect(0, 0, self.pw, self.ph))];
        c.frames = fr;
        [c setNeedsDisplay:YES];
        /* Epson re-runs auto exposure for the new marquee (DoAutoExpose after ChangeMarqueeInfo) */
        self.keepTarget = YES;
        self.pendingTarget = t;
        [self marqueeEdited:c.selected deleted:NO];
        self.keepTarget = NO;
        return;
    }
    [self updateStatus];
}

/* settings that feed auto exposure changed (Backlight Correction, Color Restoration) */
- (void)rerunAutoExposureRestoration:(BOOL)restoration backlight:(int)backlight
{
    if (self.scanning || !self.pw) return;
    self.restoration = restoration;
    self.backlight = backlight;
    [self runAutoExposure];
    [self showCurrent];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

/* Configuration: display gamma or Auto Exposure Level changed */
- (void)reapplyConfiguration
{
    if (self.scanning || !self.pw) return;
    [self runAutoExposure];
    [self showCurrent];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

/* Auto Exposure Type changed (Reflective) */
- (void)rerunAutoExposureDocument:(BOOL)document
{
    if (self.documentAE == document) return;
    self.documentAE = document;
    if (self.scanning || !self.pw || self.film) return;
    [self runAutoExposure];
    [self showCurrent];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

- (ESAdjust *)selectedAdjust
{
    if (self.scanning) return nil;
    ESPreviewCanvas *c = [self canvas];
    if (c.selected >= 0 && c.selected < (NSInteger)self.adjusts.count) return self.adjusts[c.selected];
    return self.areaAdjust;
}

- (NSRect)selectedArea
{
    ESPreviewCanvas *c = [self canvas];
    NSRect f = NSMakeRect(0, 0, self.pw, self.ph);
    if (c.frames.count && c.selected >= 0 && c.selected < (NSInteger)c.frames.count) f = c.frames[c.selected].rectValue;
    return NSIntersectionRect(f, NSMakeRect(0, 0, self.pw, self.ph));
}

/* CHistogramTable::CreateHistogramTableFromImageData for the selected marquee: the input is
 * the gamma-1.8 image FIT sees; "Show Output" uses the displayed (corrected) image. */
- (BOOL)histogram:(EsHistogram *)hg output:(BOOL)output
{
    memset(hg, 0, sizeof *hg);
    ESAdjust *A = [self selectedAdjust];
    if (!A || self.raw16.length < (size_t)self.pw * self.ph * 6) return NO;
    NSRect f = [self selectedArea];
    int x0 = (int)NSMinX(f), y0 = (int)NSMinY(f), w = (int)f.size.width, h = (int)f.size.height;
    if (w <= 0 || h <= 0) return NO;
    uint8_t *px = malloc((size_t)w * h * 4);
    if (!px) return NO;
    const uint8_t *g = ESGamma18(), *L = A.lut.bytes;
    const double *M = A.coef.bytes;
    const uint16_t *raw = self.raw16.bytes;
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++) {
            const uint16_t *s = raw + ((size_t)(y0 + y) * self.pw + x0 + x) * 3;
            uint8_t *d = px + ((size_t)y * w + x) * 4;
            if (!output) { d[1] = g[s[0]]; d[2] = g[s[1]]; d[3] = g[s[2]]; continue; }
            double v[3] = { L[g[s[0]]], L[256 + g[s[1]]], L[512 + g[s[2]]] };
            for (int c = 0; c < 3; c++) {
                double r = M[c * 3] * v[0] + M[c * 3 + 1] * v[1] + M[c * 3 + 2] * v[2] + 0.5;
                d[1 + c] = (uint8_t)(r < 0 ? 0 : r > 255 ? 255 : r);
            }
        }
    int sg = ESScreenGamma10();
    lv_histogram(hg, px, w * 4, 0, 0, w, h, sg, self.negative, !output);
    free(px);
    return YES;
}

/* the pipette's sample: average of the gamma-1.8 preview over the sampling area, as 16-bit */
- (BOOL)sampleAt:(NSPoint)pt rgb:(int *)rgb
{
    if (self.raw16.length < (size_t)self.pw * self.ph * 6) return NO;
    int cx = (int)pt.x, cy = (int)pt.y, n = 0, sum[3] = { 0, 0, 0 };
    const uint8_t *g = ESGamma18();
    const uint16_t *raw = self.raw16.bytes;
    /* Configuration > Eyedropper Sampling Area: 1 x 1, 3 x 3 or 5 x 5 */
    NSInteger ra = [NSUserDefaults.standardUserDefaults integerForKey:@"CfgSamplingArea"];
    int rr = (int)MAX(0, MIN(2, ra));
    for (int y = cy - rr; y <= cy + rr; y++)
        for (int x = cx - rr; x <= cx + rr; x++) {
            if (x < 0 || y < 0 || x >= self.pw || y >= self.ph) continue;
            const uint16_t *s = raw + ((size_t)y * self.pw + x) * 3;
            for (int c = 0; c < 3; c++) sum[c] += g[s[c]];
            n++;
        }
    if (!n) return NO;
    for (int c = 0; c < 3; c++) rgb[c] = (sum[c] + n / 2) / n * 0x101;
    return YES;
}

- (void)pickWith:(void (^)(NSPoint imagePoint))handler
{
    ESPreviewCanvas *c = [self canvas];
    c.onPick = handler;
    [self.window makeKeyAndOrderFront:nil];
    [self.window invalidateCursorRectsForView:c];
}

/* an image-adjustment dialog changed the selected marquee's settings */
- (void)adjustmentsChanged
{
    ESAdjust *sel = [self selectedAdjust];
    if ([self allMarqueesSelected])      /* All: the same settings for every marquee */
        for (ESAdjust *a in self.adjusts) {
            if (a == sel) continue;
            for (int k = 0; k < 6; k++) [a setField:kAdjustFields[k] value:[sel field:kAdjustFields[k]]];
            [a update];
        }
    [sel update];
    [self showCurrent];
}

/* Epson Scan runs auto exposure per marquee after the preview */
- (void)runAutoExposure
{
    if (self.raw16.length < (size_t)self.pw * self.ph * 6 || !self.pw || !self.ph) {
        self.adjusts = @[]; self.areaAdjust = nil; return;
    }
    if (ESColorMgr() == 2) {     /* No Color Correction: no auto exposure, no adjustments */
        self.adjusts = @[]; self.areaAdjust = nil; return;
    }
    FitParams p = ESFitParams(self.film, self.negative, self.restoration, self.backlight, self.documentAE);
    NSMutableArray *adj = [NSMutableArray array];
    for (NSValue *v in self.frames) {
        ESAdjust *a = ESFitAdjust(self.raw16.bytes, self.pw, self.ph, v.rectValue, p, [self profileIndex]);
        if (!a) { adj = nil; break; }
        [adj addObject:a];
    }
    self.adjusts = adj ?: @[];
    NSRect all = self.frames.count ? self.frames[0].rectValue : NSMakeRect(0, 0, self.pw, self.ph);
    for (NSValue *v in self.frames) all = NSUnionRect(all, v.rectValue);
    self.areaAdjust = ESFitAdjust(self.raw16.bytes, self.pw, self.ph, all, p, [self profileIndex]);
}

static int preview_data(const uint8_t *data, uint32_t len, void *ctx)
{
    ESPreviewWindow *self = (__bridge ESPreviewWindow *)ctx;
    @synchronized (self) {
        if (!self.pw) { int w, h; es_current_size(&w, &h); self.pw = w; self.ph = h; }
        [self.carry appendBytes:data length:len];
        size_t whole = self.carry.length / 6 * 6;
        if (whole) {
            const uint16_t *s = self.carry.bytes;
            size_t n = whole / 2;
            [self.raw16 appendBytes:s length:whole];
            uint8_t *b = malloc(n);
            for (size_t i = 0; i < n; i++) b[i] = (uint8_t)(s[i] >> 8);
            [self.pixels appendBytes:b length:n];
            free(b);
            [self.carry replaceBytesInRange:NSMakeRange(0, whole) withBytes:NULL length:0];
        }
    }
    dispatch_async(dispatch_get_main_queue(), ^{ @synchronized (self) { [self showCurrent]; } });
    return 0;
}

#pragma mark Preview toolbar (CPreviewWnd)

- (void)perform:(NSString *)a
{
    ESPreviewCanvas *c = [self canvas];
    if ([a isEqualToString:@"pvDelete"]) [c deleteSelected];
    else if ([a isEqualToString:@"pvCopy"]) [self copyMarquee];
    else if ([a isEqualToString:@"pvAll"]) {
        if (!c.frames.count) return;
        c.allSelected = YES;
        [c setNeedsDisplay:YES];
        [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
    }
    else if ([a isEqualToString:@"pvLocate"]) [self autoLocate];
    else if ([a isEqualToString:@"pvRotL"]) [self rotateBy:-1];
    else if ([a isEqualToString:@"pvRotR"]) [self rotateBy:1];
    else if ([a isEqualToString:@"pvZoom"]) [self zoomClicked];
    else if ([a isEqualToString:@"pvTab"]) [self tabPicked:[self shownTab]];
    else if ([a isEqualToString:@"pvDensi"]) [self toggleDensitometer];
    else if ([a hasPrefix:@"tb"]) [self thumbnailAction:a];
    [self updateToolbar];
}

- (void)updateToolbar
{
    NSDictionary *k = self.builder.controls;
    ESPreviewCanvas *c = [self canvas];
    BOOL have = self.pw > 0 && self.ph > 0 && !self.scanning && self.pdpi > 0;
    BOOL sel = have && c.selected >= 0 && c.selected < (NSInteger)c.frames.count;
    ESSetEnabled(k[@"pvCopy"], sel);
    ESSetEnabled(k[@"pvDelete"], sel);
    ESSetEnabled(k[@"pvAll"], have && c.frames.count > 0);
    ESSetEnabled(k[@"pvLocate"], have);
    ESSetEnabled(k[@"pvRotL"], have);
    ESSetEnabled(k[@"pvRotR"], have);
    ESSetEnabled(k[@"pvDensi"], have);
    ESSetEnabled(k[@"pvZoom"], have && (self.zoomed || sel));
    ESSetEnabled(k[@"tbRotate"], sel);
    ESSetEnabled(k[@"tbMirror"], sel);
    ESSetEnabled(k[@"tbDelete"], NO);        /* no marquee inside a thumbnail to delete */
    ESSetEnabled(k[@"tbAll"], have && c.frames.count > 0);
    ESSetText(k[@"statusZoom"], [NSString stringWithFormat:@"%d%%", [self zoomPercent]]);
}

/* the preview's scale on screen, as Epson shows it in the status bar */
- (int)zoomPercent
{
    ESPreviewCanvas *c = [self canvas];
    NSRect r = [c imageRect];
    if (!self.pw || r.size.width <= 0) return 100;
    return (int)lround(r.size.width / self.pw * 100.0 * self.pdpi / 72.0);
}

- (BOOL)allMarqueesSelected
{
    ESPreviewCanvas *c = [self canvas];
    return c.allSelected && c.frames.count > 1;
}

- (void)selectMarquee:(NSInteger)i
{
    ESPreviewCanvas *c = [self canvas];
    if (i < 0 || i >= (NSInteger)c.frames.count) return;
    c.selected = i;
    [c setNeedsDisplay:YES];
    [self updateStatus];
    [self refreshGrid];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

/* Copy Marquee: a duplicate of the selected marquee, its settings included, a little below and
 * to the right (kept inside the preview) */
- (void)copyMarquee
{
    ESPreviewCanvas *c = [self canvas];
    NSInteger i = c.selected;
    if (self.scanning || i < 0 || i >= (NSInteger)c.frames.count) { NSBeep(); return; }
    NSRect r = c.frames[(NSUInteger)i].rectValue;
    double d = MAX(4, self.pdpi / 10);
    r.origin.x = MIN(r.origin.x + d, MAX(0, self.pw - r.size.width));
    r.origin.y = MIN(r.origin.y + d, MAX(0, self.ph - r.size.height));
    NSMutableArray *fr = [c.frames mutableCopy];
    [fr addObject:[NSValue valueWithRect:r]];
    NSMutableArray<ESAdjust *> *adj = [self.adjusts mutableCopy] ?: [NSMutableArray array];
    if (i < (NSInteger)adj.count && adj.count == fr.count - 1) {
        ESAdjust *a = [adj[(NSUInteger)i] copy];
        EsTarget t = a.target;
        if (self.pdpi) { t.ox = r.origin.x / self.pdpi; t.oy = r.origin.y / self.pdpi; }
        a.target = t;
        [adj addObject:a];
    }
    self.frames = fr;
    self.adjusts = adj;
    c.allSelected = NO;
    c.selected = (NSInteger)fr.count - 1;
    [self showCurrent];
    [self updateStatus];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

/* Auto Locate: the film frames (or the originals on the flatbed) become the marquees, each with
 * its own auto exposure */
- (void)autoLocate
{
    if (self.scanning || !self.pw || !self.ph) { NSBeep(); return; }
    /* Epson's DTR first (DTR_DetectImageInfo for film, DTR_AutoLocate on the flatbed) */
    NSArray *fr = self.film ? ESDetectFramesDTR(self.raw16.bytes, self.pw, self.ph, self.pdpi, self.negative, self.filmTFT, 0)
                            : ESAutoLocateDTR(self.raw16.bytes, self.pw, self.ph, self.pdpi);
    if (!fr.count)
        fr = self.film ? ESDetectFrames(self.pixels.bytes, self.pw, self.ph, self.pdpi, self.negative)
                       : ESLocateReflective(self.pixels.bytes, self.pw, self.ph, self.pdpi);
    if (!fr.count) { NSBeep(); return; }
    ESPreviewCanvas *c = [self canvas];
    self.frames = fr;
    [self resetFrameInfo];
    [self runAutoExposure];
    c.allSelected = NO;
    c.selected = 0;
    ESLog(@"Auto Locate: %lu marquee(s)", (unsigned long)fr.count);
    [self showCurrent];
    [self updateStatus];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

/* Rotate: the preview turns a quarter; the marquees go with it and the scan is turned the same */
- (void)rotateBy:(int)dir
{
    if (self.scanning || !self.pw || !self.ph) { NSBeep(); return; }
    int turns = dir > 0 ? 1 : 3;
    NSMutableArray<NSValue *> *fr = [self.frames mutableCopy] ?: [NSMutableArray array];
    @synchronized (self) {
        for (int t = 0; t < turns; t++) {
            self.pixels = ESRotateBuffer(self.pixels, self.pw, self.ph, 1);
            self.raw16 = ESRotateBuffer(self.raw16, self.pw, self.ph, 2);
            for (NSUInteger i = 0; i < fr.count; i++)
                fr[i] = [NSValue valueWithRect:ESRotateRect(fr[i].rectValue, self.pw, self.ph)];
            int w = self.pw; self.pw = self.ph; self.ph = w;
        }
    }
    self.quarters = (self.quarters + turns) & 3;
    self.frames = fr;
    /* the marquees' Target Size starts over in the new orientation */
    double k = 1.0 / self.pdpi;
    for (NSUInteger i = 0; i < self.adjusts.count && i < fr.count; i++) {
        ESAdjust *a = self.adjusts[i];
        NSRect r = fr[i].rectValue;
        EsTarget t = { .trimming = a.target.trimming };
        est_init(&t, r.size.width * k, r.size.height * k, r.origin.x * k, r.origin.y * k);
        a.target = t;
    }
    if (self.areaAdjust) self.areaAdjust.target = (EsTarget){ .trimming = self.areaAdjust.target.trimming };
    ESLog(@"Preview rotated %@: %d quarter turn(s) clockwise in all", dir > 0 ? @"right" : @"left", self.quarters);
    [self showCurrent];
    [self updateStatus];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

#pragma mark Zoom (Full Preview / Zoom tabs)

- (NSInteger)shownTab
{
    NSView *v = self.builder.controls[@"pvTabs"];
    if ([v isKindOfClass:[AQControl class]]) return ((AQControl *)v).selectedTab;
    if ([v isKindOfClass:[NSTabView class]]) {
        NSTabView *tv = (NSTabView *)v;
        return tv.selectedTabViewItem ? [tv indexOfTabViewItem:tv.selectedTabViewItem] : 0;
    }
    return 0;
}

- (void)showTab:(NSInteger)i
{
    NSView *v = self.builder.controls[@"pvTabs"];
    if ([v isKindOfClass:[AQControl class]]) { ((AQControl *)v).selectedTab = i; [v setNeedsDisplay:YES]; }
    else if ([v isKindOfClass:[NSTabView class]]) {
        NSTabView *tv = (NSTabView *)v;
        id<NSTabViewDelegate> d = tv.delegate;
        tv.delegate = nil;                   /* not a click */
        if (i < tv.numberOfTabViewItems) [tv selectTabViewItemAtIndex:i];
        tv.delegate = d;
    }
}

- (void)tabView:(NSTabView *)tv didSelectTabViewItem:(NSTabViewItem *)item
{
    [self tabPicked:[tv indexOfTabViewItem:item]];
    [self updateToolbar];
}

- (NSDictionary *)snapshot
{
    ESPreviewCanvas *c = [self canvas];
    return @{ @"pixels": self.pixels ?: [NSMutableData data], @"raw16": self.raw16 ?: [NSMutableData data],
              @"pw": @(self.pw), @"ph": @(self.ph), @"pdpi": @(self.pdpi), @"frames": self.frames ?: @[],
              @"adjusts": self.adjusts ?: @[], @"area": self.areaAdjust ?: [NSNull null],
              @"selected": @(c.selected), @"quarters": @(self.quarters),
              @"turns": [self.frameTurns mutableCopy] ?: [NSMutableArray array],
              @"mirror": [self.frameMirror mutableCopy] ?: [NSMutableArray array],
              @"checked": [self.frameChecked mutableCopy] ?: [NSMutableArray array],
              @"ox": @(self.originX), @"oy": @(self.originY) };
}

- (void)restore:(NSDictionary *)st
{
    ESPreviewCanvas *c = [self canvas];
    self.pixels = st[@"pixels"]; self.raw16 = st[@"raw16"];
    self.pw = [st[@"pw"] intValue]; self.ph = [st[@"ph"] intValue]; self.pdpi = [st[@"pdpi"] intValue];
    self.frames = st[@"frames"]; self.adjusts = st[@"adjusts"];
    self.areaAdjust = st[@"area"] == [NSNull null] ? nil : st[@"area"];
    self.quarters = [st[@"quarters"] intValue];
    self.originX = [st[@"ox"] doubleValue]; self.originY = [st[@"oy"] doubleValue];
    self.frameTurns = [st[@"turns"] mutableCopy]; self.frameMirror = [st[@"mirror"] mutableCopy];
    self.frameChecked = [st[@"checked"] mutableCopy];
    c.allSelected = NO;
    c.selected = [st[@"selected"] integerValue];
    [self showCurrent];
    [self updateStatus];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

/* swap between the full preview and the zoom preview that's kept */
- (void)swapTo:(BOOL)zoom
{
    if (self.zoomed == zoom || !self.otherState) return;
    NSDictionary *st = self.otherState;
    self.otherState = [self snapshot];
    self.zoomed = zoom;
    [self restore:st];
    [self showTab:zoom ? 1 : 0];
    [self updateMode];
}

- (void)zoomClicked
{
    if (self.scanning) return;
    if (self.zoomed) { [self swapTo:NO]; return; }      /* Display full size of preview area */
    [self startZoom];                                   /* Display specified part with zoom */
}

- (void)tabPicked:(NSInteger)i
{
    if (self.scanning) { [self showTab:self.zoomed ? 1 : 0]; return; }
    if (i == 0) { [self swapTo:NO]; return; }
    if (self.zoomed) return;
    if (self.otherState) [self swapTo:YES];
    else if (![self startZoom]) [self showTab:0];      /* nothing to zoom into yet */
}

/* CPreviewWnd zoom preview: the selected marquee is previewed again at the resolution that
 * fills the preview area; marquees drawn there are scanned from it */
- (BOOL)startZoom
{
    ESPreviewCanvas *c = [self canvas];
    double ax, ay, aw, ah;
    if (self.zoomed || self.scanning || c.selected < 0 || c.selected >= (NSInteger)c.frames.count ||
        ![self selectedAreaForFilm:self.film x:&ax y:&ay w:&aw h:&ah] || aw <= 0 || ah <= 0) {
        NSBeep();
        return NO;
    }
    NSSize cs = c.bounds.size;
    CGFloat scale = self.window.backingScaleFactor ?: 1;
    BOOL q90 = self.quarters & 1;
    double vw = (q90 ? cs.height : cs.width) * scale, vh = (q90 ? cs.width : cs.height) * scale;
    int dpi = (int)MIN(vw / (aw / 25.4), vh / (ah / 25.4));
    dpi = (dpi + 99) / 100 * 100;
    int maxDPI = self.film ? 3200 : 1600;
    while (dpi > 100 && (aw / 25.4 * dpi) * (ah / 25.4 * dpi) > 30e6) dpi -= 100;   /* keep it a preview */
    dpi = MAX(self.pdpi, MIN(maxDPI, dpi));

    self.otherState = [self snapshot];   /* the full preview, for the Full Preview tab */
    self.zoomed = YES;
    [self showTab:1];
    [self updateMode];
    int keepQuarters = self.quarters;
    self.scanning = YES;
    self.pixels = [NSMutableData data];
    self.raw16 = [NSMutableData data];
    self.carry = [NSMutableData data];
    self.adjusts = @[]; self.areaAdjust = nil;
    self.pw = self.ph = 0;
    self.frames = @[];
    self.pdpi = dpi;
    self.quarters = 0;                   /* the scan arrives unrotated; turned once it's in */
    self.originX = ax; self.originY = ay;
    c.image = nil; c.frames = @[]; c.selected = -1; c.allSelected = NO;
    c.message = @"Scanning.";
    [c setNeedsDisplay:YES];
    [self updateToolbar];

    ESScanParams p = { 0 };
    p.film = self.film;
    p.negative = self.negative;
    p.color = 1;
    p.depth16 = 1;
    p.dpi = dpi;
    p.area_x_mm = ax; p.area_y_mm = ay; p.area_w_mm = aw; p.area_h_mm = ah;
    ESLog(@"Zoom preview: %.1f x %.1f mm at (%.1f, %.1f), %d dpi", aw, ah, ax, ay, dpi);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        int rc = es_open(NULL);
        ESScanResult res = { 0 };
        if (rc == 0) rc = es_scan(&p, preview_data, NULL, (__bridge void *)self, &res);
        NSString *err = rc ? [NSString stringWithUTF8String:es_last_error()] : nil;
        ESLog(@"Zoom preview %@", rc ? [NSString stringWithFormat:@"failed (code %d): %@", rc, err] :
                                      [NSString stringWithFormat:@"finished: %d x %d", self.pw, res.height]);
        dispatch_async(dispatch_get_main_queue(), ^{
            self.scanning = NO;
            c.message = nil;
            if (rc == 0 && self.pw > 0 && res.height > 0) {
                self.ph = res.height;
                if (res.dpi > 0) self.pdpi = res.dpi;
                for (int t = 0; t < keepQuarters; t++) {
                    self.pixels = ESRotateBuffer(self.pixels, self.pw, self.ph, 1);
                    self.raw16 = ESRotateBuffer(self.raw16, self.pw, self.ph, 2);
                    int w = self.pw; self.pw = self.ph; self.ph = w;
                }
                self.quarters = keepQuarters;
                [self runAutoExposure];
                c.editable = YES;
                [self showCurrent];
                [self updateStatus];
                [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
            } else {                         /* back to the full preview */
                NSDictionary *full = self.otherState;
                self.otherState = nil;
                self.zoomed = NO;
                [self restore:full];
                [self showTab:0];
                [self updateMode];
                NSAlert *al = [NSAlert new];
                al.messageText = @"EPSON Scan";
                al.informativeText = err.length ? err : @"The scanner couldn't complete the preview.";
                al.alertStyle = NSAlertStyleWarning;
                [al beginSheetModalForWindow:self.window completionHandler:nil];
            }
            [self updateToolbar];
        });
    });
    return YES;
}

#pragma mark Densitometer

/* average of the Configuration > Densitometer Sampling Area around a point: the input (the
 * scanned data at gamma 1.8) and the output (the preview as adjusted) */
- (BOOL)densityAt:(NSPoint)pt input:(int *)in output:(int *)outv
{
    if (self.raw16.length < (size_t)self.pw * self.ph * 6) return NO;
    NSInteger ra = [NSUserDefaults.standardUserDefaults integerForKey:@"CfgDenseSampArea"];
    int rr = (int)MAX(0, MIN(2, ra)), cx = (int)pt.x, cy = (int)pt.y, n = 0, m = 0;
    long si[3] = { 0, 0, 0 }, so[3] = { 0, 0, 0 };
    const uint8_t *g = ESGamma18();
    const uint16_t *raw = self.raw16.bytes;
    NSBitmapImageRep *rep = nil;
    for (NSImageRep *r in [self canvas].image.representations)
        if ([r isKindOfClass:[NSBitmapImageRep class]]) { rep = (NSBitmapImageRep *)r; break; }
    for (int y = cy - rr; y <= cy + rr; y++)
        for (int x = cx - rr; x <= cx + rr; x++) {
            if (x < 0 || y < 0 || x >= self.pw || y >= self.ph) continue;
            const uint16_t *s = raw + ((size_t)y * self.pw + x) * 3;
            for (int c = 0; c < 3; c++) si[c] += g[s[c]];
            n++;
            if (rep && x < rep.pixelsWide && y < rep.pixelsHigh) {
                NSUInteger px[4] = { 0, 0, 0, 0 };
                [rep getPixel:px atX:x y:y];
                for (int c = 0; c < 3; c++) so[c] += (long)px[c];
                m++;
            }
        }
    if (!n) return NO;
    for (int c = 0; c < 3; c++) {
        in[c] = (int)((si[c] + n / 2) / n);
        outv[c] = m ? (int)((so[c] + m / 2) / m) : in[c];
    }
    return YES;
}

- (void)toggleDensitometer
{
    ESPreviewCanvas *c = [self canvas];
    if (self.densiPanel.isVisible) {
        [self.densiPanel orderOut:nil];
        c.onHover = nil;
        return;
    }
    if (!self.densiPanel) {
        NSPanel *pnl = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, 190, 92)
                                                  styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                            NSWindowStyleMaskUtilityWindow
                                                    backing:NSBackingStoreBuffered defer:NO];
        pnl.title = @"Densitometer";
        pnl.floatingPanel = YES;
        pnl.becomesKeyOnlyIfNeeded = YES;
        pnl.releasedWhenClosed = NO;
        NSTextField *t = [NSTextField labelWithString:@""];
        t.frame = NSMakeRect(12, 8, 170, 76);
        t.font = [NSFont monospacedDigitSystemFontOfSize:11 weight:NSFontWeightRegular];
        t.tag = 1;
        [pnl.contentView addSubview:t];
        self.densiPanel = pnl;
        NSRect f = self.window.frame;
        [pnl setFrameTopLeftPoint:NSMakePoint(NSMaxX(f) + 8, NSMaxY(f) - 40)];
    }
    NSTextField *t = [self.densiPanel.contentView viewWithTag:1];
    t.stringValue = @"        Input   Output\nR\nG\nB";
    __weak ESPreviewWindow *weakSelf = self;
    c.onHover = ^(NSPoint ip, BOOL inside) {
        ESPreviewWindow *me = weakSelf;
        int in[3], out[3];
        NSTextField *lbl = [me.densiPanel.contentView viewWithTag:1];
        if (!inside || ![me densityAt:ip input:in output:out]) {
            lbl.stringValue = @"        Input   Output\nR\nG\nB";
            return;
        }
        lbl.stringValue = [NSString stringWithFormat:@"        Input   Output\nR    %5d    %5d\nG    %5d    %5d\nB    %5d    %5d",
                           in[0], out[0], in[1], out[1], in[2], out[2]];
    };
    [self.densiPanel orderFront:nil];
}

#pragma mark Thumbnail preview

- (BOOL)showingThumbnails { return self.thumbnailMode && !self.zoomed && !self.scanning && self.pw > 0; }

/* Configuration > Auto Photo Orientation (CDTR::CutAndSkew -> CAutoRotate): Epson's classifier looks
 * at each thumbnail as it's shown (at DTR's 300 dpi) and the frame is turned; for film only a quarter
 * turn either way is taken (CAutoRotate::GetRotation with the frame's rotation 0) */
- (void)autoOrientFrames
{
    NSString *engine = [[NSBundle mainBundle] pathForResource:@"UI_i386" ofType:nil];
    ESPreviewCanvas *c = [self canvas];
    NSBitmapImageRep *rep = nil;
    for (NSImageRep *r in c.image.representations)
        if ([r isKindOfClass:[NSBitmapImageRep class]]) { rep = (NSBitmapImageRep *)r; break; }
    if (!engine || !rep || !self.pdpi) return;
    [self syncFrameInfo];
    double k = 300.0 / self.pdpi;
    for (NSUInteger i = 0; i < self.frames.count && i < self.frameTurns.count; i++) {
        NSRect f = self.frames[i].rectValue;
        int w = (int)(f.size.width * k), h = (int)(f.size.height * k);
        if (w <= 99 || h <= 99) continue;                  /* CAutoRotate::CanDoAutoRotate */
        int rb = w * 4;
        uint8_t *rgb = calloc((size_t)rb * h, 1);
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                NSUInteger px[4] = { 0, 0, 0, 0 };
                [rep getPixel:px atX:(NSInteger)(f.origin.x + x / k) y:(NSInteger)(f.origin.y + y / k)];
                uint8_t *d = rgb + (size_t)y * rb + (size_t)x * 3;
                d[0] = (uint8_t)px[0]; d[1] = (uint8_t)px[1]; d[2] = (uint8_t)px[2];
            }
        int o = -1;
        char err[256] = "";
        int rc = apo_orientation(engine.fileSystemRepresentation, rgb, w, h, rb, 0.09, &o, err, sizeof err);
        free(rgb);
        if (rc) { ESLog(@"Auto Photo Orientation: %s", err); return; }
        int deg = o == 1 ? 270 : o == 3 ? 90 : 0;          /* film: 0 and 2 keep the frame as it is */
        self.frameTurns[i] = @(deg / 90);
        ESLog(@"Auto Photo Orientation: frame %lu -> %d (rotate %d)", (unsigned long)i + 1, o, deg);
    }
}

/* the per-frame lists follow the marquees: new ones unchecked, unturned */
- (void)syncFrameInfo
{
    NSUInteger n = self.frames.count;
    if (!self.frameTurns) self.frameTurns = [NSMutableArray array];
    if (!self.frameMirror) self.frameMirror = [NSMutableArray array];
    if (!self.frameChecked) self.frameChecked = [NSMutableArray array];
    for (NSMutableArray *a in @[ self.frameTurns, self.frameMirror, self.frameChecked ]) {
        while (a.count > n) [a removeLastObject];
        while (a.count < n) [a addObject:a == self.frameTurns ? @0 : @NO];
    }
}

- (void)resetFrameInfo
{
    self.frameTurns = [NSMutableArray array];
    self.frameMirror = [NSMutableArray array];
    self.frameChecked = [NSMutableArray array];
    [self syncFrameInfo];
}

- (void)updateMode
{
    BOOL thumbs = [self showingThumbnails];
    NSDictionary *k = self.builder.controls;
    self.gridScroll.hidden = !thumbs;
    [self canvas].hidden = thumbs;
    BOOL rotation = [NSUserDefaults.standardUserDefaults boolForKey:@"CfgPreviewRotation"];
    for (NSString *key in @[ @"pvZoom", @"pvL1", @"pvS1", @"pvLocate", @"pvCopy", @"pvDelete", @"pvAll" ])
        [k[key] setHidden:thumbs];
    /* Configuration > Preview image rotation shows the Rotation group */
    for (NSString *key in @[ @"pvL2", @"pvS2", @"pvRotL", @"pvRotR" ]) [k[key] setHidden:thumbs || !rotation];
    for (NSString *key in @[ @"tbL1", @"tbS1", @"tbRotate", @"tbMirror", @"tbDelete", @"tbAll", @"tbL2", @"tbS2",
                             @"tbLarge", @"tbSmall", @"tbFull" ])
        [k[key] setHidden:!thumbs];
    for (NSString *key in @[ @"tbPrev", @"tbNext", @"tbFrameText" ]) [k[key] setHidden:!thumbs || self.thumbSize != 2];
    NSString *first = self.thumbnailMode ? @"Thumbnail" : @"Full Preview";
    NSView *tv = k[@"pvTabs"];
    if ([tv isKindOfClass:[AQControl class]]) {
        ((AQControl *)tv).tabs = @[ first, @"Zoom" ];
        [tv setNeedsDisplay:YES];
    } else if ([tv isKindOfClass:[NSTabView class]] && ((NSTabView *)tv).numberOfTabViewItems)
        [((NSTabView *)tv) tabViewItemAtIndex:0].label = first;
    [self refreshGrid];
}

- (void)refreshGrid
{
    ESThumbGrid *g = (ESThumbGrid *)self.gridScroll.documentView;
    if (!g || self.gridScroll.hidden) return;
    ESPreviewCanvas *c = [self canvas];
    [self syncFrameInfo];
    g.image = c.image;
    g.frames = self.frames;
    g.turns = self.frameTurns; g.mirror = self.frameMirror; g.checked = self.frameChecked;
    g.selected = c.selected;
    g.mode = self.thumbSize;
    if (g.fullIndex < 0 || g.fullIndex >= (NSInteger)self.frames.count) g.fullIndex = MAX(0, c.selected);
    [g tile];
    [g setNeedsDisplay:YES];
    ESSetText(self.builder.controls[@"tbFrameText"], self.frames.count
              ? [NSString stringWithFormat:@"%ld / %lu", (long)g.fullIndex + 1, (unsigned long)self.frames.count] : @"");
    ESSetEnabled(self.builder.controls[@"tbPrev"], g.fullIndex > 0);
    ESSetEnabled(self.builder.controls[@"tbNext"], g.fullIndex + 1 < (NSInteger)self.frames.count);
}

- (void)toggleFrame:(NSInteger)i
{
    [self syncFrameInfo];
    if (i < 0 || i >= (NSInteger)self.frameChecked.count) return;
    self.frameChecked[(NSUInteger)i] = @(!self.frameChecked[(NSUInteger)i].boolValue);
    [self refreshGrid];
}

- (void)showFrameFull:(NSInteger)i
{
    if (i < 0 || i >= (NSInteger)self.frames.count) return;
    self.thumbSize = 2;
    ((ESThumbGrid *)self.gridScroll.documentView).fullIndex = i;
    [self selectMarquee:i];
    [self updateMode];
}

- (void)thumbnailAction:(NSString *)a
{
    ESPreviewCanvas *c = [self canvas];
    ESThumbGrid *g = (ESThumbGrid *)self.gridScroll.documentView;
    NSInteger i = c.selected;
    BOOL sel = i >= 0 && i < (NSInteger)self.frames.count;
    [self syncFrameInfo];
    if ([a isEqualToString:@"tbRotate"] && sel)          /* Rotation: a quarter turn clockwise */
        self.frameTurns[(NSUInteger)i] = @((self.frameTurns[(NSUInteger)i].intValue + 1) & 3);
    else if ([a isEqualToString:@"tbMirror"] && sel)     /* Mirroring: left to right */
        self.frameMirror[(NSUInteger)i] = @(!self.frameMirror[(NSUInteger)i].boolValue);
    else if ([a isEqualToString:@"tbAll"])               /* Select all frames */
        for (NSUInteger j = 0; j < self.frameChecked.count; j++) self.frameChecked[j] = @YES;
    else if ([a isEqualToString:@"tbSmall"]) { self.thumbSize = 0; [self updateMode]; }
    else if ([a isEqualToString:@"tbLarge"]) { self.thumbSize = 1; [self updateMode]; }
    else if ([a isEqualToString:@"tbFull"]) { [self showFrameFull:sel ? i : 0]; return; }
    else if ([a isEqualToString:@"tbPrev"] || [a isEqualToString:@"tbNext"]) {
        NSInteger j = g.fullIndex + ([a isEqualToString:@"tbNext"] ? 1 : -1);
        if (j >= 0 && j < (NSInteger)self.frames.count) { g.fullIndex = j; [self selectMarquee:j]; }
    }
    else if (sel || ![a isEqualToString:@"tbDelete"]) NSBeep();
    [self refreshGrid];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

- (NSArray<NSNumber *> *)marqueesToScan
{
    NSMutableArray *out = [NSMutableArray array];
    if ([self showingThumbnails]) {
        [self syncFrameInfo];
        for (NSUInteger i = 0; i < self.frameChecked.count; i++) if (self.frameChecked[i].boolValue) [out addObject:@(i)];
    } else if ([self allMarqueesSelected])
        for (int i = 0; i < [self activeMarquees]; i++) [out addObject:@(i)];
    return out.count ? out : nil;
}

- (int)selectedQuarters
{
    NSInteger i = [self canvas].selected;
    int q = self.quarters;
    if ([self showingThumbnails] && i >= 0 && i < (NSInteger)self.frameTurns.count) q += self.frameTurns[(NSUInteger)i].intValue;
    return q & 3;
}

- (BOOL)selectedMirrored
{
    NSInteger i = [self canvas].selected;
    return [self showingThumbnails] && i >= 0 && i < (NSInteger)self.frameMirror.count && self.frameMirror[(NSUInteger)i].boolValue;
}

/* Office Mode's Size: one marquee of that size at the scanner's origin (CDocumentDialog::SetTarget) */
- (void)placeMarqueeMM:(NSSize)size
{
    if (self.scanning || !self.pw || !self.pdpi || self.film) return;
    double k = self.pdpi / 25.4;
    NSRect r = NSIntersectionRect(NSMakeRect(0, 0, round(size.width * k), round(size.height * k)),
                                  NSMakeRect(0, 0, self.pw, self.ph));
    ESPreviewCanvas *c = [self canvas];
    self.frames = @[ [NSValue valueWithRect:r] ];
    c.frames = self.frames;
    c.selected = 0; c.allSelected = NO;
    [self marqueeEdited:0 deleted:NO];
}

/* Full Auto Mode works like a Thumbnail preview: every frame checked, so each is scanned in turn */
- (void)checkAllFrames
{
    [self syncFrameInfo];
    for (NSUInteger i = 0; i < self.frameChecked.count; i++) self.frameChecked[i] = @YES;
    [self refreshGrid];
}

/* Full Auto Mode: every marquee is scanned, each to its own file */
- (void)selectAllMarquees
{
    ESPreviewCanvas *c = [self canvas];
    c.allSelected = c.frames.count > 1;
    c.selected = 0;
    [c setNeedsDisplay:YES];
    [self updateStatus];
}

/* marquees found by the caller (Full Auto's document detection), with their auto exposure */
- (void)adoptFrames:(NSArray<NSValue *> *)frames
{
    ESPreviewCanvas *c = [self canvas];
    self.frames = frames;
    [self resetFrameInfo];
    [self runAutoExposure];
    c.selected = 0; c.allSelected = NO;
    [self showCurrent];
    [self updateStatus];
    [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
}

- (void)startPreviewFilm:(BOOL)film negative:(BOOL)neg targetDPI:(int)dpi bytesPerPixel:(int)bpp
{
    if (self.scanning) return;
    self.scanning = YES;
    self.negative = film && neg;
    self.film = film;
    self.targetDPI = dpi;
    self.bytesPerPixel = bpp;
    self.pixels = [NSMutableData data];
    self.raw16 = [NSMutableData data];
    self.carry = [NSMutableData data];
    self.adjusts = @[]; self.areaAdjust = nil;
    self.pw = self.ph = 0;
    self.frames = @[];
    self.quarters = 0; self.originX = self.originY = 0;
    self.zoomed = NO; self.otherState = nil;
    [self showTab:0];
    [self resetFrameInfo];
    [self updateMode];
    ESPreviewCanvas *c = [self canvas];
    c.image = nil; c.frames = @[]; c.selected = 0; c.allSelected = NO;
    c.message = ESS_SCANCONTROL_5000_52;   /* Epson's own status text */
    [c setNeedsDisplay:YES];

    ESScanParams p = { 0 };
    p.film = film;
    p.negative = neg;
    p.color = 1;
    p.depth16 = 1;               /* FIT needs the full range; the display copy is made from it */
    p.dpi = film ? 400 : 200;
    /* Configuration > Quality Preview off = fast preview (ESPR +0x10); the V550 plugin hangs
     * with fast preview + film */
    NSUserDefaults *cfg = NSUserDefaults.standardUserDefaults;
    BOOL fast = [cfg objectForKey:@"CfgFastPreview"] ? [cfg integerForKey:@"CfgFastPreview"] == 1 : YES;
    p.fast_preview = !film && fast;
    self.pdpi = p.dpi;
    ESLog(@"Preview clicked: %@%@ at %d dpi", film ? @"film" : @"flatbed", film ? (neg ? @" (negative)" : @" (positive)") : @"", p.dpi);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        int rc = es_open(NULL);
        ESScanResult res = { 0 };
        if (rc == 0) {
            dispatch_async(dispatch_get_main_queue(), ^{ c.message = @"Scanning."; [c setNeedsDisplay:YES]; });
            rc = es_scan(&p, preview_data, NULL, (__bridge void *)self, &res);
        }
        NSString *err = rc ? [NSString stringWithUTF8String:es_last_error()] : nil;
        ESLog(@"Preview %@%@", rc ? @"failed" : @"finished", rc ? [NSString stringWithFormat:@" (code %d): %@", rc,
              err.length ? err : @"no message from the scanner"] : [NSString stringWithFormat:@": %d x %d", self.pw, res.height]);
        dispatch_async(dispatch_get_main_queue(), ^{
            self.scanning = NO;
            c.message = nil;
            if (rc == 0) {
                self.ph = res.height;
                /* Configuration > Thumbnail Cropping Area (Thumbnail only, CDTR::AdjustMargin): margin
                 * size ID 0 / 1 / 2 for Small / middle / Large */
                NSInteger level = MAX(1, MIN(3, [NSUserDefaults.standardUserDefaults integerForKey:@"CfgDTRMargin"] ?: 1));
                int marginID = self.thumbnailMode ? (int)level - 1 : 0;
                /* Thumbnail on the glass: the photos DTR finds (CDTR::DoDetectImage, reflective) */
                NSArray *dtr = film ? ESDetectFramesDTR(self.raw16.bytes, self.pw, self.ph, self.pdpi, self.negative,
                                                        self.filmTFT, marginID)
                             : self.thumbnailMode ? ESDetectDocumentsDTR(self.raw16.bytes, self.pw, self.ph, self.pdpi, NULL) : nil;
                self.frames = dtr ?: (film ? ESDetectFrames(self.pixels.bytes, self.pw, self.ph, self.pdpi, self.negative)
                                      : self.thumbnailMode ? (ESLocateReflective(self.pixels.bytes, self.pw, self.ph, self.pdpi) ?: @[]) : @[]);
                if (self.thumbnailMode && !self.frames.count) {
                    ESLog(@"Thumbnail preview: no frames found, showing the normal preview");
                    self.thumbnailMode = NO;
                    if (!film) {      /* STR# 10008 #78 */
                        NSAlert *a = [NSAlert new];
                        a.messageText = @"EPSON Scan";
                        a.informativeText = ESS_UI_10008_78;
                        [a beginSheetModalForWindow:self.window completionHandler:nil];
                    }
                } else if (self.thumbnailMode && !dtr) {
                    /* Configuration > Thumbnail Cropping Area: Small keeps the frame, Large crops into it */
                    NSInteger m = MAX(1, MIN(3, [NSUserDefaults.standardUserDefaults integerForKey:@"CfgDTRMargin"] ?: 2));
                    double inset = (m - 1) * 0.015;
                    NSMutableArray *fr = [NSMutableArray array];
                    for (NSValue *v in self.frames)
                        [fr addObject:[NSValue valueWithRect:NSIntegralRect(NSInsetRect(v.rectValue, v.rectValue.size.width * inset,
                                                                                         v.rectValue.size.height * inset))]];
                    self.frames = fr;
                    ESLog(@"Thumbnail preview: %lu frame(s), cropping area %ld", (unsigned long)fr.count, (long)m);
                }
                [self resetFrameInfo];
                [self updateMode];
                [self runAutoExposure];
                c.editable = YES;
                [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self];
                [self showCurrent];
                if (self.thumbnailMode && [NSUserDefaults.standardUserDefaults boolForKey:@"CfgAutoRotate"]) {
                    [self autoOrientFrames];
                    [self refreshGrid];
                }
                [self updateStatus];
                if (self.onPreviewDone) self.onPreviewDone(YES);
            } else {
                if (self.onPreviewDone) { self.onPreviewDone(NO); return; }
                [self showCurrent];
                NSAlert *a = [NSAlert new];
                a.messageText = @"EPSON Scan";
                a.informativeText = err.length ? err : @"The scanner couldn't complete the preview.";
                a.alertStyle = NSAlertStyleWarning;
                [a beginSheetModalForWindow:self.window completionHandler:nil];
            }
        });
    });
}

@end


/* ------------------------------------------------------------------------ */
#pragma mark - Scan (full resolution, optional Digital ICE)

/* ------------------------------------------------------------------------ */
#pragma mark - Image Adjustment dialog (Image Control plug-in, DLOG 1000)

/* CImageControlDialog: Brightness, Contrast, Saturation and Color Balance for the selected
 * marquee. Values go straight into the marquee's FIT3_PARA (+0x4c brightness, +0x50 contrast,
 * +0x68 saturation, +0x54/58/5c colour balance), -100..100, and the preview is redrawn. */
@interface ESImageAdjustDialog : NSObject <NSWindowDelegate>
@property (nonatomic, strong) NSPanel *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic, weak) ESPreviewWindow *preview;
@property (nonatomic, copy) void (^onAction)(NSString *action);
- (instancetype)initWithPreview:(ESPreviewWindow *)preview;
- (void)rebuild;
- (void)show;
@end

static NSString *const kAdjustKeys[6] = { @"brightness", @"contrast", @"saturation", @"balCR", @"balMG", @"balYB" };

@implementation ESImageAdjustDialog

- (NSDictionary *)layout
{
    NSString *path = [[NSBundle mainBundle] pathForResource:@"imageadjust" ofType:@"json"];
    NSData *d = [NSData dataWithContentsOfFile:path];
    return d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : @{};
}

- (instancetype)initWithPreview:(ESPreviewWindow *)preview
{
    if ((self = [super init])) {
        self.preview = preview;
        NSDictionary *w = [self layout][@"window"];
        self.window = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])
                                                 styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                           NSWindowStyleMaskUtilityWindow
                                                   backing:NSBackingStoreBuffered defer:NO];
        self.window.title = w[@"title"] ?: @"Image Adjustment";
        self.window.releasedWhenClosed = NO;
        self.window.hidesOnDeactivate = NO;
        self.window.floatingPanel = YES;
        self.window.becomesKeyOnlyIfNeeded = YES;
        [self rebuild];
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(selectionChanged:)
                                                   name:ESSelectionChanged object:nil];
    }
    return self;
}

- (void)dealloc { [NSNotificationCenter.defaultCenter removeObserver:self]; }

- (void)rebuild
{
    NSDictionary *L = [self layout];
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    self.builder = [ESBuilder new];
    self.builder.native = native;
    NSDictionary *w = L[@"window"];
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, [w[@"width"] doubleValue],
                                                                          [w[@"height"] doubleValue])];
    root.wantsLayer = YES;
    root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor
                                        : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    [self.builder build:L[@"items"] into:root];
    self.window.contentView = root;
    __weak ESImageAdjustDialog *weakSelf = self;
    self.builder.onValue = ^(NSString *key, double v) { [weakSelf slider:key value:(int)v]; };
    self.builder.onAction = ^(NSString *action) { [weakSelf perform:action]; };
    for (int i = 0; i < 6; i++) {
        NSTextField *t = (NSTextField *)self.builder.controls[[kAdjustKeys[i] stringByAppendingString:@"Text"]];
        if (![t isKindOfClass:[NSTextField class]]) continue;
        t.identifier = kAdjustKeys[i];
        t.alignment = NSTextAlignmentRight;
        t.target = self;
        t.action = @selector(textEntered:);
        t.cell.sendsActionOnEndEditing = YES;
    }
    [self load];
}

- (void)show
{
    if (!self.window.isVisible) {
        NSWindow *pw = self.preview.window;
        NSRect f = self.window.frame;
        if (pw.isVisible) f.origin = NSMakePoint(NSMaxX(pw.frame) - f.size.width - 20, NSMaxY(pw.frame) - f.size.height - 40);
        else [self.window center];
        if (pw.isVisible) [self.window setFrame:f display:NO];
    }
    [self load];
    [self.window orderFront:nil];
}

/* show the selected marquee's values */
- (void)load
{
    ESAdjust *a = [self.preview selectedAdjust];
    for (int i = 0; i < 6; i++) {
        int v = a ? [a field:kAdjustFields[i]] : 0;
        ESSetSliderValue(self.builder.controls[kAdjustKeys[i]], v);
        NSTextField *t = (NSTextField *)self.builder.controls[[kAdjustKeys[i] stringByAppendingString:@"Text"]];
        if ([t isKindOfClass:[NSTextField class]]) t.stringValue = [NSString stringWithFormat:@"%d", v];
    }
}

- (void)selectionChanged:(NSNotification *)n { if (n.object == self.preview) [self load]; }

- (void)set:(NSString *)key value:(int)v
{
    v = MAX(-100, MIN(100, v));
    ESAdjust *a = [self.preview selectedAdjust];
    for (int i = 0; i < 6; i++)
        if ([kAdjustKeys[i] isEqualToString:key]) {
            NSTextField *t = (NSTextField *)self.builder.controls[[key stringByAppendingString:@"Text"]];
            if ([t isKindOfClass:[NSTextField class]]) t.stringValue = [NSString stringWithFormat:@"%d", v];
            ESSetSliderValue(self.builder.controls[key], v);
            if (a && [a field:kAdjustFields[i]] != v) {
                [a setField:kAdjustFields[i] value:v];
                [self schedulePreview];
            }
        }
}

- (void)slider:(NSString *)key value:(int)v { [self set:key value:v]; }

- (void)textEntered:(NSTextField *)t { [self set:t.identifier value:t.stringValue.intValue]; }

/* coalesce slider drags: redraw once the pending mouse events are handled */
- (void)schedulePreview
{
    [NSObject cancelPreviousPerformRequestsWithTarget:self selector:@selector(refreshPreview) object:nil];
    [self performSelector:@selector(refreshPreview) withObject:nil afterDelay:0];
}

- (void)refreshPreview { [self.preview adjustmentsChanged]; }

- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"ia:close"]) [self.window orderOut:nil];
    else if ([action isEqualToString:@"ia:reset"]) {        /* CFitIF::ResetImageCtl */
        for (int i = 0; i < 6; i++) [self set:kAdjustKeys[i] value:0];
    } else if ([action isEqualToString:@"ia:help"]) {
        NSBeep();
    } else if ([action isEqualToString:@"dlg:imageadjust"]) {
        [self load];                                        /* this dialog's own tab */
    } else if (self.onAction) self.onAction(action);
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark - Histogram Adjustment dialog (Image Control plug-in, DLOG 1001)

static void ESSetOn(NSView *v, BOOL on)
{
    if ([v isKindOfClass:[AQControl class]]) { ((AQControl *)v).on = on; [v setNeedsDisplay:YES]; }
    else if ([v isKindOfClass:[NSButton class]]) ((NSButton *)v).state = on ? NSControlStateValueOn : NSControlStateValueOff;
}

static void ESSetField(NSView *v, NSString *str)
{
    if ([v isKindOfClass:[NSTextField class]] && ![((NSTextField *)v).stringValue isEqualToString:str])
        ((NSTextField *)v).stringValue = str;
}

/* a bevel button's picture (Epson swaps cicns: orientation, lock) */
static void ESSetIcon(NSView *v, int cicn)
{
    NSImage *img = ESIcon(@(cicn));
    if (!img) return;
    if ([v isKindOfClass:[AQControl class]]) { ((AQControl *)v).icon = img; [v setNeedsDisplay:YES]; }
    else if ([v isKindOfClass:[NSButton class]]) ((NSButton *)v).image = img;
}

/* replace a popup's items, keeping the selection when it's still there */
static void ESSetMenu(NSView *v, NSArray<NSString *> *items)
{
    if ([v isKindOfClass:[AQControl class]]) {
        AQControl *c = (AQControl *)v;
        c.menuItems = items;
        if (c.arrowOnly) c.text = @"";   /* a menu button beside a field keeps showing only its arrow */
        else if (![items containsObject:c.text]) c.text = items.firstObject;
        [c setNeedsDisplay:YES];
    } else if ([v isKindOfClass:[NSPopUpButton class]]) {
        NSPopUpButton *p = (NSPopUpButton *)v;
        NSString *cur = p.titleOfSelectedItem;
        [p removeAllItems];
        [p addItemsWithTitles:items];
        if (cur && [items containsObject:cur]) [p selectItemWithTitle:cur];
    }
}

/* EnableMenuItem / DisableMenuItem on a popup (index from 0) */
static void ESSetItemEnabled(NSView *v, NSUInteger i, BOOL en)
{
    if ([v isKindOfClass:[AQControl class]]) {
        NSMutableIndexSet *set = [((AQControl *)v).disabledItems mutableCopy] ?: [NSMutableIndexSet indexSet];
        if (en) [set removeIndex:i]; else [set addIndex:i];
        ((AQControl *)v).disabledItems = set;
    } else if ([v isKindOfClass:[NSPopUpButton class]]) {
        NSPopUpButton *p = (NSPopUpButton *)v;
        p.autoenablesItems = NO;
        if (i < (NSUInteger)p.numberOfItems) [p itemAtIndex:(NSInteger)i].enabled = en;
    }
}

static void ESSelectItem(NSView *v, NSString *title)
{
    if ([v isKindOfClass:[AQControl class]]) { ((AQControl *)v).text = title; [v setNeedsDisplay:YES]; }
    else if ([v isKindOfClass:[NSPopUpButton class]]) [(NSPopUpButton *)v selectItemWithTitle:title];
}

static void ESSetEnabled(NSView *v, BOOL en)
{
    if ([v isKindOfClass:[NSControl class]]) ((NSControl *)v).enabled = en;
    if ([v isKindOfClass:[AQControl class]]) ((AQControl *)v).disabled = !en;
    v.alphaValue = en ? 1.0 : 0.45;
}

/* CLevelAdjustmentDialog: input shadow / gamma / highlight and output shadow / highlight per
 * channel (master spreads over R, G, B), shadow / mid-tone / highlight / gray pipettes, gray
 * balance intensity, shadow and highlight curve forms, Tone Curve Viewer, Show Output. */
@interface ESHistogramDialog : NSObject
@property (nonatomic, strong) NSPanel *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic, weak) ESPreviewWindow *preview;
@property (nonatomic, copy) void (^onAction)(NSString *action);
@property (nonatomic) int channel;                  /* 0 master, 1 R, 2 G, 3 B */
@property (nonatomic) BOOL showOutput;
- (instancetype)initWithPreview:(ESPreviewWindow *)preview;
- (void)rebuild;
- (void)show;
@end

@implementation ESHistogramDialog

- (NSDictionary *)layout
{
    NSString *path = [[NSBundle mainBundle] pathForResource:@"histadjust" ofType:@"json"];
    NSData *d = [NSData dataWithContentsOfFile:path];
    return d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : @{};
}

- (instancetype)initWithPreview:(ESPreviewWindow *)preview
{
    if ((self = [super init])) {
        self.preview = preview;
        NSDictionary *w = [self layout][@"window"];
        self.window = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])
                                                 styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                           NSWindowStyleMaskUtilityWindow
                                                   backing:NSBackingStoreBuffered defer:NO];
        self.window.title = w[@"title"] ?: @"Histogram Adjustment";
        self.window.releasedWhenClosed = NO;
        self.window.hidesOnDeactivate = NO;
        self.window.floatingPanel = YES;
        self.window.becomesKeyOnlyIfNeeded = YES;
        [self rebuild];
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(selectionChanged:)
                                                   name:ESSelectionChanged object:nil];
    }
    return self;
}

- (void)dealloc { [NSNotificationCenter.defaultCenter removeObserver:self]; }

- (NSView *)ctl:(NSString *)key { return self.builder.controls[key]; }

- (void)rebuild
{
    NSDictionary *L = [self layout];
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    self.builder = [ESBuilder new];
    self.builder.native = native;
    NSDictionary *w = L[@"window"];
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, [w[@"width"] doubleValue],
                                                                          [w[@"height"] doubleValue])];
    root.wantsLayer = YES;
    root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor
                                        : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    [self.builder build:L[@"items"] into:root];
    self.window.contentView = root;
    __weak ESHistogramDialog *weakSelf = self;
    self.builder.onAction = ^(NSString *a) { [weakSelf perform:a]; };
    self.builder.onValue = ^(NSString *key, double v) { [weakSelf value:key changed:(int)v]; };
    self.builder.onHold = ^(NSString *key, BOOL down) { [weakSelf hold:down]; };
    ((ESLevelArrows *)[self ctl:@"inArrows"]).onMove = ^(int arrow, int pos, BOOL done) { [weakSelf inArrow:arrow moved:pos]; };
    ((ESLevelArrows *)[self ctl:@"outArrows"]).onMove = ^(int arrow, int pos, BOOL done) { [weakSelf outArrow:arrow moved:pos]; };
    for (NSString *k in @[ @"inSD", @"inGamma", @"inHL", @"outSD", @"outHL", @"grayBalanceText" ]) {
        NSTextField *t = (NSTextField *)[self ctl:k];
        if (![t isKindOfClass:[NSTextField class]]) continue;
        t.identifier = k;
        t.alignment = NSTextAlignmentRight;
        t.target = self;
        t.action = @selector(textEntered:);
        t.cell.sendsActionOnEndEditing = YES;
    }
    [self load];
}

- (void)show
{
    if (!self.window.isVisible) {
        NSWindow *pw = self.preview.window;
        if (pw.isVisible) {
            NSRect f = self.window.frame;
            f.origin = NSMakePoint(NSMaxX(pw.frame) - f.size.width - 20, NSMaxY(pw.frame) - f.size.height - 40);
            [self.window setFrame:f display:NO];
        } else [self.window center];
    }
    [self load];
    [self.window orderFront:nil];
}

- (void)selectionChanged:(NSNotification *)n { if (n.object == self.preview && self.window.isVisible) [self load]; }

- (int)screenGamma
{
    return ESScreenGamma10();
}

/* CLevelAdjustmentDialog::UpdateRGBChannel / UpdateHistogram / UpdateHistogramValue /
 * UpdateGrayBalance / UpdateLookupTable */
- (void)load
{
    ESAdjust *a = [self.preview selectedAdjust];
    for (int k = 0; k < 4; k++) ESSetOn([self ctl:[NSString stringWithFormat:@"ch%d", k]], k == self.channel);
    NSImageView *grad = (NSImageView *)[self ctl:@"gradient"];
    if ([grad isKindOfClass:[NSImageView class]])
        grad.image = ESArt(self.channel == 1 ? @"pict_3011.png" : self.channel == 2 ? @"pict_3012.png"
                           : self.channel == 3 ? @"pict_3013.png" : @"pict_3014.png");

    EsHistogram hg;
    BOOL have = [self.preview histogram:&hg output:self.showOutput];
    ESHistogramView *hv = (ESHistogramView *)[self ctl:@"histogram"];
    hv.histogram = have ? [NSData dataWithBytes:&hg length:sizeof hg] : nil;
    hv.channel = self.channel;
    [hv setNeedsDisplay:YES];

    EsLevels lv;
    int v[5] = { 0xffff, 0, 0xffff, 0, 100 };
    if (a) { lv_from_para(&lv, a.st->para); lv_get(&lv, self.channel, v); }
    ESSetField([self ctl:@"inSD"], [NSString stringWithFormat:@"%d", v[LV_SD] / 0x101]);
    ESSetField([self ctl:@"inHL"], [NSString stringWithFormat:@"%d", v[LV_HL] / 0x101]);
    ESSetField([self ctl:@"inGamma"], [NSString stringWithFormat:@"%.2f", v[LV_GAMMA] / 100.0]);
    ESSetField([self ctl:@"outSD"], [NSString stringWithFormat:@"%d", v[LV_OSD] / 0x101]);
    ESSetField([self ctl:@"outHL"], [NSString stringWithFormat:@"%d", v[LV_OHL] / 0x101]);
    ESLevelArrows *ia = (ESLevelArrows *)[self ctl:@"inArrows"], *oa = (ESLevelArrows *)[self ctl:@"outArrows"];
    ia.left = (int)ceil(v[LV_SD] / 0x101 / 255.0 * 235.0);
    ia.right = (int)ceil(v[LV_HL] / 0x101 / 255.0 * 235.0);
    ia.center = lv_gamma_to_pos(ia.left, ia.right, v[LV_GAMMA]);
    oa.left = (int)ceil(v[LV_OSD] / 0x101 / 255.0 * 235.0);
    oa.right = (int)ceil(v[LV_OHL] / 0x101 / 255.0 * 235.0);
    [ia setNeedsDisplay:YES]; [oa setNeedsDisplay:YES];

    BOOL gray = a && a.grayIntensity != -1;
    int gi = gray ? a.grayIntensity : 100;
    ESSetSliderValue([self ctl:@"grayBalance"], gi);
    ESSetField([self ctl:@"grayBalanceText"], [NSString stringWithFormat:@"%d", gi]);
    ESSetEnabled([self ctl:@"grayBalance"], gray);
    ESSetEnabled([self ctl:@"grayBalanceText"], gray);
    for (NSString *k in @[ @"inArrows", @"outArrows", @"inSD", @"inGamma", @"inHL", @"outSD", @"outHL" ])
        ESSetEnabled([self ctl:k], a != nil);

    ESCurveView *cv = (ESCurveView *)[self ctl:@"curve"];
    cv.lut = a.lut; cv.channel = self.channel; cv.screenGamma10 = [self screenGamma];
    cv.negative = self.preview.negative; cv.hideDots = self.showOutput;
    cv.levels = a ? [NSData dataWithBytes:&lv length:sizeof lv] : nil;
    [cv setNeedsDisplay:YES];
    if (a) {
        int16_t hlc, sdc;
        memcpy(&hlc, a.st->para + 0x48, 2); memcpy(&sdc, a.st->para + 0x4a, 2);
        ESCurveButton *hb = (ESCurveButton *)[self ctl:@"hlCurve"], *sb = (ESCurveButton *)[self ctl:@"sdCurve"];
        hb.selected = hlc < 3 ? hlc : hlc - 3; sb.selected = sdc < 3 ? sdc : sdc - 3;
        [hb setNeedsDisplay:YES]; [sb setNeedsDisplay:YES];
    }
}

/* the marquee changed: new table, preview, dialog */
- (void)commit:(ESAdjust *)a
{
    [self.preview adjustmentsChanged];
    [self load];
}

/* an indicator moved (OnIndicatorValueChanged: gray balance is dropped) */
- (void)setField:(int)field value:(int)value
{
    ESAdjust *a = [self.preview selectedAdjust];
    if (!a) return;
    EsLevels lv;
    lv_from_para(&lv, a.st->para);
    lv_set(&lv, self.channel, field, value);
    lv_to_para(&lv, a.st->para);
    a.grayIntensity = -1;
    [self commit:a];
}

- (void)inArrow:(int)arrow moved:(int)pos
{
    ESLevelArrows *ia = (ESLevelArrows *)[self ctl:@"inArrows"];
    if (arrow == 1) {
        int g = lv_pos_to_gamma(ia.left, ia.right, MAX(ia.left + 5, MIN(ia.right - 5, pos)));
        [self setField:LV_GAMMA value:g];
    } else {
        int v = (int)floor(pos / 235.0 * 255.0) * 0x101;
        [self setField:arrow == 0 ? LV_SD : LV_HL value:v];
    }
}

- (void)outArrow:(int)arrow moved:(int)pos
{
    int v = (int)floor(pos / 235.0 * 255.0) * 0x101;
    [self setField:arrow == 0 ? LV_OSD : LV_OHL value:v];
}

- (void)textEntered:(NSTextField *)t
{
    NSString *k = t.identifier;
    if ([k isEqualToString:@"inGamma"]) [self setField:LV_GAMMA value:(int)lround(t.doubleValue * 100)];
    else if ([k isEqualToString:@"inSD"]) [self setField:LV_SD value:MAX(0, MIN(255, t.intValue)) * 0x101];
    else if ([k isEqualToString:@"inHL"]) [self setField:LV_HL value:MAX(0, MIN(255, t.intValue)) * 0x101];
    else if ([k isEqualToString:@"outSD"]) [self setField:LV_OSD value:MAX(0, MIN(255, t.intValue)) * 0x101];
    else if ([k isEqualToString:@"outHL"]) [self setField:LV_OHL value:MAX(0, MIN(255, t.intValue)) * 0x101];
    else if ([k isEqualToString:@"grayBalanceText"]) [self value:@"grayBalance" changed:t.intValue];
}

/* host SetParameter(0) with a gray point: FIT GetGrayBalance on the saved levels */
- (void)applyGray:(ESAdjust *)a
{
    if (a.grayIntensity < 0 || a.baseLevels.length != 12 * sizeof(int)) return;
    int rgb[3] = { a.grayR, a.grayG, a.grayB };
    char err[256];
    if (fit_state_gray_balance(ESFitEngine().fileSystemRepresentation, a.st, a.baseLevels.bytes, rgb,
                               a.grayIntensity, err, sizeof err))
        NSLog(@"gray balance: %s", err);
}

- (void)value:(NSString *)key changed:(int)v
{
    ESAdjust *a = [self.preview selectedAdjust];
    if (!a) return;
    if ([key isEqualToString:@"grayBalance"]) {
        if (a.grayIntensity < 0) { [self load]; return; }
        a.grayIntensity = MAX(0, MIN(100, v));
        [self applyGray:a];
        [self commit:a];
    } else if ([key isEqualToString:@"hlCurve"] || [key isEqualToString:@"sdCurve"]) {
        /* DoDataExchange: +0x1c = highlight form (0..2), +0x1e = shadow form + 3 */
        int16_t x = (int16_t)([key isEqualToString:@"hlCurve"] ? v : v + 3);
        memcpy(a.st->para + ([key isEqualToString:@"hlCurve"] ? 0x48 : 0x4a), &x, 2);
        [self commit:a];
    }
}

/* Show Output: while held, the histogram of the corrected image */
- (void)hold:(BOOL)down
{
    self.showOutput = down;
    [self load];
    [self.window displayIfNeeded];
}

/* CMainDialog::PipetteHandling: the levels at this moment become the gray-balance base */
- (void)saveBase:(ESAdjust *)a
{
    int b[12];
    for (int c = 0; c < 3; c++)
        for (int k = 0; k < 4; k++) memcpy(&b[c * 4 + k], a.st->para + 0x0c + c * 0x14 + k * 4, 4);
    a.baseLevels = [NSData dataWithBytes:b length:sizeof b];
}

- (void)pipette:(NSString *)which
{
    __weak ESHistogramDialog *weakSelf = self;
    ESPreviewWindow *pv = self.preview;
    [pv pickWith:^(NSPoint pt) {
        ESHistogramDialog *me = weakSelf;
        ESAdjust *a = [pv selectedAdjust];
        int rgb[3];
        char err[256];
        if (!me || !a || ![pv sampleAt:pt rgb:rgb]) return;
        if (fit_state_screen_values(ESFitEngine().fileSystemRepresentation, a.st, rgb, err, sizeof err)) return;
        [me saveBase:a];
        EsLevels lv;
        lv_from_para(&lv, a.st->para);
        if ([which isEqualToString:@"highlight"] || [which isEqualToString:@"shadow"]) {
            BOOL hl = [which isEqualToString:@"highlight"];
            for (int c = 0; c < 3; c++) {          /* OnIDC_CHECK_SPOITO_HIGHLIGHT / SHADOW clamps */
                int *ch = lv.ch[c], x = rgb[c];
                if (hl) { x = MAX(2, MIN(0xffff, x)); if (x < ch[LV_SD] + 0x606) x = ch[LV_SD] + 0x606; ch[LV_HL] = x; }
                else { x = MAX(0, MIN(0xfdfd, x)); if (x > ch[LV_HL] - 0x606) x = ch[LV_HL] - 0x606; ch[LV_SD] = x; }
            }
            lv_to_para(&lv, a.st->para);
            a.grayIntensity = -1;
        } else if ([which isEqualToString:@"gamma"]) {
            int g[3] = { rgb[0] / 0x101, rgb[1] / 0x101, rgb[2] / 0x101 };
            if (fit_state_pipette_gamma(ESFitEngine().fileSystemRepresentation, a.st, g, err, sizeof err))
                NSLog(@"gamma pipette: %s", err);
        } else {                                   /* gray point */
            a.grayR = rgb[0] / 0x101; a.grayG = rgb[1] / 0x101; a.grayB = rgb[2] / 0x101;
            a.grayIntensity = 100;
            [me applyGray:a];
        }
        [me commit:a];
    }];
}

- (void)perform:(NSString *)action
{
    if ([action hasPrefix:@"ha:ch"]) {
        self.channel = [action substringFromIndex:5].intValue;
        [self load];
    } else if ([action isEqualToString:@"ha:pipShadow"]) [self pipette:@"shadow"];
    else if ([action isEqualToString:@"ha:pipHighlight"]) [self pipette:@"highlight"];
    else if ([action isEqualToString:@"ha:pipGamma"]) [self pipette:@"gamma"];
    else if ([action isEqualToString:@"ha:pipGray"]) [self pipette:@"gray"];
    else if ([action isEqualToString:@"ha:close"]) [self.window orderOut:nil];
    else if ([action isEqualToString:@"ha:reset"]) {
        /* OnReset: channel back to master; the marquee's levels and curve forms back to auto exposure */
        self.channel = 0;
        ESAdjust *a = [self.preview selectedAdjust];
        if (a && a.autoPara.length == 0x80) {
            memcpy(a.st->para + 0x0c, (const uint8_t *)a.autoPara.bytes + 0x0c, 0x40);
            a.grayIntensity = -1;
            a.baseLevels = nil;
            [self commit:a];
        } else [self load];
    } else if ([action isEqualToString:@"ha:help"]) NSBeep();
    else if ([action isEqualToString:@"dlg:histogram"]) [self load];
    else if (self.onAction) self.onAction(action);
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark - Tone Correction dialog (Image Control plug-in, DLOG 1002)

/* user tone curves, stored as Epson Scan stores them (CToneCurve::SaveUserToneCurve):
 * 'TONU' resources in the Professional mode prefs file,
 * ~/Library/Preferences/EPSON/EPSON Scan/ES00EB/EPSON Scan AD Prefs (type 'Pref', creator 'eSTW').
 * 0x00EB is the V550's model ID (its device files are "EPSON Scan ES00EB IDX/HRD"). */
/* a prefs file in Epson's folder (CUIPrefsBase::MakeMyFSSpec): Preferences/EPSON/EPSON Scan/ES00EB/<name> */
static NSString *ESEpsonPrefsPath(NSString *name, BOOL create)
{
    NSString *dir = [NSSearchPathForDirectoriesInDomains(NSLibraryDirectory, NSUserDomainMask, YES).firstObject
                     stringByAppendingPathComponent:@"Preferences/EPSON/EPSON Scan/ES00EB"];
    NSString *file = [dir stringByAppendingPathComponent:name];
    if (create && ![NSFileManager.defaultManager fileExistsAtPath:file]) {
        [NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];
        /* CUIPrefsBase::Open: FSpCreateResFile(spec, 'eSTW', 'Pref') */
        [NSFileManager.defaultManager createFileAtPath:file contents:[NSData data]
                                            attributes:@{ NSFileHFSCreatorCode: @((OSType)'eSTW'),
                                                          NSFileHFSTypeCode: @((OSType)'Pref') }];
    }
    return file;
}

static NSString *ESAdvancedPrefsPath(BOOL create) { return ESEpsonPrefsPath(ESS_UI_10006_14, create); }

/* one saved curve: name + EsToneCurve bytes */
static NSMutableArray<NSDictionary *> *ESToneStoreLoad(void)
{
    NSMutableArray *out = [NSMutableArray array];
    EsToneCurve *list = NULL;
    int n = tonu_load(ESAdvancedPrefsPath(NO).fileSystemRepresentation, &list);
    for (int i = 0; i < n; i++) {
        NSString *name = [NSString stringWithCString:list[i].name encoding:NSMacOSRomanStringEncoding] ?: @"";
        [out addObject:@{ @"name": name, @"curve": [NSData dataWithBytes:&list[i] length:sizeof list[i]] }];
    }
    free(list);
    return out;
}

static BOOL ESToneStoreSave(NSArray<NSDictionary *> *a)
{
    NSUInteger n = a.count;
    EsToneCurve *list = calloc(n ? n : 1, sizeof *list);
    if (!list) return NO;
    for (NSUInteger i = 0; i < n; i++) memcpy(&list[i], [a[i][@"curve"] bytes], sizeof *list);
    BOOL ok = tonu_save(ESAdvancedPrefsPath(YES).fileSystemRepresentation, list, (int)n) == 0;
    free(list);
    return ok;
}

static NSString *const kToneCurrent = @"Current Setting", *const kToneUser = @"User Defined", *const kToneAuto = @"Auto";

/* CToneCorrectionDialog: curve per channel (master, R, G, B) edited with the mouse or the
 * Input/Output boxes; Epson's six presets plus saved curves in the name box. */
@interface ESToneDialog : NSObject <NSWindowDelegate, NSTextFieldDelegate>
@property (nonatomic, strong) NSPanel *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic, weak) ESPreviewWindow *preview;
@property (nonatomic, copy) void (^onAction)(NSString *action);
@property (nonatomic) int channel;
@property (nonatomic) int dragIndex, dragLo, dragHi;   /* CToneCurvePaintCtrl +0x3c, survival rect */
- (instancetype)initWithPreview:(ESPreviewWindow *)preview;
- (void)rebuild;
- (void)show;
@end

@implementation ESToneDialog {
    int _sel[4];                                          /* selected point per channel (+0xa8, +0x238..) */
}

- (NSDictionary *)layout
{
    NSString *path = [[NSBundle mainBundle] pathForResource:@"tonecurve" ofType:@"json"];
    NSData *d = [NSData dataWithContentsOfFile:path];
    return d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : @{};
}

- (instancetype)initWithPreview:(ESPreviewWindow *)preview
{
    if ((self = [super init])) {
        self.preview = preview;
        NSDictionary *w = [self layout][@"window"];
        self.window = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])
                                                 styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                           NSWindowStyleMaskUtilityWindow
                                                   backing:NSBackingStoreBuffered defer:NO];
        self.window.title = w[@"title"] ?: @"Tone Correction";
        self.window.releasedWhenClosed = NO;
        self.window.hidesOnDeactivate = NO;
        self.window.floatingPanel = YES;
        self.window.becomesKeyOnlyIfNeeded = YES;
        [self rebuild];
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(selectionChanged:)
                                                   name:ESSelectionChanged object:nil];
    }
    return self;
}

- (void)dealloc { [NSNotificationCenter.defaultCenter removeObserver:self]; }

- (NSView *)ctl:(NSString *)key { return self.builder.controls[key]; }

- (void)rebuild
{
    NSDictionary *L = [self layout];
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    self.builder = [ESBuilder new];
    self.builder.native = native;
    NSDictionary *w = L[@"window"];
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, [w[@"width"] doubleValue],
                                                                          [w[@"height"] doubleValue])];
    root.wantsLayer = YES;
    root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor
                                        : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    [self.builder build:L[@"items"] into:root];
    self.window.contentView = root;
    __weak ESToneDialog *weakSelf = self;
    self.builder.onAction = ^(NSString *a) { [weakSelf perform:a]; };
    ((ESToneView *)[self ctl:@"toneView"]).onMouse = ^(int phase, int cx, int x, int y) {
        [weakSelf mouse:phase ctrlX:cx x:x y:y];
    };
    for (NSString *k in @[ @"tcIn", @"tcOut", @"toneName" ]) {
        NSTextField *t = (NSTextField *)[self ctl:k];
        if (![t isKindOfClass:[NSTextField class]]) continue;
        t.identifier = k;
        if (![k isEqualToString:@"toneName"]) t.alignment = NSTextAlignmentRight;
        else t.delegate = self;                        /* Save / Delete follow the typed name */
        t.target = self;
        t.action = @selector(textEntered:);
        t.cell.sendsActionOnEndEditing = YES;
    }
    [self load];
}

- (void)show
{
    if (!self.window.isVisible) {
        NSWindow *pw = self.preview.window;
        if (pw.isVisible) {
            NSRect f = self.window.frame;
            f.origin = NSMakePoint(NSMaxX(pw.frame) - f.size.width - 20, NSMaxY(pw.frame) - f.size.height - 40);
            [self.window setFrame:f display:NO];
        } else [self.window center];
    }
    [self load];
    [self.window orderFront:nil];
}

- (void)selectionChanged:(NSNotification *)n
{
    if (n.object != self.preview || !self.window.isVisible) return;
    for (int c = 0; c < 4; c++) _sel[c] = 0;
    [self load];
}

/* the four curves of the marquee (FitState tone_master + tone_rgb) */
- (uint8_t *)curve:(ESAdjust *)a channel:(int)c
{
    FitState *st = a.st;
    return c == 0 ? st->tone_master : st->tone_rgb + (c - 1) * TC_SIZE;
}

- (void)getCurves:(ESAdjust *)a into:(uint8_t *)out
{
    for (int c = 0; c < 4; c++) memcpy(out + c * TC_SIZE, [self curve:a channel:c], TC_SIZE);
}

- (void)setCurves:(const uint8_t *)in on:(ESAdjust *)a
{
    for (int c = 0; c < 4; c++) memcpy([self curve:a channel:c], in + c * TC_SIZE, TC_SIZE);
}

- (BOOL)isPreset:(NSString *)name
{
    for (int i = 0; i < TC_PRESETS; i++) if ([name isEqualToString:@(tc_preset_name(i))]) return YES;
    return NO;
}

- (NSDictionary *)userCurveNamed:(NSString *)name
{
    for (NSDictionary *d in ESToneStoreLoad()) if ([d[@"name"] isEqualToString:name]) return d;
    return nil;
}

/* the marquee's curves as a ToneCurveInfo record named `name` */
- (EsToneCurve)record:(ESAdjust *)a name:(NSString *)name
{
    EsToneCurve e;
    memset(&e, 0, sizeof e);
    [name getCString:e.name maxLength:sizeof e.name encoding:NSMacOSRomanStringEncoding];
    [self getCurves:a into:&e.curves[0][0]];
    for (int c = 0; c < 4; c++) e.selected[c] = _sel[c] < 0 ? 0 : _sel[c];
    return e;
}

/* CToneCurve::CompareCurrentSetting: are the marquee's curves the saved ones? */
- (BOOL)sameAsSaved:(ESAdjust *)a name:(NSString *)name
{
    NSDictionary *d = [self userCurveNamed:name];
    if (!d || !a) return NO;
    const EsToneCurve *e = [d[@"curve"] bytes];
    for (int c = 0; c < 4; c++) if (!tc_equal(e->curves[c], [self curve:a channel:c])) return NO;
    return YES;
}

/* CanSaveToneName: not empty, not a preset, not "Current Setting" or "Auto", not the
 * current curve unchanged, not starting with a space; at most 32 Mac Roman characters */
- (BOOL)canSaveName:(NSString *)n
{
    ESAdjust *a = [self.preview selectedAdjust];
    if (!n.length || [self isPreset:n] || [n isEqualToString:kToneCurrent] || [n isEqualToString:kToneAuto]) return NO;
    if ([n hasPrefix:@" "]) return NO;
    char buf[0x24];
    if (![n getCString:buf maxLength:sizeof buf - 3 encoding:NSMacOSRomanStringEncoding]) return NO;
    if ([n isEqualToString:a.toneName] && [self sameAsSaved:a name:n]) return NO;
    return YES;
}

/* the name list: presets, saved curves, then the marquee's own entry if it's none of those */
- (NSArray<NSString *> *)names:(ESAdjust *)a
{
    NSMutableArray *n = [NSMutableArray array];
    for (int i = 0; i < TC_PRESETS; i++) [n addObject:@(tc_preset_name(i))];
    for (NSDictionary *d in ESToneStoreLoad()) [n addObject:d[@"name"]];
    if (a.toneName.length && ![n containsObject:a.toneName]) [n addObject:a.toneName];
    return n;
}

- (void)load
{
    ESAdjust *a = [self.preview selectedAdjust];
    for (int k = 0; k < 4; k++) ESSetOn([self ctl:[NSString stringWithFormat:@"ch%d", k]], k == self.channel);
    static NSString *const hg[4] = { @"pict_3019.png", @"pict_3020.png", @"pict_3021.png", @"pict_3022.png" };
    static NSString *const vg[4] = { @"pict_3015.png", @"pict_3016.png", @"pict_3017.png", @"pict_3018.png" };
    NSImageView *h = (NSImageView *)[self ctl:@"hgrad"], *v = (NSImageView *)[self ctl:@"vgrad"];
    if ([h isKindOfClass:[NSImageView class]]) h.image = ESArt(hg[self.channel]);
    if ([v isKindOfClass:[NSImageView class]]) v.image = ESArt(vg[self.channel]);

    NSArray *names = [self names:a];
    NSView *pop = [self ctl:@"tonePopup"];
    if ([pop isKindOfClass:[AQControl class]]) {
        ((AQControl *)pop).menuItems = names;
        ((AQControl *)pop).text = @"";
        [pop setNeedsDisplay:YES];
    } else if ([pop isKindOfClass:[NSPopUpButton class]]) {
        NSPopUpButton *pb = (NSPopUpButton *)pop;
        [pb removeAllItems];
        [pb addItemWithTitle:@""];
        [pb addItemsWithTitles:names];
        for (NSMenuItem *it in pb.itemArray) it.state = [it.title isEqualToString:a.toneName] ? NSControlStateValueOn : NSControlStateValueOff;
    }
    NSTextField *nameField = (NSTextField *)[self ctl:@"toneName"];
    if ([nameField isKindOfClass:[NSTextField class]] && nameField.currentEditor == nil)
        nameField.stringValue = a.toneName ?: @"";
    [self updateButtons];

    ESToneView *tv = (ESToneView *)[self ctl:@"toneView"];
    if (a) {
        uint8_t cv[4 * TC_SIZE];
        [self getCurves:a into:cv];
        tv.curves = [NSData dataWithBytes:cv length:sizeof cv];
        int n = tc_count(cv + self.channel * TC_SIZE);
        if (_sel[self.channel] >= n) _sel[self.channel] = n - 1;
    } else tv.curves = nil;
    tv.channel = self.channel;
    tv.selected = _sel[self.channel];
    [tv setNeedsDisplay:YES];
    [self updateEdits:a];
}

/* CToneCorrectionDialog::UpdateEditBox: the selected point */
- (void)updateEdits:(ESAdjust *)a
{
    int x = 0, y = 0, i = _sel[self.channel];
    if (a && i >= 0) tc_point([self curve:a channel:self.channel], i, &x, &y);
    ESSetField([self ctl:@"tcIn"], a && i >= 0 ? [NSString stringWithFormat:@"%d", x] : @"");
    ESSetField([self ctl:@"tcOut"], a && i >= 0 ? [NSString stringWithFormat:@"%d", y] : @"");
}

- (void)controlTextDidChange:(NSNotification *)n { [self updateButtons]; }

/* UpdateSaveDeleteButton: Save for a new name, Delete for a saved curve */
- (void)updateButtons
{
    NSString *n = ESValue([self ctl:@"toneName"]);
    ESAdjust *a = [self.preview selectedAdjust];
    /* CanSaveButton: a valid name, and not a saved curve that is unchanged */
    ESSetEnabled([self ctl:@"toneSave"], a && [self canSaveName:n] && ![self sameAsSaved:a name:n]);
    ESSetEnabled([self ctl:@"toneDelete"], a && [self userCurveNamed:n] != nil);
}

- (void)commit:(ESAdjust *)a
{
    [self.preview adjustmentsChanged];
    [self load];
}

/* OnAddUserSetting: editing a preset (or the auto / current curve) makes it "User Defined" */
- (void)beginEdit:(ESAdjust *)a
{
    if ([self isPreset:a.toneName] || [a.toneName isEqualToString:kToneCurrent] || [a.toneName isEqualToString:kToneAuto] ||
        !a.toneName.length)
        a.toneName = kToneUser;
}

/* CToneCurvePaintCtrl::OnMouseDown / OnMouseMove / OnMouseUp */
- (void)mouse:(int)phase ctrlX:(int)cx x:(int)x y:(int)y
{
    ESAdjust *a = [self.preview selectedAdjust];
    if (!a) return;
    uint8_t *ic = [self curve:a channel:self.channel];
    int n = tc_count(ic);
    if (phase == 0) {
        [self beginEdit:a];
        int hit = -1;
        for (int k = 0; k < n && hit < 0; k++) {                 /* GetFixedPointIndexFromXAxis: +-10 px */
            int px, py; tc_point(ic, k, &px, &py);
            int pcx = (int)(px * 171.0 / 255.0 - 1.0);
            if (cx >= pcx - 10 && cx < pcx + 10) hit = k;
        }
        if (n < TC_MAX) {
            if (hit < 0) {                                       /* GetToInsertFixedPointIndexFromXAxis */
                hit = n;
                for (int k = 0; k < n; k++) {
                    int px, py; tc_point(ic, k, &px, &py);
                    if (cx < (int)(px * 171.0 / 255.0 - 1.0)) { hit = k; break; }
                }
                tc_insert(ic, hit, x, y);
            }
        } else if (hit < 0) {                                    /* GetNearestFixedPointIndexFromXAxis */
            int best = 0xab;
            for (int k = 0; k < n; k++) {
                int px, py; tc_point(ic, k, &px, &py);
                int d = abs(cx - (int)(px * 171.0 / 255.0 - 1.0));
                if (d < best) { best = d; hit = k; }
            }
        }
        if (hit < 0) hit = 0;
        self.dragIndex = hit;
        _sel[self.channel] = hit;
        tc_set(ic, hit, x, y);
        int lo, hi; tc_survival(ic, hit, &lo, &hi);
        self.dragLo = lo; self.dragHi = hi;
        [self commit:a];
    } else if (phase == 1) {
        if (x >= self.dragLo && x <= self.dragHi) {
            if (_sel[self.channel] == -1) {                      /* dragged back in: put the point back */
                tc_insert(ic, self.dragIndex, x, y);
                _sel[self.channel] = self.dragIndex;
            }
            tc_set(ic, _sel[self.channel], x, y);
            [self commit:a];
        } else if (tc_count(ic) < 3) {                           /* the two end points stay */
            int s = _sel[self.channel];
            if (x < self.dragLo && s == 1) { tc_set(ic, s, self.dragLo, y); [self commit:a]; }
            else if (x > self.dragHi && s == 0) { tc_set(ic, s, self.dragHi, y); [self commit:a]; }
        } else if (_sel[self.channel] != -1) {                   /* dragged out sideways: removed */
            if (tc_remove(ic, self.dragIndex)) {
                _sel[self.channel] = -1;
                [self commit:a];
            }
        }
    } else {
        if (_sel[self.channel] == -1) { _sel[self.channel] = 0; [self load]; }
    }
}

- (void)textEntered:(NSTextField *)t
{
    ESAdjust *a = [self.preview selectedAdjust];
    if ([t.identifier isEqualToString:@"toneName"]) { [self updateButtons]; return; }
    if (!a) return;
    int i = _sel[self.channel];
    uint8_t *ic = [self curve:a channel:self.channel];
    if (i < 0 || i >= tc_count(ic)) return;
    int x, y;
    tc_point(ic, i, &x, &y);
    int nx = [t.identifier isEqualToString:@"tcIn"] ? t.intValue : x;
    int ny = [t.identifier isEqualToString:@"tcOut"] ? t.intValue : y;
    if (nx == x && ny == y) return;
    [self beginEdit:a];
    tc_set(ic, i, nx, ny);                                       /* OnToneEditValueChanged */
    [self commit:a];
}

/* OnIDC_COMBO_TONECURVE_NAMESelChange */
- (void)pick:(NSString *)name
{
    ESAdjust *a = [self.preview selectedAdjust];
    if (!a || !name.length) { [self load]; return; }
    uint8_t cv[4][TC_SIZE];
    BOOL found = NO;
    for (int i = 0; i < TC_PRESETS && !found; i++)
        if ([name isEqualToString:@(tc_preset_name(i))]) { tc_preset(i, cv); found = YES; }
    int savedSel[4] = { 0, 0, 0, 0 };
    if (!found) {
        NSDictionary *d = [self userCurveNamed:name];
        if (d) {
            const EsToneCurve *e = [d[@"curve"] bytes];
            memcpy(cv, e->curves, sizeof cv);
            for (int c = 0; c < 4; c++) savedSel[c] = e->selected[c];
            found = YES;
        }
    }
    if (found) {
        [self setCurves:&cv[0][0] on:a];
        a.toneName = name;
        for (int c = 0; c < 4; c++) _sel[c] = savedSel[c];
        NSTextField *nf = (NSTextField *)[self ctl:@"toneName"];
        if ([nf isKindOfClass:[NSTextField class]]) { [nf abortEditing]; nf.stringValue = name; }
        [self commit:a];
    } else [self load];                                          /* the marquee's own entry: nothing to load */
}

- (void)confirm:(NSString *)text then:(void (^)(void))block
{
    NSAlert *al = [NSAlert new];
    al.messageText = @"Tone Correction";
    al.informativeText = text;
    [al addButtonWithTitle:@"OK"];
    [al addButtonWithTitle:@"Cancel"];
    [al beginSheetModalForWindow:self.window completionHandler:^(NSModalResponse r) {
        if (r == NSAlertFirstButtonReturn) block();
    }];
}

/* OnIDC_SAVEClicked + SaveToneCurve + CToneCurve::SaveUserToneCurve */
- (void)save
{
    ESAdjust *a = [self.preview selectedAdjust];
    NSString *n = ESValue([self ctl:@"toneName"]);
    if (!a || ![self canSaveName:n] || [self sameAsSaved:a name:n]) { NSBeep(); return; }
    NSMutableArray *all = ESToneStoreLoad();
    NSUInteger at = [all indexOfObjectPassingTest:^BOOL(NSDictionary *d, NSUInteger i, BOOL *stop) {
        return [d[@"name"] isEqualToString:n];
    }];
    if (at == NSNotFound && all.count >= TONU_MAX_USER) { NSBeep(); return; }
    EsToneCurve e = [self record:a name:n];
    NSDictionary *entry = @{ @"name": n, @"curve": [NSData dataWithBytes:&e length:sizeof e] };
    void (^store)(void) = ^{
        NSMutableArray *list = ESToneStoreLoad();
        NSUInteger i = [list indexOfObjectPassingTest:^BOOL(NSDictionary *d, NSUInteger k, BOOL *stop) {
            return [d[@"name"] isEqualToString:n];
        }];
        if (i == NSNotFound) [list addObject:entry];       /* AddToneCurveInfo: at the end */
        else list[i] = entry;                              /* ApplyCurrentToneCurve: in place */
        if (!ESToneStoreSave(list)) {
            NSAlert *al = [NSAlert new];
            al.messageText = @"Tone Correction";
            al.informativeText = @"The tone curve couldn't be saved to the EPSON Scan preferences file.";
            [al beginSheetModalForWindow:self.window completionHandler:nil];
            return;
        }
        a.toneName = n;
        [self load];
    };
    if (at != NSNotFound)                                  /* STR# 5009 #3 */
        [self confirm:[NSString stringWithFormat:ESS_IMAGECONTROL_5009_3, n]
                 then:store];
    else store();
}

/* OnIDC_DELClicked: delete, then the list's first entry (Linear) is applied */
- (void)deleteCurve
{
    NSString *n = ESValue([self ctl:@"toneName"]);
    if (![self userCurveNamed:n]) { NSBeep(); return; }
    [self confirm:[NSString stringWithFormat:ESS_UI_10008_15, n] then:^{      /* STR# 5009 #4 */
        NSMutableArray *all = ESToneStoreLoad();
        [all filterUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *d, NSDictionary *b) {
            return ![d[@"name"] isEqualToString:n];
        }]];
        ESToneStoreSave(all);
        [self pick:@(tc_preset_name(0))];
    }];
}

- (void)perform:(NSString *)action
{
    if ([action hasPrefix:@"tc:ch"]) {
        self.channel = [action substringFromIndex:5].intValue;
        [self load];
    } else if ([action isEqualToString:@"tc:pick"]) {
        [self pick:ESValue([self ctl:@"tonePopup"])];
    } else if ([action isEqualToString:@"tc:save"]) [self save];
    else if ([action isEqualToString:@"tc:delete"]) [self deleteCurve];
    else if ([action isEqualToString:@"tc:close"]) [self.window orderOut:nil];
    else if ([action isEqualToString:@"tc:reset"]) {
        /* OnReset -> host ResetToneCurve: every channel back to a straight line */
        self.channel = 0;
        [self pick:@(tc_preset_name(0))];
    } else if ([action isEqualToString:@"tc:help"]) NSBeep();
    else if ([action isEqualToString:@"dlg:tonecurve"]) [self load];
    else if (self.onAction) self.onAction(action);
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark - Color Palette dialog (Image Control plug-in, DLOG 1003)

/* the palette colours Epson keeps between sessions: 'CPST' 10000 "Color Palette Setting" in
 * the main prefs file (CUIPrefsBase::Get/SetColorPaletteSetting), big-endian (EPFlipColorPaletteSetting):
 * int32 r, g, b (current colour), int16 count, count x int32 r, g, b (the saved colours) */
#define CPST 0x43505354u
static BOOL ESPaletteLoad(int cur[3], int store[9][3])
{
    for (int c = 0; c < 3; c++) cur[c] = 0xc0;                 /* the default record in Epson's resources */
    for (int i = 0; i < 9; i++) for (int c = 0; c < 3; c++) store[i][c] = 0xc0;
    uint8_t *d = NULL;
    uint32_t len = 0;
    if (rsrc_get(ESEpsonPrefsPath(@"EPSON Scan Prefs", NO).fileSystemRepresentation, CPST, 10000, &d, &len) != 1) return NO;
    BOOL ok = NO;
    if (len >= 14) {
        for (int c = 0; c < 3; c++) cur[c] = (int32_t)OSReadBigInt32(d, 4 * c);
        int n = (int16_t)OSReadBigInt16(d, 12);
        for (int i = 0; i < n && i < 9 && 14u + 12u * (uint32_t)i + 12 <= len; i++)
            for (int c = 0; c < 3; c++) store[i][c] = (int32_t)OSReadBigInt32(d, 14 + 12 * i + 4 * c);
        ok = YES;
    }
    free(d);
    return ok;
}

static BOOL ESPaletteSave(const int cur[3], const int store[9][3])
{
    uint8_t d[14 + 12 * 9];
    for (int c = 0; c < 3; c++) OSWriteBigInt32(d, 4 * c, (uint32_t)cur[c]);
    OSWriteBigInt16(d, 12, 9);
    for (int i = 0; i < 9; i++) for (int c = 0; c < 3; c++) OSWriteBigInt32(d, 14 + 12 * i + 4 * c, (uint32_t)store[i][c]);
    return rsrc_put(ESEpsonPrefsPath(@"EPSON Scan Prefs", YES).fileSystemRepresentation, CPST, 10000,
                    "Color Palette Setting", d, sizeof d) == 0;
}

/* CColorPaletteDialog */
@interface ESPaletteDialog : NSObject
@property (nonatomic, strong) NSPanel *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic, weak) ESPreviewWindow *preview;
@property (nonatomic, copy) void (^onAction)(NSString *action);
@property (nonatomic, weak) ESAdjust *pointAdjust;      /* marquee the pipette point belongs to */
@property (nonatomic, strong) NSData *snapshot;          /* GetParameter(10): the marquee's FitState at the pipette */
@property (nonatomic, strong) NSData *snapshotCoef;      /* ... and its colour coefficients */
@property (nonatomic) BOOL resetEnabled;
- (instancetype)initWithPreview:(ESPreviewWindow *)preview;
- (void)rebuild;
- (void)show;
- (void)savePrefs;
@end

@implementation ESPaletteDialog {
    int _cur[3];
    int _store[9][3];
    int _point[3];                                          /* the pipette point, gamma-1.8 0..255 */
}

- (NSDictionary *)layout
{
    NSString *path = [[NSBundle mainBundle] pathForResource:@"colorpalette" ofType:@"json"];
    NSData *d = [NSData dataWithContentsOfFile:path];
    return d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : @{};
}

- (instancetype)initWithPreview:(ESPreviewWindow *)preview
{
    if ((self = [super init])) {
        self.preview = preview;
        ESPaletteLoad(_cur, _store);                        /* CMainDialog: read at start-up */
        NSDictionary *w = [self layout][@"window"];
        self.window = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])
                                                 styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                           NSWindowStyleMaskUtilityWindow
                                                   backing:NSBackingStoreBuffered defer:NO];
        self.window.title = w[@"title"] ?: @"Color Palette";
        self.window.releasedWhenClosed = NO;
        self.window.hidesOnDeactivate = NO;
        self.window.floatingPanel = YES;
        self.window.becomesKeyOnlyIfNeeded = YES;
        [self rebuild];
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(windowClosing:)
                                                   name:NSWindowWillCloseNotification object:self.window];
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(selectionChanged:)
                                                   name:ESSelectionChanged object:preview];
    }
    return self;
}

- (void)dealloc { [NSNotificationCenter.defaultCenter removeObserver:self]; }

- (NSView *)ctl:(NSString *)key { return self.builder.controls[key]; }

- (void)rebuild
{
    NSDictionary *L = [self layout];
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    NSInteger sel = ((ESColorStoreView *)[self ctl:@"store"]).selected;
    self.builder = [ESBuilder new];
    self.builder.native = native;
    NSDictionary *w = L[@"window"];
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, [w[@"width"] doubleValue],
                                                                          [w[@"height"] doubleValue])];
    root.wantsLayer = YES;
    root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor
                                        : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    [self.builder build:L[@"items"] into:root];
    self.window.contentView = root;
    __weak ESPaletteDialog *weakSelf = self;
    self.builder.onAction = ^(NSString *a) { [weakSelf perform:a]; };
    ((ESPaletteView *)[self ctl:@"palette"]).onPick = ^(const int rgb[3]) { [weakSelf change:rgb apply:YES]; };
    ESColorStoreView *st = (ESColorStoreView *)[self ctl:@"store"];
    st.selected = sel;
    for (int i = 0; i < 9; i++) [st setColor:_store[i] at:i];
    st.onSelect = ^(NSInteger i) { };
    ESSetEnabled([self ctl:@"dlg:palette"], NO);
    for (NSString *k in @[ @"palR", @"palG", @"palB" ]) {
        NSTextField *t = (NSTextField *)[self ctl:k];
        if (![t isKindOfClass:[NSTextField class]]) continue;
        t.identifier = k;
        t.alignment = NSTextAlignmentRight;
        t.target = self;
        t.action = @selector(textEntered:);
        t.cell.sendsActionOnEndEditing = YES;
    }
    [self load];
}

- (void)show
{
    if (!self.window.isVisible) {
        NSWindow *pw = self.preview.window;
        if (pw.isVisible) {
            NSRect f = self.window.frame;
            f.origin = NSMakePoint(NSMaxX(pw.frame) - f.size.width - 20, NSMaxY(pw.frame) - f.size.height - 40);
            [self.window setFrame:f display:NO];
        } else [self.window center];
    }
    [self load];
    [self.window orderFront:nil];
}

/* DoDataExchange(0) */
- (void)load
{
    [(ESPaletteView *)[self ctl:@"palette"] setColor:_cur];
    [self showRGB];
    ESSetEnabled([self ctl:@"cpReset"], self.resetEnabled && [self pointValid]);
}

- (void)showRGB
{
    ESSetField([self ctl:@"palR"], [NSString stringWithFormat:@"%d", _cur[0]]);
    ESSetField([self ctl:@"palG"], [NSString stringWithFormat:@"%d", _cur[1]]);
    ESSetField([self ctl:@"palB"], [NSString stringWithFormat:@"%d", _cur[2]]);
}

/* IsPipettePointEnable: a point picked on the marquee being adjusted */
- (BOOL)pointValid
{
    ESAdjust *a = [self.preview selectedAdjust];
    return a && a == self.pointAdjust && self.snapshot.length == sizeof(FitState);
}

/* CColorPaletteDialog::ChangeColorPalette */
- (void)change:(const int *)rgb apply:(BOOL)apply
{
    int c[3];
    for (int k = 0; k < 3; k++) c[k] = MAX(0, MIN(255, rgb[k]));
    ESPaletteView *pv = (ESPaletteView *)[self ctl:@"palette"];
    int shown[3];
    [pv getColor:shown];
    if (memcmp(shown, c, sizeof c)) [pv setColor:c];
    memcpy(_cur, c, sizeof c);
    [self showRGB];
    if ([self pointValid] && apply) {
        [self adjustTo:c];
        self.resetEnabled = YES;
        ESSetEnabled([self ctl:@"cpReset"], YES);
    }
}

/* CHostIF::AdjustColorPaletteParam -> CFitIF::DoConvertColorPalette */
- (void)adjustTo:(const int *)target
{
    ESAdjust *a = [self.preview selectedAdjust];
    if (!a || self.snapshot.length != sizeof(FitState)) return;
    const FitState *snap = self.snapshot.bytes;
    FitState work = *a.st;
    memcpy(work.para + 0x08, snap->para + 0x08, 4);          /* screen gamma */
    memcpy(work.para + 0x0c, snap->para + 0x0c, 15 * 4);     /* levels at the pipette */
    memcpy(work.para + 0x4c, snap->para + 0x4c, 8);          /* brightness, contrast */
    memcpy(work.para + 0x54, snap->para + 0x54, 12);         /* colour balance */
    memcpy(work.tone_master, snap->tone_master, sizeof work.tone_master);   /* tone curves at the pipette */
    memcpy(work.tone_rgb, snap->tone_rgb, sizeof work.tone_rgb);
    char err[256];
    int rc = fit_state_adjust_color(ESFitEngine().fileSystemRepresentation, &work, _point, target,
                                    kRedMatrix[a.profile], self.snapshotCoef.bytes, err, sizeof err);
    if (rc) { NSLog(@"Color Palette: %s", err); return; }
    memcpy(a.st->para + 0x0c, work.para + 0x0c, 15 * 4);     /* marquee +0x7c..+0xb4 */
    [self.preview adjustmentsChanged];
}

/* CHostIF::ConvertPreviewRGB: how the point looks now (table, then colour matrix) */
- (void)displayed:(int *)out
{
    ESAdjust *a = [self.preview selectedAdjust];
    const uint8_t *L = a.lut.bytes;
    const double *M = a.coef.bytes;
    if (!L || !M) { memcpy(out, _point, 3 * sizeof(int)); return; }
    double v[3] = { L[_point[0]], L[256 + _point[1]], L[512 + _point[2]] };
    for (int c = 0; c < 3; c++) {
        double r = M[c * 3] * v[0] + M[c * 3 + 1] * v[1] + M[c * 3 + 2] * v[2];
        r = r > 255 ? 255 : r < 0 ? 0 : r;
        out[c] = (int)(r + 0.5);
    }
}

/* the two pipettes: Get takes the colour from the image, Set applies the palette colour there */
- (void)pipette:(BOOL)apply
{
    __weak ESPaletteDialog *weakSelf = self;
    ESPreviewWindow *pv = self.preview;
    [pv pickWith:^(NSPoint pt) {
        ESPaletteDialog *me = weakSelf;
        ESAdjust *a = [pv selectedAdjust];
        int rgb[3];
        if (!me || !a || ![pv sampleAt:pt rgb:rgb]) return;
        for (int c = 0; c < 3; c++) me->_point[c] = rgb[c] / 0x101;
        me.snapshot = [NSData dataWithBytes:a.st length:sizeof(FitState)];   /* GetUIColorPaletteParameter */
        me.snapshotCoef = a.coef;
        me.pointAdjust = a;
        if (apply) {                                         /* OnIDC_BUTTON_SET_PALETTE_SPOITOClicked */
            me.resetEnabled = YES;
            ESSetEnabled([me ctl:@"cpReset"], YES);
            [me adjustTo:me->_cur];
        } else {                                             /* OnIDC_BUTTON_GET_PALETTE_SPOITOClicked */
            me.resetEnabled = NO;
            ESSetEnabled([me ctl:@"cpReset"], NO);
            int col[3];
            [me displayed:col];
            [me change:col apply:NO];
        }
    }];
}

- (void)textEntered:(NSTextField *)t
{
    int c[3];
    memcpy(c, _cur, sizeof c);
    int k = [t.identifier isEqualToString:@"palR"] ? 0 : [t.identifier isEqualToString:@"palG"] ? 1 : 2;
    int v = MAX(0, MIN(255, t.intValue));
    if (v == c[k]) { [self showRGB]; return; }
    c[k] = v;
    [self change:c apply:YES];                               /* OnIndicatorValueChanged */
}

- (void)perform:(NSString *)action
{
    ESColorStoreView *st = (ESColorStoreView *)[self ctl:@"store"];
    if ([action isEqualToString:@"cp:get"]) [self pipette:NO];
    else if ([action isEqualToString:@"cp:set"]) [self pipette:YES];
    else if ([action isEqualToString:@"cp:save"]) {           /* OnIDC_BUTTON_COLOR_SAVEClicked */
        [st setColor:_cur at:st.selected];
        memcpy(_store[st.selected], _cur, sizeof _cur);
        st.selected = st.selected < 8 ? st.selected + 1 : 0; /* CColorStore::SelectColor(): next, wrapping */
        [st setNeedsDisplay:YES];
    } else if ([action isEqualToString:@"cp:load"]) {         /* OnIDC_BUTTON_COLOR_LOADClicked */
        int c[3];
        [st getColor:c at:st.selected];
        [self change:c apply:YES];
    } else if ([action isEqualToString:@"cp:reset"]) {        /* OnIDC_BUTTON_PALETTE_RESETClicked */
        self.resetEnabled = NO;
        ESSetEnabled([self ctl:@"cpReset"], NO);
        ESAdjust *a = [self.preview selectedAdjust];
        if (![self pointValid]) return;
        const FitState *snap = self.snapshot.bytes;
        memcpy(a.st->para + 0x0c, snap->para + 0x0c, 15 * 4);   /* CHostIF::SetParameter(10) */
        [self.preview adjustmentsChanged];
        int col[3];
        [self displayed:col];
        [self change:col apply:NO];
    } else if ([action isEqualToString:@"cp:close"]) [self.window orderOut:nil];
    else if ([action isEqualToString:@"cp:help"]) NSBeep();
    else if ([action isEqualToString:@"dlg:palette"]) [self load];
    else if (self.onAction) self.onAction(action);
    if ([action isEqualToString:@"cp:close"]) [self savePrefs];
}

- (void)windowClosing:(NSNotification *)n { [self savePrefs]; }

/* another marquee: the pipette point belongs to the old one */
- (void)selectionChanged:(NSNotification *)n
{
    if (![self pointValid]) self.resetEnabled = NO;
    if (self.window.isVisible) [self load];
}

/* CloseDialog -> SetUIColorPaletteData; WriteColorPaletteSetting */
- (void)savePrefs
{
    if (!ESPaletteSave(_cur, (const int (*)[3])_store)) NSLog(@"Color Palette: couldn't write the EPSON Scan Prefs file");
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark - Target Size dialog ("Customize...", CTargetSizeDialog, DLOG 10500)

static NSString *ESNumber(double v, int decimals);

/* the user's target sizes: 'TSIZ' 10000 "TargetSize" in the Professional Mode prefs (CADPrefs ->
 * EPSON Scan AD Prefs). Big-endian count, then 0xa6-byte records of Pascal strings:
 * name (0x40), width (0x22), height (0x22), unit (0x22; 0 pixels, 1 mm, 2 in.) */
#define TSIZ 0x5453495Au
static const double kUserLimit[3][2] = { { 25, 30000 }, { 2.5, 15240 }, { 0.1, 600 } };   /* _LimitValue */

static NSString *ESPString(const uint8_t *p, size_t cap)
{
    size_t n = p[0] < cap ? p[0] : cap - 1;
    return [[NSString alloc] initWithBytes:p + 1 length:n encoding:NSMacOSRomanStringEncoding] ?: @"";
}

static void ESPutPString(uint8_t *p, size_t cap, NSString *s)
{
    NSData *d = [s dataUsingEncoding:NSMacOSRomanStringEncoding allowLossyConversion:YES] ?: [NSData data];
    size_t n = MIN(d.length, cap - 1);
    p[0] = (uint8_t)n;
    memcpy(p + 1, d.bytes, n);
}

static NSArray<NSDictionary *> *ESUserTargetsLoad(void)
{
    NSMutableArray *out = [NSMutableArray array];
    uint8_t *d = NULL;
    uint32_t len = 0;
    if (rsrc_get(ESAdvancedPrefsPath(NO).fileSystemRepresentation, TSIZ, 10000, &d, &len) != 1) return out;
    int n = len >= 2 ? (int16_t)OSReadBigInt16(d, 0) : 0;
    for (int i = 0; i < n && 2u + 0xa6u * (uint32_t)(i + 1) <= len; i++) {
        const uint8_t *r = d + 2 + 0xa6 * i;
        [out addObject:@{ @"name": ESPString(r, 0x40), @"w": @(ESPString(r + 0x40, 0x22).doubleValue),
                          @"h": @(ESPString(r + 0x62, 0x22).doubleValue), @"unit": @(ESPString(r + 0x84, 0x22).intValue) }];
    }
    free(d);
    return out;
}

static BOOL ESUserTargetsSave(NSArray<NSDictionary *> *list)
{
    const char *file = ESAdvancedPrefsPath(YES).fileSystemRepresentation;
    if (!list.count) return rsrc_put(file, TSIZ, 10000, NULL, NULL, 0) == 0;
    size_t len = 2 + 0xa6 * list.count;
    uint8_t *d = calloc(len, 1);
    OSWriteBigInt16(d, 0, (uint16_t)list.count);
    for (NSUInteger i = 0; i < list.count; i++) {
        uint8_t *r = d + 2 + 0xa6 * i;
        NSDictionary *e = list[i];
        int unit = [e[@"unit"] intValue];
        ESPutPString(r, 0x40, e[@"name"]);
        ESPutPString(r + 0x40, 0x22, ESNumber([e[@"w"] doubleValue], est_decimals(unit)));
        ESPutPString(r + 0x62, 0x22, ESNumber([e[@"h"] doubleValue], est_decimals(unit)));
        ESPutPString(r + 0x84, 0x22, [NSString stringWithFormat:@"%d", unit]);
    }
    BOOL ok = rsrc_put(file, TSIZ, 10000, "TargetSize", d, (uint32_t)len) == 0;
    free(d);
    return ok;
}

@interface ESTargetSizeDialog : NSObject <NSTableViewDataSource, NSTableViewDelegate>
@property (nonatomic, strong) NSPanel *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic, strong) NSTableView *table;
@property (nonatomic, strong) NSMutableArray<NSDictionary *> *list;
@property (nonatomic) NSInteger result;              /* chosen entry, -1 = Cancel */
@property (nonatomic) BOOL edited;                   /* this+0x146: the fields differ from the entry */
@property (nonatomic) int unit;                      /* this+0x140 */
- (NSInteger)runSelecting:(NSInteger)index;
@end

@implementation ESTargetSizeDialog

- (NSView *)ctl:(NSString *)k { return self.builder.controls[k]; }

- (NSInteger)runSelecting:(NSInteger)index
{
    NSString *path = [[NSBundle mainBundle] pathForResource:@"targetsize" ofType:@"json"];
    NSDictionary *L = [NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:path] options:0 error:nil];
    NSDictionary *w = L[@"window"];
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    self.window = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])
                                             styleMask:NSWindowStyleMaskTitled backing:NSBackingStoreBuffered defer:NO];
    self.window.title = w[@"title"];
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])];
    root.wantsLayer = YES;
    root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.builder = [ESBuilder new];
    self.builder.native = native;
    [self.builder build:L[@"items"] into:root];
    __weak ESTargetSizeDialog *weakSelf = self;
    self.builder.onAction = ^(NSString *a) { [weakSelf perform:a]; };
    for (NSDictionary *it in L[@"items"])
        if ([it[@"kind"] isEqualToString:@"list"]) {
            NSScrollView *sv = [[NSScrollView alloc] initWithFrame:ESRect(it[@"rect"])];
            sv.hasVerticalScroller = YES;
            sv.borderType = NSBezelBorder;
            self.table = [[NSTableView alloc] initWithFrame:sv.bounds];
            NSTableColumn *col = [[NSTableColumn alloc] initWithIdentifier:@"name"];
            col.width = sv.contentSize.width;
            [self.table addTableColumn:col];
            self.table.headerView = nil;
            self.table.rowHeight = 16;
            self.table.dataSource = self;
            self.table.delegate = self;
            if (@available(macOS 11.0, *)) self.table.style = NSTableViewStylePlain;
            sv.documentView = self.table;
            [root addSubview:sv];
        }
    for (NSString *k in @[ @"tsName", @"tsW", @"tsH" ]) {
        NSTextField *t = (NSTextField *)[self ctl:k];
        if (![t isKindOfClass:[NSTextField class]]) continue;
        t.identifier = k;
        t.target = self;
        t.action = @selector(fieldChanged:);
        t.cell.sendsActionOnEndEditing = YES;
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(textChanged:)
                                                   name:NSControlTextDidChangeNotification object:t];
    }
    self.window.contentView = root;
    self.list = [ESUserTargetsLoad() mutableCopy];
    [self.table reloadData];
    self.result = -1;
    if (index >= 0 && index < (NSInteger)self.list.count) {
        [self.table selectRowIndexes:[NSIndexSet indexSetWithIndex:(NSUInteger)index] byExtendingSelection:NO];
        [self show:self.list[(NSUInteger)index]];
    } else [self showDefaults];
    [self updateButtons];
    [self.window center];
    [NSApp runModalForWindow:self.window];
    [self.window orderOut:nil];
    [NSNotificationCenter.defaultCenter removeObserver:self];
    return self.result;
}

/* TSIZ 10001: the "User Defined" starting values */
- (void)showDefaults
{
    self.unit = EST_INCHES;
    ESSelectItem([self ctl:@"tsUnits"], @"in.");
    ESSetField([self ctl:@"tsName"], @"User Defined");
    ESSetField([self ctl:@"tsW"], @"8.27");
    ESSetField([self ctl:@"tsH"], @"11.69");
    self.edited = YES;
}

/* SetTargetSizeData */
- (void)show:(NSDictionary *)e
{
    self.unit = [e[@"unit"] intValue];
    ESSelectItem([self ctl:@"tsUnits"], self.unit == EST_PIXELS ? @"pixels" : self.unit == EST_MM ? @"mm" : @"in.");
    ESSetField([self ctl:@"tsName"], e[@"name"]);
    ESSetField([self ctl:@"tsW"], ESNumber([e[@"w"] doubleValue], est_decimals(self.unit)));
    ESSetField([self ctl:@"tsH"], ESNumber([e[@"h"] doubleValue], est_decimals(self.unit)));
    self.edited = NO;
}

- (NSInteger)numberOfRowsInTableView:(NSTableView *)t { return (NSInteger)self.list.count; }
- (id)tableView:(NSTableView *)t objectValueForTableColumn:(NSTableColumn *)c row:(NSInteger)r { return self.list[(NSUInteger)r][@"name"]; }
- (BOOL)tableView:(NSTableView *)t shouldEditTableColumn:(NSTableColumn *)c row:(NSInteger)r { return NO; }
- (void)tableViewSelectionDidChange:(NSNotification *)n            /* DoListClick */
{
    NSInteger r = self.table.selectedRow;
    if (r >= 0 && r < (NSInteger)self.list.count) [self show:self.list[(NSUInteger)r]];
    [self updateButtons];
}

/* InputDataCheck: empty -> the default, clamped to the unit's range, shown with its decimals */
- (double)checkField:(NSString *)key
{
    NSTextField *t = (NSTextField *)[self ctl:key];
    NSString *s = [ESValue(t) stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
    double v = s.length ? s.doubleValue : ([key isEqualToString:@"tsW"] ? 8.27 : 11.693);
    if (v < kUserLimit[self.unit][0]) { v = kUserLimit[self.unit][0]; self.edited = YES; }
    else if (v > kUserLimit[self.unit][1]) { v = kUserLimit[self.unit][1]; self.edited = YES; }
    ESSetField(t, ESNumber(v, est_decimals(self.unit)));
    return v;
}

- (void)textChanged:(NSNotification *)n { self.edited = YES; [self updateButtons]; }
- (void)fieldChanged:(NSTextField *)t
{
    if (![t.identifier isEqualToString:@"tsName"]) [self checkField:t.identifier];
    [self updateButtons];
}

- (NSString *)trimmedName
{
    NSString *n = ESValue([self ctl:@"tsName"]);
    while ([n hasSuffix:@" "]) n = [n substringToIndex:n.length - 1];      /* trailing blanks go */
    return n;
}

/* SetSaveButtonStatus / SetDeleteButtonStatus */
- (void)updateButtons
{
    NSString *name = [self trimmedName];
    BOOL canSave = name.length > 0 && ![name hasPrefix:@"-"] && ![name hasPrefix:@" "] &&
                   ESValue([self ctl:@"tsW"]).length && ESValue([self ctl:@"tsH"]).length;
    BOOL isPreset = NO;
    for (int i = 0; i < es_target_preset_count; i++)
        if ([name isEqualToString:@(es_target_presets[i].name)]) isPreset = YES;
    BOOL full = NO;
    if (self.list.count >= 50) {                                 /* 50 at most */
        full = YES;
        for (NSDictionary *e in self.list) if ([e[@"name"] isEqualToString:name]) full = NO;
    }
    NSInteger sel = self.table.selectedRow;
    if (isPreset || full) {
        ESSetEnabled([self ctl:@"tsSave"], NO);
        ESSetEnabled([self ctl:@"tsOK"], NO);
    } else {
        ESSetEnabled([self ctl:@"tsSave"], self.edited && canSave);
        ESSetEnabled([self ctl:@"tsOK"], self.list.count > 0 && sel >= 0);
    }
    ESSetEnabled([self ctl:@"tsDelete"], sel >= 0 && ESValue([self ctl:@"tsW"]).length && ESValue([self ctl:@"tsH"]).length);
}

- (BOOL)confirm:(NSString *)text
{
    NSAlert *a = [NSAlert new];
    a.messageText = @"EPSON Scan";
    a.informativeText = text;
    [a addButtonWithTitle:@"OK"];
    [a addButtonWithTitle:@"Cancel"];
    return [a runModal] == NSAlertFirstButtonReturn;
}

- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"ts:save"]) {                   /* DoSave */
        double w = [self checkField:@"tsW"], h = [self checkField:@"tsH"];
        if (self.unit == EST_MM) {                                /* as Epson: the mm minimum is stored as 2.54 */
            if (w == kUserLimit[EST_MM][0]) w = 2.54;
            if (h == kUserLimit[EST_MM][0]) h = 2.54;
        }
        NSString *name = [self trimmedName];
        NSDictionary *e = @{ @"name": name, @"w": @(w), @"h": @(h), @"unit": @(self.unit) };
        NSUInteger at = NSNotFound;
        for (NSUInteger i = 0; i < self.list.count; i++)
            if ([self.list[i][@"name"] caseInsensitiveCompare:name] == NSOrderedSame) at = i;
        if (at != NSNotFound) {
            if (![self confirm:[NSString stringWithFormat:ESS_UI_10008_14, self.list[at][@"name"]]]) return;
            self.list[at] = e;
        } else { [self.list addObject:e]; at = self.list.count - 1; }
        ESUserTargetsSave(self.list);
        [self.table reloadData];
        [self.table selectRowIndexes:[NSIndexSet indexSetWithIndex:at] byExtendingSelection:NO];
        self.edited = NO;
        [self updateButtons];
    } else if ([action isEqualToString:@"ts:delete"]) {          /* DoDelete */
        NSString *name = ESValue([self ctl:@"tsName"]);
        NSUInteger at = NSNotFound;
        for (NSUInteger i = 0; i < self.list.count; i++)
            if ([self.list[i][@"name"] caseInsensitiveCompare:name] == NSOrderedSame) at = i;
        if (at == NSNotFound) return;
        if (![self confirm:[NSString stringWithFormat:ESS_UI_10008_15, self.list[at][@"name"]]]) return;
        [self.list removeObjectAtIndex:at];
        ESUserTargetsSave(self.list);
        [self.table reloadData];
        if (self.list.count) {
            [self.table selectRowIndexes:[NSIndexSet indexSetWithIndex:0] byExtendingSelection:NO];
            [self show:self.list[0]];
        } else { [self.table deselectAll:nil]; [self showDefaults]; }
        [self updateButtons];
    } else if ([action isEqualToString:@"ts:units"]) {           /* DoUnitMenuClick: mm <-> in. convert, pixels clear */
        NSString *u = ESValue([self ctl:@"tsUnits"]);
        int nu = [u isEqualToString:@"pixels"] ? EST_PIXELS : [u isEqualToString:@"mm"] ? EST_MM : EST_INCHES;
        if (nu == self.unit) return;
        double w = ESValue([self ctl:@"tsW"]).doubleValue, h = ESValue([self ctl:@"tsH"]).doubleValue;
        BOOL have = ESValue([self ctl:@"tsW"]).length && ESValue([self ctl:@"tsH"]).length;
        int old = self.unit;
        self.unit = nu;
        self.edited = YES;
        if (old != EST_PIXELS && nu != EST_PIXELS && have) {
            double k = nu == EST_MM ? 25.4 : 1 / 25.4;
            ESSetField([self ctl:@"tsW"], ESNumber(w * k, est_decimals(nu)));
            ESSetField([self ctl:@"tsH"], ESNumber(h * k, est_decimals(nu)));
            [self checkField:@"tsW"]; [self checkField:@"tsH"];
        } else { ESSetField([self ctl:@"tsW"], @""); ESSetField([self ctl:@"tsH"], @""); }
        [self updateButtons];
    } else if ([action isEqualToString:@"ts:ok"]) {
        self.result = self.table.selectedRow;
        [NSApp stopModal];
    } else if ([action isEqualToString:@"ts:cancel"]) {
        self.result = -1;
        [NSApp stopModal];
    }
}
@end

#pragma mark - File Save Settings

/* CESPrefs file-save values; defaults from ESPR 10000 ("img", 001, overwrite off, show this
 * dialog on, open folder on, Pictures) and the plug-ins (TIFF "MM", JPEG level 16, Standard). */
static NSString *const kFSRadio = @"FSLastSelectedRadio";      /* 0/2 Pictures, 1 Documents, 3 Other */
static NSString *const kFSOther = @"FSOthersFolder";
static NSString *const kFSPrefix = @"FSFilePrefix";
static NSString *const kFSStart = @"FSFileStartNumber";
static NSString *const kFSFormat = @"FSFormatType";            /* "JPEG (*.jpg)" / "TIFF (*.tif)" */
static NSString *const kFSOverwrite = @"FSFileOverwrite";
static NSString *const kFSShow = @"FSShowDialog";
static NSString *const kFSOpen = @"FSOpenFolder";
static NSString *const kFSAddPage = @"FSShowAddPageDialog";
static NSString *const kTIFFMM = @"TIFFByteOrderMacintosh";
static NSString *const kTIFFICC = @"TIFFEmbedICC";
static NSString *const kJPEGLevel = @"JPEGCompressionLevel";
static NSString *const kJPEGProg = @"JPEGProgressive";
static NSString *const kJPEGICC = @"JPEGEmbedICC";
static NSString *const kFormatJPEG = @"JPEG (*.jpg)", *const kFormatTIFF = @"TIFF (*.tif)";
static NSString *const kFormatMTIFF = @"Multi-TIFF (*.tif)";
static NSString *const kTIFFBWG4 = @"TIFFBWCompressionCCITT";     /* TIFF Compression > B&W: CCITT Group4 */
static NSString *const kMTIFFBWG4 = @"MTIFFBWCompressionCCITT";
static BOOL gImageIsBW;        /* the main window's Image Type is Black & White (the B&W menu is for it) */
static NSString *const kFormatPDF = @"PDF (*.pdf)";
/* the PICT and PRINT Image Matching II plug-ins (STR# in their Localized.rsrc) */
static NSString *const kFormatPICT = @"PICT(*.pct)";
static NSString *const kFormatPIMJ = @"EPSON EXIF&PRINT Image Matching II (JPEG) (*.jpg)";
static NSString *const kFormatPIMT = @"EPSON EXIF&PRINT Image Matching II (TIFF) (*.tif)";
/* EPSON PDF Plug-in (EPdf 10000 / EPSZ / EUNI / ECMP defaults): Actual Image Size, Portrait,
 * margins 0 in mm, all pages in one file, Standard Compression */
static NSString *const kPDFPaper = @"PDFPaperSize";
static NSString *const kPDFLandscape = @"PDFLandscape";
static NSString *const kPDFUnits = @"PDFUnits";
static NSString *const kPDFTop = @"PDFMarginTop";          /* in the units, like EPDFPREF_INFO +0x98 / 100 */
static NSString *const kPDFLeft = @"PDFMarginLeft";        /* +0x9c / 100 */
static NSString *const kPDFPageMode = @"PDFPageMode";      /* +0x132: 0 all pages, 1 every N pages */
static NSString *const kPDFPageNumber = @"PDFPageNumber";  /* +0x134 */
static NSString *const kPDFCompression = @"PDFCompression";
static NSString *const kMTIFFMM = @"MTIFFByteOrderMacintosh";   /* Emtf 10000 +0x46 "MM" */

static NSUserDefaults *ESFSPrefs(void)
{
    NSUserDefaults *ud = NSUserDefaults.standardUserDefaults;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        [ud registerDefaults:@{ kFSRadio: @0, kFSPrefix: @"img", kFSStart: @1, kFSFormat: kFormatJPEG,
                                kFSOverwrite: @0, kFSShow: @1, kFSOpen: @1, kFSAddPage: @1,
                                kTIFFMM: @1, kMTIFFMM: @1, kTIFFICC: @1, kPDFPaper: @"Actual Image Size", kPDFLandscape: @0,
                                kPDFUnits: @"mm", kPDFTop: @0, kPDFLeft: @0, kPDFPageMode: @0, kPDFPageNumber: @1,
                                kPDFCompression: @"Standard Compression", kJPEGLevel: @16, kJPEGProg: @0, kJPEGICC: @1 }];
    });
    return ud;
}

static BOOL ESFSIsTIFF(NSString *format) { return [format hasPrefix:@"TIFF"]; }
static BOOL ESFSIsMulti(NSString *format) { return [format hasPrefix:@"Multi-TIFF"]; }
static BOOL ESFSIsPDF(NSString *format) { return [format hasPrefix:@"PDF"]; }
static BOOL ESFSIsMultiPage(NSString *format) { return ESFSIsMulti(format) || ESFSIsPDF(format); }
static BOOL ESFSIsPICT(NSString *format) { return [format isEqualToString:kFormatPICT]; }
static BOOL ESFSIsPIM(NSString *format) { return [format hasPrefix:@"EPSON EXIF&PRINT Image Matching"]; }
static NSString *ESFSExtension(NSString *format)   /* STR# 2001 #3, PDF STR# 2002 #1 */
{
    if (ESFSIsPICT(format)) return @"pct";
    if ([format isEqualToString:kFormatPIMT]) return @"tif";
    return ESFSIsPDF(format) ? @"pdf" : ESFSIsTIFF(format) || ESFSIsMulti(format) ? @"tif" : @"jpg";
}

/* EPSZ 10002: name, size (in its units), inch flag; Actual Image Size is 0 x 0 */
static NSArray<NSArray *> *ESPdfPapers(void)
{
    return @[ @[ @"A5 (148 x 210 mm)", @148, @210, @0 ], @[ @"B5 (182 x 257 mm)", @182, @257, @0 ],
              @[ @"Letter (8 1/2 x 11 in.)", @8.5, @11, @1 ], @[ @"A4 (210 x 297 mm)", @210, @297, @0 ],
              @[ @"Legal (8 1/2 x 14 in.)", @8.5, @14, @1 ], @[ @"US B (11 x 17 in.)", @11, @17, @1 ],
              @[ @"B4 (257 x 364 mm)", @257, @364, @0 ], @[ @"A3 (297 x 420 mm)", @297, @420, @0 ],
              @[ @"Actual Image Size", @0, @0, @0 ] ];
}

/* CPdf: the paper in 1/10 mm, 0 x 0 for Actual Image Size */
static void ESPdfPaper10(NSString *name, int *w10, int *h10)
{
    *w10 = *h10 = 0;
    for (NSArray *p in ESPdfPapers())
        if ([p[0] isEqualToString:name]) {
            double k = [p[3] boolValue] ? 254.0 : 10.0;
            *w10 = (int)lround([p[1] doubleValue] * k);
            *h10 = (int)lround([p[2] doubleValue] * k);
        }
}

static NSString *ESPdfMarginText(double v, NSString *units)
{
    return [NSString stringWithFormat:[units isEqualToString:@"in."] ? @"%.2f" : @"%.1f", v];
}
static NSString *ESFSFormat(NSString *f)          /* the saved type, or JPEG */
{
    return [f isEqualToString:kFormatTIFF] || [f isEqualToString:kFormatMTIFF] || [f isEqualToString:kFormatPDF] ||
           [f isEqualToString:kFormatPICT] || [f isEqualToString:kFormatPIMJ] || [f isEqualToString:kFormatPIMT] ? f : kFormatJPEG;
}

static NSString *ESFSStandardFolder(NSSearchPathDirectory d)
{
    return [NSSearchPathForDirectoriesInDomains(d, NSUserDomainMask, YES) firstObject];
}

/* CheckEnableCreateFile: a folder we can make files in */
static BOOL ESFSWritable(NSString *dir)
{
    BOOL isDir = NO;
    return dir.length && [NSFileManager.defaultManager fileExistsAtPath:dir isDirectory:&isDir] && isDir &&
           [NSFileManager.defaultManager isWritableFileAtPath:dir];
}

static NSString *ESFSOtherFolder(void)
{
    NSString *o = [ESFSPrefs() stringForKey:kFSOther];
    return o.length ? o : ESFSStandardFolder(NSDesktopDirectory);     /* GetDesktopFolderFFSpec */
}

static NSString *ESFSFolderFor(int radio)
{
    if (radio == 1) return ESFSStandardFolder(NSDocumentDirectory);
    if (radio == 3) return ESFSOtherFolder();
    return ESFSStandardFolder(NSPicturesDirectory);
}

/* CFilePlugIn::MakeCompleteFileName: "%s%03d.%s"; without Overwrite the next number whose file
 * doesn't exist (999 wraps to 1); all taken -> STR#10008 #31. *next is the following number. */
static NSString *ESFSMakeFileName(NSString *dir, NSString *prefix, int start, NSString *ext, BOOL overwrite,
                                  int *next, NSString **err)
{
    NSFileManager *fm = NSFileManager.defaultManager;
    int n = start;
    if (!overwrite) {
        do {
            NSString *name = [NSString stringWithFormat:@"%@%03d.%@", prefix, n, ext];
            int following = n == 999 ? 1 : n + 1;
            if (![fm fileExistsAtPath:[dir stringByAppendingPathComponent:name]]) { *next = following; return name; }
            n = following;
        } while (n != start);
    } else {
        NSString *name = [NSString stringWithFormat:@"%@%03d.%@", prefix, n, ext];
        n = n == 999 ? 1 : n + 1;
        if (n != start) { *next = n; return name; }
    }
    if (err) *err = ESS_UI_10008_31;
    return nil;
}

/* The details text the plug-ins give the dialog (STR# 2002 + STR# 2000 #11/12 or #14/15) */
static NSString *ESFSDetails(NSString *format)
{
    NSUserDefaults *ud = ESFSPrefs();
    if (ESFSIsPDF(format)) {          /* CPdf::DoParameter, STR# 2001 */
        NSString *units = [ud stringForKey:kPDFUnits];
        BOOL sel = [ud integerForKey:kPDFPageMode] != 0;
        return [NSString stringWithFormat:@"Paper Size: %@\nOrientation: %@\nMargin: (Left, Top)-( %@ %@, %@ %@)\n%@\nCompression Level : %@",
                [ud stringForKey:kPDFPaper], [ud boolForKey:kPDFLandscape] ? @"Landscape" : @"Portrait",
                ESPdfMarginText([ud doubleForKey:kPDFLeft], units), units,
                ESPdfMarginText([ud doubleForKey:kPDFTop], units), units,
                sel ? [NSString stringWithFormat:ESS_PDF_2001_7,
                       (int)[ud integerForKey:kPDFPageNumber]]
                    : ESS_PDF_2001_6,
                [ud stringForKey:kPDFCompression]];
    }
    if (ESFSIsPICT(format) || [format isEqualToString:kFormatPIMT]) return @"";
    if ([format isEqualToString:kFormatPIMJ])  /* CExif: the compression level */
        return [NSString stringWithFormat:@"Compression Level: [%d]", (int)[ud integerForKey:kJPEGLevel]];
    if (ESFSIsMulti(format))          /* CMultiTiff::DoParameter: byte order + compression */
        return [NSString stringWithFormat:@"Byte Order: %@\nCompression: %@",
                [ud boolForKey:kMTIFFMM] ? @"Macintosh" : @"Windows",
                gImageIsBW && [ud boolForKey:kMTIFFBWG4] ? @"CCITT Group4" : @"None"];
    if (ESFSIsTIFF(format))
        return [NSString stringWithFormat:@"Byte Order: %@\nCompression: %@\nEmbed ICC Profile: %@",
                [ud boolForKey:kTIFFMM] ? @"Macintosh" : @"Windows",
                gImageIsBW && [ud boolForKey:kTIFFBWG4] ? @"CCITT Group4" : @"None", [ud boolForKey:kTIFFICC] ? @"ON" : @"OFF"];
    return [NSString stringWithFormat:@"Compression Level: [%d]\nEncoding: %@\nEmbed ICC Profile: %@",
            (int)[ud integerForKey:kJPEGLevel], [ud boolForKey:kJPEGProg] ? @"Progressive" : @"Standard",
            [ud boolForKey:kJPEGICC] ? @"ON" : @"OFF"];
}

static void ESFSAlert(NSString *text)
{
    NSAlert *a = [NSAlert new];
    a.messageText = @"EPSON Scan";
    a.informativeText = text;
    a.alertStyle = NSAlertStyleWarning;
    [a runModal];
}

/* A modal panel built from one of the exported layouts */
@interface ESLayoutDialog : NSObject
@property (nonatomic, strong) NSPanel *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic, strong) ESFlippedView *root;
@property (nonatomic, strong) NSArray<NSDictionary *> *items;
@property (nonatomic) BOOL result;
- (void)load:(NSString *)layout;
- (BOOL)runModal;
- (void)perform:(NSString *)action;
@end

@implementation ESLayoutDialog
- (NSView *)ctl:(NSString *)k { return self.builder.controls[k]; }
- (void)load:(NSString *)layout
{
    NSString *path = [[NSBundle mainBundle] pathForResource:layout ofType:@"json"];
    NSDictionary *L = [NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:path] options:0 error:nil];
    NSDictionary *w = L[@"window"];
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    NSRect r = NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue]);
    self.window = [[NSPanel alloc] initWithContentRect:r styleMask:NSWindowStyleMaskTitled
                                               backing:NSBackingStoreBuffered defer:NO];
    self.window.title = w[@"title"];
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    self.root = [[ESFlippedView alloc] initWithFrame:r];
    self.root.wantsLayer = YES;
    self.root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.builder = [ESBuilder new];
    self.builder.native = native;
    self.items = L[@"items"];
    [self.builder build:self.items into:self.root];
    __weak ESLayoutDialog *weakSelf = self;
    self.builder.onAction = ^(NSString *a) { [weakSelf perform:a]; };
    self.window.contentView = self.root;
}
- (BOOL)runModal
{
    self.result = NO;
    [self.window center];
    [NSApp runModalForWindow:self.window];
    [self.window orderOut:nil];
    [NSNotificationCenter.defaultCenter removeObserver:self];
    return self.result;
}
- (void)finish:(BOOL)ok { self.result = ok; [NSApp stopModal]; }
- (void)perform:(NSString *)action {}
@end

/* EPSON TIFF Plug-in Settings (TIFF.rsrc DLOG 10001): Byte Order, B&W compression (B&W images
 * only, so off here), Embed ICC Profile. Saved by the plug-in when OK is clicked. */
@interface ESTiffOptionsDialog : ESLayoutDialog
@property (nonatomic) BOOL mac;
@property (nonatomic) BOOL multi;      /* EPSON Multi-TIFF Plug-in Settings (Multiple TIFF.rsrc DLOG 10001) */
@end
@implementation ESTiffOptionsDialog
- (BOOL)run
{
    [self load:@"tiffopts"];
    NSUserDefaults *ud = ESFSPrefs();
    NSString *orderKey = self.multi ? kMTIFFMM : kTIFFMM;
    if (self.multi) {                  /* the same dialog without Embed ICC Profile, 400 x 193 */
        self.window.title = ESS_MULTIPLETIFF_2000_1;
        [self ctl:@"tICC"].hidden = YES;
        [self.window setContentSize:NSMakeSize(self.root.frame.size.width, 193)];
    }
    self.mac = [ud boolForKey:orderKey];
    ESSetOn([self ctl:@"tMac"], self.mac);
    ESSetOn([self ctl:@"tWin"], !self.mac);
    ESSetOn([self ctl:@"tICC"], [ud boolForKey:kTIFFICC]);
    /* Compression > B&W: offered when the image is Black & White */
    NSString *g4Key = self.multi ? kMTIFFBWG4 : kTIFFBWG4;
    ESSelectItem([self ctl:@"tBW"], [ud boolForKey:g4Key] ? @"CCITT Group4" : @"None");
    ESSetEnabled([self ctl:@"tBW"], gImageIsBW);
    if (![self runModal]) return NO;
    [ud setBool:self.mac forKey:orderKey];
    if (gImageIsBW) [ud setBool:[ESValue([self ctl:@"tBW"]) isEqualToString:@"CCITT Group4"] forKey:g4Key];
    if (!self.multi) [ud setBool:ESIsOn([self ctl:@"tICC"]) forKey:kTIFFICC];
    return YES;
}
- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"t:mac"] || [action isEqualToString:@"t:win"]) {
        self.mac = [action isEqualToString:@"t:mac"];
        ESSetOn([self ctl:@"tMac"], self.mac);
        ESSetOn([self ctl:@"tWin"], !self.mac);
    } else if ([action isEqualToString:@"t:ok"]) [self finish:YES];
    else if ([action isEqualToString:@"t:cancel"]) [self finish:NO];
    else if ([action isEqualToString:@"t:help"]) NSBeep();
}
@end

/* EPSON JPEG Plug-in Settings (JPEG.rsrc DLOG 10000): Compression Level 1-100 (field and
 * slider), Standard / Progressive, Embed ICC Profile. */
@interface ESJpegOptionsDialog : ESLayoutDialog
@property (nonatomic) int level;
@property (nonatomic) BOOL progressive;
@end
@implementation ESJpegOptionsDialog
- (void)showLevel
{
    ESSetField([self ctl:@"jLevel"], [NSString stringWithFormat:@"%d", self.level]);
    ESSetSliderValue([self ctl:@"jSlider"], self.level);
}
- (BOOL)run
{
    [self load:@"jpegopts"];
    NSUserDefaults *ud = ESFSPrefs();
    self.level = (int)MAX(1, MIN(100, [ud integerForKey:kJPEGLevel]));
    self.progressive = [ud boolForKey:kJPEGProg];
    [self showLevel];
    ESSetOn([self ctl:@"jStd"], !self.progressive);
    ESSetOn([self ctl:@"jProg"], self.progressive);
    ESSetOn([self ctl:@"jICC"], [ud boolForKey:kJPEGICC]);
    __weak ESJpegOptionsDialog *weakSelf = self;
    self.builder.onValue = ^(NSString *key, double v) {
        if (![key isEqualToString:@"jSlider"]) return;
        weakSelf.level = (int)lround(v);
        ESSetField([weakSelf ctl:@"jLevel"], [NSString stringWithFormat:@"%d", weakSelf.level]);
    };
    NSTextField *t = (NSTextField *)[self ctl:@"jLevel"];
    if ([t isKindOfClass:[NSTextField class]]) {
        t.target = self; t.action = @selector(levelEntered:);
        t.cell.sendsActionOnEndEditing = YES;
    }
    if (![self runModal]) return NO;
    [self levelEntered:nil];
    [ud setInteger:self.level forKey:kJPEGLevel];
    [ud setBool:self.progressive forKey:kJPEGProg];
    [ud setBool:ESIsOn([self ctl:@"jICC"]) forKey:kJPEGICC];
    return YES;
}
- (void)levelEntered:(id)sender
{
    NSString *s = [ESValue([self ctl:@"jLevel"]) stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
    if (s.length) {
        int v = s.intValue;
        if (v < 1 || v > 100) NSBeep();
        self.level = MAX(1, MIN(100, v));
    }
    [self showLevel];
}
- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"j:std"] || [action isEqualToString:@"j:prog"]) {
        self.progressive = [action isEqualToString:@"j:prog"];
        ESSetOn([self ctl:@"jStd"], !self.progressive);
        ESSetOn([self ctl:@"jProg"], self.progressive);
    } else if ([action isEqualToString:@"j:ok"]) [self finish:YES];
    else if ([action isEqualToString:@"j:cancel"]) [self finish:NO];
    else if ([action isEqualToString:@"j:help"]) NSBeep();
}
@end

/* EPSON PDF Plug-in Settings (CDetailsUI, PDF.rsrc DLOG 10000 + General tab 10101) */
@interface ESPdfOptionsDialog : ESLayoutDialog
@property (nonatomic) BOOL landscape, selected;
@property (nonatomic, copy) NSString *units;
@property (nonatomic) double top, left;
@property (nonatomic) int number;
@end
@implementation ESPdfOptionsDialog
- (BOOL)run
{
    [self load:@"pdfopts"];
    NSUserDefaults *ud = ESFSPrefs();
    ESSelectItem([self ctl:@"pPaper"], [ud stringForKey:kPDFPaper]);
    self.landscape = [ud boolForKey:kPDFLandscape];
    self.units = [[ud stringForKey:kPDFUnits] isEqualToString:@"in."] ? @"in." : @"mm";
    ESSelectItem([self ctl:@"pUnits"], self.units);
    self.top = [ud doubleForKey:kPDFTop];
    self.left = [ud doubleForKey:kPDFLeft];
    self.selected = [ud integerForKey:kPDFPageMode] != 0;
    self.number = (int)MAX(1, MIN(999, [ud integerForKey:kPDFPageNumber]));
    NSString *comp = [ud stringForKey:kPDFCompression];
    if (![comp isEqualToString:@"High Compression"]) comp = @"Standard Compression";
    ESSelectItem([self ctl:@"pComp"], comp);
    for (NSString *k in @[ @"pTop", @"pLeft", @"pNum" ]) {
        NSTextField *t = (NSTextField *)[self ctl:k];
        if (![t isKindOfClass:[NSTextField class]]) continue;
        t.identifier = k; t.target = self; t.action = @selector(fieldEntered:);
        t.cell.sendsActionOnEndEditing = YES;
    }
    [self show];
    if (![self runModal]) return NO;
    for (NSString *k in @[ @"pTop", @"pLeft", @"pNum" ]) {
        NSTextField *t = (NSTextField *)[self ctl:k];
        if ([t isKindOfClass:[NSTextField class]]) [self fieldEntered:t];
    }
    [ud setObject:ESValue([self ctl:@"pPaper"]) forKey:kPDFPaper];
    [ud setBool:self.landscape forKey:kPDFLandscape];
    [ud setObject:self.units forKey:kPDFUnits];
    [ud setDouble:self.top forKey:kPDFTop];
    [ud setDouble:self.left forKey:kPDFLeft];
    [ud setInteger:self.selected forKey:kPDFPageMode];
    [ud setInteger:self.number forKey:kPDFPageNumber];
    [ud setObject:ESValue([self ctl:@"pComp"]) forKey:kPDFCompression];
    return YES;
}
- (BOOL)actual { return [ESValue([self ctl:@"pPaper"]) isEqualToString:@"Actual Image Size"]; }
/* UpdatePaperSizeUI: Actual Image Size has no orientation or margins (they go to 0) */
- (void)show
{
    BOOL actual = [self actual];
    if (actual) { self.top = 0; self.left = 0; }
    ESSetOn([self ctl:@"pPortrait"], !self.landscape);
    ESSetOn([self ctl:@"pLandscape"], self.landscape);
    ESSetField([self ctl:@"pTop"], ESPdfMarginText(self.top, self.units));
    ESSetField([self ctl:@"pLeft"], ESPdfMarginText(self.left, self.units));
    for (NSString *k in @[ @"pPortrait", @"pLandscape", @"pTopL", @"pTop", @"pLeftL", @"pLeft", @"pUnits" ])
        ESSetEnabled([self ctl:k], !actual);
    ESSetOn([self ctl:@"pAll"], !self.selected);
    ESSetOn([self ctl:@"pSel"], self.selected);
    ESSetField([self ctl:@"pNum"], [NSString stringWithFormat:@"%d", self.number]);
    ESSetEnabled([self ctl:@"pNum"], self.selected);
    ESSetEnabled([self ctl:@"pArrows"], self.selected);
}
/* CheckEBMarginValue (0..100 mm or 0..3.94 in.) / CheckEBPageNumberValue (1..999) */
- (void)fieldEntered:(NSTextField *)t
{
    NSString *k = t.identifier ?: @"";
    NSString *s = [ESValue(t) stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
    if ([k isEqualToString:@"pNum"]) {
        if (s.length) {
            int v = s.intValue;
            if (v < 1 || v > 999) NSBeep();
            self.number = MAX(1, MIN(999, v));
        }
    } else if ([k isEqualToString:@"pTop"] || [k isEqualToString:@"pLeft"]) {
        double max = [self.units isEqualToString:@"in."] ? 3.94 : 100.0;
        double v = [k isEqualToString:@"pTop"] ? self.top : self.left;
        if (s.length) {
            v = s.doubleValue;
            if (v < 0 || v > max) NSBeep();
            v = MAX(0, MIN(max, v));
        }
        if ([k isEqualToString:@"pTop"]) self.top = v; else self.left = v;
    }
    [self show];
}
- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"p:paper"]) [self show];
    else if ([action isEqualToString:@"p:portrait"]) { self.landscape = NO; [self show]; }
    else if ([action isEqualToString:@"p:landscape"]) { self.landscape = YES; [self show]; }
    else if ([action isEqualToString:@"p:units"]) {          /* UpdateMarginValue: same length, new units */
        NSString *u = ESValue([self ctl:@"pUnits"]);
        if (![u isEqualToString:self.units]) {
            double k = [u isEqualToString:@"in."] ? 1 / 25.4 : 25.4;
            self.top = MIN(self.top * k, [u isEqualToString:@"in."] ? 3.94 : 100.0);
            self.left = MIN(self.left * k, [u isEqualToString:@"in."] ? 3.94 : 100.0);
            self.units = u;
        }
        [self show];
    } else if ([action isEqualToString:@"p:all"]) { self.selected = NO; [self show]; }
    else if ([action isEqualToString:@"p:sel"]) { self.selected = YES; [self show]; }
    else if ([action isEqualToString:@"p:step"]) {          /* PageNumberLittleArrowsAction */
        NSView *st = [self ctl:@"pArrows"];
        int dir = [st isKindOfClass:[AQControl class]] ? ((AQControl *)st).stepDirection : self.builder.lastStep;
        int v = self.number + dir;
        if (v < 1 || v > 999) NSBeep(); else self.number = v;
        [self show];
    } else if ([action isEqualToString:@"p:ok"]) [self finish:YES];
    else if ([action isEqualToString:@"p:cancel"]) [self finish:NO];
    else if ([action isEqualToString:@"p:help"]) NSBeep();
}
@end

/* CFileSaveDialog (DLOG/DITL 10900) */
@interface ESFileSaveDialog : ESLayoutDialog
@property (nonatomic) int radio;
@property (nonatomic, copy) NSString *other;
@property (nonatomic, strong) NSTextField *pathText, *detailsText;
@property (nonatomic) int start;
@end

@implementation ESFileSaveDialog

- (BOOL)run
{
    [self load:@"filesave"];
    NSUserDefaults *ud = ESFSPrefs();
    BOOL native = self.builder.native;
    for (NSDictionary *it in self.items) {
        NSString *kind = it[@"kind"];
        if ([kind isEqualToString:@"path"]) {               /* item 5: the "Other" folder's path */
            self.pathText = [NSTextField labelWithString:@""];
            self.pathText.frame = ESRect(it[@"rect"]);
            self.pathText.font = native ? [NSFont systemFontOfSize:11] : ESFont(11, NO);
            self.pathText.lineBreakMode = NSLineBreakByTruncatingMiddle;
            [self.root addSubview:self.pathText];
        } else if ([kind isEqualToString:@"details"]) {     /* items 29 (frame) and 19 (text) */
            NSBox *box = [[NSBox alloc] initWithFrame:ESRect(it[@"rect"])];
            box.boxType = NSBoxCustom;
            box.borderColor = NSColor.gridColor;
            box.borderWidth = 1;
            box.fillColor = NSColor.textBackgroundColor;     /* Epson's white list box */
            [self.root addSubview:box];
            self.detailsText = [NSTextField wrappingLabelWithString:@""];
            self.detailsText.frame = ESRect(it[@"inner"]);
            self.detailsText.font = native ? [NSFont systemFontOfSize:11] : ESFont(11, NO);
            [self.root addSubview:self.detailsText];
        }
    }
    /* SetInitLocation: Documents / Pictures are offered only if files can be made there */
    if (!ESFSWritable(ESFSFolderFor(1))) [self ctl:@"fsDocuments"].hidden = YES;
    if (!ESFSWritable(ESFSFolderFor(0))) [self ctl:@"fsPictures"].hidden = YES;
    self.other = [ud stringForKey:kFSOther] ?: ESFSOtherFolder();
    int radio = (int)[ud integerForKey:kFSRadio];
    if (radio < 0 || radio > 4) radio = 0;
    if (radio == 2 || radio == 4) radio = radio == 2 ? 0 : 3;
    if ((radio == 1 && [self ctl:@"fsDocuments"].hidden) || (radio == 0 && [self ctl:@"fsPictures"].hidden)) radio = 3;
    [self selectRadio:radio];

    ESSetField([self ctl:@"fsPrefix"], [ud stringForKey:kFSPrefix] ?: @"img");
    self.start = (int)MAX(1, MIN(999, [ud integerForKey:kFSStart]));
    [self showStart];
    NSString *fmt = ESFSFormat([ud stringForKey:kFSFormat]);
    ESSelectItem([self ctl:@"fsType"], fmt);
    [self showDetails];
    ESSetOn([self ctl:@"fsOverwrite"], [ud boolForKey:kFSOverwrite]);
    ESSetOn([self ctl:@"fsShow"], [ud boolForKey:kFSShow]);
    ESSetOn([self ctl:@"fsOpen"], [ud boolForKey:kFSOpen]);
    ESSetOn([self ctl:@"fsAddPage"], [ud boolForKey:kFSAddPage]);
    [self updateAddPage];

    NSTextField *pre = (NSTextField *)[self ctl:@"fsPrefix"], *num = (NSTextField *)[self ctl:@"fsStart"];
    if ([pre isKindOfClass:[NSTextField class]])
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(prefixChanged:)
                                                   name:NSControlTextDidChangeNotification object:pre];
    if ([num isKindOfClass:[NSTextField class]]) {
        num.target = self; num.action = @selector(startEntered:);
        num.cell.sendsActionOnEndEditing = YES;
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(startChanged:)
                                                   name:NSControlTextDidChangeNotification object:num];
    }
    if (![self runModal]) return NO;

    [ud setInteger:self.radio forKey:kFSRadio];
    [ud setObject:self.other forKey:kFSOther];
    [ud setObject:ESValue(pre) forKey:kFSPrefix];
    [ud setInteger:self.start forKey:kFSStart];
    [ud setObject:ESValue([self ctl:@"fsType"]) forKey:kFSFormat];
    [ud setBool:ESIsOn([self ctl:@"fsOverwrite"]) forKey:kFSOverwrite];
    [ud setBool:ESIsOn([self ctl:@"fsShow"]) forKey:kFSShow];
    [ud setBool:ESIsOn([self ctl:@"fsOpen"]) forKey:kFSOpen];
    if (ESFSIsMultiPage(ESValue([self ctl:@"fsType"]))) [ud setBool:ESIsOn([self ctl:@"fsAddPage"]) forKey:kFSAddPage];
    return YES;
}

/* "Show Add Page dialog after scanning." is for the multi-page formats */
- (void)updateAddPage { ESSetEnabled([self ctl:@"fsAddPage"], ESFSIsMultiPage(ESValue([self ctl:@"fsType"]))); }

- (void)selectRadio:(int)r
{
    self.radio = r;
    ESSetOn([self ctl:@"fsDocuments"], r == 1);
    ESSetOn([self ctl:@"fsPictures"], r == 0);
    ESSetOn([self ctl:@"fsOther"], r == 3);
    self.pathText.stringValue = self.other ?: @"";
    self.pathText.textColor = r == 3 ? NSColor.labelColor : NSColor.disabledControlTextColor;
}

- (void)showStart { ESSetField([self ctl:@"fsStart"], [NSString stringWithFormat:@"%03d", self.start]); }

- (void)showDetails { self.detailsText.stringValue = ESFSDetails(ESValue([self ctl:@"fsType"])); }

/* CheckFileNamePrefix: at most 24 characters */
- (void)prefixChanged:(NSNotification *)n
{
    NSTextField *t = n.object;
    if (t.stringValue.length > 24) { t.stringValue = [t.stringValue substringToIndex:24]; NSBeep(); }
}

/* the Start Number field takes up to 3 digits */
- (void)startChanged:(NSNotification *)n
{
    NSTextField *t = n.object;
    NSString *s = [[t.stringValue componentsSeparatedByCharactersInSet:NSCharacterSet.decimalDigitCharacterSet.invertedSet]
                   componentsJoinedByString:@""];
    if (s.length > 3) s = [s substringToIndex:3];
    if (![s isEqualToString:t.stringValue]) { t.stringValue = s; NSBeep(); }
}

/* ValidateStartNumber: empty -> the last value; 1..999 with a beep; shown as "%03d" */
- (void)startEntered:(id)sender
{
    NSString *s = ESValue([self ctl:@"fsStart"]);
    if (s.length) {
        int v = s.intValue;
        if (v >= 1000) { v = 999; NSBeep(); }
        else if (v < 1) { v = 1; NSBeep(); }
        self.start = v;
    }
    [self showStart];
}

/* ValidatePrefix: leading periods go; empty -> STR#10008 #28; ':' -> #29 */
- (BOOL)validatePrefix
{
    NSString *p = ESValue([self ctl:@"fsPrefix"]);
    while ([p hasPrefix:@"."]) p = [p substringFromIndex:1];
    ESSetField([self ctl:@"fsPrefix"], p);
    if (!p.length) { ESFSAlert(ESS_UI_10008_28); return NO; }
    if ([p containsString:@":"] || [p containsString:@"/"]) {
        ESFSAlert(ESS_UI_10008_29); return NO;
    }
    return YES;
}

- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"fs:documents"]) [self selectRadio:1];
    else if ([action isEqualToString:@"fs:pictures"]) [self selectRadio:0];
    else if ([action isEqualToString:@"fs:other"]) [self selectRadio:3];
    else if ([action isEqualToString:@"fs:choose"]) {        /* DoChooseButtonClick */
        NSOpenPanel *op = [NSOpenPanel openPanel];
        op.canChooseDirectories = YES;
        op.canChooseFiles = NO;
        op.canCreateDirectories = YES;
        op.prompt = @"Choose";
        op.directoryURL = [NSURL fileURLWithPath:self.other ?: ESFSOtherFolder()];
        if ([op runModal] == NSModalResponseOK) {
            self.other = op.URL.path;
            [self selectRadio:3];
        }
    } else if ([action isEqualToString:@"fs:step"]) {       /* StartNumberLittleArrowsAction */
        NSView *st = [self ctl:@"fsArrows"];
        int dir = [st isKindOfClass:[AQControl class]] ? ((AQControl *)st).stepDirection : self.builder.lastStep;
        [self startEntered:nil];
        int v = self.start + dir;
        if (v < 1 || v > 999) NSBeep();
        else self.start = v;
        [self showStart];
    } else if ([action isEqualToString:@"fs:type"]) {
        [self showDetails]; [self updateAddPage];
        NSString *t = ESValue([self ctl:@"fsType"]);       /* PICT and PIM TIFF have no settings */
        ESSetEnabled([self ctl:@"fsOptions"], !(ESFSIsPICT(t) || [t isEqualToString:kFormatPIMT]));
    }
    else if ([action isEqualToString:@"fs:options"]) {       /* DoOptionsButtonClick: the plug-in's dialog */
        NSString *type = ESValue([self ctl:@"fsType"]);
        if (ESFSIsPDF(type)) [[ESPdfOptionsDialog new] run];
        else if (ESFSIsTIFF(type) || ESFSIsMulti(type)) {
            ESTiffOptionsDialog *d = [ESTiffOptionsDialog new];
            d.multi = ESFSIsMulti(type);
            [d run];
        } else if (ESFSIsPICT(type) || [type isEqualToString:kFormatPIMT]) NSBeep();
        else [[ESJpegOptionsDialog new] run];      /* JPEG, and PIM JPEG's compression level */
        [self.window makeKeyAndOrderFront:nil];
        [self showDetails];
    } else if ([action isEqualToString:@"fs:ok"]) {           /* DoOKButtonClick */
        [self startEntered:nil];
        if (![self validatePrefix]) { [self.window makeFirstResponder:[self ctl:@"fsPrefix"]]; return; }
        NSString *dir = ESFSFolderFor(self.radio == 3 ? 3 : self.radio);
        if (self.radio == 3) dir = self.other;
        if (!ESFSWritable(dir)) {                              /* IsAvailableDestination */
            ESFSAlert(@"The selected folder cannot be found or files cannot be saved there.\nSelect another folder.");
            return;
        }
        [self finish:YES];
    } else if ([action isEqualToString:@"fs:cancel"]) [self finish:NO];
    else if ([action isEqualToString:@"fs:help"]) NSBeep();
}
@end

/* CMsgScnContinueDlg (DITL 11007): after each page of a multi-page file */
@interface ESContinueDialog : ESLayoutDialog
@property (nonatomic) int choice;      /* 1 Edit Page, 2 Add Page, 3 Save File */
@end
@implementation ESContinueDialog
- (int)run
{
    [self load:@"continue"];
    BOOL native = self.builder.native;
    for (NSDictionary *it in self.items) {
        NSString *kind = it[@"kind"];
        if ([kind isEqualToString:@"noteicon"]) {
            NSImageView *iv = [[NSImageView alloc] initWithFrame:ESRect(it[@"rect"])];
            iv.image = [NSWorkspace.sharedWorkspace iconForFileType:NSFileTypeForHFSTypeCode(kAlertNoteIcon)];
            [self.root addSubview:iv];
        } else if ([kind isEqualToString:@"text"]) {
            NSTextField *t = [NSTextField wrappingLabelWithString:it[@"text"]];
            t.frame = ESRect(it[@"rect"]);
            t.font = native ? ([it[@"bold"] boolValue] ? [NSFont boldSystemFontOfSize:13] : [NSFont systemFontOfSize:11])
                            : ESFont([it[@"bold"] boolValue] ? 13 : 11, [it[@"bold"] boolValue]);
            [self.root addSubview:t];
        }
    }
    self.choice = 3;
    [self runModal];
    return self.choice;
}
- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"mp:edit"]) { self.choice = 1; [self finish:YES]; }
    else if ([action isEqualToString:@"mp:add"]) { self.choice = 2; [self finish:YES]; }
    else if ([action isEqualToString:@"mp:save"]) { self.choice = 3; [self finish:YES]; }
}
@end

#pragma mark - Editing Page (Multi Page Saving.bundle, PPob 10000 "DlgMultiImageLibrary")

/* a page's thumbnail from its raw file: every n-th pixel, high byte of 16-bit, gray as RGB */
static NSImage *ESPageThumb(NSDictionary *pg, int maxSide)
{
    int w = [pg[@"w"] intValue], h = [pg[@"h"] intValue], spp = [pg[@"spp"] intValue];
    int bps = [pg[@"bits"] intValue] > 8 ? 2 : 1;
    if (w <= 0 || h <= 0) return nil;
    int step = MAX(1, (MAX(w, h) + maxSide - 1) / maxSide);
    int tw = MAX(1, w / step), th = MAX(1, h / step);
    FILE *f = fopen([pg[@"raw"] fileSystemRepresentation], "rb");
    if (!f) return nil;
    size_t row = (size_t)w * spp * bps;
    uint8_t *buf = malloc(row);
    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:tw pixelsHigh:th
                                                                 bitsPerSample:8 samplesPerPixel:3 hasAlpha:NO
                                                                      isPlanar:NO colorSpaceName:NSDeviceRGBColorSpace
                                                                   bytesPerRow:tw * 3 bitsPerPixel:24];
    uint8_t *dst = rep.bitmapData;
    const uint16_t probe = 1;
    int hi = bps == 2 && *(const uint8_t *)&probe == 1 ? 1 : 0;
    for (int ty = 0; ty < th; ty++) {
        if (fseek(f, (long)((size_t)ty * step * row), SEEK_SET) || fread(buf, 1, row, f) != row) break;
        for (int tx = 0; tx < tw; tx++) {
            size_t s = ((size_t)tx * step * spp) * bps;
            for (int c = 0; c < 3; c++) {
                int cc = spp == 3 ? c : 0;
                dst[((size_t)ty * tw + tx) * 3 + c] = buf[s + (size_t)cc * bps + hi];
            }
        }
    }
    free(buf);
    fclose(f);
    NSImage *im = [[NSImage alloc] initWithSize:NSMakeSize(tw, th)];
    [im addRepresentation:rep];
    return im;
}

static void ESDrawPage(NSImage *im, int quarters, NSRect box)
{
    if (!im) return;
    NSSize s = im.size;
    BOOL turned = quarters & 1;
    double iw = turned ? s.height : s.width, ih = turned ? s.width : s.height;
    double k = MIN(box.size.width / iw, box.size.height / ih);
    double dw = iw * k, dh = ih * k;
    NSRect r = NSMakeRect(NSMidX(box) - dw / 2, NSMidY(box) - dh / 2, dw, dh);
    [NSGraphicsContext saveGraphicsState];
    NSAffineTransform *t = [NSAffineTransform transform];
    [t translateXBy:NSMidX(r) yBy:NSMidY(r)];
    [t rotateByDegrees:-90.0 * quarters];         /* clockwise on screen (flipped view) */
    [t concat];
    double ww = turned ? dh : dw, hh = turned ? dw : dh;
    [im drawInRect:NSMakeRect(-ww / 2, -hh / 2, ww, hh) fromRect:NSZeroRect operation:NSCompositingOperationSourceOver
          fraction:1 respectFlipped:YES hints:nil];
    [NSGraphicsContext restoreGraphicsState];
    [[NSColor colorWithWhite:0.5 alpha:1] setStroke];
    NSFrameRect(r);
}

/* the thumbnail table (LTable 1004: 169 x 186 cells) */
@interface ESThumbView : NSView
@property (nonatomic, strong) NSMutableArray<NSMutableDictionary *> *items;   /* {page, thumb, quarters, num} */
@property (nonatomic, strong) NSMutableIndexSet *selection;
@property (nonatomic) NSInteger anchor, dropAt;
@property (nonatomic) NSPoint downAt;
@property (nonatomic) BOOL dragging;
@property (nonatomic, copy) void (^onChange)(void);
@property (nonatomic, copy) void (^onOpen)(NSInteger index);
@end

@implementation ESThumbView
- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstResponder { return YES; }
- (NSInteger)columns { return MAX(1, (NSInteger)(self.bounds.size.width / 169)); }
- (NSRect)cellRect:(NSInteger)i
{
    NSInteger c = [self columns];
    return NSMakeRect((i % c) * 169, (i / c) * 186, 169, 186);
}
- (void)relayout
{
    NSInteger rows = ((NSInteger)self.items.count + [self columns] - 1) / [self columns];
    NSSize vis = self.enclosingScrollView.contentSize;
    [self setFrameSize:NSMakeSize(vis.width, MAX(vis.height, rows * 186))];
    [self setNeedsDisplay:YES];
}
- (NSInteger)indexAt:(NSPoint)p
{
    NSInteger c = [self columns], col = (NSInteger)(p.x / 169), row = (NSInteger)(p.y / 186);
    if (col >= c || p.x < 0 || p.y < 0) return -1;
    NSInteger i = row * c + col;
    return i < (NSInteger)self.items.count ? i : -1;
}
- (NSInteger)dropIndexAt:(NSPoint)p
{
    NSInteger c = [self columns], col = (NSInteger)lround(p.x / 169), row = (NSInteger)(p.y / 186);
    col = MAX(0, MIN(c, col));
    return MAX(0, MIN((NSInteger)self.items.count, row * c + col));
}
- (void)drawRect:(NSRect)dirty
{
    [[NSColor whiteColor] setFill];
    NSRectFill(dirty);
    NSDictionary *a = @{ NSFontAttributeName: [NSFont systemFontOfSize:11], NSForegroundColorAttributeName: NSColor.blackColor };
    for (NSUInteger i = 0; i < self.items.count; i++) {
        NSRect r = [self cellRect:i];
        if (!NSIntersectsRect(r, dirty)) continue;
        NSDictionary *it = self.items[i];
        if ([self.selection containsIndex:i]) {
            [[NSColor colorWithCalibratedRed:0.70 green:0.82 blue:1 alpha:1] setFill];
            NSRectFill(NSInsetRect(r, 3, 3));
        }
        ESDrawPage(it[@"thumb"], [it[@"quarters"] intValue], NSMakeRect(r.origin.x + 12, r.origin.y + 8, 145, 145));
        NSString *label = [NSString stringWithFormat:@"%lu", (unsigned long)i + 1];
        NSSize ls = [label sizeWithAttributes:a];
        [label drawAtPoint:NSMakePoint(NSMidX(r) - ls.width / 2, r.origin.y + 160) withAttributes:a];
    }
    if (self.dragging && self.dropAt >= 0) {                /* where the pages go */
        NSInteger c = [self columns];
        NSInteger i = self.dropAt;
        double x = (i % c) * 169, y = (i / c) * 186;
        if (i == (NSInteger)self.items.count && i > 0 && i % c == 0) { x = c * 169; y = ((i - 1) / c) * 186; }
        [[NSColor colorWithCalibratedRed:0 green:0.35 blue:0.9 alpha:1] setFill];
        NSRectFill(NSMakeRect(x - 1.5, y + 6, 3, 174));
    }
}
- (void)mouseDown:(NSEvent *)e
{
    [self.window makeFirstResponder:self];
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    NSInteger i = [self indexAt:p];
    self.downAt = p;
    self.dragging = NO;
    if (e.clickCount == 2 && i >= 0) { if (self.onOpen) self.onOpen(i); return; }
    NSUInteger mods = e.modifierFlags;
    if (i < 0) { if (!(mods & (NSEventModifierFlagShift | NSEventModifierFlagCommand))) [self.selection removeAllIndexes]; }
    else if (mods & NSEventModifierFlagCommand) {
        if ([self.selection containsIndex:i]) [self.selection removeIndex:i]; else [self.selection addIndex:i];
        self.anchor = i;
    } else if (mods & NSEventModifierFlagShift && self.anchor >= 0) {
        [self.selection addIndexesInRange:NSMakeRange(MIN(self.anchor, i), labs(self.anchor - i) + 1)];
    } else {
        if (![self.selection containsIndex:i]) { [self.selection removeAllIndexes]; [self.selection addIndex:i]; }
        self.anchor = i;
    }
    [self setNeedsDisplay:YES];
    if (self.onChange) self.onChange();
}
- (void)mouseDragged:(NSEvent *)e
{
    NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
    if (!self.selection.count) return;
    if (!self.dragging && hypot(p.x - self.downAt.x, p.y - self.downAt.y) < 4) return;
    self.dragging = YES;
    [self autoscroll:e];
    self.dropAt = [self dropIndexAt:p];
    [self setNeedsDisplay:YES];
}
- (void)mouseUp:(NSEvent *)e
{
    if (self.dragging) {                                    /* move the selected pages, in order */
        NSArray *moving = [self.items objectsAtIndexes:self.selection];
        NSInteger at = self.dropAt - (NSInteger)[self.selection countOfIndexesInRange:NSMakeRange(0, (NSUInteger)self.dropAt)];
        [self.items removeObjectsAtIndexes:self.selection];
        at = MAX(0, MIN((NSInteger)self.items.count, at));
        [self.items insertObjects:moving atIndexes:[NSIndexSet indexSetWithIndexesInRange:NSMakeRange((NSUInteger)at, moving.count)]];
        [self.selection removeAllIndexes];
        [self.selection addIndexesInRange:NSMakeRange((NSUInteger)at, moving.count)];
        self.dragging = NO;
        [self setNeedsDisplay:YES];
        if (self.onChange) self.onChange();
    }
}
@end

/* Editing Page: select odd / even / all, rotate left / right, sort by page number, delete,
 * reorder by dragging; OK saves in this order, Cancel discards the scans */
@interface ESEditPageWindow : NSObject
@property (nonatomic, strong) NSPanel *window;
@property (nonatomic, strong) ESThumbView *grid;
@property (nonatomic, strong) NSTextField *total;
@property (nonatomic, strong) NSMutableDictionary<NSString *, NSButton *> *buttons;
@property (nonatomic) BOOL result;
@property (nonatomic, strong) NSMutableArray<NSPanel *> *magnifiers;
@end

@implementation ESEditPageWindow

- (NSButton *)iconButton:(int)icon x:(double)x tip:(NSString *)tip action:(SEL)sel
{
    NSButton *b = [[NSButton alloc] initWithFrame:NSMakeRect(x, 517, 30, 30)];
    b.bezelStyle = NSBezelStyleShadowlessSquare;
    b.image = ESArt([NSString stringWithFormat:@"mps_%d.png", icon]);
    b.imagePosition = NSImageOnly;
    b.toolTip = tip;
    b.target = self;
    b.action = sel;
    return b;
}

- (NSButton *)push:(NSString *)title x:(double)x action:(SEL)sel
{
    NSButton *b = [NSButton buttonWithTitle:title target:self action:sel];
    b.frame = NSMakeRect(x, 521, 90, 20);
    b.bezelStyle = NSBezelStyleRounded;
    b.font = [NSFont systemFontOfSize:11];
    return b;
}

/* pages: the session's page dictionaries; on OK they come back edited (order, rotation) */
- (NSArray *)runWithPages:(NSArray *)pages
{
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    self.window = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, 800, 560)
                                             styleMask:NSWindowStyleMaskTitled backing:NSBackingStoreBuffered defer:NO];
    self.window.title = @"Editing Page";
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, 800, 560)];
    self.total = [NSTextField labelWithString:@""];
    self.total.frame = NSMakeRect(15, 10, 300, 20);
    self.total.font = native ? [NSFont systemFontOfSize:11] : ESFont(11, NO);
    [root addSubview:self.total];
    NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSMakeRect(15, 34, 770, 469)];
    sv.hasVerticalScroller = YES;
    sv.borderType = NSBezelBorder;
    self.grid = [[ESThumbView alloc] initWithFrame:NSMakeRect(0, 0, 753, 467)];
    self.grid.items = [NSMutableArray array];
    self.grid.selection = [NSMutableIndexSet indexSet];
    self.grid.anchor = -1;
    NSUInteger n = 0;
    for (NSDictionary *pg in pages)
        [self.grid.items addObject:[@{ @"page": pg, @"thumb": ESPageThumb(pg, 320) ?: [NSImage new],
                                       @"quarters": @0, @"num": @(++n) } mutableCopy]];
    sv.documentView = self.grid;
    [root addSubview:sv];
    __weak ESEditPageWindow *weakSelf = self;
    self.grid.onChange = ^{ [weakSelf update]; };
    self.grid.onOpen = ^(NSInteger i) { [weakSelf magnify:i]; };

    self.buttons = [NSMutableDictionary dictionary];
    self.buttons[@"odd"] = [self iconButton:1280 x:15 tip:@"Selects odd-numbered pages" action:@selector(selectOdd:)];
    self.buttons[@"even"] = [self iconButton:1290 x:61 tip:@"Selects even-numbered pages" action:@selector(selectEven:)];
    self.buttons[@"all"] = [self iconButton:1300 x:107 tip:@"Selects all pages" action:@selector(selectAll:)];
    self.buttons[@"ccw"] = [self iconButton:131 x:166 tip:ESS_MULTIPAGESAVINGUS_128_9 action:@selector(rotateLeft:)];
    self.buttons[@"cw"] = [self iconButton:132 x:212 tip:ESS_MULTIPAGESAVINGUS_128_10 action:@selector(rotateRight:)];
    self.buttons[@"sort"] = [self iconButton:1302 x:258 tip:ESS_MULTIPAGESAVINGUS_128_18 action:@selector(sortPages:)];
    self.buttons[@"delete"] = [self iconButton:133 x:304 tip:@"Deletes selected pages" action:@selector(deletePages:)];
    for (NSButton *b in self.buttons.allValues) [root addSubview:b];
    NSBox *sep = [[NSBox alloc] initWithFrame:NSMakeRect(150, 517, 1, 30)];
    sep.boxType = NSBoxSeparator;
    [root addSubview:sep];
    NSButton *ok = [self push:@"OK" x:486 action:@selector(ok:)];
    ok.keyEquivalent = @"\r";
    self.buttons[@"ok"] = ok;
    [root addSubview:ok];
    [root addSubview:[self push:@"Cancel" x:590 action:@selector(cancel:)]];
    [root addSubview:[self push:@"Help" x:695 action:@selector(help:)]];
    self.window.contentView = root;
    [self.grid relayout];
    [self update];
    self.result = NO;
    [self.window center];
    [NSApp runModalForWindow:self.window];
    [self.window orderOut:nil];
    for (NSPanel *m in self.magnifiers) [m orderOut:nil];
    if (!self.result) return nil;
    NSMutableArray *out = [NSMutableArray array];
    for (NSDictionary *it in self.grid.items) {
        NSMutableDictionary *pg = [it[@"page"] mutableCopy];
        pg[@"quarters"] = it[@"quarters"];
        [out addObject:pg];
    }
    return out;
}

- (void)update
{
    self.total.stringValue = [NSString stringWithFormat:@"Total Pages: %lu", (unsigned long)self.grid.items.count];
    BOOL sel = self.grid.selection.count > 0;
    for (NSString *k in @[ @"ccw", @"cw", @"delete" ]) self.buttons[k].enabled = sel;
    self.buttons[@"ok"].enabled = self.grid.items.count > 0;
    [self.grid setNeedsDisplay:YES];
}

- (void)selectEvery:(NSUInteger)first
{
    [self.grid.selection removeAllIndexes];
    for (NSUInteger i = first; i < self.grid.items.count; i += 2) [self.grid.selection addIndex:i];
    [self update];
}
- (void)selectOdd:(id)s { [self selectEvery:0]; }
- (void)selectEven:(id)s { [self selectEvery:1]; }
- (void)selectAll:(id)s
{
    [self.grid.selection addIndexesInRange:NSMakeRange(0, self.grid.items.count)];
    [self update];
}
- (void)turn:(int)q
{
    [self.grid.selection enumerateIndexesUsingBlock:^(NSUInteger i, BOOL *stop) {
        NSMutableDictionary *it = self.grid.items[i];
        it[@"quarters"] = @((([it[@"quarters"] intValue] + q) % 4 + 4) % 4);
    }];
    [self update];
}
- (void)rotateLeft:(id)s { [self turn:-1]; }
- (void)rotateRight:(id)s { [self turn:1]; }
- (void)sortPages:(id)s
{
    [self.grid.items sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) {
        return [a[@"num"] compare:b[@"num"]];
    }];
    [self.grid.selection removeAllIndexes];
    [self update];
}
- (BOOL)ask:(NSString *)text
{
    NSAlert *a = [NSAlert new];
    a.messageText = @"EPSON Scan";
    a.informativeText = text;
    [a addButtonWithTitle:@"Yes"];
    [a addButtonWithTitle:@"No"];
    return [a runModal] == NSAlertFirstButtonReturn;
}
- (void)deletePages:(id)s
{
    if (!self.grid.selection.count || ![self ask:ESS_MULTIPAGESAVINGUS_129_1]) return;
    [self.grid.items removeObjectsAtIndexes:self.grid.selection];
    [self.grid.selection removeAllIndexes];
    [self.grid relayout];
    [self update];
}
/* CMagnificationWindow (WIND 11000, 350 x 350) */
- (void)magnify:(NSInteger)i
{
    NSDictionary *it = self.grid.items[(NSUInteger)i];
    NSImage *big = ESPageThumb(it[@"page"], 700) ?: it[@"thumb"];
    NSPanel *p = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, 350, 350)
                                            styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable
                                              backing:NSBackingStoreBuffered defer:NO];
    p.title = [NSString stringWithFormat:@"%ld", (long)i + 1];
    ESFlippedView *v = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, 350, 350)];
    NSImageView *iv = [[NSImageView alloc] initWithFrame:NSInsetRect(v.bounds, 8, 8)];
    NSImage *shown = [NSImage imageWithSize:NSMakeSize(334, 334) flipped:YES drawingHandler:^BOOL(NSRect r) {
        ESDrawPage(big, [it[@"quarters"] intValue], r);
        return YES;
    }];
    iv.image = shown;
    [v addSubview:iv];
    p.contentView = v;
    p.releasedWhenClosed = NO;
    [p center];
    [p makeKeyAndOrderFront:nil];
    if (!self.magnifiers) self.magnifiers = [NSMutableArray array];
    [self.magnifiers addObject:p];
}
- (void)ok:(id)s { self.result = YES; [NSApp stopModal]; }
- (void)cancel:(id)s
{
    if (![self ask:ESS_MULTIPAGESAVINGUS_129_2]) return;
    self.result = NO;
    [NSApp stopModal];
}
- (void)help:(id)s { ESShowHelp(@"edit"); }
@end

#pragma mark - Configuration

/* CESPrefs values the Configuration dialog edits, with the ESPR 10000 defaults: preview rotation
 * off (+0x0e), fast preview on (+0x10, so Quality Preview off), sampling areas 1 x 1 (+0x12, +0x14),
 * units from the scanner (+0x16 = -1), Color Control (+0x18), continuous AE on (+0x1a), display
 * gamma 2.2 (+0x1c), monitor compensation off (+0x29e), Save settings on (+0x2a2), Thumbnail
 * Cropping Area 1 (+0x52e), Auto Exposure Level 4 (+0x578), Auto Photo Orientation off (+0x65e),
 * skew off (+0x664). */
static NSString *const kCfgTab = @"CfgTabNo";
static NSString *const kCfgRotation = @"CfgPreviewRotation";
static NSString *const kCfgFastPreview = @"CfgFastPreview";
static NSString *const kCfgSampArea = @"CfgSamplingArea";
static NSString *const kCfgDenseArea = @"CfgDenseSampArea";
static NSString *const kCfgUnits = @"CfgUnitType";               /* "mm" / "in." */
static NSString *const kCfgAutoRotate = @"CfgAutoRotate";
static NSString *const kCfgDTRMargin = @"CfgDTRMargin";
static NSString *const kCfgColorMgr = @"CfgColorMgrType";        /* 0 Color Control, 1 ColorSync, 2 None */
static NSString *const kCfgContAE = @"CfgAutoExpose";
static NSString *const kCfgGamma = @"DisplayGamma";              /* x10, already used by FIT */
static NSString *const kCfgSource = @"CfgCSyncSourceName";
static NSString *const kCfgTarget = @"CfgCSyncTargetName";
static NSString *const kCfgTargetPath = @"CfgCSyncTargetFile";
static NSString *const kCfgUseMonitor = @"CfgUseMonitor";
static NSString *const kCfgExposure = @"ExposureLevel";          /* 1..7, already used by FIT */
static NSString *const kCfgSaveSettings = @"CfgSaveSettings";
static NSString *const kCfgWorkArea = @"CfgWorkAreaVolume";      /* volume path, empty = startup disk */
static NSString *const kCfgSkew = @"CfgSkew";
static NSString *const kESConfigChanged = @"ESConfigChanged";

static NSUserDefaults *ESCfgPrefs(void)
{
    NSUserDefaults *ud = NSUserDefaults.standardUserDefaults;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        [ud registerDefaults:@{ kCfgTab: @0, kCfgRotation: @0, kCfgFastPreview: @1, kCfgSampArea: @0,
                                kCfgDenseArea: @0, kCfgUnits: @"in.", kCfgAutoRotate: @0, kCfgDTRMargin: @1,
                                kCfgColorMgr: @0, kCfgContAE: @1, kCfgGamma: @22, kCfgSource: @"EPSON Standard",
                                kCfgUseMonitor: @0, kCfgExposure: @4, kCfgSaveSettings: @1, kCfgSkew: @0 }];
    });
    return ud;
}

/* GetTempFolderWithVolume: Epson's work files go on the Work Area volume */
static NSString *ESWorkFolder(void)
{
    NSString *vol = [ESCfgPrefs() stringForKey:kCfgWorkArea];
    if (vol.length && ![vol isEqualToString:@"/"] && [NSFileManager.defaultManager isWritableFileAtPath:vol]) {
        NSString *dir = [vol stringByAppendingPathComponent:@".EPSON Scan Temp"];
        if ([NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil])
            return dir;
    }
    return NSTemporaryDirectory();
}

/* AppendTargetProfileMenu: the RGB display / color space profiles ColorSync knows */
static NSArray<NSDictionary *> *ESRGBProfiles(void)
{
    static NSArray *cache;
    if (cache) return cache;
    NSMutableArray *out = [NSMutableArray array];
    NSMutableSet *names = [NSMutableSet set];
    NSArray *dirs = @[ [NSHomeDirectory() stringByAppendingPathComponent:@"Library/ColorSync/Profiles"],
                       @"/Library/ColorSync/Profiles", @"/System/Library/ColorSync/Profiles" ];
    for (NSString *dir in dirs) {
        NSDirectoryEnumerator *en = [NSFileManager.defaultManager enumeratorAtPath:dir];
        for (NSString *rel in en) {
            NSString *ext = rel.pathExtension.lowercaseString;
            if (![ext isEqualToString:@"icc"] && ![ext isEqualToString:@"icm"]) continue;
            NSString *path = [dir stringByAppendingPathComponent:rel];
            NSData *d = [NSData dataWithContentsOfFile:path options:NSDataReadingMappedIfSafe error:nil];
            if (d.length < 128) continue;
            const char *h = d.bytes;
            BOOL rgb = memcmp(h + 16, "RGB ", 4) == 0;
            BOOL cls = memcmp(h + 12, "mntr", 4) == 0 || memcmp(h + 12, "spac", 4) == 0;
            if (!rgb || !cls) continue;
            NSColorSpace *cs = [[NSColorSpace alloc] initWithICCProfileData:d];
            NSString *name = cs.localizedName ?: rel.lastPathComponent.stringByDeletingPathExtension;
            if (!name.length || [names containsObject:name]) continue;
            [names addObject:name];
            [out addObject:@{ @"name": name, @"path": path }];
        }
    }
    [out sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) {
        return [a[@"name"] localizedCaseInsensitiveCompare:b[@"name"]];
    }];
    if (!out.count) [out addObject:@{ @"name": @"sRGB IEC61966-2.1", @"path": @"" }];
    cache = out;
    return out;
}

/* CreateWorkAreaMenu: the mounted, writable volumes */
static NSArray<NSURL *> *ESVolumes(void)
{
    NSMutableArray *out = [NSMutableArray array];
    NSArray *keys = @[ NSURLVolumeNameKey, NSURLVolumeIsBrowsableKey ];
    for (NSURL *u in [NSFileManager.defaultManager mountedVolumeURLsIncludingResourceValuesForKeys:keys
                                                                                            options:NSVolumeEnumerationSkipHiddenVolumes]) {
        NSNumber *b = nil;
        [u getResourceValue:&b forKey:NSURLVolumeIsBrowsableKey error:nil];
        if (b && !b.boolValue) continue;
        if (![NSFileManager.defaultManager isWritableFileAtPath:u.path]) continue;
        [out addObject:u];
    }
    return out;
}

static NSString *ESVolumeName(NSURL *u)
{
    NSString *n = nil;
    [u getResourceValue:&n forKey:NSURLVolumeNameKey error:nil];
    return n ?: u.lastPathComponent;
}

@interface ESConfigDialog : ESLayoutDialog <NSTabViewDelegate>
@property (nonatomic) int tab;
@property (nonatomic) int colorMgr;
@property (nonatomic, strong) NSArray<NSURL *> *volumes;
@property (nonatomic, strong) NSArray<NSDictionary *> *profiles;
@property (nonatomic) BOOL resetAll;
@end

@implementation ESConfigDialog

- (BOOL)run
{
    [self load:@"config"];
    NSUserDefaults *ud = ESCfgPrefs();
    /* labels that wrap or sit beside a check box without a title */
    NSTabView *tv = (NSTabView *)[self ctl:@"tabs"];
    if ([tv isKindOfClass:[NSTabView class]]) tv.delegate = self;

    ESSetOn([self ctl:@"rotation"], [ud boolForKey:kCfgRotation]);
    ESSetOn([self ctl:@"quality"], [ud integerForKey:kCfgFastPreview] != 1);
    NSArray *areas = @[ @"1 x 1 pixel", @"3 x 3 pixels", @"5 x 5 pixels" ];
    ESSelectItem([self ctl:@"sampArea"], areas[MAX(0, MIN(2, [ud integerForKey:kCfgSampArea]))]);
    ESSelectItem([self ctl:@"denseArea"], areas[MAX(0, MIN(2, [ud integerForKey:kCfgDenseArea]))]);
    ESSelectItem([self ctl:@"units"], [ud stringForKey:kCfgUnits]);
    ESSetOn([self ctl:@"autoRotate"], [ud boolForKey:kCfgAutoRotate]);
    ESSetSliderValue([self ctl:@"dtrMargin"], MAX(1, MIN(3, [ud integerForKey:kCfgDTRMargin])));

    ESSetOn([self ctl:@"contAE"], [ud boolForKey:kCfgContAE]);
    ESSelectItem([self ctl:@"gamma"], [ud integerForKey:kCfgGamma] == 18 ? @"1.8" : @"2.2");
    self.profiles = ESRGBProfiles();
    NSMutableArray *pn = [NSMutableArray array];
    for (NSDictionary *p in self.profiles) [pn addObject:p[@"name"]];
    ESSetMenu([self ctl:@"target"], pn);
    NSString *tgt = [ud stringForKey:kCfgTarget];
    if (![pn containsObject:tgt]) tgt = [pn containsObject:@"sRGB IEC61966-2.1"] ? @"sRGB IEC61966-2.1" : pn.firstObject;
    ESSelectItem([self ctl:@"target"], tgt);
    ESSetOn([self ctl:@"useMonitor"], [ud boolForKey:kCfgUseMonitor]);
    ESSetSliderValue([self ctl:@"expLevel"], MAX(1, MIN(7, [ud integerForKey:kCfgExposure])));
    self.colorMgr = (int)MAX(0, MIN(2, [ud integerForKey:kCfgColorMgr]));
    [self updateColorItems];

    ESSetOn([self ctl:@"skew"], [ud boolForKey:kCfgSkew]);
    ESSetOn([self ctl:@"saveSettings"], [ud boolForKey:kCfgSaveSettings]);
    self.volumes = ESVolumes();
    NSMutableArray *vn = [NSMutableArray array];
    NSString *cur = [ud stringForKey:kCfgWorkArea] ?: @"/";
    NSString *curName = nil;
    for (NSURL *u in self.volumes) {
        [vn addObject:ESVolumeName(u)];
        if ([u.path isEqualToString:cur]) curName = vn.lastObject;
    }
    if (!vn.count) [vn addObject:@"Macintosh HD"];
    ESSetMenu([self ctl:@"workArea"], vn);
    ESSelectItem([self ctl:@"workArea"], curName ?: vn.firstObject);
    [self showFreeSpace];

    self.tab = (int)MAX(0, MIN(2, [ud integerForKey:kCfgTab]));
    [self showTab];
    if (![self runModal]) return NO;
    if (self.resetAll) return YES;

    [ud setInteger:self.tab forKey:kCfgTab];
    [ud setInteger:ESIsOn([self ctl:@"rotation"]) forKey:kCfgRotation];
    [ud setInteger:ESIsOn([self ctl:@"quality"]) ? 0 : 1 forKey:kCfgFastPreview];
    [ud setInteger:(NSInteger)[areas indexOfObject:ESValue([self ctl:@"sampArea"])] forKey:kCfgSampArea];
    [ud setInteger:(NSInteger)[areas indexOfObject:ESValue([self ctl:@"denseArea"])] forKey:kCfgDenseArea];
    [ud setObject:ESValue([self ctl:@"units"]) forKey:kCfgUnits];
    [ud setInteger:ESIsOn([self ctl:@"autoRotate"]) forKey:kCfgAutoRotate];
    [ud setInteger:lround([self sliderValue:@"dtrMargin"]) forKey:kCfgDTRMargin];
    [ud setInteger:self.colorMgr forKey:kCfgColorMgr];
    [ud setInteger:ESIsOn([self ctl:@"contAE"]) forKey:kCfgContAE];
    [ud setInteger:[ESValue([self ctl:@"gamma"]) isEqualToString:@"1.8"] ? 18 : 22 forKey:kCfgGamma];
    NSString *tname = ESValue([self ctl:@"target"]);
    [ud setObject:tname forKey:kCfgTarget];
    for (NSDictionary *p in self.profiles) if ([p[@"name"] isEqualToString:tname]) [ud setObject:p[@"path"] forKey:kCfgTargetPath];
    [ud setInteger:ESIsOn([self ctl:@"useMonitor"]) forKey:kCfgUseMonitor];
    [ud setInteger:lround([self sliderValue:@"expLevel"]) forKey:kCfgExposure];
    [ud setInteger:ESIsOn([self ctl:@"skew"]) forKey:kCfgSkew];
    [ud setInteger:ESIsOn([self ctl:@"saveSettings"]) forKey:kCfgSaveSettings];
    NSURL *vol = [self selectedVolume];
    if (vol) [ud setObject:vol.path forKey:kCfgWorkArea];
    [NSNotificationCenter.defaultCenter postNotificationName:kESConfigChanged object:nil];
    return YES;
}

- (double)sliderValue:(NSString *)key
{
    NSView *v = [self ctl:key];
    if ([v isKindOfClass:[AQSlider class]]) return ((AQSlider *)v).value;
    if ([v isKindOfClass:[NSSlider class]]) return ((NSSlider *)v).doubleValue;
    return 0;
}

- (NSURL *)selectedVolume
{
    NSString *n = ESValue([self ctl:@"workArea"]);
    for (NSURL *u in self.volumes) if ([ESVolumeName(u) isEqualToString:n]) return u;
    return nil;
}

/* SetFreeSpece */
- (void)showFreeSpace
{
    NSURL *u = [self selectedVolume] ?: [NSURL fileURLWithPath:@"/"];
    NSNumber *free = nil;
    [u getResourceValue:&free forKey:NSURLVolumeAvailableCapacityKey error:nil];
    NSString *s = free ? [NSByteCountFormatter stringFromByteCount:free.longLongValue
                                                        countStyle:NSByteCountFormatterCountStyleFile] : @"";
    NSTextField *t = (NSTextField *)[self ctl:@"freeSpace"];
    if ([t isKindOfClass:[NSTextField class]]) { t.stringValue = s; [t sizeToFit]; }
}

/* ChangeConfigTabItem: only the current tab's items are shown */
- (void)showTab
{
    for (NSDictionary *it in self.items) {
        if (!it[@"tab"]) continue;
        NSView *v = [self ctl:it[@"key"]];
        v.hidden = [it[@"tab"] intValue] != self.tab;
    }
    NSView *tv = [self ctl:@"tabs"];
    if ([tv isKindOfClass:[AQControl class]]) { ((AQControl *)tv).selectedTab = self.tab; [tv setNeedsDisplay:YES]; }
    else if ([tv isKindOfClass:[NSTabView class]] && ((NSTabView *)tv).numberOfTabViewItems > self.tab)
        [(NSTabView *)tv selectTabViewItemAtIndex:self.tab];
}

- (void)tabView:(NSTabView *)tv didSelectTabViewItem:(NSTabViewItem *)item
{
    int t = (int)[tv indexOfTabViewItem:item];
    if (t != self.tab) { self.tab = t; [self showTab]; }
}

/* UpdateTabItems: the radio's own options are active, the others' are not */
- (void)updateColorItems
{
    ESSetOn([self ctl:@"ccColor"], self.colorMgr == 0);
    ESSetOn([self ctl:@"ccSync"], self.colorMgr == 1);
    ESSetOn([self ctl:@"ccNone"], self.colorMgr == 2);
    for (NSString *k in @[ @"contAE", @"i22", @"gamma" ]) ESSetEnabled([self ctl:k], self.colorMgr == 0);
    for (NSString *k in @[ @"i25", @"source", @"i27", @"target", @"useMonitor" ]) ESSetEnabled([self ctl:k], self.colorMgr == 1);
}

- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"cfg:tab"]) {
        NSView *tv = [self ctl:@"tabs"];
        if ([tv isKindOfClass:[AQControl class]]) { self.tab = (int)((AQControl *)tv).selectedTab; [self showTab]; }
    } else if ([action isEqualToString:@"cfg:cc"]) { self.colorMgr = 0; [self updateColorItems]; }
    else if ([action isEqualToString:@"cfg:cs"]) { self.colorMgr = 1; [self updateColorItems]; }
    else if ([action isEqualToString:@"cfg:none"]) { self.colorMgr = 2; [self updateColorItems]; }
    else if ([action isEqualToString:@"cfg:recommend"]) {
        /* DoRecommendSettingButtonClick: ESPR's color settings, the monitor's gamma (2.2 on any
         * current Mac), the first profiles, the scanner's exposure level (4) */
        self.colorMgr = 0;
        ESSetOn([self ctl:@"contAE"], YES);
        ESSelectItem([self ctl:@"gamma"], @"2.2");
        NSString *first = self.profiles.firstObject[@"name"];
        if (first) ESSelectItem([self ctl:@"target"], first);
        ESSetOn([self ctl:@"useMonitor"], NO);
        ESSetSliderValue([self ctl:@"expLevel"], 4);
        [self updateColorItems];
    } else if ([action isEqualToString:@"cfg:reset"]) {      /* DoResetSettingsButtonClick */
        NSAlert *a = [NSAlert new];
        a.messageText = @"EPSON Scan";
        a.informativeText = ESS_UI_10008_7;
        [a addButtonWithTitle:@"OK"];
        [a addButtonWithTitle:@"Cancel"];
        if ([a runModal] != NSAlertFirstButtonReturn) return;
        NSString *domain = NSBundle.mainBundle.bundleIdentifier;
        if (domain) [NSUserDefaults.standardUserDefaults removePersistentDomainForName:domain];
        self.resetAll = YES;
        [self finish:YES];
        dispatch_async(dispatch_get_main_queue(), ^{ [NSApp terminate:nil]; });
    } else if ([action isEqualToString:@"cfg:vol"]) [self showFreeSpace];
    else if ([action isEqualToString:@"cfg:ok"]) [self finish:YES];
    else if ([action isEqualToString:@"cfg:cancel"]) [self finish:NO];
    else if ([action isEqualToString:@"cfg:help"]) NSBeep();
}
@end

/* CColorSync::InitTransform + TransformBits (CImgProcessMgr::DoColorMatch): the scanner profile
 * to the target profile with the source profile's rendering intent (perceptual for
 * PERV550R/F.ICC), on 24- or 48-bit RGB, in place. Epson does this last, after every other
 * filter, for color images only. */
static BOOL ESColorMatchFile(NSString *raw, int w, int h, int bits, NSString *srcICC, NSString *dstICC, NSString **err)
{
    ColorSyncProfileRef src = ColorSyncProfileCreateWithURL((__bridge CFURLRef)[NSURL fileURLWithPath:srcICC], NULL);
    ColorSyncProfileRef dst = ColorSyncProfileCreateWithURL((__bridge CFURLRef)[NSURL fileURLWithPath:dstICC], NULL);
    if (!src || !dst) {
        if (src) CFRelease(src);
        if (dst) CFRelease(dst);
        if (err) *err = ESS_UI_10008_27;
        return NO;
    }
    NSArray *spec = @[
        @{ (__bridge id)kColorSyncProfile: (__bridge id)src,
           (__bridge id)kColorSyncRenderingIntent: (__bridge id)kColorSyncRenderingIntentPerceptual,
           (__bridge id)kColorSyncTransformTag: (__bridge id)kColorSyncTransformDeviceToPCS },
        @{ (__bridge id)kColorSyncProfile: (__bridge id)dst,
           (__bridge id)kColorSyncRenderingIntent: (__bridge id)kColorSyncRenderingIntentPerceptual,
           (__bridge id)kColorSyncTransformTag: (__bridge id)kColorSyncTransformPCSToDevice },
    ];
    ColorSyncTransformRef t = ColorSyncTransformCreate((__bridge CFArrayRef)spec, NULL);
    CFRelease(src); CFRelease(dst);
    if (!t) { if (err) *err = @"ColorSync couldn't set up the color matching."; return NO; }
    BOOL ok = YES;
    size_t row = (size_t)w * 3 * (bits > 8 ? 2 : 1);
    int strip = 256;
    uint8_t *buf = malloc(row * strip);
    FILE *f = fopen(raw.fileSystemRepresentation, "r+b");
    ColorSyncDataDepth depth = bits > 8 ? kColorSync16BitInteger : kColorSync8BitInteger;
    ColorSyncDataLayout layout = kColorSyncAlphaNone | kColorSyncByteOrderDefault;
    for (int y = 0; ok && f && buf && y < h; y += strip) {
        int n = MIN(strip, h - y);
        long off = (long)y * (long)row;
        if (fseek(f, off, SEEK_SET) || fread(buf, 1, row * n, f) != row * n) { ok = NO; break; }
        if (!ColorSyncTransformConvert(t, (size_t)w, (size_t)n, buf, depth, layout, row, buf, depth, layout, row, NULL)) {
            ok = NO; break;
        }
        if (fseek(f, off, SEEK_SET) || fwrite(buf, 1, row * n, f) != row * n) { ok = NO; break; }
    }
    if (!f || !buf) ok = NO;
    if (f) fclose(f);
    free(buf);
    CFRelease(t);
    if (!ok && err) *err = @"The color matching (ColorSync) failed.";
    return ok;
}

/* the target profile chosen in Configuration (sRGB until one is chosen) */
static NSString *ESTargetProfilePath(void)
{
    NSUserDefaults *ud = ESCfgPrefs();
    NSString *path = [ud stringForKey:kCfgTargetPath];
    if (path.length && [NSFileManager.defaultManager fileExistsAtPath:path]) return path;
    NSString *name = [ud stringForKey:kCfgTarget] ?: @"sRGB IEC61966-2.1";
    for (NSDictionary *p in ESRGBProfiles()) if ([p[@"name"] isEqualToString:name] && [p[@"path"] length]) return p[@"path"];
    for (NSDictionary *p in ESRGBProfiles()) if ([p[@"name"] hasPrefix:@"sRGB"] && [p[@"path"] length]) return p[@"path"];
    return nil;
}

@interface ESProgressSheet : NSObject
@property (nonatomic, strong) NSWindow *panel;
@property (nonatomic, strong) NSTextField *label;
@property (nonatomic, strong) NSProgressIndicator *bar;
@property (atomic) BOOL cancelled;
@end

@implementation ESProgressSheet
- (instancetype)init
{
    if ((self = [super init])) {
        self.panel = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, 360, 110) styleMask:NSWindowStyleMaskTitled
                                                  backing:NSBackingStoreBuffered defer:NO];
        NSView *v = self.panel.contentView;
        self.label = [NSTextField labelWithString:@"Scanning..."];
        self.label.frame = NSMakeRect(20, 72, 320, 18);
        self.label.font = [NSFont systemFontOfSize:12];
        [v addSubview:self.label];
        self.bar = [[NSProgressIndicator alloc] initWithFrame:NSMakeRect(20, 48, 320, 18)];
        self.bar.indeterminate = NO; self.bar.minValue = 0; self.bar.maxValue = 1;
        [v addSubview:self.bar];
        NSButton *b = [NSButton buttonWithTitle:@"Cancel" target:self action:@selector(cancel:)];
        b.frame = NSMakeRect(250, 10, 96, 30);
        b.keyEquivalent = @"\e";
        [v addSubview:b];
    }
    return self;
}
- (void)cancel:(id)sender { self.cancelled = YES; self.label.stringValue = @"Cancelling..."; es_cancel(); }
- (void)step:(NSString *)text fraction:(double)f
{
    dispatch_async(dispatch_get_main_queue(), ^{
        if (text && !self.cancelled) self.label.stringValue = text;
        self.bar.doubleValue = f;
    });
}
@end

typedef struct {
    FILE *f;
    __unsafe_unretained ESProgressSheet *sheet;
    double base, span;    /* this pass's share of the whole bar */
    NSString *__unsafe_unretained text;
} ESJob;

static int job_data(const uint8_t *data, uint32_t len, void *ctx)
{
    ESJob *j = ctx;
    if (j->sheet.cancelled) return 1;
    return fwrite(data, 1, len, j->f) == len ? 0 : 1;
}
static void job_progress(double f, void *ctx)
{
    ESJob *j = ctx;
    [j->sheet step:nil fraction:j->base + j->span * f];
}
static int job_ice_progress(int pct, void *ctx)
{
    ESJob *j = ctx;
    [j->sheet step:nil fraction:j->base + j->span * pct / 100.0];
    return j->sheet.cancelled;
}

/* One scanner pass into a raw file. */
static BOOL ESScanToFile(ESScanParams p, NSString *path, ESJob *j, ESScanResult *res, NSString **err)
{
    j->f = fopen(path.fileSystemRepresentation, "wb");
    if (!j->f) { *err = @"Couldn't create a temporary file."; return NO; }
    [j->sheet step:j->text fraction:j->base];
    int rc = es_scan(&p, job_data, job_progress, j, res);
    if (fclose(j->f)) rc = rc ?: -1;
    if (rc) *err = j->sheet.cancelled ? nil : ([NSString stringWithUTF8String:es_last_error()] ?: @"The scan failed.");
    return rc == 0;
}

/* Scan log: ~/Library/Logs/EPSON Scan.log (one line per stage, newest at the end). */
static void ESLog(NSString *fmt, ...) NS_FORMAT_FUNCTION(1, 2);
static void ESLog(NSString *fmt, ...)
{
    va_list ap; va_start(ap, fmt);
    NSString *msg = [[NSString alloc] initWithFormat:fmt arguments:ap];
    va_end(ap);
    NSString *path = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Logs/EPSON Scan.log"];
    NSDateFormatter *df = [NSDateFormatter new];
    df.dateFormat = @"yyyy-MM-dd HH:mm:ss";
    NSString *line = [NSString stringWithFormat:@"%@  %@\n", [df stringFromDate:NSDate.date], msg];
    FILE *f = fopen(path.fileSystemRepresentation, "a");
    if (f) { fputs(line.UTF8String, f); fclose(f); }
}

/* ICE diagnostics: an 8-bit TIFF crop of one of the intermediate raw files. */
static void ESDebugCrop(NSString *raw, int w, int h, int spp, int cx, int cy, int dpi, NSString *outTiff)
{
    int size = 1200;
    FrameRect r = { MAX(0, MIN(w - size, cx - size / 2)), MAX(0, MIN(h - size, cy - size / 2)), MIN(size, w), MIN(size, h) };
    NSString *tmp = [raw stringByAppendingString:@".crop"];
    char e[256];
    if (crop_raw(raw.fileSystemRepresentation, tmp.fileSystemRepresentation, w, spp * 2, r) == 0)
        es_convert_to_tiff(tmp.fileSystemRepresentation, outTiff.fileSystemRepresentation, r.w, r.h, spp, 16, 8, 0, dpi, e, sizeof e);
    unlink(tmp.fileSystemRepresentation);
}

/* How much of the aligned infrared looks like a defect (much darker than typical). */
static void ESLogIRStats(NSString *ir, int w, int h)
{
    FILE *f = fopen(ir.fileSystemRepresentation, "rb");
    if (!f) return;
    uint32_t *hist = calloc(65536, sizeof(uint32_t));
    uint16_t *row = malloc((size_t)w * 2);
    long n = 0;
    for (int y = 0; y < h && fread(row, 2, (size_t)w, f) == (size_t)w; y++)
        for (int x = 0; x < w; x++, n++) hist[row[x]]++;
    fclose(f);
    long acc = 0; int med = 0;
    for (int v = 0; v < 65536; v++) { acc += hist[v]; if (acc >= n / 2) { med = v; break; } }
    long dark = 0;
    for (int v = 0; v < med * 6 / 10; v++) dark += hist[v];
    ESLog(@"ICE infrared: median %d of 65535, %.3f%% of pixels look like defects", med, n ? 100.0 * dark / n : 0);
    free(hist); free(row);
}

@interface ESProfessionalWindow : NSObject <NSWindowDelegate>
@property (nonatomic, strong) NSWindow *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic, strong) NSMutableDictionary<NSString *, NSNumber *> *open;   /* triangle groups */
@property (nonatomic, strong) NSMutableArray<NSDictionary *> *rows;                  /* {view, group, height, section} */
@property (nonatomic, strong) ESFlippedView *doc;
@property (nonatomic, strong) NSScrollView *scroll;
@property (nonatomic, strong) ESPreviewWindow *preview;
@property (nonatomic, strong) ESMenuArrow *previewArrow;
@property (nonatomic, strong) ESImageAdjustDialog *imageAdjust;
@property (nonatomic, strong) ESHistogramDialog *histogramAdjust;
@property (nonatomic, strong) ESToneDialog *toneCorrection;
@property (nonatomic, strong) ESPaletteDialog *colorPalette;
@property (nonatomic, copy) NSString *lastResolution;
- (void)saveSettings;
@property (nonatomic) EsTarget areaTarget;                 /* no preview yet: the whole scan area */
@property (nonatomic, copy) NSArray<NSDictionary *> *userTargets;   /* "Customize..." sizes (AD Prefs TSIZ) */
@property (nonatomic) BOOL busy;
/* CMltPgSaveMgr: the pages of a multi-page file being scanned {path, pages[], mm, next, open} */
@property (nonatomic, strong) NSMutableDictionary *multi;
/* All marquees selected: the marquees still to scan after this one (Epson scans each in turn) */
@property (nonatomic, strong) NSMutableArray<NSNumber *> *batchQueue;
@property (nonatomic) BOOL batchFollowing;
/* Home / Office / Full Auto: the window that drives this one (sheets and alerts go there) and
 * Office Mode's document size (mm, scanner's origin) for a scan without a preview */
@property (nonatomic, weak) NSWindow *hostWindow;
@property (nonatomic) NSRect fixedAreaMM;
@property (nonatomic, strong) NSNumber *forcedThumbnail;   /* Home / Office: the Preview kind they chose */
- (NSWindow *)host;
- (void)rebuild;
- (void)perform:(NSString *)action;
- (void)startScan;
- (void)relayout;
- (void)updateItemStatus;
- (BOOL)isFilm;
- (int)imageTypeID;
- (NSDictionary *)snapshotSettings;
- (void)applySettings:(NSDictionary *)d;
@end

@implementation ESProfessionalWindow

- (instancetype)init
{
    if ((self = [super init])) {
        NSDictionary *L = [self layout];
        NSDictionary *w = L[@"window"];
        CGFloat W = [w[@"width"] doubleValue], H = [w[@"height"] doubleValue];
        self.window = [[NSWindow alloc] initWithContentRect:NSMakeRect(0, 0, W, H)
                                                  styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                            NSWindowStyleMaskMiniaturizable | NSWindowStyleMaskResizable
                                                    backing:NSBackingStoreBuffered defer:NO];
        self.window.title = w[@"title"];
        self.window.delegate = self;
        self.window.contentMinSize = NSMakeSize(W, H);         /* the original size is the minimum */
        self.window.contentMaxSize = NSMakeSize(W, 100000);    /* grows vertically only */
        self.open = [NSMutableDictionary dictionary];
        for (NSDictionary *sec in L[@"scroll"][@"sections"])
            for (NSDictionary *row in sec[@"rows"])
                for (NSDictionary *it in row[@"items"])
                    if (it[@"toggles"]) self.open[it[@"toggles"]] = @([it[@"on"] boolValue]);
        [self rebuild];
        [self restoreSettings];
        [self fitHeightToContent];
        [self.window center];
    }
    return self;
}

/* sheets, alerts and the Preview window's place go with the window the user is working in: this
 * one, or the Home / Office / Full Auto window that drives it */
- (NSWindow *)host { return self.hostWindow ?: self.window; }

/* Configuration > Save settings (ESPR +0x2a2, on): the main window's settings come back next time */
static NSArray<NSString *> *ESSavedKeys(void)
{
    return @[ @"documentType", @"docSource", @"aeType", @"filmType", @"imageType", @"imageOption", @"resolution",
              @"srcUnits", @"tgtUnits", @"thresholdValue", @"unsharp", @"unsharpLevel", @"grain", @"grainLevel",
              @"descreen", @"descreenLevel", @"Color Restoration", @"backlight", @"backlightLevel", @"dust",
              @"dustLevel", @"ice", @"iceLevel" ];
}

- (void)saveSettings
{
    NSUserDefaults *ud = NSUserDefaults.standardUserDefaults;
    BOOL save = [ud objectForKey:@"CfgSaveSettings"] ? [ud boolForKey:@"CfgSaveSettings"] : YES;
    if (!save) { [ud removeObjectForKey:@"SavedMainSettings"]; return; }
    [ud setObject:[self snapshotSettings] forKey:@"SavedMainSettings"];
}

/* the main window's settings as Save settings keeps them (also held while another mode drives
 * this window, and put back when Professional Mode comes back) */
- (NSDictionary *)snapshotSettings
{
    NSMutableDictionary *d = [NSMutableDictionary dictionary];
    for (NSString *k in ESSavedKeys()) {
        NSView *v = self.builder.controls[k];
        if (!v) continue;
        BOOL check = ([v isKindOfClass:[AQControl class]] && ((AQControl *)v).kind == AQCheck) ||
                     ([v isKindOfClass:[NSButton class]] && ![v isKindOfClass:[NSPopUpButton class]]);
        d[k] = check ? @(ESIsOn(v)) : ESValue(v);
    }
    return d;
}

- (void)restoreSettings
{
    NSUserDefaults *ud = NSUserDefaults.standardUserDefaults;
    BOOL save = [ud objectForKey:@"CfgSaveSettings"] ? [ud boolForKey:@"CfgSaveSettings"] : YES;
    [self applySettings:save ? [ud dictionaryForKey:@"SavedMainSettings"] : nil];
}

- (void)applySettings:(NSDictionary *)d
{
    if (!d.count) return;
    for (NSString *k in ESSavedKeys()) {
        NSView *v = self.builder.controls[k];
        id val = d[k];
        if (!v || !val) continue;
        if ([val isKindOfClass:[NSNumber class]]) ESSetOn(v, [val boolValue]);
        else if ([v isKindOfClass:[NSTextField class]]) ESSetField(v, val);
        else ESSelectItem(v, val);
    }
    NSString *t = d[@"thresholdValue"];
    if (t) ESSetSliderValue(self.builder.controls[@"threshold"], t.intValue);
    self.lastResolution = d[@"resolution"];
    [self relayout];
    [self updateItemStatus];
}

- (NSDictionary *)layout
{
    NSString *path = [[NSBundle mainBundle] pathForResource:@"professional" ofType:@"json"];
    NSData *d = [NSData dataWithContentsOfFile:path];
    return d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : @{};
}

- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"preview"]) {
        if (!self.preview) self.preview = [ESPreviewWindow new];
        if (!self.preview.window.isVisible) {
            /* like Epson Scan: the Preview window opens to the left of the main window, tops aligned */
            NSRect pf = self.preview.window.frame, mf = [self host].frame;
            pf.origin.x = MAX(NSScreen.mainScreen.visibleFrame.origin.x, mf.origin.x - pf.size.width - 8);
            pf.origin.y = NSMaxY(mf) - pf.size.height;
            [self.preview.window setFrame:pf display:NO];
        }
        [self.preview.window makeKeyAndOrderFront:nil];
        NSDictionary *k = self.builder.controls;
        NSString *doc = ESValue(k[@"documentType"]), *ft = ESValue(k[@"filmType"]), *it = ESValue(k[@"imageType"]);
        BOOL film = [doc hasPrefix:@"Film"];
        BOOL neg = [ft containsString:@"Negative"];
        int dpi = ESValue(k[@"resolution"]).intValue ?: 300;
        int bpp = [it hasPrefix:@"48"] ? 6 : [it hasPrefix:@"24"] || [it hasPrefix:@"Color"] ? 3
                : [it hasPrefix:@"16"] ? 2 : 1;
        self.preview.restoration = k[@"Color Restoration"] && ESIsOn(k[@"Color Restoration"]);
        self.preview.documentAE = !film && [ESValue(k[@"aeType"]) isEqualToString:@"Document"];
        NSString *bl = ESValue(k[@"backlightLevel"]);
        self.preview.backlight = k[@"backlight"] && ESIsOn(k[@"backlight"])
                               ? ([bl hasPrefix:@"Low"] ? 1 : [bl hasPrefix:@"High"] ? 3 : 2) : 0;
        /* the Preview button's menu: Normal or Thumbnail, for film and for the glass (Home Mode
         * decides for itself) */
        self.preview.thumbnailMode = self.forcedThumbnail ? self.forcedThumbnail.boolValue : ESThumbnailPreview(film);
        self.preview.filmTFT = [ft hasPrefix:@"Positive"] ? 2 : [ft hasPrefix:@"B&W"] ? 1 : 0;
        [self.preview startPreviewFilm:film negative:neg targetDPI:dpi bytesPerPixel:bpp];
    } else if ([action hasPrefix:@"target"] || [action hasPrefix:@"trim-"] || [action isEqualToString:@"scale-step"] ||
               [action isEqualToString:@"size-units"]) {
        [self targetAction:action];
    } else if ([action isEqualToString:@"state"]) {
        BOOL film = [self isFilm];
        [self relayout];
        [self updateItemStatus];
        if (!film && self.preview)
            [self.preview rerunAutoExposureDocument:[ESValue(self.builder.controls[@"aeType"]) isEqualToString:@"Document"]];
    } else if ([action hasPrefix:@"autoexposure"]) {
        [self updateItemStatus];
        NSDictionary *k = self.builder.controls;
        NSString *bl = ESValue(k[@"backlightLevel"]);
        int backlight = k[@"backlight"] && ESIsOn(k[@"backlight"])
                      ? ([bl hasPrefix:@"Low"] ? 1 : [bl hasPrefix:@"High"] ? 3 : 2) : 0;
        [self.preview rerunAutoExposureRestoration:k[@"Color Restoration"] && ESIsOn(k[@"Color Restoration"])
                                         backlight:backlight];
    } else if ([action isEqualToString:@"dlg:imageadjust"]) {
        if (!self.preview) self.preview = [ESPreviewWindow new];
        if (!self.imageAdjust) {
            self.imageAdjust = [[ESImageAdjustDialog alloc] initWithPreview:self.preview];
            __weak ESProfessionalWindow *weakSelf = self;
            self.imageAdjust.onAction = ^(NSString *a) { [weakSelf perform:a]; };
        }
        [self.imageAdjust show];
    } else if ([action isEqualToString:@"dlg:histogram"]) {
        if (!self.preview) self.preview = [ESPreviewWindow new];
        if (!self.histogramAdjust) {
            self.histogramAdjust = [[ESHistogramDialog alloc] initWithPreview:self.preview];
            __weak ESProfessionalWindow *weakSelf = self;
            self.histogramAdjust.onAction = ^(NSString *a) { [weakSelf perform:a]; };
        }
        [self.histogramAdjust show];
    } else if ([action isEqualToString:@"dlg:tonecurve"]) {
        if (!self.preview) self.preview = [ESPreviewWindow new];
        if (!self.toneCorrection) {
            self.toneCorrection = [[ESToneDialog alloc] initWithPreview:self.preview];
            __weak ESProfessionalWindow *weakSelf = self;
            self.toneCorrection.onAction = ^(NSString *a) { [weakSelf perform:a]; };
        }
        [self.toneCorrection show];
    } else if ([action isEqualToString:@"dlg:palette"]) {
        if (!self.preview) self.preview = [ESPreviewWindow new];
        if (!self.colorPalette) {
            self.colorPalette = [[ESPaletteDialog alloc] initWithPreview:self.preview];
            __weak ESProfessionalWindow *weakSelf = self;
            self.colorPalette.onAction = ^(NSString *a) { [weakSelf perform:a]; };
        }
        [self.colorPalette show];
    } else if ([action isEqualToString:@"reset-adjust"]) {
        ESAdjust *a = [self.preview selectedAdjust];
        if (a) {
            for (int i = 0; i < 6; i++) [a setField:kAdjustFields[i] value:0];
            if (a.autoPara.length == 0x80) memcpy(a.st->para + 0x0c, (const uint8_t *)a.autoPara.bytes + 0x0c, 0x40);
            a.grayIntensity = -1;
            [self.preview adjustmentsChanged];
            [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self.preview];
        }
    } else if ([action isEqualToString:@"scan"]) {
        [self startScan];
    } else if ([action isEqualToString:@"configuration"]) {
        if (self.busy) return;
        NSUserDefaults *ud = ESCfgPrefs();
        NSInteger gamma = ESScreenGamma10(), level = [ud integerForKey:kCfgExposure], mgr = ESColorMgr();
        BOOL monitor = [ud boolForKey:kCfgUseMonitor];
        NSString *units = [ud stringForKey:kCfgUnits];
        if (![[ESConfigDialog new] run]) return;
        [self.preview updateMode];             /* Preview image rotation shows or hides the Rotation tools */
        /* UpdateConfigInfo: new units show at once; a new display gamma or exposure level
         * redoes the preview's auto exposure */
        if (![[ud stringForKey:kCfgUnits] isEqualToString:units]) {
            ESSelectItem(self.builder.controls[@"srcUnits"], [ud stringForKey:kCfgUnits]);
            [self perform:@"size-units"];
        }
        if (ESScreenGamma10() != gamma || [ud integerForKey:kCfgExposure] != level || ESColorMgr() != mgr ||
            [ud boolForKey:kCfgUseMonitor] != monitor)
            [self.preview reapplyConfiguration];
    } else if ([action isEqualToString:@"filesave"]) {
        if (!self.busy) [[ESFileSaveDialog new] run];
    } else if ([action isEqualToString:@"close"]) {
        [[self host] performClose:nil];
    } else if ([action hasPrefix:@"settings:"]) {
        [self settingsAction:action];
    } else if ([action isEqualToString:@"mode"]) {
        /* the Mode list: the app switches windows (CMainDialog::DoUIModeMenuClick) */
        [NSNotificationCenter.defaultCenter postNotificationName:ESModeChangeRequest
                                                          object:ESValue(self.builder.controls[@"mode"])];
    }
}

/* A page of a multi-page file was scanned: Add Page / Save File (CMsgScnContinueDlg), or save
 * straight away when "Show Add Page dialog after scanning." is off */
- (void)appendPage:(NSDictionary *)page adjust:(NSDictionary *)adj path:(NSString *)outPath
{
    if (!self.multi)
        self.multi = [@{ @"path": outPath, @"dir": adj[@"multiDir"], @"pages": [NSMutableArray array],
                         @"format": adj[@"format"] ?: kFormatMTIFF,
                         @"mm": adj[@"mtiffMM"] ?: @1, @"next": adj[@"nextNumber"] ?: @1,
                         @"g4": @([ESFSPrefs() boolForKey:kMTIFFBWG4] && gImageIsBW),
                         @"open": adj[@"openFolder"] ?: @0 } mutableCopy];
    [self.multi[@"pages"] addObject:page];
}

- (void)addPage:(NSDictionary *)page adjust:(NSDictionary *)adj path:(NSString *)outPath
{
    [self appendPage:page adjust:adj path:outPath];
    if ([ESFSPrefs() boolForKey:kFSAddPage]) {
        int c = [[ESContinueDialog new] run];
        if (c == 1) {                  /* Edit Page: reorder / rotate / delete, then save */
            NSArray *edited = [[ESEditPageWindow new] runWithPages:self.multi[@"pages"]];
            if (!edited) {             /* Cancel: the scans are discarded */
                ESLog(@"Editing Page cancelled: %lu page(s) discarded", (unsigned long)[(NSArray *)self.multi[@"pages"] count]);
                [NSFileManager.defaultManager removeItemAtPath:self.multi[@"dir"] error:nil];
                self.multi = nil;
                return;
            }
            self.multi[@"pages"] = [edited mutableCopy];
        } else if (c == 2) {           /* Add Page: place the next page and click Scan */
            NSArray *pages = self.multi[@"pages"];
            ESLog(@"%@: %lu page(s), adding another", self.multi[@"format"], (unsigned long)pages.count);
            return;
        }
    }
    [self finishMultiPage];
}

/* Save File: CMultiTiff writes the pages in scan order into one file */
- (void)finishMultiPage
{
    NSMutableDictionary *m = self.multi;
    self.multi = nil;
    if (!m) return;
    self.busy = YES;
    ESProgressSheet *sheet = [ESProgressSheet new];
    [[self host] beginSheet:sheet.panel completionHandler:nil];
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        NSArray *pages = m[@"pages"];
        NSString *path = m[@"path"];
        unsigned int link = 0;
        char e[256] = "";
        BOOL ok = YES;
        /* the Editing Page rotations */
        NSMutableArray *turned = [NSMutableArray array];
        for (NSDictionary *pg in pages) {
            int q = [pg[@"quarters"] intValue];
            if (!q || !ok) { [turned addObject:pg]; continue; }
            NSString *out = [m[@"dir"] stringByAppendingPathComponent:[NSString stringWithFormat:@"turn-%@.raw", NSUUID.UUID.UUIDString]];
            int ow = 0, oh = 0;
            ok = es_rotate_raw([pg[@"raw"] fileSystemRepresentation], out.fileSystemRepresentation, [pg[@"w"] intValue],
                               [pg[@"h"] intValue], [pg[@"spp"] intValue], [pg[@"bits"] intValue], q, &ow, &oh, e, sizeof e);
            NSMutableDictionary *np = [pg mutableCopy];
            np[@"raw"] = out; np[@"w"] = @(ow); np[@"h"] = @(oh); np[@"quarters"] = @0;
            [turned addObject:np];
        }
        pages = turned;
        if (ok && ESFSIsPDF(m[@"format"])) {
            ok = [self writePdfPages:pages session:m sheet:sheet error:e size:sizeof e];
            pages = @[];
        }
        es_tiff_set_bw_g4([m[@"g4"] boolValue]);          /* Multi-TIFF Compression > B&W */
        for (NSUInteger i = 0; ok && i < pages.count; i++) {
            NSDictionary *pg = pages[i];
            [sheet step:[NSString stringWithFormat:@"Saving page %lu of %lu...", (unsigned long)i + 1,
                         (unsigned long)pages.count] fraction:(double)i / pages.count];
            ok = es_mtiff_add_page([pg[@"raw"] fileSystemRepresentation], path.fileSystemRepresentation, (int)i, &link,
                                   [pg[@"w"] intValue], [pg[@"h"] intValue], [pg[@"spp"] intValue], [pg[@"bits"] intValue],
                                   [pg[@"dpi"] intValue], [pg[@"dpi"] intValue], [m[@"mm"] boolValue], e, sizeof e);
        }
        if (pages.count)
            ESLog(@"Multi-TIFF: %@ %lu page(s) to %@ %s", ok ? @"saved" : @"FAILED", (unsigned long)pages.count, path, ok ? "" : e);
        [NSFileManager.defaultManager removeItemAtPath:m[@"dir"] error:nil];
        NSString *msg = [NSString stringWithFormat:@"Couldn't save the image: %s", e];
        dispatch_async(dispatch_get_main_queue(), ^{
            [[self host] endSheet:sheet.panel];
            self.busy = NO;
            if (!ok) { [self alert:msg]; return; }
            [ESFSPrefs() setInteger:[m[@"next"] intValue] forKey:kFSStart];
            if ([m[@"open"] boolValue])
                [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:path.stringByDeletingLastPathComponent]];
        });
    });
}

/* CPdf::DoCheckLimitEx: an image bigger than the paper (with its margins) asks first */
- (BOOL)pdfFits:(ESScanParams)p scale:(int)scalePct
{
    NSUserDefaults *ud = ESFSPrefs();
    int w10, h10;
    ESPdfPaper10([ud stringForKey:kPDFPaper], &w10, &h10);
    if (!w10 || p.area_w_mm <= 0 || p.area_h_mm <= 0) return YES;
    if ([ud boolForKey:kPDFLandscape]) { int t = w10; w10 = h10; h10 = t; }
    double k = [[ud stringForKey:kPDFUnits] isEqualToString:@"in."] ? 254 : 10;
    double iw = p.area_w_mm * 10 * scalePct / 100, ih = p.area_h_mm * 10 * scalePct / 100;
    if (iw + [ud doubleForKey:kPDFLeft] * k <= w10 && ih + [ud doubleForKey:kPDFTop] * k <= h10) return YES;
    NSAlert *a = [NSAlert new];
    a.messageText = @"EPSON Scan";
    a.informativeText = ESS_PDF_2004_4;
    [a addButtonWithTitle:@"OK"];
    [a addButtonWithTitle:@"Cancel"];
    return [a runModal] == NSAlertFirstButtonReturn;
}

/* CPdf / CEpPDFCreate::SaveToPDF: all pages in one file, or files of N pages ("Select number to
 * make file"), the later files taking the next numbers */
- (BOOL)writePdfPages:(NSArray *)pages session:(NSMutableDictionary *)m sheet:(ESProgressSheet *)sheet
                error:(char *)e size:(size_t)elen
{
    NSUserDefaults *ud = ESFSPrefs();
    int w10, h10;
    ESPdfPaper10([ud stringForKey:kPDFPaper], &w10, &h10);
    double k = [[ud stringForKey:kPDFUnits] isEqualToString:@"in."] ? 254 : 10;
    int left10 = (int)lround([ud doubleForKey:kPDFLeft] * k), top10 = (int)lround([ud doubleForKey:kPDFTop] * k);
    BOOL high = [[ud stringForKey:kPDFCompression] isEqualToString:@"High Compression"];
    if (high) es_pdf_set_hc_engine([[NSBundle mainBundle] pathForResource:@"PDFLib_i386" ofType:nil].fileSystemRepresentation);
    NSUInteger per = [ud integerForKey:kPDFPageMode] ? (NSUInteger)MAX(1, [ud integerForKey:kPDFPageNumber]) : pages.count;
    NSString *dir = [m[@"path"] stringByDeletingLastPathComponent];
    int next = [m[@"next"] intValue];
    for (NSUInteger start = 0; start < pages.count; start += per) {
        NSUInteger n = MIN(per, pages.count - start);
        NSString *path = m[@"path"];
        if (start > 0) {                       /* MakeCompleteFileName for the next file */
            NSString *err = nil;
            int following = next;
            NSString *name = ESFSMakeFileName(dir, [ud stringForKey:kFSPrefix] ?: @"img", next, @"pdf",
                                              [ud boolForKey:kFSOverwrite], &following, &err);
            if (!name) { snprintf(e, elen, "%s", err.UTF8String); return NO; }
            path = [dir stringByAppendingPathComponent:name];
            next = following;
        }
        EsPdfPage *pp = calloc(n, sizeof *pp);
        for (NSUInteger i = 0; i < n; i++) {
            NSDictionary *pg = pages[start + i];
            pp[i].raw = [pg[@"raw"] fileSystemRepresentation];
            pp[i].w = [pg[@"w"] intValue]; pp[i].h = [pg[@"h"] intValue];
            pp[i].spp = [pg[@"spp"] intValue]; pp[i].bits = [pg[@"bits"] intValue]; pp[i].dpi = [pg[@"dpi"] intValue];
        }
        [sheet step:[NSString stringWithFormat:@"Saving %@...", path.lastPathComponent]
           fraction:(double)start / pages.count];
        BOOL ok = es_save_pdf(path.fileSystemRepresentation, pp, (int)n, w10, h10, [ud boolForKey:kPDFLandscape],
                              left10, top10, high, e, elen);
        free(pp);
        ESLog(@"PDF: %@ %lu page(s) to %@ %s", ok ? @"saved" : @"FAILED", (unsigned long)n, path, ok ? "" : e);
        if (!ok) return NO;
    }
    m[@"next"] = @(next);
    return YES;
}

/* CSettings (Settings: Name, Save, Delete; UISets.dat): named sets of the main window's settings and
 * the Image Adjustment values, recalled from the Name list */
- (NSDictionary *)namedSettings
{
    return [NSUserDefaults.standardUserDefaults dictionaryForKey:@"NamedSettings"] ?: @{};
}

- (void)updateSettingsMenu
{
    NSMutableArray *names = [NSMutableArray arrayWithObject:@"Current Setting"];
    [names addObjectsFromArray:[[self namedSettings].allKeys sortedArrayUsingSelector:@selector(localizedCaseInsensitiveCompare:)]];
    NSView *m = self.builder.controls[@"settingsMenu"];
    if ([m isKindOfClass:[NSPopUpButton class]]) {
        NSPopUpButton *p = (NSPopUpButton *)m;
        [p removeAllItems];
        [p addItemWithTitle:@""];
        [p addItemsWithTitles:names];
    } else ESSetMenu(m, names);
}

- (BOOL)confirm:(NSString *)text
{
    NSAlert *a = [NSAlert new];
    a.messageText = @"EPSON Scan";
    a.informativeText = text;
    [a addButtonWithTitle:@"OK"];
    [a addButtonWithTitle:@"Cancel"];
    return [a runModal] == NSAlertFirstButtonReturn;
}

- (void)settingsAction:(NSString *)action
{
    NSView *field = self.builder.controls[@"settingsName"];
    NSString *name = [ESValue(field) stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
    NSMutableDictionary *all = [[self namedSettings] mutableCopy];
    if ([action isEqualToString:@"settings:pick"]) {
        NSDictionary *set = all[name];
        if (!set) return;                        /* Current Setting: nothing to load */
        [self applySettings:set[@"main"]];
        NSArray *adj = set[@"adjust"];
        ESAdjust *a = [self.preview selectedAdjust];
        if (a && adj.count == 6) {
            for (int i = 0; i < 6; i++) [a setField:kAdjustFields[i] value:[adj[(NSUInteger)i] intValue]];
            [self.preview adjustmentsChanged];
            [NSNotificationCenter.defaultCenter postNotificationName:ESSelectionChanged object:self.preview];
        }
        [self perform:@"state"];
    } else if ([action isEqualToString:@"settings:save"]) {
        if (!name.length || [name isEqualToString:@"Current Setting"]) { NSBeep(); return; }
        if (all[name] && ![self confirm:[NSString stringWithFormat:ESS_UI_10008_14, name]])
            return;
        NSMutableArray *adj = [NSMutableArray array];
        ESAdjust *a = [self.preview selectedAdjust];
        for (int i = 0; i < 6; i++) [adj addObject:@(a ? [a field:kAdjustFields[i]] : 0)];
        all[name] = @{ @"main": [self snapshotSettings], @"adjust": adj };
        [NSUserDefaults.standardUserDefaults setObject:all forKey:@"NamedSettings"];
        [self updateSettingsMenu];
    } else if ([action isEqualToString:@"settings:delete"]) {
        if (!all[name]) { NSBeep(); return; }
        if (![self confirm:[NSString stringWithFormat:ESS_UI_10008_15, name]]) return;
        [all removeObjectForKey:name];
        [NSUserDefaults.standardUserDefaults setObject:all forKey:@"NamedSettings"];
        ESSetField(field, @"Current Setting");
        [self updateSettingsMenu];
    }
}

- (void)alert:(NSString *)text
{
    NSAlert *a = [NSAlert new];
    a.messageText = @"EPSON Scan";
    a.informativeText = text;
    a.alertStyle = NSAlertStyleWarning;
    [a beginSheetModalForWindow:[self host] completionHandler:nil];
}

- (void)startScan
{
    if (self.busy || self.preview.scanning) return;
    /* All marquees (or the checked thumbnails): each is scanned in turn, to its own file (or page) */
    NSArray<NSNumber *> *list = self.batchFollowing ? nil : [self.preview marqueesToScan];
    if (list.count) {
        self.batchQueue = [[list subarrayWithRange:NSMakeRange(1, list.count - 1)] mutableCopy];
        [self.preview selectMarquee:list[0].integerValue];
        if (list.count > 1) ESLog(@"Scanning %lu marquees in turn", (unsigned long)list.count);
    } else if (!self.batchFollowing) self.batchQueue = nil;
    BOOL following = self.batchFollowing;
    self.batchFollowing = NO;
    NSDictionary *k = self.builder.controls;
    NSString *doc = ESValue(k[@"documentType"]), *ft = ESValue(k[@"filmType"]), *it = ESValue(k[@"imageType"]);
    BOOL film = [doc hasPrefix:@"Film"];
    BOOL neg = film && [ft containsString:@"Negative"];
    BOOL color = [it containsString:@"Color"];
    BOOL bits16 = [it hasPrefix:@"48"] || [it hasPrefix:@"16"];
    int dpi = ESValue(k[@"resolution"]).intValue ?: 300;
    /* Scale: Scan Control works at Resolution x Scale / 100 (the marquee's integer scale); the
     * file keeps the Resolution */
    int fileDPI = dpi;
    EsTarget tgt = [self target];
    int scalePct = tgt.sw > 0 ? (int)tgt.scale : 100;
    dpi = dpi * scalePct / 100;
    if (scalePct != 100) ESLog(@"Scale %d%%: %d dpi in the file, worked at %d dpi", scalePct, fileDPI, dpi);
    BOOL ice = film && color && k[@"ice"] && ESIsOn(k[@"ice"]);
    ESLog(@"Scan clicked: document=%@ film=%@ imageType=%@ resolution=%d ICE checkbox=%@ (%@) -> ICE %@",
          doc, ft, it, dpi, k[@"ice"] ? (ESIsOn(k[@"ice"]) ? @"on" : @"off") : @"not found",
          NSStringFromClass([k[@"ice"] class]), ice ? @"will run" : @"will NOT run");

    /* Black & White and Dropout: Epson's interpreter binarizes (value >= threshold is white) and
     * takes one channel of a colour read for the dropout colour; the same is done here on the
     * scan, so a dropout scan reads colour */
    int typeID = [self imageTypeID], dropout = [self dropoutChannel];
    BOOL bw = typeID == 6;
    /* Image Option filters (Epson's DDE): Color Enhance reads colour like a dropout scan;
     * Text Enhancement and Auto Area Segmentation read 8-bit gray and binarize */
    int ddeOpt = [self ddeOption], ceMask = [self colorEnhanceMask];
    if (dropout >= 0 || ddeOpt == ES_DDE_CE) { color = YES; bits16 = NO; }
    ESScanParams p = { 0 };
    p.film = film; p.negative = neg; p.color = color; p.depth16 = bits16; p.dpi = dpi;

    /* Descreening (Reflective): CDTR checks the resolution against CapMaxResForDescreening first;
     * Scan Control (IPInitMoire) then scans at the Descreening table's resolution and the Moire
     * filter blurs the screen and scales to the requested resolution */
    int dsValue = 0, dsDPI = 0;
    if (!film && k[@"descreen"] && ESIsOn(k[@"descreen"])) {
        if (dpi > es_descreen_max_res()) {
            [self alert:ESS_SCANCONTROL_5000_39];
            return;
        }
        NSArray *rulings = @[ @"General", @"Newspaper (85 lpi)", @"Magazine (133 lpi)", @"Fine Prints (175 lpi)" ];
        NSUInteger ruling = [rulings indexOfObject:ESValue(k[@"descreenLevel"])];
        int scanDPI = 0;
        if (es_descreen_params(dpi, ruling == NSNotFound ? 0 : (int)ruling, &scanDPI, &dsValue) == 0) {
            dsDPI = dpi;
            p.dpi = scanDPI; p.dpi_y = scanDPI; p.exact = 1;
            ESLog(@"Descreening: %@, %d dpi -> scan at %d dpi, filter value %d", ESValue(k[@"descreenLevel"]),
                  dpi, scanDPI, dsValue);
        }
    }
    /* Any resolution (CScanner::IPInitZoom): scan at what Device Control's GetResolution picks
     * for it (X and Y can differ), then Epson's Resize filter makes the requested size */
    if (!dsValue) {
        int sx = dpi, sy = dpi;
        if (es_scan_resolution(film, 0, dpi, &sx, &sy) == 0) { p.dpi = sx; p.dpi_y = sy; p.exact = 1; }
        if (sx != dpi || sy != dpi) ESLog(@"Resolution: %d dpi -> scan at %d x %d dpi, then resize", dpi, sx, sy);
    }
    double ax, ay, aw, ah;
    NSArray<NSNumber *> *skewLoc = nil;
    if ([self.preview selectedAreaForFilm:film x:&ax y:&ay w:&aw h:&ah]) {
        p.area_x_mm = ax; p.area_y_mm = ay; p.area_w_mm = aw; p.area_h_mm = ah;
        if (!film && [NSUserDefaults.standardUserDefaults boolForKey:@"CfgSkew"])
            skewLoc = [self.preview skewForAreaX:ax y:ay w:aw h:ah];
    } else if (film) {
        [self alert:@"Run a preview first and select the frame to scan (click it in the Preview window)."];
        return;
    } else if (!NSIsEmptyRect(self.fixedAreaMM)) {
        /* Office Mode's Size and Orientation before there is a preview */
        p.area_x_mm = self.fixedAreaMM.origin.x; p.area_y_mm = self.fixedAreaMM.origin.y;
        p.area_w_mm = self.fixedAreaMM.size.width; p.area_h_mm = self.fixedAreaMM.size.height;
    }
    /* CPreviewDialog::SetScanCapability: DIGITAL ICE's resolution limit (STR#10008 #22) */
    if (ice && dpi > 12800) {
        [self alert:ESS_SCANCONTROL_5000_59];
        return;
    }
    /* CPreviewDialog::CheckSizeLimit (EPSON Scan stand-alone): 30000 pixels on the long side and
     * 10500 (48-bit Color) or 21000 on the short side (STR#10008 #69-#72) */
    long scanW = p.area_w_mm > 0 ? lround(p.area_w_mm / 25.4 * dpi) : 0;
    long scanH = p.area_h_mm > 0 ? lround(p.area_h_mm / 25.4 * dpi) : 0;
    if (scanW > 0 && scanH > 0) {
        long shortMax = typeID == 0 ? 10500 : 21000;
        BOOL wide = scanW >= scanH;
        if ((wide && (scanW > 30000 || scanH > shortMax)) || (!wide && (scanH > 30000 || scanW > shortMax))) {
            /* STR# 10008 #69-#72: 30000 x 10500, 10500 x 30000, 30000 x 21000, 21000 x 30000 */
            [self alert:typeID == 0 ? (wide ? ESS_UI_10008_69 : ESS_UI_10008_70)
                                    : (wide ? ESS_UI_10008_71 : ESS_UI_10008_72)];
            ESLog(@"Size limit: %ld x %ld pixels is over Epson's limit", scanW, scanH);
            return;
        }
    }

    /* Epson's auto exposure result for this marquee (needs a preview of the same source) */
    int colorMgr = ESColorMgr();
    ESAdjust *fit = color && dropout < 0 && ddeOpt != ES_DDE_CE && colorMgr != 2 && self.preview.film == film && !self.preview.scanning
                  ? [self.preview selectedAdjust] : nil;
    NSData *lut = fit.lut;
    /* Adjustments panel */
    NSString *usmLevel = ESValue(k[@"unsharpLevel"]);
    NSDictionary *adj = @{
        @"usm": @(k[@"unsharp"] && ESIsOn(k[@"unsharp"])),
        @"usmLevel": @([usmLevel hasPrefix:@"Low"] ? 0 : [usmLevel hasPrefix:@"High"] ? 2 : 1),
        @"filmType": @(film ? (neg ? ES_FILM_NEGA : ES_FILM_POSI) : ES_FILM_NONE),
        @"grain": @(k[@"grain"] && ESIsOn(k[@"grain"])),
        @"dust": @(k[@"dust"] && ESIsOn(k[@"dust"])),
        @"dustLevel": @([ESValue(k[@"dustLevel"]) hasPrefix:@"Low"] ? 0 : [ESValue(k[@"dustLevel"]) hasPrefix:@"High"] ? 2 : 1),
        @"grainLevel": @([ESValue(k[@"grainLevel"]) hasPrefix:@"Low"] ? 0 : [ESValue(k[@"grainLevel"]) hasPrefix:@"High"] ? 2 : 1),
        @"coef": fit.coef ?: [NSData data],
        @"descreen": @(dsValue),
        @"descreenDPI": @(dsDPI),
        @"targetDPI": @(dpi),
        @"fileDPI": @(fileDPI),
        @"bw": @(bw),
        @"threshold": @([self threshold]),
        @"dropout": @(dropout),
        @"dde": @(ddeOpt),
        @"skewLoc": skewLoc ?: @[],
        @"colorSmooth": @(typeID == 2),
        @"ceMask": @(ceMask),
        @"quarters": @(self.preview.film == film && !self.preview.scanning ? [self.preview selectedQuarters] : 0),
        @"mirror": @(self.preview.film == film && !self.preview.scanning && [self.preview selectedMirrored]),
    };
    if (fit)
        ESLog(@"Image Adjustment: brightness %d contrast %d saturation %d balance %d/%d/%d",
              [fit field:FIT_BRIGHTNESS], [fit field:FIT_CONTRAST], [fit field:FIT_SATURATION],
              [fit field:FIT_BAL_CR], [fit field:FIT_BAL_MG], [fit field:FIT_BAL_YB]);
    ESLog(@"Adjustments: Unsharp Mask %@ (%@), Grain Reduction %@ (%@), Dust Removal %@ (%@)",
          [adj[@"usm"] boolValue] ? @"on" : @"off", usmLevel, [adj[@"grain"] boolValue] ? @"on" : @"off",
          ESValue(k[@"grainLevel"]), [adj[@"dust"] boolValue] ? @"on" : @"off", ESValue(k[@"dustLevel"]));
    if (lut) p.depth16 = 1;      /* the curve is applied to the full 16-bit linear data */
    ESLog(@"Film color: %@", lut ? @"Epson FIT auto exposure from the preview" : @"no preview result - simple conversion");

    /* File Save Settings first when "Show this dialog box before next scan" is on; Cancel stops */
    NSUserDefaults *ud = ESFSPrefs();
    BOOL addingPage = self.multi != nil;   /* Add Page: the next page goes into the same file */
    if (!addingPage && !following && [ud boolForKey:kFSShow] && ![[ESFileSaveDialog new] run]) {
        self.batchQueue = nil;
        return;
    }
    /* GetDestinationFSSpec + MakeCompleteFileName */
    NSString *format = addingPage ? self.multi[@"format"] : ESFSFormat([ud stringForKey:kFSFormat]);
    int radio = (int)[ud integerForKey:kFSRadio];
    NSString *dir = ESFSFolderFor(radio == 1 ? 1 : radio == 3 || radio == 4 ? 3 : 0);
    if (!ESFSWritable(dir)) {
        [self alert:@"The selected folder cannot be found or files cannot be saved there.\nSelect another folder in the File Save Settings dialog."];
        return;
    }
    int next = 1;
    NSString *ferr = nil;
    NSString *name = addingPage ? [self.multi[@"path"] lastPathComponent]
                   : ESFSMakeFileName(dir, [ud stringForKey:kFSPrefix] ?: @"img",
                                      (int)MAX(1, MIN(999, [ud integerForKey:kFSStart])), ESFSExtension(format),
                                      [ud boolForKey:kFSOverwrite], &next, &ferr);
    if (!name) { [self alert:ferr]; return; }
    if (addingPage) { dir = [self.multi[@"path"] stringByDeletingLastPathComponent]; next = [self.multi[@"next"] intValue]; }
    NSMutableDictionary *a2 = [adj mutableCopy];
    a2[@"format"] = format;
    a2[@"tiffMM"] = @([ud boolForKey:kTIFFMM]);
    a2[@"tiffG4"] = @([ud boolForKey:kTIFFBWG4]);
    a2[@"jpegLevel"] = @(MAX(1, MIN(100, [ud integerForKey:kJPEGLevel])));
    a2[@"jpegProgressive"] = @([ud boolForKey:kJPEGProg]);
    a2[@"nextNumber"] = @(next);
    /* the file format plug-in's DoCheckLimit (g_stLIMITINFO / gs_llMaxFileSize): JPEG at most
     * 65500 pixels a side (libjpeg) and 2 GB of image data, TIFF 4 GB, Multi-TIFF and PDF 1.5 GB */
    if (scanW > 0 && scanH > 0) {
        int spp = bw ? 1 : (color && dropout < 0 && ddeOpt != ES_DDE_CE ? 3 : 1);
        double bytes = bw ? (double)((scanW + 7) / 8) * scanH
                          : (double)scanW * scanH * spp * (bits16 && !ESFSIsPDF(format) && ![format hasPrefix:@"JPEG"] ? 2 : 1);
        if (ESFSIsMultiPage(format) && addingPage)
            for (NSDictionary *pg in self.multi[@"pages"])
                bytes += [[NSFileManager.defaultManager attributesOfItemAtPath:pg[@"raw"] error:nil] fileSize];
        double maxBytes = [format hasPrefix:@"JPEG"] ? 2147483647.0 : ESFSIsTIFF(format) ? 4294967295.0
                        : ESFSIsMulti(format) ? 1610612736.0 : 1610612736.0;
        if ((([format hasPrefix:@"JPEG"] || [format isEqualToString:kFormatPIMJ]) && (scanW > 65500 || scanH > 65500)) ||
            (ESFSIsPICT(format) && (scanW > 32767 || scanH > 32767))) {
            [self alert:ESS_UI_10008_43];
            return;
        }
        if (bytes > maxBytes) {
            [self alert:ESS_UI_10008_46];
            ESLog(@"Size limit: %.0f bytes is over %@'s %.0f", bytes, format, maxBytes);
            return;
        }
        /* STR#10008 #47: not enough room where the file goes */
        NSDictionary *fs = [NSFileManager.defaultManager attributesOfFileSystemForPath:dir error:nil];
        if (fs[NSFileSystemFreeSize] && [fs[NSFileSystemFreeSize] doubleValue] < bytes) {
            [self alert:ESS_UI_10008_47];
            return;
        }
    }
    if (ESFSIsPDF(format) && ![self pdfFits:p scale:scalePct]) return;
    /* CPdf::DoCheckHighCompLimit: past 7000 x 5000 pixels the page is saved with Standard Compression */
    if (ESFSIsPDF(format) && [[ud stringForKey:kPDFCompression] isEqualToString:@"High Compression"] && scanW > 0 &&
        !es_pdf_high_fits((int)scanW, (int)scanH, [ud boolForKey:kPDFLandscape]))
        [self alert:ESS_PDF_2004_5];
    if (ESFSIsMultiPage(format)) {
        a2[@"format"] = format;
        a2[@"multiDir"] = self.multi[@"dir"] ?: [ESWorkFolder() stringByAppendingPathComponent:
                                                 [NSString stringWithFormat:@"esmulti-%@", NSUUID.UUID.UUIDString]];
        a2[@"mtiffMM"] = addingPage ? self.multi[@"mm"] : @([ud boolForKey:kMTIFFMM]);
    }
    a2[@"openFolder"] = @([ud boolForKey:kFSOpen]);
    /* Configuration > Color */
    a2[@"colorMgr"] = @(colorMgr);
    if (colorMgr == 1 && color) {
        NSString *srcICC = [[NSBundle mainBundle] pathForResource:film ? @"PERV550F" : @"PERV550R" ofType:@"ICC"];
        NSString *dstICC = ESTargetProfilePath();
        if (!srcICC || !dstICC) {
            [self alert:ESS_UI_10008_27_V1];
            dstICC = ESTargetProfilePath();
        }
        if (srcICC && dstICC) {
            a2[@"cmmSource"] = srcICC;
            a2[@"cmmTarget"] = dstICC;
            BOOL embed = ESFSIsTIFF(format) ? [ud boolForKey:kTIFFICC] : [ud boolForKey:kJPEGICC];
            NSData *icc = embed ? [NSData dataWithContentsOfFile:dstICC] : nil;
            if (icc) a2[@"embedICC"] = icc;
            ESLog(@"ColorSync: %@ -> %@%@", srcICC.lastPathComponent, dstICC.lastPathComponent, icc ? @" (embedded)" : @"");
        }
    }
    NSString *outPath = [dir stringByAppendingPathComponent:name];
    ESLog(@"File Save: %@ (%@)", outPath, format);
    [self runScan:p ice:ice negative:neg bits16:bits16 lut:lut adjust:a2 to:outPath];
}

- (void)runScan:(ESScanParams)p ice:(BOOL)ice negative:(BOOL)neg bits16:(BOOL)bits16 lut:(NSData *)lut
         adjust:(NSDictionary *)adj to:(NSString *)outPath
{
    self.busy = YES;
    ESProgressSheet *sheet = [ESProgressSheet new];
    [[self host] beginSheet:sheet.panel completionHandler:nil];
    NSString *tmp = [ESWorkFolder() stringByAppendingPathComponent:
                     [NSString stringWithFormat:@"esscan-%@", NSUUID.UUID.UUIDString]];
    [NSFileManager.defaultManager createDirectoryAtPath:tmp withIntermediateDirectories:YES attributes:nil error:nil];
    NSString *engine = [[NSBundle mainBundle] pathForResource:@"DigitalICE_i386" ofType:nil];

    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        NSString *err = nil;
        char cerr[512] = "";
        ESJob j = { .sheet = sheet };
        __block ESScanResult res = { 0 };
        NSString *rgb = [tmp stringByAppendingPathComponent:@"rgb.raw"];
        NSString *src = rgb;            /* raw file that gets converted to the TIFF */
        int spp = p.color ? 3 : 1, inBits = p.depth16 ? 16 : 8;
        BOOL ok = es_open(NULL) == 0;
        if (!ok) err = [NSString stringWithUTF8String:es_last_error()];

        if (ok && !ice) {
            j.base = 0; j.span = 0.9; j.text = @"Scanning...";
            ok = ESScanToFile(p, rgb, &j, &res, &err);
            ESLog(@"Scan (no ICE): ok=%d %dx%d at %d dpi", ok, res.width, res.height, res.dpi);
        } else if (ok) {
            /* Digital ICE: 16-bit color pass + infrared pass at the same (IR) resolution */
            ESScanParams c = p;
            /* CICEScanner::IPInitZoom: GetDICEResolution, then resize to the requested resolution */
            int target = [adj[@"targetDPI"] intValue] ?: p.dpi, ix = 3200, iy = 3200;
            es_scan_resolution(1, 1, target, &ix, &iy);
            c.dpi = ix; c.dpi_y = iy; c.exact = 1;
            c.depth16 = 1; inBits = 16;
            j.base = 0; j.span = 0.35; j.text = @"Scanning (color)...";
            ok = ESScanToFile(c, rgb, &j, &res, &err);
            ESLog(@"ICE color pass: ok=%d %dx%d at %d dpi, %d-bit", ok, res.width, res.height, res.dpi, res.depth);
            ESScanResult ires = { 0 };
            NSString *ir = [tmp stringByAppendingPathComponent:@"ir.raw"];
            if (ok) {
                ESScanParams i = c;
                i.infrared = 1; i.color = 0;
                j.base = 0.35; j.span = 0.25; j.text = @"Scanning (infrared)...";
                ok = ESScanToFile(i, ir, &j, &ires, &err);
                ESLog(@"ICE infrared pass: ok=%d %dx%d at %d dpi, %d-bit", ok, ires.width, ires.height, ires.dpi, ires.depth);
            }
            if (ok && (ires.width != res.width || ires.height < res.height)) {
                ok = NO; err = @"The infrared pass didn't match the color pass. Please try again.";
            }
            NSString *ira = [tmp stringByAppendingPathComponent:@"ir_aligned.raw"];
            NSString *iced = [tmp stringByAppendingPathComponent:@"ice.raw"];
            if (ok) {
                [sheet step:@"Aligning infrared..." fraction:0.6];
                int dy = 2, dx = 2;     /* typical V550 offset if the image has too little detail to measure */
                NSUserDefaults *d = NSUserDefaults.standardUserDefaults;
                if ([d objectForKey:@"ICEShiftX"] || [d objectForKey:@"ICEShiftY"]) {
                    dy = (int)[d integerForKey:@"ICEShiftY"]; dx = (int)[d integerForKey:@"ICEShiftX"];
                    ESLog(@"ICE alignment: fixed by setting, dy=%d dx=%d", dy, dx);
                } else if (ir_estimate_shift(rgb.fileSystemRepresentation, ir.fileSystemRepresentation,
                                             res.width, res.height, &dy, &dx) != 0) {
                    ESLog(@"ICE alignment: couldn't measure, using default 2,2");
                    dy = 2; dx = 2;
                } else ESLog(@"ICE alignment: measured shift dy=%d dx=%d", dy, dx);
                IRMap map;
                char rep[256] = "";
                if ([d objectForKey:@"ICEShiftX"] || [d objectForKey:@"ICEShiftY"]) {
                    memset(&map, 0, sizeof map); map.ax[0] = dx; map.ay[0] = dy;
                } else {
                    [sheet step:@"Aligning infrared (local)..." fraction:0.6];
                    ir_measure_map(rgb.fileSystemRepresentation, ir.fileSystemRepresentation,
                                   res.width, res.height, dy, dx, &map, rep, sizeof rep);
                    ESLog(@"ICE local alignment: %s", rep);
                }
                ok = ir_warp_file(ir.fileSystemRepresentation, ira.fileSystemRepresentation,
                                  res.width, res.height, &map) == 0;
                if (!ok) err = @"Couldn't align the infrared scan.";
            }
            if (ok && !sheet.cancelled) {
                j.base = 0.62; j.span = 0.33;
                [sheet step:@"DIGITAL ICE: removing dust and scratches..." fraction:0.62];
                ok = ice_film(engine.fileSystemRepresentation, rgb.fileSystemRepresentation,
                              ira.fileSystemRepresentation, iced.fileSystemRepresentation,
                              res.width, res.height, res.dpi, 2, 9, job_ice_progress, &j, cerr, sizeof cerr) == 0;
                ESLog(@"DIGITAL ICE engine: %@ %s", ok ? @"finished" : @"FAILED", cerr);
                ESLogIRStats(ira, res.width, res.height);
                NSUserDefaults *dd = NSUserDefaults.standardUserDefaults;
                if ([dd boolForKey:@"ICEDebug"]) {
                    int cx = [dd objectForKey:@"ICEDebugX"] ? (int)[dd integerForKey:@"ICEDebugX"] : res.width / 2;
                    int cy = [dd objectForKey:@"ICEDebugY"] ? (int)[dd integerForKey:@"ICEDebugY"] : res.height / 2;
                    NSString *base = [outPath stringByDeletingPathExtension];
                    ESDebugCrop(rgb, res.width, res.height, 3, cx, cy, res.dpi, [base stringByAppendingString:@"_debug_1_color.tif"]);
                    ESDebugCrop(ir, res.width, res.height, 1, cx, cy, res.dpi, [base stringByAppendingString:@"_debug_2_infrared.tif"]);
                    ESDebugCrop(ira, res.width, res.height, 1, cx, cy, res.dpi, [base stringByAppendingString:@"_debug_3_infrared_aligned.tif"]);
                    if (ok) ESDebugCrop(iced, res.width, res.height, 3, cx, cy, res.dpi, [base stringByAppendingString:@"_debug_4_after_ice.tif"]);
                    ESLog(@"ICE debug crops written around x=%d y=%d", cx, cy);
                }
                if (!ok && !sheet.cancelled) err = [NSString stringWithFormat:@"DIGITAL ICE failed: %s", cerr];
                src = iced;
            }
        }
        NSString *eng = [[NSBundle mainBundle] pathForResource:@"ImageFilter_i386" ofType:nil];
        int dsValue = [adj[@"descreen"] intValue], dsDPI = [adj[@"descreenDPI"] intValue];
        /* Descreening: the requested size, computed like the scan's own (area at the new resolution) */
        int (^descreen)(NSString *, NSString *, int, BOOL) = ^int(NSString *in, NSString *out, int channels, BOOL b16) {
            int ow = p.area_w_mm > 0 ? (int)(p.area_w_mm / 25.4 * dsDPI + 0.5) : (int)lround((double)res.width * dsDPI / res.dpi);
            int oh = p.area_h_mm > 0 ? (int)(p.area_h_mm / 25.4 * dsDPI + 0.5) : (int)lround((double)res.height * dsDPI / res.dpi);
            [sheet step:@"Descreening..." fraction:0.962];
            char e2[256] = "";
            int rc = es_descreen_file(eng.fileSystemRepresentation, in.fileSystemRepresentation, res.width, res.height,
                                      out.fileSystemRepresentation, ow, oh, channels, b16, dsDPI, dsValue, e2, sizeof e2);
            ESLog(@"Descreening: %dx%d at %d dpi -> %dx%d at %d dpi, value %d: %s", res.width, res.height, res.dpi,
                  ow, oh, dsDPI, dsValue, rc ? e2 : "done");
            if (rc == 0) { res.width = ow; res.height = oh; res.dpi = dsDPI; }
            return rc;
        };
        int target = [adj[@"targetDPI"] intValue];
        int fileDPI = [adj[@"fileDPI"] intValue];
        /* Resize (IPInitZoom): from the scanned resolution(s) to the requested one, first thing after
         * the scan in Epson's chain (where Descreening goes when it's on) */
        int (^resize)(NSString *, NSString *, int, BOOL) = ^int(NSString *in, NSString *out, int channels, BOOL b16) {
            int ry = res.dpi_y ?: res.dpi;
            int ow = p.area_w_mm > 0 ? (int)(p.area_w_mm / 25.4 * target) : (int)lround((double)res.width * target / res.dpi);
            int oh = p.area_h_mm > 0 ? (int)(p.area_h_mm / 25.4 * target) : (int)lround((double)res.height * target / ry);
            [sheet step:@"Resizing..." fraction:0.962];
            char e2[256] = "";
            int rc = es_resize_file(eng.fileSystemRepresentation, in.fileSystemRepresentation, res.width, res.height,
                                    out.fileSystemRepresentation, ow, oh, channels, b16, e2, sizeof e2);
            ESLog(@"Resize: %dx%d at %d x %d dpi -> %dx%d at %d dpi: %s", res.width, res.height, res.dpi, ry,
                  ow, oh, target, rc ? e2 : "done");
            if (rc == 0) { res.width = ow; res.height = oh; res.dpi = target; res.dpi_y = target; }
            return rc;
        };
        /* The file format plug-in: Epson TIFF layout or Epson JPEG settings; the file keeps the
         * Resolution (fileDPI) */
        __block NSString *saveErr = nil;
        __block NSDictionary *multiPage = nil;
        BOOL (^save)(NSString *, int, int) = ^BOOL(NSString *raw, int channels, int bits) {
            char e2[512] = "";
            int fdpi = fileDPI ?: res.dpi;
            NSString *fmt = adj[@"format"] ?: kFormatTIFF;
            NSBundle *mb = [NSBundle mainBundle];
            NSString *dtr1 = [mb pathForResource:@"DTR_i386" ofType:nil];
            /* Color Smoothing (CImgProcessMgr::ImageProcess -> CColReduction::DoColorReduction): Epson
             * builds the palette from the marquee in the preview; the scan itself, reduced to preview
             * size, stands in for it here */
            if ([adj[@"colorSmooth"] boolValue] && channels == 3 && bits == 8 && dtr1) {
                [sheet step:@"Color Smoothing..." fraction:0.975];
                int pw = res.width, ph = res.height, step = 1;
                while (pw / step > 800 || ph / step > 800) step++;
                pw = res.width / step; ph = res.height / step;
                NSMutableData *pv = [NSMutableData dataWithLength:(NSUInteger)pw * ph * 3];
                FILE *pf = fopen(raw.fileSystemRepresentation, "rb");
                NSMutableData *row = [NSMutableData dataWithLength:(NSUInteger)res.width * 3];
                for (int y = 0; pf && y < ph; y++) {
                    fseeko(pf, (off_t)y * step * res.width * 3, SEEK_SET);
                    if (fread(row.mutableBytes, 1, row.length, pf) != row.length) break;
                    for (int x = 0; x < pw; x++)
                        memcpy((uint8_t *)pv.mutableBytes + ((size_t)y * pw + x) * 3, (uint8_t *)row.bytes + (size_t)x * step * 3, 3);
                }
                if (pf) fclose(pf);
                int area[4] = { 0, 0, pw, ph };
                if (es_color_smoothing_file(dtr1.fileSystemRepresentation, raw.fileSystemRepresentation, res.width,
                                            res.height, pv.bytes, pw, ph, area, e2, sizeof e2)) {
                    saveErr = [NSString stringWithFormat:@"Color Smoothing failed: %s", e2];
                    return NO;
                }
                ESLog(@"Color Smoothing: palette from %dx%d", pw, ph);
            }
            /* Correct Document Skew (CScanner::DoSkew / IPC_SKInit) */
            NSArray<NSNumber *> *sk = adj[@"skewLoc"];
            if (sk.count == 9 && dtr1) {
                [sheet step:@"Correcting skew..." fraction:0.98];
                Dtr1Location loc = { sk[0].doubleValue, { 0 } };
                for (int k = 0; k < 8; k++) loc.loc[k] = (int32_t)lround(sk[1 + k].doubleValue * res.dpi);
                NSString *dsk = [raw stringByAppendingString:@".skew"];
                int ow = 0, oh = 0;
                if (es_deskew_file(dtr1.fileSystemRepresentation, raw.fileSystemRepresentation, dsk.fileSystemRepresentation,
                                   res.width, res.height, channels, bits, &loc, &ow, &oh, e2, sizeof e2)) {
                    saveErr = [NSString stringWithFormat:@"Correct Document Skew failed: %s", e2];
                    return NO;
                }
                [NSFileManager.defaultManager removeItemAtPath:raw error:nil];
                [NSFileManager.defaultManager moveItemAtPath:dsk toPath:raw error:nil];
                ESLog(@"Correct Document Skew: %dx%d -> %dx%d", res.width, res.height, ow, oh);
                res.width = ow; res.height = oh;
            }
            /* the preview's rotation (CPreviewWnd Rotate) turns the image the same way */
            int quarters = [adj[@"quarters"] intValue] & 3;
            BOOL mirror = [adj[@"mirror"] boolValue];      /* Thumbnail: Mirroring */
            if (quarters || mirror) {
                NSString *rot = [raw stringByAppendingString:@".rot"];
                int ow = 0, oh = 0;
                if (!es_transform_raw(raw.fileSystemRepresentation, rot.fileSystemRepresentation, res.width, res.height,
                                      channels, bits, quarters, mirror, &ow, &oh, e2, sizeof e2)) {
                    saveErr = [NSString stringWithFormat:@"Couldn't rotate the image: %s", e2];
                    return NO;
                }
                [NSFileManager.defaultManager removeItemAtPath:raw error:nil];
                [NSFileManager.defaultManager moveItemAtPath:rot toPath:raw error:nil];
                ESLog(@"%@rotated %d quarter turn(s) clockwise: %dx%d -> %dx%d", mirror ? @"Mirrored, " : @"",
                      quarters, res.width, res.height, ow, oh);
                res.width = ow; res.height = oh;
            }
            if (adj[@"cmmSource"] && channels == 3) {
                [sheet step:@"Color matching (ColorSync)..." fraction:0.985];
                NSString *cmErr = nil;
                if (!ESColorMatchFile(raw, res.width, res.height, bits, adj[@"cmmSource"], adj[@"cmmTarget"], &cmErr)) {
                    saveErr = cmErr;
                    return NO;
                }
            }
            NSData *icc = channels == 3 ? adj[@"embedICC"] : nil;
            if (adj[@"multiDir"]) {    /* CMltPgSaveMgr::SetImageData: keep the page until Save File */
                NSString *mdir = adj[@"multiDir"];
                [NSFileManager.defaultManager createDirectoryAtPath:mdir withIntermediateDirectories:YES attributes:nil error:nil];
                NSString *page = [mdir stringByAppendingPathComponent:[NSString stringWithFormat:@"page-%@.raw", NSUUID.UUID.UUIDString]];
                NSError *mvErr = nil;
                if (![NSFileManager.defaultManager moveItemAtPath:raw toPath:page error:&mvErr]) {
                    saveErr = [NSString stringWithFormat:@"Couldn't keep the scanned page: %@", mvErr.localizedDescription];
                    return NO;
                }
                multiPage = @{ @"raw": page, @"w": @(res.width), @"h": @(res.height), @"spp": @(channels),
                               @"bits": @(bits), @"dpi": @(fdpi) };
                ESLog(@"Multi-TIFF page kept: %dx%d, %d channel(s), %d-bit", res.width, res.height, channels, bits);
                return YES;
            }
            [sheet step:@"Saving..." fraction:0.99];
            int rc;
            es_tiff_set_bw_g4(bits == 1 && [adj[@"tiffG4"] boolValue]);
            if (ESFSIsPICT(fmt))
                rc = es_save_pict(raw.fileSystemRepresentation, outPath.fileSystemRepresentation, res.width, res.height,
                                  channels, bits, fdpi, e2, sizeof e2);
            else if (ESFSIsPIM(fmt)) {
                /* CExif::DoFinish: a plain 24-bit TIFF, then the PIM engine (CEsExfIF::EsExf_Entry) */
                BOOL pj = [fmt isEqualToString:kFormatPIMJ];
                NSString *rgb = raw, *tif = [raw stringByAppendingString:@".pim.tif"];
                rc = 1;
                if (channels != 3 || bits != 8) {
                    rgb = [raw stringByAppendingString:@".rgb"];
                    rc = es_raw_to_rgb8(raw.fileSystemRepresentation, rgb.fileSystemRepresentation, res.width, res.height,
                                        channels, bits, e2, sizeof e2);
                }
                if (rc) rc = es_save_tiff(rgb.fileSystemRepresentation, tif.fileSystemRepresentation, res.width, res.height,
                                          3, 8, fdpi, fdpi, 1, NULL, 0, e2, sizeof e2);
                if (rc) {
                    NSString *eng = [[NSBundle mainBundle] pathForResource:pj ? @"PIMJPEGSupport_i386" : @"PIMTIFFSupport_i386"
                                                                    ofType:nil];
                    NSString *work = tif.stringByDeletingLastPathComponent;
                    unsigned long q = pj ? (unsigned long)(100 - [ESFSPrefs() integerForKey:kJPEGLevel]) : 0;
                    int pr = (pj ? pim_jpeg_make : pim_tiff_make)(eng.fileSystemRepresentation, work.fileSystemRepresentation,
                                                                 tif.fileSystemRepresentation, outPath.fileSystemRepresentation,
                                                                 "EPSON Scan", q, e2, sizeof e2);
                    rc = pr == 0;
                }
                if (rgb != raw) [NSFileManager.defaultManager removeItemAtPath:rgb error:nil];
                [NSFileManager.defaultManager removeItemAtPath:tif error:nil];
            }
            else if (ESFSIsTIFF(fmt))
                rc = es_save_tiff(raw.fileSystemRepresentation, outPath.fileSystemRepresentation, res.width, res.height,
                                  channels, bits, fdpi, fdpi, [adj[@"tiffMM"] boolValue], icc.bytes, icc.length, e2, sizeof e2);
            else
                rc = es_save_jpeg(raw.fileSystemRepresentation, outPath.fileSystemRepresentation, res.width, res.height,
                                  channels, bits, fdpi, fdpi, [adj[@"jpegLevel"] intValue],
                                  [adj[@"jpegProgressive"] boolValue], icc.bytes, icc.length, e2, sizeof e2);
            ESLog(@"Saved %@: %dx%d, %d channel(s), %d-bit, %d dpi: %s", fmt, res.width, res.height, channels, bits,
                  fdpi, rc ? "ok" : e2);
            if (!rc) saveErr = [NSString stringWithFormat:@"Couldn't save the image: %s", e2];
            return rc != 0;
        };
        BOOL (^needsResize)(void) = ^BOOL { return target > 0 && !dsValue && (res.dpi != target || (res.dpi_y ?: res.dpi) != target); };
        if (ok && !sheet.cancelled) {
            [sheet step:@"Saving..." fraction:0.96];
            if (lut && spp == 3 && inBits == 16) {
                /* Epson's order: tone curve, then Unsharp Mask on the toned image */
                uint16_t *t12 = malloc(sizeof(uint16_t) * 3 * 4096);
                fit_make_lut12(lut.bytes, NULL, t12);
                int outBits = bits16 ? 16 : 8;
                NSString *toned = [tmp stringByAppendingPathComponent:@"toned.raw"];
                ok = es_apply_lut_raw(src.fileSystemRepresentation, toned.fileSystemRepresentation,
                                      res.width, res.height, t12, outBits, cerr, sizeof cerr) == 0;
                free(t12);
                NSData *coef = adj[@"coef"];
                if (ok && coef.length == 9 * sizeof(double) && !sheet.cancelled) {
                    /* Epson's colour correction + saturation, after the tone curve (as in its preview) */
                    ok = es_apply_matrix_raw(toned.fileSystemRepresentation, res.width, res.height, outBits == 16,
                                             coef.bytes, cerr, sizeof cerr) == 0;
                    if (!ok) err = [NSString stringWithFormat:@"Color correction failed: %s", cerr];
                }
                NSString *final = toned;
                if (ok && dsValue > 0 && !sheet.cancelled) {        /* same place as Grain Reduction */
                    NSString *ds = [tmp stringByAppendingPathComponent:@"descreen.raw"];
                    ok = descreen(final, ds, 3, outBits == 16) == 0;
                    if (!ok) err = @"Descreening failed.";
                    final = ds;
                } else if (ok && needsResize() && !sheet.cancelled) {
                    NSString *rs = [tmp stringByAppendingPathComponent:@"resized.raw"];
                    ok = resize(final, rs, 3, outBits == 16) == 0;
                    if (!ok) err = @"Resizing failed.";
                    final = rs;
                }
                if (ok && [adj[@"grain"] boolValue] && !sheet.cancelled) {
                    int g = es_grain_value(res.dpi, [adj[@"grainLevel"] intValue]);
                    if (g > 0) {
                        [sheet step:@"Grain Reduction..." fraction:0.965];
                        NSString *smooth = [tmp stringByAppendingPathComponent:@"grain.raw"];
                        ESLog(@"Grain Reduction: value %d at %d dpi", g, res.dpi);
                        ok = es_grain_file(eng.fileSystemRepresentation, final.fileSystemRepresentation,
                                           smooth.fileSystemRepresentation, res.width, res.height, bits16,
                                           res.dpi, g, cerr, sizeof cerr) == 0;
                        if (!ok) err = [NSString stringWithFormat:@"Grain Reduction failed: %s", cerr];
                        final = smooth;
                    }
                }
                if (ok && [adj[@"usm"] boolValue] && !sheet.cancelled) {
                    [sheet step:@"Unsharp Mask..." fraction:0.97];
                    IfUsmParams up;
                    double sg = ESScreenGamma10() / 10.0;
                    if (es_usm_params(res.dpi, [adj[@"usmLevel"] intValue], [adj[@"filmType"] intValue],
                                      self.preview.backlight, sg,
                                      lut.bytes, &up) == 0) {
                        NSString *sharp = [tmp stringByAppendingPathComponent:@"sharp.raw"];
                        ESLog(@"Unsharp Mask: strength %d radius %d clipping %d at %d dpi", up.strength, up.radius,
                              up.clipping, res.dpi);
                        ok = es_usm_file(eng.fileSystemRepresentation, final.fileSystemRepresentation,
                                         sharp.fileSystemRepresentation, res.width, res.height, bits16, &up,
                                         cerr, sizeof cerr) == 0;
                        if (!ok) err = [NSString stringWithFormat:@"Unsharp Mask failed: %s", cerr];
                        final = sharp;
                    }
                }
                if (ok && [adj[@"dust"] boolValue] && !sheet.cancelled) {
                    [sheet step:@"Dust Removal..." fraction:0.98];
                    int dp[8], dtype;
                    es_dust_params([adj[@"dustLevel"] intValue], [adj[@"filmType"] intValue], dp, &dtype);
                    NSString *deng = [[NSBundle mainBundle] pathForResource:@"EsDDC_i386" ofType:nil];
                    NSString *prm = [[NSBundle mainBundle] pathForResource:@"EsDDC" ofType:@"prm"];
                    ESLog(@"Dust Removal: level %d, type %d", [adj[@"dustLevel"] intValue], dtype);
                    ok = es_dust_file(deng.fileSystemRepresentation, prm.fileSystemRepresentation,
                                      final.fileSystemRepresentation, res.width, res.height, bits16, res.dpi,
                                      dtype, dp, cerr, sizeof cerr) == 0;
                    if (!ok) err = [NSString stringWithFormat:@"Dust Removal failed: %s", cerr];
                }
                if (ok) ok = save(final, 3, outBits);
            } else {
            if (ok && dsValue > 0 && !sheet.cancelled) {
                /* no auto exposure result (no preview): the filter runs on the scanner's data */
                NSString *ds = [tmp stringByAppendingPathComponent:@"descreen.raw"];
                ok = descreen(src, ds, spp, inBits == 16) == 0;
                if (!ok) err = @"Descreening failed.";
                src = ds;
            } else if (ok && needsResize() && !sheet.cancelled) {
                NSString *rs = [tmp stringByAppendingPathComponent:@"resized.raw"];
                ok = resize(src, rs, spp, inBits == 16) == 0;
                if (!ok) err = @"Resizing failed.";
                src = rs;
            }
            NSString *conv = [tmp stringByAppendingPathComponent:@"out.raw"];
            int dch = [adj[@"dropout"] intValue];
            BOOL bw = [adj[@"bw"] boolValue];
            int ddeOpt = [adj[@"dde"] intValue];
            if (ok && ddeOpt && !sheet.cancelled) {
                NSBundle *mb = [NSBundle mainBundle];
                EsDdeJob job = { ddeOpt, [adj[@"ceMask"] intValue], bw, [adj[@"threshold"] intValue], res.dpi,
                                 /* the UI asks for gamma 1.8 with Text Enhancement (CScanBase::SetScanCapability) */
                                 ddeOpt == ES_DDE_TET ? 1.8 : ESScreenGamma10() / 10.0,
                                 [mb pathForResource:@"ImageFilter_i386" ofType:nil].fileSystemRepresentation,
                                 [mb pathForResource:@"EsDDE_i386" ofType:nil].fileSystemRepresentation,
                                 [mb pathForResource:@"EsDDE" ofType:@"prm"].fileSystemRepresentation };
                [sheet step:ddeOpt == ES_DDE_CE ? @"Color Enhance..." : ddeOpt == ES_DDE_TET
                            ? @"Text Enhancement Technology..." : @"Auto Area Segmentation..." fraction:0.95];
                ok = es_dde_run(&job, src.fileSystemRepresentation, conv.fileSystemRepresentation, res.width,
                                res.height, spp, inBits, neg, cerr, sizeof cerr) == 0;
                ESLog(@"Image Option: %@%@", ddeOpt == ES_DDE_CE ? [NSString stringWithFormat:@"Color Enhance mask 0x%x",
                      [adj[@"ceMask"] intValue]] : ddeOpt == ES_DDE_TET ? @"Text Enhancement Technology"
                      : @"Auto Area Segmentation", ok ? @"" : [NSString stringWithFormat:@" failed: %s", cerr]);
                if (!ok) err = [NSString stringWithFormat:@"Image Option failed: %s", cerr];
                if (ok) ok = save(conv, 1, (bw || ddeOpt != ES_DDE_CE) ? 1 : 8);
            } else if (ok && (bw || dch >= 0)) {
                ok = es_mono_convert(src.fileSystemRepresentation, conv.fileSystemRepresentation, res.width, res.height,
                                     spp, inBits, dch, ESScreenGamma10() / 10.0, bw, [adj[@"threshold"] intValue], neg,
                                     cerr, sizeof cerr) == 0;
                ESLog(@"%@%@: threshold %d", bw ? @"Black & White" : @"8-bit Grayscale",
                      dch >= 0 ? [NSString stringWithFormat:@", dropout channel %d", dch] : @"", [adj[@"threshold"] intValue]);
                if (ok) ok = save(conv, 1, bw ? 1 : 8);
            } else {
                if (ok)
                    ok = ([adj[@"colorMgr"] intValue] == 2
                          ? es_convert_plain(src.fileSystemRepresentation, conv.fileSystemRepresentation, res.width,
                                             res.height, spp, inBits, bits16 ? 16 : 8, neg, 1.8, cerr, sizeof cerr)
                          : es_convert_to_raw_gamma(src.fileSystemRepresentation, conv.fileSystemRepresentation,
                                                    res.width, res.height, spp, inBits, bits16 ? 16 : 8, neg,
                                                    [adj[@"colorMgr"] intValue] == 1 ? 1.8 : 2.2, cerr, sizeof cerr)) == 0;
                if (ok) ok = save(conv, spp, bits16 ? 16 : 8);
            }
            }
            if (!ok && !err) err = saveErr ?: [NSString stringWithFormat:@"Couldn't save the image: %s", cerr];
        }
        BOOL cancelled = sheet.cancelled;
        ESLog(@"Result: %@ %@%@", cancelled ? @"cancelled" : ok ? @"saved" : @"failed", outPath, err ? [@" - " stringByAppendingString:err] : @"");
        [NSFileManager.defaultManager removeItemAtPath:tmp error:nil];
        dispatch_async(dispatch_get_main_queue(), ^{
            [[self host] endSheet:sheet.panel];
            self.busy = NO;
            if (cancelled) {
                self.batchQueue = nil;
                [NSFileManager.defaultManager removeItemAtPath:outPath error:nil];
                return;
            }
            if (!ok) { self.batchQueue = nil; [self alert:err.length ? err : @"The scan couldn't be completed."]; return; }
            BOOL more = self.batchQueue.count > 0;
            if (multiPage) {
                if (more) [self appendPage:multiPage adjust:adj path:outPath];   /* the dialog comes after the last */
                else [self addPage:multiPage adjust:adj path:outPath];
            } else {
                /* the plug-in moves on to the next number; "Open image folder after scanning" */
                if (adj[@"nextNumber"]) [ESFSPrefs() setInteger:[adj[@"nextNumber"] intValue] forKey:kFSStart];
                if ([adj[@"openFolder"] boolValue] && !more)
                    [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:outPath.stringByDeletingLastPathComponent]];
            }
            if (more) {
                NSInteger next = self.batchQueue.firstObject.integerValue;
                [self.batchQueue removeObjectAtIndex:0];
                [self.preview selectMarquee:next];
                self.batchFollowing = YES;
                dispatch_async(dispatch_get_main_queue(), ^{ [self startScan]; });
            } else self.batchQueue = nil;
        });
    });
}

/* Open tall enough to show every setting without scrolling, if the screen allows. */
- (void)fitHeightToContent
{
    CGFloat extra = self.doc.frame.size.height - self.scroll.contentSize.height;
    if (extra <= 0) return;
    NSRect f = self.window.frame;
    CGFloat maxH = NSScreen.mainScreen.visibleFrame.size.height - 20;
    CGFloat newH = MIN(f.size.height + extra + 2, maxH);
    f.origin.y -= newH - f.size.height;
    f.size.height = newH;
    [self.window setFrame:f display:YES];
}

/* Reflective and Film show different rows in the same places (ShowOriginalItem,
 * CAdvancedDialog::InitMenu/UpdateMenu: Film Type or Auto Exposure Type; Grain Reduction or
 * Descreening; DIGITAL ICE for film only on the V550) */
- (BOOL)isFilm { return [ESValue(self.builder.controls[@"documentType"]) hasPrefix:@"Film"]; }

- (BOOL)condition:(NSString *)c
{
    if ([c containsString:@"+"]) {                 /* every part must hold */
        for (NSString *part in [c componentsSeparatedByString:@"+"]) if (![self condition:part]) return NO;
        return YES;
    }
    /* Black & White shows its Threshold instead of the colour adjustments (ShowAdjustmentItem) */
    if ([c isEqualToString:@"bw"]) return [self imageTypeID] == 6;
    if ([c isEqualToString:@"color"]) return [self imageTypeID] != 6;
    if ([c isEqualToString:@"film"]) return [self isFilm];
    if ([c isEqualToString:@"reflective"]) return ![self isFilm];
    if ([c isEqualToString:@"imageOption"]) { int t = [self imageTypeID]; return t == 4 || t == 6; }
    return YES;
}

/* CAdvancedDialog::ValidateResolution: at least 50; above the optical 6400 only the menu's
 * values; never above twice it (12800 at 100% scale). Corrections beep. */
- (void)validateResolution:(NSTextField *)t
{
    static NSArray *menu;
    if (!menu) menu = @[ @"50", @"72", @"96", @"150", @"200", @"240", @"266", @"300", @"350", @"360", @"400",
                         @"600", @"720", @"800", @"1200", @"2400", @"3200", @"4800", @"6400", @"9600", @"12800" ];
    NSString *text = [t.stringValue stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
    if (!text.length) { t.stringValue = self.lastResolution ?: @"300"; return; }
    int v = text.intValue, optical = 6400, maxRes = optical * 2;
    BOOL fixed = NO;
    if (v < 50) { v = 50; fixed = YES; }
    else {
        if (v > optical && ![menu containsObject:[NSString stringWithFormat:@"%d", v]]) { v = optical; fixed = YES; }
        if (v > maxRes) { v = maxRes; fixed = YES; }
    }
    if (fixed) NSBeep();
    t.stringValue = [NSString stringWithFormat:@"%d", v];
    self.lastResolution = t.stringValue;
    self.preview.targetDPI = v;
    [self refreshSizes];
}

/* ------------------------------------------------------------------ Target Size / Scale */

- (int)resolution { return ESValue(self.builder.controls[@"resolution"]).intValue ?: 300; }

/* the scan area in inches: the preview's, or the V550's glass before there is one */
- (void)areaW:(double *)w h:(double *)h
{
    if (self.preview.hasArea) { [self.preview areaInches:w h:h]; return; }
    *w = 216 / 25.4; *h = 297 / 25.4;
}

- (int)trimmingSetting { return [self isOn:@"trimHigh"] ? 1 : 0; }

- (EsTarget)target
{
    if (self.preview.hasArea) { self.preview.defaultTrimming = [self trimmingSetting]; return [self.preview currentTarget]; }
    EsTarget t = self.areaTarget;
    if (t.sw <= 0) {
        double w, h;
        [self areaW:&w h:&h];
        t.trimming = [self trimmingSetting];
        est_init(&t, w, h, 0, 0);
        self.areaTarget = t;
    }
    return t;
}

- (void)storeTarget:(EsTarget)t moved:(BOOL)moved
{
    if (self.preview.hasArea) [self.preview setCurrentTarget:t moved:moved];
    else self.areaTarget = t;
    [self refreshSizes];
}

static NSString *ESNumber(double v, int decimals)
{
    return [NSString stringWithFormat:@"%.*f", decimals, decimals ? v : floor(v)];
}

static int ESUnitOf(NSString *title)
{
    return [title isEqualToString:@"pixels"] ? EST_PIXELS : [title isEqualToString:@"mm"] ? EST_MM : EST_INCHES;
}

- (void)previewSelectionChanged:(NSNotification *)n { [self refreshSizes]; }

/* CAdvancedDialog::UpdateTargetSizeMenu: Epson's sizes, the user's sizes, "Customize..." */
- (void)updateTargetMenu
{
    self.userTargets = ESUserTargetsLoad();
    NSMutableArray *items = [NSMutableArray array];
    for (int i = 0; i < es_target_preset_count; i++) [items addObject:@(es_target_presets[i].name)];
    for (NSDictionary *e in self.userTargets) [items addObject:e[@"name"]];
    [items addObject:@"Customize..."];
    ESSetMenu(self.builder.controls[@"target"], items);
}

/* a menu index's size: Epson's list, then the user's */
- (BOOL)targetSize:(int)index w:(double *)w h:(double *)h unit:(int *)unit name:(NSString **)name
{
    if (index >= 0 && index < es_target_preset_count) {
        const EsTargetPreset *p = &es_target_presets[index];
        *w = p->w; *h = p->h; *unit = p->unit; if (name) *name = @(p->name);
        return YES;
    }
    NSInteger u = index - es_target_preset_count;
    if (u < 0 || u >= (NSInteger)self.userTargets.count) return NO;
    NSDictionary *e = self.userTargets[(NSUInteger)u];
    *w = [e[@"w"] doubleValue]; *h = [e[@"h"] doubleValue]; *unit = [e[@"unit"] intValue];
    if (name) *name = e[@"name"];
    return YES;
}

/* CAdvancedDialog::UpdateSourceSize / UpdateTargetSize / SetTargetSizeControlsStatus */
- (void)refreshSizes
{
    NSDictionary *k = self.builder.controls;
    if (!k[@"target"]) return;
    int res = [self resolution];
    EsTarget t = [self target];
    int su = ESUnitOf(ESValue(k[@"srcUnits"])), tu = ESUnitOf(ESValue(k[@"tgtUnits"]));
    double f = su == EST_MM ? 25.4 : 1;
    ESSetField(k[@"srcW"], ESNumber(t.sw * f, est_decimals(su)));
    ESSetField(k[@"srcH"], ESNumber(t.sh * f, est_decimals(su)));
    double tw = est_convert(t.unit, tu, t.tw, res), th = est_convert(t.unit, tu, t.th, res);
    ESSetField(k[@"tgtW"], ESNumber(tw, est_decimals(tu)));
    ESSetField(k[@"tgtH"], ESNumber(th, est_decimals(tu)));
    ESSetField(k[@"scale"], [NSString stringWithFormat:@"%d", (int)t.scale]);
    {
        double w, h; int u; NSString *name = nil;
        if (!self.userTargets) [self updateTargetMenu];
        if (t.index <= 0 || ![self targetSize:t.index w:&w h:&h unit:&u name:&name]) name = @"Original";
        ESSelectItem(k[@"target"], name);
    }
    ESSetIcon(k[@"targetRotate"], t.landscape ? 10022 : 10021);
    ESSetIcon(k[@"targetLock"], t.active ? 10010 : 10009);
    BOOL single = [self.preview hasArea] ? [self.preview activeMarquees] < 2 : YES;
    ESSetEnabled(k[@"target"], single);
    ESSetEnabled(k[@"targetRotate"], single && t.index != 0);
    ESSetEnabled(k[@"tgtW"], !t.active && single);
    ESSetEnabled(k[@"tgtH"], !t.active && single);
    ESSetEnabled(k[@"targetLock"], single && [self.preview hasArea] && [self.preview activeMarquees] > 0);
    /* a fixed target keeps its kind of unit: pixels, or mm / in. */
    NSView *units = k[@"tgtUnits"];
    for (NSUInteger i = 0; i < 3; i++)
        ESSetItemEnabled(units, i, !t.active || (t.unit == EST_PIXELS ? i == 0 : i != 0));
    ESSetEnabled(k[@"scale"], single);
    ESSetEnabled(k[@"scaleStepper"], single);
    ESSetOn(k[@"trimStd"], !t.trimming);
    ESSetOn(k[@"trimHigh"], t.trimming);
}

- (void)scaleOutOfRange
{
    NSAlert *a = [NSAlert new];
    a.messageText = @"EPSON Scan";
    a.informativeText = ESS_UI_10008_19;
    [a beginSheetModalForWindow:[self host] completionHandler:nil];
}

- (void)targetAction:(NSString *)action
{
    NSDictionary *k = self.builder.controls;
    int res = [self resolution];
    double aw, ah;
    [self areaW:&aw h:&ah];
    EsTarget t = [self target];
    if ([action isEqualToString:@"target"]) {
        NSString *name = ESValue(k[@"target"]);
        int index = 0;
        for (int i = 0; i < es_target_preset_count; i++)
            if ([name isEqualToString:@(es_target_presets[i].name)]) index = i;
        for (NSUInteger i = 0; i < self.userTargets.count; i++)
            if ([name isEqualToString:self.userTargets[i][@"name"]]) index = es_target_preset_count + (int)i;
        if ([name hasPrefix:@"Customize"]) {
            /* ShowTargetSizeDialog: OK picks the size selected in its list; Cancel changes nothing */
            ESTargetSizeDialog *d = [ESTargetSizeDialog new];
            NSInteger cur = t.index >= es_target_preset_count ? t.index - es_target_preset_count : -1;
            NSInteger r = [d runSelecting:cur];
            [self updateTargetMenu];
            if (r < 0) { [self refreshSizes]; return; }
            index = es_target_preset_count + (int)r;
        }
        if (index == 0) {
            /* Original: ChangeMarqueeInfo(mode 3, 100%) */
            t.active = 0; t.scale = 100; est_original(&t);
            [self storeTarget:t moved:NO];
            return;
        }
        double pw, ph; int pu;
        if (![self targetSize:index w:&pw h:&ph unit:&pu name:NULL]) { [self refreshSizes]; return; }
        if (!est_select(&t, index, pw, ph, pu, res, aw, ah)) {
            [self scaleOutOfRange];
            t.active = 0; t.scale = 100; est_original(&t);
            [self storeTarget:t moved:NO];
            return;
        }
        [self storeTarget:t moved:t.trimming == 1 || [self.preview activeMarquees] > 0];
    } else if ([action isEqualToString:@"target-rotate"]) {
        double pw = 0, ph = 0; int pu;
        [self targetSize:t.index w:&pw h:&ph unit:&pu name:NULL];
        if (est_rotate(&t, pw, ph, res, aw, ah)) [self storeTarget:t moved:t.trimming == 1 || [self.preview activeMarquees] > 0];
    } else if ([action isEqualToString:@"target-lock"]) {
        est_lock(&t, !t.active);
        [self storeTarget:t moved:NO];
    } else if ([action isEqualToString:@"scale-step"]) {
        /* UpdateScaleValue: one percent at a time, inside the scale range */
        AQControl *st = (AQControl *)k[@"scaleStepper"];
        int dir = [st isKindOfClass:[AQControl class]] ? st.stepDirection : self.builder.lastStep;
        double mn, mx;
        est_scale_limits(res, &mn, &mx);
        int v = (int)t.scale + dir;
        if (v < (int)mn || v > (int)mx) { NSBeep(); return; }
        if (est_set_scale(&t, v, res, aw, ah)) [self storeTarget:t moved:t.active];
    } else if ([action hasPrefix:@"trim-"]) {
        int high = [action isEqualToString:@"trim-high"];
        if (t.trimming == high) { [self refreshSizes]; return; }
        t.trimming = high;
        self.preview.defaultTrimming = high;
        if (t.active) {
            /* DoADDestTrimmingRadioButtonClick: the fixed target again, trimmed the new way */
            double w = t.tw, h = t.th; int unit = t.unit;
            if (t.index > 0) [self targetSize:t.index w:&w h:&h unit:&unit name:NULL];
            if (!est_select(&t, t.index, w, h, unit, res, aw, ah)) { NSBeep(); t.trimming = high; }
            [self storeTarget:t moved:YES];
        } else [self storeTarget:t moved:NO];
    } else if ([action isEqualToString:@"size-units"]) {
        [self refreshSizes];
    }
}

/* ValidateSourceSizeEdit / ValidateTargeSizeEdit / ValidateScaleEdit */
- (void)sizeEntered:(NSTextField *)field
{
    NSDictionary *k = self.builder.controls;
    int res = [self resolution];
    double aw, ah;
    [self areaW:&aw h:&ah];
    EsTarget t = [self target];
    NSString *key = field.identifier;
    double v = field.doubleValue;
    if ([key isEqualToString:@"scale"]) {
        double mn, mx;
        est_scale_limits(res, &mn, &mx);
        int pct = (int)v;
        if (pct < (int)ceil(mn)) { pct = (int)ceil(mn); NSBeep(); }
        if (pct > (int)mx) { pct = (int)mx; NSBeep(); }
        if (est_set_scale(&t, pct, res, aw, ah)) [self storeTarget:t moved:t.active];
        else [self refreshSizes];
    } else if ([key hasPrefix:@"tgt"]) {
        if (t.active) { [self refreshSizes]; return; }
        int tu = ESUnitOf(ESValue(k[@"tgtUnits"]));
        double in = est_convert(tu, EST_INCHES, v, res);
        est_set_target_dim(&t, [key isEqualToString:@"tgtW"] ? 5 : 6, in, res);
        [self storeTarget:t moved:NO];
    } else {
        /* Document Size typed: the marquee takes that size where it is */
        if (![self.preview hasArea] || [self.preview activeMarquees] == 0) { [self refreshSizes]; return; }
        double in = ESUnitOf(ESValue(k[@"srcUnits"])) == EST_MM ? v / 25.4 : v;
        double w = t.sw, h = t.sh;
        if ([key isEqualToString:@"srcW"]) w = MIN(MAX(in, 0.1), aw - t.ox); else h = MIN(MAX(in, 0.1), ah - t.oy);
        est_marquee_changed(&t, w, h, t.ox, t.oy, res);
        [self storeTarget:t moved:YES];
    }
}

/* Image Type as Epson numbers it (MINF 15004) */
- (int)imageTypeID
{
    NSString *t = ESValue(self.builder.controls[@"imageType"]);
    NSArray *names = @[ @"48-bit Color", @"24-bit Color", @"Color Smoothing", @"16-bit Grayscale",
                        @"8-bit Grayscale", @"Halftone", @"Black & White" ];
    NSUInteger i = [names indexOfObject:t];
    return i == NSNotFound ? 0 : (int)i;
}

/* checkbox + its label and menu (ActivateControlLoop over the item and the row under it) */
- (void)activate:(NSString *)key on:(BOOL)en
{
    NSDictionary *k = self.builder.controls;
    ESSetEnabled(k[key], en);
    NSView *level = k[[key stringByAppendingString:@"Level"]];
    for (NSView *v in level.superview.subviews) ESSetEnabled(v, en);
}

- (BOOL)isOn:(NSString *)key { NSView *v = self.builder.controls[key]; return v && ESIsOn(v); }
- (void)turnOff:(NSString *)key { NSView *v = self.builder.controls[key]; if (v) ESSetOn(v, NO); }

/* CAdvancedDialog::Set*ItemStatus, in UpdateAdjColorMenu's order. Configuration's "No Color
 * Correction" (ConfigInf+0x18 == 2) also turns these off; there's no Configuration dialog yet,
 * so it is never set. Reflective DIGITAL ICE doesn't exist on the V550. */
/* the Threshold (0..255, Epson's default 110) as the slider / field hold it */
- (int)threshold
{
    NSView *v = self.builder.controls[@"threshold"];
    double t = 110;
    if ([v isKindOfClass:[AQSlider class]]) t = ((AQSlider *)v).value;
    else if ([v isKindOfClass:[NSSlider class]]) t = ((NSSlider *)v).doubleValue;
    return (int)MAX(0, MIN(255, lround(t)));
}

/* Dropout: Image Option "Dropout: Red/Green/Blue" (8-bit Grayscale and Black & White) */
- (int)dropoutChannel
{
    int t = [self imageTypeID];
    if (t != 4 && t != 6) return -1;
    NSString *o = ESValue(self.builder.controls[@"imageOption"]);
    if ([o hasPrefix:@"Dropout: Red"]) return 0;
    if ([o hasPrefix:@"Dropout: Green"]) return 1;
    if ([o hasPrefix:@"Dropout: Blue"]) return 2;
    return -1;
}

/* Image Option "Color Enhance: Red/Green/Blue", "Text Enhancement Technology" (Black & White) and
 * "Auto Area Segmentation" (Black & White). Color Enhance's hue classes come from EsDDE.prm
 * (DDEColor::CheckHS): Red 0x20, Green 0x10, Blue 0x08. */
- (int)ddeOption
{
    int t = [self imageTypeID];
    if (t != 4 && t != 6) return 0;
    NSString *o = ESValue(self.builder.controls[@"imageOption"]);
    if ([o hasPrefix:@"Color Enhance"]) return ES_DDE_CE;
    if (t == 6 && [o hasPrefix:@"Text Enhancement"]) return ES_DDE_TET;
    if (t == 6 && [o hasPrefix:@"Auto Area"]) return ES_DDE_AAS;
    return 0;
}

- (int)colorEnhanceMask
{
    NSString *o = ESValue(self.builder.controls[@"imageOption"]);
    if ([o hasSuffix:@"Red"]) return 0x20;
    if ([o hasSuffix:@"Green"]) return 0x10;
    if ([o hasSuffix:@"Blue"]) return 0x08;
    return 0;
}

/* the preview follows Black & White's threshold and the dropout colour */
- (void)applyImageOptions
{
    int bw = [self imageTypeID] == 6 ? [self threshold] : -1;
    int d = [self dropoutChannel];
    if (self.preview.bwThreshold != bw || self.preview.dropout != d) {
        self.preview.bwThreshold = bw;
        self.preview.dropout = d;
        [self.preview showCurrent];
    }
}

- (void)thresholdEntered:(NSTextField *)t
{
    int v = t.intValue;
    if (v < 0 || v > 255) NSBeep();
    v = MAX(0, MIN(255, v));
    ESSetField(t, [NSString stringWithFormat:@"%d", v]);
    ESSetSliderValue(self.builder.controls[@"threshold"], v);
    [self applyImageOptions];
}

- (void)updateItemStatus
{
    gImageIsBW = [self imageTypeID] == 6;
    self.previewArrow.current = ESThumbnailPreview([self isFilm]) ? @"Thumbnail" : @"Normal";
    /* ShowDestinationItem: the Image Type triangle (and Image Option) only for 8-bit Grayscale and
     * Black & White. ShowAdjustmentItem: for 8-bit Grayscale, Text Enhancement Technology and Auto
     * Area Segmentation (items 8, 9) are disabled and dropped if chosen; Black & White has all. */
    {
        int t = [self imageTypeID];
        self.builder.controls[@"imageTypeDisclosure"].hidden = !(t == 4 || t == 6);
        NSView *opt = self.builder.controls[@"imageOption"];
        for (NSUInteger i = 0; i < 9; i++) ESSetItemEnabled(opt, i, t == 6 || i < 7);
        NSString *cur = ESValue(opt);
        if (t == 4 && ([cur hasPrefix:@"Text Enhancement"] || [cur hasPrefix:@"Auto Area"])) ESSelectItem(opt, @"None");
    }
    BOOL film = [self isFilm];
    BOOL document = !film && [ESValue(self.builder.controls[@"aeType"]) isEqualToString:@"Document"];
    int type = [self imageTypeID];
    BOOL keep = !(type == 5 || type == 6);       /* Halftone / B&W keep their values (other panel) */
    BOOL en;
    /* SetUSMItemStatus */
    en = type != 2;
    if (keep && !en) [self turnOff:@"unsharp"];
    [self activate:@"unsharp" on:en];
    /* SetPhotoRestoItemStatus */
    en = !document && type != 2;
    if (keep && !en) [self turnOff:@"Color Restoration"];
    ESSetEnabled(self.builder.controls[@"Color Restoration"], en);
    /* SetDustRemoverItemStatus: off with Document, Color Smoothing, or DIGITAL ICE on (film) */
    en = !document && type != 2;
    if (keep && !en) [self turnOff:@"dust"];
    if (film && [self isOn:@"ice"]) { en = NO; [self turnOff:@"dust"]; }
    [self activate:@"dust" on:en];
    /* SetDescreenItemStatus: Grain Reduction off with Color Smoothing */
    NSString *slot = film ? @"grain" : @"descreen";
    en = !(film && type == 2);
    if (keep && !en) [self turnOff:slot];
    [self activate:slot on:en];
    /* SetDigitalICEItemStatus: off with Color Smoothing or Dust Removal on */
    if (film) {
        en = type != 2;
        if (keep && !en) [self turnOff:@"ice"];
        if ([self isOn:@"dust"]) { en = NO; [self turnOff:@"ice"]; }
        [self activate:@"ice" on:en];
    }
    /* SetBackLightCorrItemStatus */
    en = !document && type != 2;
    if (keep && !en) [self turnOff:@"backlight"];
    [self activate:@"backlight" on:en];
    NSTextField *tv = (NSTextField *)self.builder.controls[@"thresholdValue"];
    if ([tv isKindOfClass:[NSTextField class]] && tv.action != @selector(thresholdEntered:)) {
        tv.target = self; tv.action = @selector(thresholdEntered:);
        tv.cell.sendsActionOnEndEditing = YES;
    }
    [self applyImageOptions];
}

- (void)relayout
{
    NSDictionary *S = [self layout][@"scroll"];
    CGFloat gap = [S[@"sectionGap"] doubleValue];
    CGFloat y = gap;
    NSInteger lastSection = 0;
    for (NSDictionary *r in self.rows) {
        if ([r[@"section"] integerValue] != lastSection) { y += gap; lastSection = [r[@"section"] integerValue]; }
        NSView *v = r[@"view"];
        NSString *g = r[@"group"];
        BOOL show = (!g || [self.open[g] boolValue]) && [self condition:r[@"show"]];
        v.hidden = !show;
        if (!show) continue;
        NSRect f = v.frame;
        f.origin.y = y;
        v.frame = f;
        y += [r[@"height"] doubleValue];
    }
    y += gap;
    NSRect df = self.doc.frame;
    df.size.height = y;
    self.doc.frame = df;
}

- (void)rebuild
{
    NSDictionary *L = [self layout];
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    self.builder = [ESBuilder new];
    self.builder.native = native;
    __weak ESProfessionalWindow *weakSelf = self;
    self.builder.onToggle = ^(NSString *group, BOOL isOpen) {
        weakSelf.open[group] = @(isOpen);
        [weakSelf relayout];
    };
    self.builder.onAction = ^(NSString *action) { [weakSelf perform:action]; };
    self.builder.onValue = ^(NSString *key, double v) {      /* DoADBWAdjustThresholdSlider */
        if (![key isEqualToString:@"threshold"]) return;
        ESSetField(weakSelf.builder.controls[@"thresholdValue"], [NSString stringWithFormat:@"%d", (int)lround(v)]);
        [weakSelf applyImageOptions];
    };

    NSRect cr = [self.window contentRectForFrameRect:self.window.frame];
    NSDictionary *w = L[@"window"];
    CGFloat baseH = [w[@"height"] doubleValue];
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, cr.size.width, baseH)];
    root.wantsLayer = YES;
    root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor
                                        : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];

    [self.builder build:L[@"items"] into:root];
    /* the Preview button's Normal / Thumbnail menu sits inside the button, lower right */
    NSView *pb = self.builder.controls[@"previewButton"];
    if (pb) {
        NSSize bs = pb.bounds.size;
        CGFloat ay = pb.isFlipped ? bs.height - 16 : 4;
        ESMenuArrow *arrow = [[ESMenuArrow alloc] initWithFrame:NSMakeRect(bs.width - 22, ay, 16, 12)];
        arrow.autoresizingMask = NSViewMinXMargin | (pb.isFlipped ? NSViewMinYMargin : NSViewMaxYMargin);
        arrow.items = @[ @"Normal", @"Thumbnail" ];
        __weak typeof(self) weakMain = self;
        arrow.onPick = ^(NSString *t) {
            weakMain.previewArrow.current = t;
            ESSetThumbnailPreview([weakMain isFilm], [t isEqualToString:@"Thumbnail"]);
            if (!weakMain.busy) [weakMain perform:@"preview"];
        };
        [pb addSubview:arrow];
        self.previewArrow = arrow;
    }

    NSDictionary *S = L[@"scroll"];
    self.scroll = [[NSScrollView alloc] initWithFrame:ESRect(S[@"rect"])];
    self.scroll.hasVerticalScroller = YES;
    self.scroll.borderType = NSBezelBorder;
    self.scroll.drawsBackground = NO;
    self.scroll.autoresizingMask = NSViewHeightSizable;      /* the settings panel grows with the window */
    if (!native) self.scroll.scrollerStyle = NSScrollerStyleLegacy;
    CGFloat cw = [S[@"contentWidth"] doubleValue];
    self.doc = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, cw, 10)];
    self.rows = [NSMutableArray array];
    NSInteger si = 0;
    for (NSDictionary *sec in S[@"sections"]) {
        for (NSDictionary *row in sec[@"rows"]) {
            CGFloat h = [row[@"height"] doubleValue];
            ESFlippedView *rv = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, cw, h)];
            [self.builder build:row[@"items"] into:rv];
            for (NSView *sub in rv.subviews) sub.autoresizingMask = NSViewNotSizable;
            [self.doc addSubview:rv];
            id group = row[@"group"];
            [self.rows addObject:@{ @"view": rv, @"height": @(h), @"section": @(si),
                                    @"group": [group isKindOfClass:[NSString class]] ? group : [NSNull null],
                                    @"show": [row[@"show"] isKindOfClass:[NSString class]] ? row[@"show"] : @"" }];
        }
        si++;
    }
    /* NSNull -> nil for the group lookups in relayout */
    for (NSUInteger k = 0; k < self.rows.count; k++)
        if (self.rows[k][@"group"] == [NSNull null]) {
            NSMutableDictionary *m = [self.rows[k] mutableCopy];
            [m removeObjectForKey:@"group"];
            self.rows[k] = m;
        }
    [self relayout];
    [self updateItemStatus];
    NSTextField *resField = (NSTextField *)self.builder.controls[@"resolution"];
    if ([resField isKindOfClass:[NSTextField class]]) {
        resField.target = self;
        resField.action = @selector(validateResolution:);
        resField.cell.sendsActionOnEndEditing = YES;
    }
    for (NSString *key in @[ @"srcW", @"srcH", @"tgtW", @"tgtH", @"scale" ]) {
        NSTextField *t = (NSTextField *)self.builder.controls[key];
        if (![t isKindOfClass:[NSTextField class]]) continue;
        t.identifier = key;
        t.target = self;
        t.action = @selector(sizeEntered:);
        t.cell.sendsActionOnEndEditing = YES;
    }
    static BOOL observing;
    if (!observing) {
        observing = YES;
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(previewSelectionChanged:)
                                                   name:ESSelectionChanged object:nil];
    }
    [self updateTargetMenu];
    [self updateSettingsMenu];
    [self refreshSizes];
    self.scroll.documentView = self.doc;
    [root addSubview:self.scroll];

    /* size the root to the current window, letting the autoresizing masks place everything */
    self.window.contentView = root;
    root.autoresizesSubviews = YES;
    [root setFrameSize:cr.size];
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark - Home, Office and Full Auto Modes

/* Epson Scan's other three modes (CSimpleDialog, CDocumentDialog, CFullAutoDialog). Each has its
 * own window, made from the original DITLs, and drives the Professional Mode machinery hidden
 * behind it: the same preview, Epson's auto exposure, File Save Settings and scan path. */

static NSDictionary *ESModeDefaults(void)
{
    static NSDictionary *d;
    if (!d) {
        NSString *path = [[NSBundle mainBundle] pathForResource:@"modedefaults" ofType:@"json"];
        NSData *data = path ? [NSData dataWithContentsOfFile:path] : nil;
        d = data ? [NSJSONSerialization JSONObjectWithData:data options:0 error:nil] : @{};
    }
    return d;
}

static NSDictionary *ESLoadLayoutNamed(NSString *name)
{
    NSString *path = [[NSBundle mainBundle] pathForResource:name ofType:@"json"];
    NSData *d = path ? [NSData dataWithContentsOfFile:path] : nil;
    return d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : @{};
}

static NSArray<NSString *> *ESMenuOf(NSView *v)
{
    if ([v isKindOfClass:[AQControl class]]) return ((AQControl *)v).menuItems ?: @[];
    if ([v isKindOfClass:[NSPopUpButton class]]) return ((NSPopUpButton *)v).itemTitles;
    return @[];
}

static void ESRadioSelect(NSDictionary<NSString *, NSView *> *k, NSArray<NSString *> *keys, NSString *on)
{
    for (NSString *x in keys) if (k[x]) ESSetOn(k[x], [x isEqualToString:on]);
}

static NSString *ESRadioValue(NSDictionary<NSString *, NSView *> *k, NSArray<NSString *> *keys)
{
    for (NSString *x in keys) if (k[x] && ESIsOn(k[x])) return x;
    return keys.firstObject;
}

static void ESSetWrap(NSView *v, NSString *s)
{
    if ([v isKindOfClass:[NSTextField class]]) ((NSTextField *)v).stringValue = s ?: @"";
}

/* Full Auto's documents on the glass (CFullAutoAnalyz -> CDTR::DoDetectImage, reflective): DTR
 * looks at a 50 dpi preview in Full Auto Mode (CDTR::GetResolution) */
static NSArray<NSValue *> *ESDetectDocumentsDTR(const uint16_t *raw, int w, int h, int dpi, NSArray<NSNumber *> **types)
{
    NSString *engine = ESDTREngine();
    if (!engine || !raw || !dpi) return nil;
    int W = 0, H = 0;
    NSMutableData *px = ESDTRPreview(raw, w, h, dpi, 50, &W, &H);
    if (!px) return nil;
    DtrImage im = ESDTRImage(px.bytes, W, H, 50, NO, NO, -1);
    DtrFrame fr[64];
    int n = 0;
    char err[256] = "";
    int rc = dtr_detect(engine.fileSystemRepresentation, engine.stringByDeletingLastPathComponent.fileSystemRepresentation,
                        &im, fr, 64, &n, err, sizeof err);
    if (rc) { ESLog(@"DTR document detection: %s", err); return nil; }
    double k = (double)dpi / 50.0;
    NSMutableArray *out = [NSMutableArray array], *kinds = [NSMutableArray array];
    for (int i = 0; i < n; i++) {
        NSRect r = NSMakeRect(fr[i].pt[1] * k, fr[i].pt[0] * k, fr[i].pt[2] * k, fr[i].pt[3] * k);
        r = NSIntersectionRect(NSIntegralRect(r), NSMakeRect(0, 0, w, h));
        /* a document is at least half an inch a side; the DTR image type (CDTR::GetDocType):
         * 1 photograph, 0 document, 2 text / line art */
        if (r.size.width >= dpi / 2.0 && r.size.height >= dpi / 2.0) {
            [out addObject:[NSValue valueWithRect:r]];
            [kinds addObject:@(fr[i].info & 0xFFFF)];
        }
    }
    if (types) *types = kinds;
    ESLog(@"DTR document detection: %lu document(s)", (unsigned long)out.count);
    return out.count ? out : nil;
}

/* Full Auto with no document type set (CDTR::CheckDocSource): DTR2 looks at the glass preview at
 * 50 dpi and says whether a film holder lies on the glass (DTR_DetectFilmHolder, TWEP unit 3 = the
 * V550's transparency unit). 1 holder, 0 none, negative when DTR couldn't tell */
static int ESDetectFilmHolderDTR(const uint16_t *raw, int w, int h, int dpi)
{
    NSString *engine = ESDTREngine();
    if (!engine || !raw || !dpi) return -1;
    int W = 0, H = 0;
    NSMutableData *px = ESDTRPreview(raw, w, h, dpi, 50, &W, &H);
    if (!px) return -1;
    DtrImage im = ESDTRImage(px.bytes, W, H, 50, NO, NO, -1);
    char err[256] = "";
    int rc = dtr_detect_holder(engine.fileSystemRepresentation, engine.stringByDeletingLastPathComponent.fileSystemRepresentation,
                               &im, err, sizeof err);
    ESLog(@"DTR film holder detection: %@", rc == 1 ? @"film holder on the glass" : rc == 0 ? @"no film holder"
                                               : [NSString stringWithFormat:@"failed: %s", err]);
    return rc;
}

static void ESShowViews(NSArray<NSView *> *views, BOOL show) { for (NSView *v in views) v.hidden = !show; }

static void ESSetSlider(NSDictionary<NSString *, NSView *> *k, NSString *key, int v)
{
    ESSetSliderValue(k[key], v);
    ESSetField(k[[key stringByAppendingString:@"Text"]], [NSString stringWithFormat:@"%d", v]);
}

@interface ESModeWindow : NSObject <NSWindowDelegate>
@property (nonatomic, strong) NSWindow *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic, weak) ESProfessionalWindow *pro;
@property (nonatomic, copy) NSString *layoutName, *modeName, *stateKey;
@property (nonatomic, strong) NSMutableDictionary *state;
- (instancetype)initWithLayout:(NSString *)layout mode:(NSString *)mode pro:(ESProfessionalWindow *)pro;
- (void)rebuild;
- (void)perform:(NSString *)action;
- (void)takeOver;           /* this mode becomes the one in use: its settings go to the scanner side */
- (void)saveState;
- (NSDictionary<NSString *, NSView *> *)k;
@end

@implementation ESModeWindow

- (instancetype)initWithLayout:(NSString *)layout mode:(NSString *)mode pro:(ESProfessionalWindow *)pro
{
    if ((self = [super init])) {
        self.layoutName = layout; self.modeName = mode; self.pro = pro;
        NSDictionary *w = ESLoadLayoutNamed(layout)[@"window"];
        self.window = [[NSWindow alloc] initWithContentRect:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])
                                                  styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                            NSWindowStyleMaskMiniaturizable
                                                    backing:NSBackingStoreBuffered defer:NO];
        self.window.title = w[@"title"] ?: @"EPSON Scan";
        self.window.delegate = self;
        self.window.releasedWhenClosed = NO;
        [self loadState];
        [self rebuild];
        [self.window center];
    }
    return self;
}

- (NSDictionary<NSString *, NSView *> *)k { return self.builder.controls; }

- (NSDictionary *)defaultState { return @{}; }

- (void)loadState
{
    NSDictionary *saved = self.stateKey ? [NSUserDefaults.standardUserDefaults dictionaryForKey:self.stateKey] : nil;
    self.state = [[self defaultState] mutableCopy];
    for (NSString *key in saved) self.state[key] = saved[key];
}

/* CMainDialog::Close: with Save settings on, the mode's settings come back next time */
- (void)saveState
{
    [self readControls];
    NSUserDefaults *ud = NSUserDefaults.standardUserDefaults;
    BOOL save = [ud objectForKey:@"CfgSaveSettings"] ? [ud boolForKey:@"CfgSaveSettings"] : YES;
    if (!self.stateKey) return;
    if (save) [ud setObject:self.state forKey:self.stateKey];
    else [ud removeObjectForKey:self.stateKey];
}

- (void)rebuild
{
    NSDictionary *L = ESLoadLayoutNamed(self.layoutName);
    NSDictionary *w = L[@"window"];
    BOOL native = [NSUserDefaults.standardUserDefaults boolForKey:kThemeDefault];
    if (self.builder) [self readControls];
    self.builder = [ESBuilder new];
    self.builder.native = native;
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])];
    root.wantsLayer = YES;
    root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    [self.builder build:L[@"items"] into:root];
    __weak ESModeWindow *weakSelf = self;
    self.builder.onAction = ^(NSString *a) { [weakSelf perform:a]; };
    self.builder.onValue = ^(NSString *key, double v) { [weakSelf slider:key value:(int)lround(v)]; };
    self.window.contentView = root;
    [self wireControls];
    [self writeControls];
    [self updateItems];
}

- (void)wireControls {}
- (void)readControls {}
- (void)writeControls {}
- (void)updateItems {}
- (void)syncToPro {}
- (void)slider:(NSString *)key value:(int)v {}

/* edit boxes next to sliders: typing a value moves the slider */
- (void)wireEdit:(NSString *)key
{
    NSTextField *t = (NSTextField *)self.k[[key stringByAppendingString:@"Text"]];
    if (![t isKindOfClass:[NSTextField class]]) return;
    t.identifier = key;
    t.alignment = NSTextAlignmentRight;
    t.target = self;
    t.action = @selector(editEntered:);
    t.cell.sendsActionOnEndEditing = YES;
}

- (void)editEntered:(NSTextField *)t { [self slider:t.identifier value:t.intValue]; }

- (void)takeOver
{
    self.pro.hostWindow = self.window;
    ESSelectItem(self.k[@"mode"], self.modeName);
    [self syncToPro];
}

/* the Professional Mode controls this mode sets */
- (void)pro:(NSString *)key select:(NSString *)title { NSView *v = self.pro.builder.controls[key]; if (v) ESSelectItem(v, title); }
- (void)pro:(NSString *)key on:(BOOL)on { NSView *v = self.pro.builder.controls[key]; if (v) ESSetOn(v, on); }
- (void)pro:(NSString *)key text:(NSString *)t { NSView *v = self.pro.builder.controls[key]; if (v) ESSetField(v, t); }

- (void)setResolution:(int)dpi
{
    NSString *t = [NSString stringWithFormat:@"%d", dpi];
    [self pro:@"resolution" text:t];
    self.pro.lastResolution = t;
    if (self.pro.preview) self.pro.preview.targetDPI = dpi;
}

/* Target Size: Professional Mode's own handling (CMarqCtl target), only when it changes */
- (void)setTarget:(NSString *)name
{
    NSView *v = self.pro.builder.controls[@"target"];
    if (!v || !name.length || [ESValue(v) isEqualToString:name]) return;
    ESSelectItem(v, name);
    [self.pro perform:@"target"];
}

- (void)setThreshold:(int)t
{
    ESSetSliderValue(self.pro.builder.controls[@"threshold"], t);
    [self pro:@"thresholdValue" text:[NSString stringWithFormat:@"%d", t]];
}

/* Brightness and Contrast (marquee +0x310 / +0x314, -100..100) for every marquee of the preview */
- (void)applyBrightness:(int)b contrast:(int)c
{
    ESPreviewWindow *pv = self.pro.preview;
    if (!pv || pv.scanning) return;
    NSMutableArray *all = [pv.adjusts mutableCopy] ?: [NSMutableArray array];
    if (pv.areaAdjust) [all addObject:pv.areaAdjust];
    for (ESAdjust *a in all) {
        [a setField:FIT_BRIGHTNESS value:b];
        [a setField:FIT_CONTRAST value:c];
        [a update];
    }
    [pv showCurrent];
}

- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"mode"]) {
        [NSNotificationCenter.defaultCenter postNotificationName:ESModeChangeRequest object:ESValue(self.k[@"mode"])];
    } else if ([action isEqualToString:@"preview"] || [action isEqualToString:@"scan"]) {
        [self readControls];
        [self syncToPro];
        [self.pro perform:action];
    } else if ([action isEqualToString:@"filesave"] || [action isEqualToString:@"configuration"]) {
        [self.pro perform:action];
        [self updateItems];
    } else if ([action isEqualToString:@"close"]) {
        [self.window performClose:nil];
    }
}

/* closing a mode's window closes EPSON Scan, like the Close button */
- (void)windowWillClose:(NSNotification *)n
{
    [self saveState];
    dispatch_async(dispatch_get_main_queue(), ^{ [NSApp terminate:nil]; });
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark Home Mode

/* CImageAdjustmentDialog (DITL 10110): Brightness and Contrast, or Threshold for Black & White */
@interface ESHomeAdjustDialog : NSObject
@property (nonatomic, strong) NSPanel *window;
@property (nonatomic, strong) ESBuilder *builder;
@property (nonatomic) int brightness, contrast, threshold;
@property (nonatomic) BOOL bw;
@property (nonatomic, copy) void (^onChange)(ESHomeAdjustDialog *me);
- (void)show;
- (void)rebuild;
@end

@implementation ESHomeAdjustDialog
- (instancetype)init
{
    if ((self = [super init])) {
        NSDictionary *w = ESLoadLayoutNamed(@"homeadjust")[@"window"];
        self.window = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])
                                                 styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable |
                                                           NSWindowStyleMaskUtilityWindow
                                                   backing:NSBackingStoreBuffered defer:NO];
        self.window.title = w[@"title"];
        self.window.releasedWhenClosed = NO;
        self.window.floatingPanel = YES;
        self.window.hidesOnDeactivate = NO;
        self.threshold = 110;
        [self rebuild];
    }
    return self;
}
- (void)rebuild
{
    NSDictionary *L = ESLoadLayoutNamed(@"homeadjust");
    NSDictionary *w = L[@"window"];
    BOOL native = [NSUserDefaults.standardUserDefaults boolForKey:kThemeDefault];
    self.builder = [ESBuilder new];
    self.builder.native = native;
    ESFlippedView *root = [[ESFlippedView alloc] initWithFrame:NSMakeRect(0, 0, [w[@"width"] doubleValue], [w[@"height"] doubleValue])];
    root.wantsLayer = YES;
    root.layer.backgroundColor = native ? NSColor.windowBackgroundColor.CGColor : [NSColor colorWithWhite:0.91 alpha:1].CGColor;
    self.window.appearance = native ? nil : [NSAppearance appearanceNamed:NSAppearanceNameAqua];
    [self.builder build:L[@"items"] into:root];
    __weak ESHomeAdjustDialog *weakSelf = self;
    self.builder.onValue = ^(NSString *key, double v) { [weakSelf set:key value:(int)lround(v)]; };
    self.builder.onAction = ^(NSString *a) {
        if ([a isEqualToString:@"ha:close"]) [weakSelf.window orderOut:nil];
        else if ([a isEqualToString:@"ha:reset"]) {         /* CImageAdjustmentDialog::ResetImageAdjustment */
            [weakSelf set:@"brightness" value:0];
            [weakSelf set:@"contrast" value:0];
            [weakSelf set:@"threshold" value:110];
        }
    };
    for (NSString *key in @[ @"brightness", @"contrast", @"threshold" ]) {
        NSTextField *t = (NSTextField *)self.builder.controls[[key stringByAppendingString:@"Text"]];
        if (![t isKindOfClass:[NSTextField class]]) continue;
        t.identifier = key; t.alignment = NSTextAlignmentRight; t.target = self; t.action = @selector(entered:);
        t.cell.sendsActionOnEndEditing = YES;
    }
    self.window.contentView = root;
    [self load];
}
- (void)entered:(NSTextField *)t { [self set:t.identifier value:t.intValue]; }
- (void)load
{
    NSDictionary<NSString *, NSView *> *k = self.builder.controls;
    ESSetSlider(k, @"brightness", self.brightness);
    ESSetSlider(k, @"contrast", self.contrast);
    ESSetSlider(k, @"threshold", self.threshold);
    /* UpdateBrightnessControls / UpdateThresholdControls: Black & White shows the Threshold in
     * Brightness's place */
    for (NSString *x in @[ @"bLabel", @"brightness", @"brightnessText", @"cLabel", @"contrast", @"contrastText" ])
        k[x].hidden = self.bw;
    for (NSString *x in @[ @"tLabel", @"threshold", @"thresholdText" ]) k[x].hidden = !self.bw;
}
- (void)set:(NSString *)key value:(int)v
{
    BOOL th = [key isEqualToString:@"threshold"];
    v = th ? MAX(0, MIN(255, v)) : MAX(-100, MIN(100, v));
    if ([key isEqualToString:@"brightness"]) self.brightness = v;
    else if ([key isEqualToString:@"contrast"]) self.contrast = v;
    else if (th) self.threshold = v;
    else return;
    ESSetSlider(self.builder.controls, key, v);
    if (self.onChange) self.onChange(self);
}
- (void)show
{
    [self load];
    if (!self.window.isVisible) [self.window center];
    [self.window orderFront:nil];
}
@end

@interface ESHomeWindow : ESModeWindow
@property (nonatomic, strong) ESHomeAdjustDialog *adjust;
@end

@implementation ESHomeWindow

static NSArray *kHomeImageKeys, *kHomeDestKeys;

- (instancetype)initWithPro:(ESProfessionalWindow *)pro
{
    kHomeImageKeys = @[ @"itColor", @"itGray", @"itBW" ];
    kHomeDestKeys = @[ @"dScreen", @"dPrinter", @"dOther" ];
    self.stateKey = @"HomeModeSettings";
    return [super initWithLayout:@"home" mode:@"Home Mode" pro:pro];
}

/* CSPPrefs (SPPR 10000): a record of settings for each document type; Unsharp Mask stays off and
 * DIGITAL ICE starts on (this app's defaults) */
- (NSDictionary *)defaultState
{
    NSDictionary *h = ESModeDefaults()[@"home"];
    NSMutableArray *types = [NSMutableArray array];
    for (NSDictionary *t in h[@"types"]) {
        NSMutableDictionary *m = [t mutableCopy];
        m[@"usm"] = @0;
        m[@"otherResolution"] = m[@"resolution"] ?: @300;
        m[@"target"] = @"Original";
        if ([types count] >= 1 && [types count] <= 3) m[@"ice"] = @1;
        [types addObject:m];
    }
    return @{ @"current": h[@"current"] ?: @0, @"types": types, @"brightness": @0, @"contrast": @0, @"threshold": @110 };
}

- (void)loadState
{
    [super loadState];
    /* deep-mutable: the per-type records are edited in place */
    NSMutableArray *types = [NSMutableArray array];
    for (NSDictionary *t in self.state[@"types"]) [types addObject:[t mutableCopy]];
    if (types.count < 8) types = [[self defaultState][@"types"] mutableCopy];
    self.state[@"types"] = types;
}

- (int)docType { return MAX(0, MIN(7, [self.state[@"current"] intValue])); }
- (NSMutableDictionary *)rec { return self.state[@"types"][(NSUInteger)[self docType]]; }
- (BOOL)film { int d = [self docType]; return d >= 1 && d <= 3; }
- (BOOL)thumbnail { return [self docType] < 4 && [[self rec][@"previewMode"] intValue] == 0; }

/* CScanBase image type IDs: Color is 24-bit Color (Color Smoothing for Illustration), Grayscale
 * 8-bit, Black&White 6 */
- (int)imageTypeID
{
    NSString *r = ESRadioValue(self.k, kHomeImageKeys);
    if ([r isEqualToString:@"itGray"]) return 4;
    if ([r isEqualToString:@"itBW"]) return 6;
    return [self docType] == 4 ? 2 : 1;
}

- (void)wireControls
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    ESSetMenu(k[@"target"], ESMenuOf(self.pro.builder.controls[@"target"]));
    NSTextField *res = (NSTextField *)k[@"resolution"];
    if ([res isKindOfClass:[NSTextField class]]) {
        res.target = self; res.action = @selector(resolutionEntered:);
        res.cell.sendsActionOnEndEditing = YES;
    }
    /* the Preview button's Normal / Thumbnail menu (CSimpleDialog::DoPreviewKindMenuClick): Photograph and
     * the films; SPPR's preview mode is 0 Thumbnail, 1 Normal */
    NSView *pb = k[@"previewButton"];
    if (pb) {
        NSSize bs = pb.bounds.size;
        CGFloat ay = pb.isFlipped ? bs.height - 16 : 4;
        ESMenuArrow *arrow = [[ESMenuArrow alloc] initWithFrame:NSMakeRect(bs.width - 22, ay, 16, 12)];
        arrow.items = @[ @"Normal", @"Thumbnail" ];
        arrow.identifier = @"previewArrow";
        __weak ESHomeWindow *weakSelf = self;
        arrow.onPick = ^(NSString *t) {
            [weakSelf rec][@"previewMode"] = @([t isEqualToString:@"Thumbnail"] ? 0 : 1);
            [weakSelf updateItems];
            if (!weakSelf.pro.busy) [weakSelf perform:@"preview"];
        };
        [pb addSubview:arrow];
    }
}

- (ESMenuArrow *)previewArrow
{
    for (NSView *v in self.k[@"previewButton"].subviews) if ([v isKindOfClass:[ESMenuArrow class]]) return (ESMenuArrow *)v;
    return nil;
}

/* the document type's record -> the window (CSimpleDialog::SetAllControlValuesAndTexts) */
- (void)writeControls
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    NSMutableDictionary *r = [self rec];
    ESIconPopup *dt = (ESIconPopup *)k[@"docType"];
    if ([dt isKindOfClass:[ESIconPopup class]]) { dt.selected = [self docType]; [dt setNeedsDisplay:YES]; }
    int it = [r[@"imageType"] intValue];
    ESRadioSelect(k, kHomeImageKeys, it == 6 || it == 5 ? @"itBW" : it == 3 || it == 4 ? @"itGray" : @"itColor");
    int dest = MAX(0, MIN(2, [r[@"destination"] intValue]));
    ESRadioSelect(k, kHomeDestKeys, kHomeDestKeys[(NSUInteger)dest]);
    [self showResolution];
    ESSelectItem(k[@"target"], r[@"target"] ?: @"Original");
    ESSetOn(k[@"descreen"], [r[@"descreen"] boolValue]);
    ESSetOn(k[@"restoration"], [r[@"restoration"] boolValue]);
    ESSetOn(k[@"backlight"], [r[@"backlight"] boolValue]);
    ESSetOn(k[@"dustIce"], [self film] ? [r[@"ice"] boolValue] : [r[@"dust"] boolValue]);
    ESSetOn(k[@"imageOption"], [r[@"imageOption"] boolValue]);
    ESRadioSelect(k, @[ @"ioTET", @"ioAAS" ], [r[@"imageOptionRadio"] intValue] == 1 ? @"ioAAS" : @"ioTET");
}

/* Screen/Web 96 dpi, Printer 300 dpi, Other: the user's (CSimpleDialog::DoDestRadioButtonClick) */
- (void)showResolution
{
    NSString *d = ESRadioValue(self.k, kHomeDestKeys);
    int dpi = [d isEqualToString:@"dScreen"] ? 96 : [d isEqualToString:@"dPrinter"] ? 300
            : MAX(50, [[self rec][@"otherResolution"] intValue] ?: 300);
    ESSetField(self.k[@"resolution"], [NSString stringWithFormat:@"%d", dpi]);
}

- (void)readControls
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    if (!k.count) return;
    NSMutableDictionary *r = [self rec];
    r[@"imageType"] = @([self imageTypeID]);
    r[@"destination"] = @([kHomeDestKeys indexOfObject:ESRadioValue(k, kHomeDestKeys)]);
    if ([ESRadioValue(k, kHomeDestKeys) isEqualToString:@"dOther"]) r[@"otherResolution"] = @(MAX(50, ESValue(k[@"resolution"]).intValue));
    r[@"resolution"] = @(MAX(50, ESValue(k[@"resolution"]).intValue));
    r[@"target"] = ESValue(k[@"target"]);
    r[@"descreen"] = @(ESIsOn(k[@"descreen"]));
    r[@"restoration"] = @(ESIsOn(k[@"restoration"]));
    r[@"backlight"] = @(ESIsOn(k[@"backlight"]));
    if ([self film]) r[@"ice"] = @(ESIsOn(k[@"dustIce"])); else r[@"dust"] = @(ESIsOn(k[@"dustIce"]));
    r[@"imageOption"] = @(ESIsOn(k[@"imageOption"]));
    r[@"imageOptionRadio"] = @([ESRadioValue(k, @[ @"ioTET", @"ioAAS" ]) isEqualToString:@"ioAAS"] ? 1 : 0);
}

- (void)enable:(NSString *)key on:(BOOL)en
{
    NSView *v = self.k[key];
    if (!v) return;
    if (!en) ESSetOn(v, NO);       /* Epson clears a check box it deactivates */
    ESSetEnabled(v, en);
}

/* CSimpleDialog::Update*CheckBox and UpdateImageOptionItems */
- (void)updateItems
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    int doc = [self docType], t = [self imageTypeID];
    BOOL bw = t == 6;
    [self enable:@"descreen" on:!bw && ((1 << doc) & 0xf1)];
    BOOL restore = !bw && ((1 << t) & 0x1b) && doc < 4;
    [self enable:@"restoration" on:restore];
    [self enable:@"backlight" on:restore];
    /* DIGITAL ICE for film on the V550; Dust Removal for photographs (UpdateDigitalICECheckBox /
     * UpdateDustRemoverCheckBox, STR# 10002 #59 / #58) */
    NSView *di = k[@"dustIce"];
    NSString *title = [self film] ? @"DIGITAL ICE Technology" : @"Dust Removal";
    if ([di isKindOfClass:[AQControl class]]) { ((AQControl *)di).text = title; [di setNeedsDisplay:YES]; }
    else if ([di isKindOfClass:[NSButton class]]) { ((NSButton *)di).title = title; [(NSButton *)di sizeToFit]; }
    [self enable:@"dustIce" on:!bw && doc < 4];
    /* Image Option for Magazine, Newspaper and Text/Line Art; Text Enhancement and Auto Area
     * Segmentation work on Black & White */
    BOOL io = doc >= 5 && bw;
    [self enable:@"imageOption" on:io];
    BOOL radios = io && ESIsOn(k[@"imageOption"]);
    ESSetEnabled(k[@"ioTET"], radios);
    ESSetEnabled(k[@"ioAAS"], radios);
    BOOL other = [ESRadioValue(k, kHomeDestKeys) isEqualToString:@"dOther"];
    ESSetEnabled(k[@"resolution"], other);
    ESSetEnabled(k[@"resArrows"], other);
    ESMenuArrow *arrow = [self previewArrow];
    arrow.hidden = doc >= 4;
    arrow.current = [self thumbnail] ? @"Thumbnail" : @"Normal";
    self.adjust.bw = bw;
}

/* the Home settings -> Professional Mode's controls, which the scan reads */
- (void)syncToPro
{
    self.pro.fixedAreaMM = NSZeroRect;
    self.pro.forcedThumbnail = @([self thumbnail]);
    NSMutableDictionary *r = [self rec];
    int doc = [self docType], t = [self imageTypeID];
    BOOL film = [self film];
    if (film) {
        [self pro:@"documentType" select:@"Film (with Film Area Guide)"];
        [self pro:@"filmType" select:doc == 1 ? @"Positive Film" : doc == 2 ? @"Color Negative Film" : @"B&W Negative Film"];
    } else {
        [self pro:@"documentType" select:@"Reflective"];
        [self pro:@"aeType" select:[r[@"aeType"] intValue] == 1 ? @"Document" : @"Photo"];
    }
    NSArray *types = @[ @"48-bit Color", @"24-bit Color", @"Color Smoothing", @"16-bit Grayscale", @"8-bit Grayscale",
                        @"Halftone", @"Black & White" ];
    [self pro:@"imageType" select:types[(NSUInteger)t]];
    [self.pro relayout];
    [self.pro updateItemStatus];
    [self setResolution:MAX(50, ESValue(self.k[@"resolution"]).intValue)];
    [self setTarget:ESValue(self.k[@"target"])];
    [self pro:@"unsharp" on:[r[@"usm"] boolValue]];
    [self pro:@"grain" on:NO];
    BOOL descreen = !film && ESIsOn(self.k[@"descreen"]);
    [self pro:@"descreen" on:descreen];
    NSArray *rulings = @[ @"General", @"Newspaper (85 lpi)", @"Magazine (133 lpi)", @"Fine Prints (175 lpi)" ];
    int lvl = [r[@"descreenLevel"] intValue];
    [self pro:@"descreenLevel" select:rulings[(NSUInteger)(lvl >= 0 && lvl < 4 ? lvl : 0)]];
    [self pro:@"Color Restoration" on:ESIsOn(self.k[@"restoration"])];
    [self pro:@"backlight" on:ESIsOn(self.k[@"backlight"])];
    NSArray *levels = @[ @"Low", @"Medium", @"High" ];
    int bl = [r[@"backlightLevel"] intValue];
    [self pro:@"backlightLevel" select:levels[(NSUInteger)(bl >= 0 && bl < 3 ? bl : 1)]];
    BOOL di = ESIsOn(self.k[@"dustIce"]);
    [self pro:@"ice" on:film && di];
    [self pro:@"dust" on:!film && di];
    int dl = [r[@"dustLevel"] intValue];
    [self pro:@"dustLevel" select:levels[(NSUInteger)(dl >= 0 && dl < 3 ? dl : 1)]];
    NSString *opt = @"None";
    if (ESIsOn(self.k[@"imageOption"]) && t == 6)
        opt = [ESRadioValue(self.k, @[ @"ioTET", @"ioAAS" ]) isEqualToString:@"ioAAS"] ? @"Auto Area Segmentation"
                                                                                        : @"Text Enhancement Technology";
    [self pro:@"imageOption" select:opt];
    [self setThreshold:[self.state[@"threshold"] intValue] ?: 110];
    [self.pro updateItemStatus];
}

- (void)applyAdjustments
{
    [self applyBrightness:[self.state[@"brightness"] intValue] contrast:[self.state[@"contrast"] intValue]];
}

- (void)resolutionEntered:(NSTextField *)t
{
    int v = t.intValue;
    if (v < 50) { v = 50; NSBeep(); }
    if (v > 12800) { v = 12800; NSBeep(); }
    t.stringValue = [NSString stringWithFormat:@"%d", v];
    [self rec][@"otherResolution"] = @(v);
}

- (void)perform:(NSString *)action
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    if ([action isEqualToString:@"home:doctype"]) {
        /* a change between reflective and film erases the preview (STR# 10008 #9) */
        int newType = (int)((ESIconPopup *)k[@"docType"]).selected;
        BOOL newFilm = newType >= 1 && newType <= 3;
        if (newFilm != [self film] && self.pro.preview.pw > 0 && self.pro.preview.window.isVisible) {
            NSAlert *a = [NSAlert new];
            a.messageText = @"EPSON Scan";
            a.informativeText = ESS_UI_10008_9;
            [a addButtonWithTitle:@"OK"]; [a addButtonWithTitle:@"Cancel"];
            if ([a runModal] != NSAlertFirstButtonReturn) {
                ((ESIconPopup *)k[@"docType"]).selected = [self docType];
                [k[@"docType"] setNeedsDisplay:YES];
                return;
            }
            [self.pro.preview.window orderOut:nil];
        }
        [self readControls];
        self.state[@"current"] = @(newType);
        [self writeControls];
        [self updateItems];
        [self syncToPro];
    } else if ([action isEqualToString:@"home:imagetype"] || [action isEqualToString:@"home:dest"] ||
               [action isEqualToString:@"home:imgoptradio"]) {
        /* Aqua radios with an action leave the group to the window */
        NSArray *group = [action isEqualToString:@"home:imagetype"] ? kHomeImageKeys
                       : [action isEqualToString:@"home:dest"] ? kHomeDestKeys : @[ @"ioTET", @"ioAAS" ];
        [self radioClicked:group];
        if ([action isEqualToString:@"home:dest"]) [self showResolution];
        [self readControls];
        [self updateItems];
        [self syncToPro];
    } else if ([action isEqualToString:@"home:adjust"] || [action isEqualToString:@"home:imgopt"]) {
        [self readControls];
        [self updateItems];
        [self syncToPro];
        if (self.pro.preview.pw > 0) [self.pro perform:@"autoexposure"];
    } else if ([action isEqualToString:@"home:res"]) {
        [self resolutionEntered:(NSTextField *)k[@"resolution"]];
    } else if ([action isEqualToString:@"home:target"]) {
        [self setTarget:ESValue(k[@"target"])];
        ESSetMenu(k[@"target"], ESMenuOf(self.pro.builder.controls[@"target"]));    /* Customize... may add sizes */
        ESSelectItem(k[@"target"], ESValue(self.pro.builder.controls[@"target"]));
        [self readControls];
    } else if ([action isEqualToString:@"home:rotate"]) {
        [self.pro perform:@"target-rotate"];
    } else if ([action isEqualToString:@"home:brightness"]) {
        if (!self.adjust) {
            self.adjust = [ESHomeAdjustDialog new];
            __weak ESHomeWindow *weakSelf = self;
            self.adjust.onChange = ^(ESHomeAdjustDialog *d) {
                weakSelf.state[@"brightness"] = @(d.brightness);
                weakSelf.state[@"contrast"] = @(d.contrast);
                weakSelf.state[@"threshold"] = @(d.threshold);
                [weakSelf setThreshold:d.threshold];
                [weakSelf.pro updateItemStatus];
                [weakSelf applyAdjustments];
            };
        }
        self.adjust.brightness = [self.state[@"brightness"] intValue];
        self.adjust.contrast = [self.state[@"contrast"] intValue];
        self.adjust.threshold = [self.state[@"threshold"] intValue] ?: 110;
        self.adjust.bw = [self imageTypeID] == 6;
        [self.adjust show];
    } else if ([action isEqualToString:@"preview"]) {
        [self readControls];
        [self syncToPro];
        if (!self.pro.preview) self.pro.preview = [ESPreviewWindow new];
        __weak ESHomeWindow *weakSelf = self;
        self.pro.preview.onPreviewDone = ^(BOOL ok) { if (ok) [weakSelf applyAdjustments]; };
        [self.pro perform:@"preview"];
    } else [super perform:action];
}

/* the radio just clicked stays on, the others in its group go off; native radios do this
 * themselves (same action, same superview) */
- (void)radioClicked:(NSArray<NSString *> *)group
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    NSEvent *e = NSApp.currentEvent;
    NSView *hit = e ? [self.window.contentView hitTest:[self.window.contentView convertPoint:e.locationInWindow fromView:nil]] : nil;
    for (NSString *x in group)
        if (k[x] == hit || [hit isDescendantOf:k[x]]) { ESRadioSelect(k, group, x); return; }
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark Office Mode

@interface ESOfficeWindow : ESModeWindow
@end

@implementation ESOfficeWindow

static NSArray *kOfficeImageKeys, *kOfficeOptionKeys;

- (instancetype)initWithPro:(ESProfessionalWindow *)pro
{
    kOfficeImageKeys = @[ @"itColor", @"itGray", @"itBW" ];
    kOfficeOptionKeys = @[ @"ioTET", @"ioAAS", @"ioDropout", @"ioEnhance" ];
    self.stateKey = @"OfficeModeSettings";
    if ((self = [super initWithLayout:@"office" mode:@"Office Mode" pro:pro]))
        [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(previewSelectionChanged:)
                                                   name:ESSelectionChanged object:nil];
    return self;
}

- (void)dealloc { [NSNotificationCenter.defaultCenter removeObserver:self]; }

/* CDocumentDialog::SetSizeMenu: a marquee drawn or changed in the preview makes the Size
 * "User Defined" (STR# 10002 #14); the scan then takes the marquee */
- (void)previewSelectionChanged:(NSNotification *)n
{
    ESPreviewWindow *pv = self.pro.preview;
    if (n.object != pv || self.pro.hostWindow != self.window || !pv.frames.count || pv.film) return;
    double x, y, w, h;
    if (![pv selectedAreaForFilm:NO x:&x y:&y w:&w h:&h]) return;
    NSSize mm = [self documentSizeMM];
    BOOL same = fabs(w - mm.width) < 2 && fabs(h - mm.height) < 2 && x < 2 && y < 2;
    NSView *size = self.k[@"size"];
    NSMutableArray *menu = [[[self sizes] valueForKey:@"name"] mutableCopy];
    if (!same) {
        [menu addObject:@"User Defined"];
        ESSetMenu(size, menu);
        ESSelectItem(size, @"User Defined");
    } else if ([ESValue(size) isEqualToString:@"User Defined"]) ESSetMenu(size, menu);
}

/* CDMPrefs (DMPR 10000) holds Office Mode's settings; Unsharp Mask stays off (this app's default) */
- (NSDictionary *)defaultState
{
    return @{ @"imageType": @"itColor", @"size": @"Letter", @"orientation": @"orPortrait", @"resolution": @300,
              @"unsharp": @0, @"descreen": @0, @"imageOption": @0, @"option": @"ioTET",
              @"dropoutColor": @"Red", @"enhanceColor": @"Red", @"brightness": @0, @"contrast": @0, @"threshold": @110 };
}

- (NSArray *)sizes
{
    for (NSDictionary *it in ESLoadLayoutNamed(@"office")[@"items"]) if ([it[@"key"] isEqualToString:@"size"]) return it[@"sizes"];
    return @[];
}

- (int)imageTypeID
{
    NSString *r = ESRadioValue(self.k, kOfficeImageKeys);
    return [r isEqualToString:@"itGray"] ? 4 : [r isEqualToString:@"itBW"] ? 6 : 1;
}

- (void)wireControls
{
    NSTextField *res = (NSTextField *)self.k[@"resolution"];
    if ([res isKindOfClass:[NSTextField class]]) { res.target = self; res.action = @selector(resolutionEntered:); res.cell.sendsActionOnEndEditing = YES; }
    for (NSString *x in @[ @"brightness", @"contrast", @"threshold" ]) [self wireEdit:x];
}

- (void)writeControls
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    NSDictionary *s = self.state;
    ESRadioSelect(k, kOfficeImageKeys, s[@"imageType"]);
    ESSelectItem(k[@"size"], s[@"size"]);
    ESRadioSelect(k, @[ @"orPortrait", @"orLandscape" ], s[@"orientation"]);
    ESSetField(k[@"resolution"], [NSString stringWithFormat:@"%d", [s[@"resolution"] intValue] ?: 300]);
    ESSetOn(k[@"unsharp"], [s[@"unsharp"] boolValue]);
    ESSetOn(k[@"descreen"], [s[@"descreen"] boolValue]);
    ESSetOn(k[@"imageOption"], [s[@"imageOption"] boolValue]);
    ESRadioSelect(k, kOfficeOptionKeys, s[@"option"]);
    ESSelectItem(k[@"dropoutColor"], s[@"dropoutColor"]);
    ESSelectItem(k[@"enhanceColor"], s[@"enhanceColor"]);
    ESSetSlider(k, @"brightness", [s[@"brightness"] intValue]);
    ESSetSlider(k, @"contrast", [s[@"contrast"] intValue]);
    ESSetSlider(k, @"threshold", [s[@"threshold"] intValue] ?: 110);
}

- (void)readControls
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    if (!k.count) return;
    NSMutableDictionary *s = self.state;
    s[@"imageType"] = ESRadioValue(k, kOfficeImageKeys);
    if (![ESValue(k[@"size"]) isEqualToString:@"User Defined"]) s[@"size"] = ESValue(k[@"size"]);
    s[@"orientation"] = ESRadioValue(k, @[ @"orPortrait", @"orLandscape" ]);
    s[@"resolution"] = @(MAX(50, ESValue(k[@"resolution"]).intValue));
    s[@"unsharp"] = @(ESIsOn(k[@"unsharp"]));
    s[@"descreen"] = @(ESIsOn(k[@"descreen"]));
    s[@"imageOption"] = @(ESIsOn(k[@"imageOption"]));
    s[@"option"] = ESRadioValue(k, kOfficeOptionKeys);
    s[@"dropoutColor"] = ESValue(k[@"dropoutColor"]);
    s[@"enhanceColor"] = ESValue(k[@"enhanceColor"]);
}

/* CDocumentDialog::UpdateAdjustItems / SetImageOptionDisplayData */
- (void)updateItems
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    int t = [self imageTypeID];
    BOOL bw = t == 6, gray = t == 4;
    BOOL io = bw || gray;
    if (!io) ESSetOn(k[@"imageOption"], NO);
    ESSetEnabled(k[@"imageOption"], io);
    BOOL on = io && ESIsOn(k[@"imageOption"]);
    /* Text Enhancement and Auto Area Segmentation are Black & White only; a choice that isn't
     * available falls back to the first one that is */
    NSString *opt = ESRadioValue(k, kOfficeOptionKeys);
    if (!bw && ([opt isEqualToString:@"ioTET"] || [opt isEqualToString:@"ioAAS"])) ESRadioSelect(k, kOfficeOptionKeys, @"ioDropout");
    ESSetEnabled(k[@"ioTET"], on && bw);
    ESSetEnabled(k[@"ioAAS"], on && bw);
    ESSetEnabled(k[@"ioDropout"], on);
    ESSetEnabled(k[@"ioEnhance"], on);
    opt = ESRadioValue(k, kOfficeOptionKeys);
    ESSetEnabled(k[@"dropoutColor"], on && [opt isEqualToString:@"ioDropout"]);
    ESSetEnabled(k[@"enhanceColor"], on && [opt isEqualToString:@"ioEnhance"]);
    /* Unsharp Mask and Descreening aren't used for Black & White */
    for (NSString *x in @[ @"unsharp", @"descreen" ]) { if (bw) ESSetOn(k[x], NO); ESSetEnabled(k[x], !bw); }
    /* Black & White shows the Threshold in Brightness's place; Contrast goes */
    for (NSString *x in @[ @"bLabel", @"brightness", @"brightnessText", @"cLabel", @"contrast", @"contrastText" ]) k[x].hidden = bw;
    for (NSString *x in @[ @"tLabel", @"threshold", @"thresholdText" ]) k[x].hidden = !bw;
}

- (NSSize)documentSizeMM
{
    NSString *name = ESValue(self.k[@"size"]);
    if ([name isEqualToString:@"User Defined"]) {
        double x, y, w, h;
        if ([self.pro.preview selectedAreaForFilm:NO x:&x y:&y w:&w h:&h]) return NSMakeSize(w, h);
        name = self.state[@"size"];
    }
    for (NSDictionary *z in [self sizes])
        if ([z[@"name"] isEqualToString:name]) {
            double w = [z[@"wmm"] doubleValue], h = [z[@"hmm"] doubleValue];
            /* the V550's glass is 216 x 297 mm: larger sizes are cut to it */
            w = MIN(w, 216); h = MIN(h, 297);
            BOOL land = [ESRadioValue(self.k, @[ @"orPortrait", @"orLandscape" ]) isEqualToString:@"orLandscape"];
            return land ? NSMakeSize(MIN(h, 216), MIN(w, 297)) : NSMakeSize(w, h);
        }
    return NSMakeSize(216, 297);
}

- (void)syncToPro
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    int t = [self imageTypeID];
    [self pro:@"documentType" select:@"Reflective"];
    [self pro:@"docSource" select:@"Scanner Glass"];
    [self pro:@"aeType" select:@"Document"];
    self.pro.forcedThumbnail = @NO;          /* Office Mode previews in Normal */
    [self pro:@"imageType" select:t == 6 ? @"Black & White" : t == 4 ? @"8-bit Grayscale" : @"24-bit Color"];
    [self.pro relayout];
    [self.pro updateItemStatus];
    [self setResolution:MAX(50, ESValue(k[@"resolution"]).intValue)];
    [self setTarget:@"Original"];
    [self pro:@"unsharp" on:ESIsOn(k[@"unsharp"])];
    [self pro:@"unsharpLevel" select:@"Medium"];
    [self pro:@"descreen" on:ESIsOn(k[@"descreen"])];
    [self pro:@"descreenLevel" select:@"General"];
    for (NSString *x in @[ @"grain", @"Color Restoration", @"backlight", @"dust", @"ice" ]) [self pro:x on:NO];
    NSString *opt = @"None";
    if (ESIsOn(k[@"imageOption"])) {
        NSString *r = ESRadioValue(k, kOfficeOptionKeys);
        if ([r isEqualToString:@"ioTET"]) opt = @"Text Enhancement Technology";
        else if ([r isEqualToString:@"ioAAS"]) opt = @"Auto Area Segmentation";
        else if ([r isEqualToString:@"ioDropout"]) opt = [@"Dropout: " stringByAppendingString:ESValue(k[@"dropoutColor"])];
        else opt = [@"Color Enhance: " stringByAppendingString:ESValue(k[@"enhanceColor"])];
    }
    [self pro:@"imageOption" select:opt];
    [self setThreshold:[self.state[@"threshold"] intValue] ?: 110];
    NSSize mm = [self documentSizeMM];
    self.pro.fixedAreaMM = NSMakeRect(0, 0, mm.width, mm.height);
    [self.pro updateItemStatus];
}

- (void)placeMarquee
{
    if ([ESValue(self.k[@"size"]) isEqualToString:@"User Defined"]) { [self applyAdjustments]; return; }
    NSSize mm = [self documentSizeMM];
    ESPreviewWindow *pv = self.pro.preview;
    if (pv.pw > 0 && !pv.scanning && !pv.film) {
        [pv placeMarqueeMM:mm];
        [self applyAdjustments];
    }
}

- (void)applyAdjustments
{
    [self applyBrightness:[self.state[@"brightness"] intValue] contrast:[self.state[@"contrast"] intValue]];
}

/* CDocumentDialog::DoAdjust*Slider */
- (void)slider:(NSString *)key value:(int)v
{
    BOOL th = [key isEqualToString:@"threshold"];
    v = th ? MAX(0, MIN(255, v)) : MAX(-100, MIN(100, v));
    self.state[key] = @(v);
    ESSetSlider(self.k, key, v);
    if (th) { [self setThreshold:v]; [self.pro updateItemStatus]; }
    else [self applyAdjustments];
}

- (void)resolutionEntered:(NSTextField *)t
{
    int v = t.intValue;
    if (v < 50) { v = 50; NSBeep(); }
    if (v > 12800) { v = 12800; NSBeep(); }
    t.stringValue = [NSString stringWithFormat:@"%d", v];
    self.state[@"resolution"] = @(v);
}

- (void)radioClicked:(NSArray<NSString *> *)group
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    NSEvent *e = NSApp.currentEvent;
    NSView *hit = e ? [self.window.contentView hitTest:[self.window.contentView convertPoint:e.locationInWindow fromView:nil]] : nil;
    for (NSString *x in group)
        if (k[x] == hit || [hit isDescendantOf:k[x]]) { ESRadioSelect(k, group, x); return; }
}

- (void)perform:(NSString *)action
{
    NSDictionary<NSString *, NSView *> *k = self.k;
    if ([action isEqualToString:@"office:imagetype"] || [action isEqualToString:@"office:imgoptradio"] ||
        [action isEqualToString:@"office:orientation"]) {
        [self radioClicked:[action isEqualToString:@"office:imagetype"] ? kOfficeImageKeys
                           : [action isEqualToString:@"office:orientation"] ? @[ @"orPortrait", @"orLandscape" ]
                           : kOfficeOptionKeys];
        [self readControls];
        [self updateItems];
        [self syncToPro];
        if ([action isEqualToString:@"office:orientation"]) [self placeMarquee];
    } else if ([action isEqualToString:@"office:size"]) {
        [self readControls];
        [self syncToPro];
        [self placeMarquee];
    } else if ([action isEqualToString:@"office:adjust"] || [action isEqualToString:@"office:imgopt"]) {
        [self readControls];
        [self updateItems];
        [self syncToPro];
    } else if ([action isEqualToString:@"office:res"]) {
        [self resolutionEntered:(NSTextField *)k[@"resolution"]];
    } else if ([action isEqualToString:@"preview"]) {
        [self readControls];
        [self syncToPro];
        if (!self.pro.preview) self.pro.preview = [ESPreviewWindow new];
        __weak ESOfficeWindow *weakSelf = self;
        self.pro.preview.onPreviewDone = ^(BOOL ok) { if (ok) [weakSelf placeMarquee]; };
        [self.pro perform:@"preview"];
    } else [super perform:action];
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark Full Auto Mode

/* CFADisclosDialog (DITL 10010): what Full Auto scans and how */
@interface ESFullAutoCustomDialog : ESLayoutDialog
@property (nonatomic, strong) NSMutableDictionary *state;
@end

@implementation ESFullAutoCustomDialog
- (BOOL)runWith:(NSMutableDictionary *)state
{
    self.state = state;
    [self load:@"fullautocustom"];
    NSDictionary<NSString *, NSView *> *k = self.builder.controls;
    ESSetOn(k[@"specDoc"], [state[@"specifyDocument"] boolValue]);
    ESRadioSelect(k, @[ @"docPhoto", @"docFilm" ], [state[@"documentType"] intValue] == 1 ? @"docFilm" : @"docPhoto");
    ESSetOn(k[@"specRes"], [state[@"specifyResolution"] boolValue]);
    ESSetField(k[@"resReflective"], [NSString stringWithFormat:@"%d", [state[@"reflectiveResolution"] intValue] ?: 300]);
    ESSetField(k[@"resFilm"], [NSString stringWithFormat:@"%d", [state[@"filmResolution"] intValue] ?: 300]);
    ESSetOn(k[@"dust"], [state[@"dust"] boolValue]);
    ESSetOn(k[@"restoration"], [state[@"restoration"] boolValue]);
    ESSetOn(k[@"autoRotate"], [state[@"autoRotate"] boolValue]);
    [self update];
    return [self runModal];
}
- (void)update      /* DoDocTypeGroupBoxClick / DoResolutionGroupBoxClick */
{
    NSDictionary<NSString *, NSView *> *k = self.builder.controls;
    BOOL doc = ESIsOn(k[@"specDoc"]), res = ESIsOn(k[@"specRes"]);
    for (NSString *x in @[ @"docPhoto", @"docFilm" ]) ESSetEnabled(k[x], doc);
    for (NSString *x in @[ @"resReflLabel", @"resReflective", @"resReflArrows", @"resReflDpi", @"resFilmLabel", @"resFilm",
                           @"resFilmArrows", @"resFilmDpi" ]) ESSetEnabled(k[x], res);
}
- (void)perform:(NSString *)action
{
    NSDictionary<NSString *, NSView *> *k = self.builder.controls;
    if ([action isEqualToString:@"fac:state"]) [self update];
    else if ([action isEqualToString:@"fac:doc"]) {
        NSEvent *e = NSApp.currentEvent;
        NSView *hit = e ? [self.root hitTest:[self.root convertPoint:e.locationInWindow fromView:nil]] : nil;
        for (NSString *x in @[ @"docPhoto", @"docFilm" ])
            if (k[x] == hit || [hit isDescendantOf:k[x]]) ESRadioSelect(k, @[ @"docPhoto", @"docFilm" ], x);
    } else if ([action isEqualToString:@"filesave"]) {
        [[ESFileSaveDialog new] run];
    } else if ([action isEqualToString:@"fac:cancel"]) {
        [self finish:NO];
    } else if ([action isEqualToString:@"fac:ok"]) {
        int rr = MAX(50, MIN(12800, ESValue(k[@"resReflective"]).intValue)), rf = MAX(50, MIN(12800, ESValue(k[@"resFilm"]).intValue));
        self.state[@"specifyDocument"] = @(ESIsOn(k[@"specDoc"]));
        self.state[@"documentType"] = @([ESRadioValue(k, @[ @"docPhoto", @"docFilm" ]) isEqualToString:@"docFilm"] ? 1 : 0);
        self.state[@"specifyResolution"] = @(ESIsOn(k[@"specRes"]));
        self.state[@"reflectiveResolution"] = @(rr);
        self.state[@"filmResolution"] = @(rf);
        self.state[@"dust"] = @(ESIsOn(k[@"dust"]));
        self.state[@"restoration"] = @(ESIsOn(k[@"restoration"]));
        self.state[@"autoRotate"] = @(ESIsOn(k[@"autoRotate"]));
        [self finish:YES];
    }
}
@end

@interface ESFullAutoWindow : ESModeWindow
@property (nonatomic) BOOL working, cancelled, retried, sawBusy;
@property (nonatomic, strong) NSTimer *watch;
@property (nonatomic, strong) NSDate *scanStart;
@end

@implementation ESFullAutoWindow

- (instancetype)initWithPro:(ESProfessionalWindow *)pro
{
    self.stateKey = @"FullAutoSettings";
    return [super initWithLayout:@"fullauto" mode:@"Full Auto Mode" pro:pro];
}

/* CFAPrefs (FAPR 10000); Dust Removal starts on so film gets DIGITAL ICE (this app's default) */
- (NSDictionary *)defaultState
{
    NSMutableDictionary *d = [ESModeDefaults()[@"fullAuto"] mutableCopy] ?: [NSMutableDictionary dictionary];
    d[@"dust"] = @1;
    return d;
}

- (void)writeControls { [self showState]; }

/* CFullAutoDialog::ChangeDialogItems: the waiting window (DITL 10003) or the working one (10001) */
- (void)showState
{
    ESShowViews(self.builder.groups[@"idle"], !self.working);
    ESShowViews(self.builder.groups[@"work"], self.working);
    ESSetEnabled(self.k[@"mode"], !self.working);
    NSProgressIndicator *pi = (NSProgressIndicator *)self.k[@"progress"];
    if ([pi isKindOfClass:[NSProgressIndicator class]]) {
        pi.indeterminate = YES;
        if (self.working) [pi startAnimation:nil]; else [pi stopAnimation:nil];
    }
}

- (void)status:(NSString *)text { ESSetWrap(self.k[@"status"], text); }

- (void)setDocPicture:(NSString *)art name:(NSString *)name
{
    NSImageView *iv = (NSImageView *)self.k[@"docPicture"];
    if ([iv isKindOfClass:[NSImageView class]]) iv.image = art ? ESArt(art) : nil;
    ESSetWrap(self.k[@"docTypeText"], name ? [@"Document Type: " stringByAppendingString:name] : @"");
}

- (BOOL)filmChosen { return [self.state[@"specifyDocument"] boolValue] && [self.state[@"documentType"] intValue] == 1; }

- (void)syncToPro
{
    BOOL film = [self filmChosen];
    [self pro:@"documentType" select:film ? @"Film (with Film Area Guide)" : @"Reflective"];
    [self pro:@"aeType" select:@"Photo"];
    [self pro:@"imageType" select:@"24-bit Color"];
    [self.pro relayout];
    [self.pro updateItemStatus];
    [self setTarget:@"Original"];
    for (NSString *x in @[ @"unsharp", @"grain", @"descreen", @"backlight" ]) [self pro:x on:NO];
    [self pro:@"imageOption" select:@"None"];
    [self pro:@"Color Restoration" on:[self.state[@"restoration"] boolValue]];
    BOOL dust = [self.state[@"dust"] boolValue];
    [self pro:@"ice" on:film && dust];
    [self pro:@"dust" on:!film && dust];
    [self pro:@"dustLevel" select:@"Medium"];
    self.pro.fixedAreaMM = NSZeroRect;
    [self.pro updateItemStatus];
}

- (void)perform:(NSString *)action
{
    if ([action isEqualToString:@"fa:scan"]) [self startFullAuto];
    else if ([action isEqualToString:@"fa:cancel"]) {
        self.cancelled = YES;
        self.pro.batchQueue = nil;
        es_cancel();
        [self finish];
    } else if ([action isEqualToString:@"fa:customize"]) {
        if ([[ESFullAutoCustomDialog new] runWith:self.state]) [self saveState];
    } else [super perform:action];
}

/* CFullAutoDialog::DoScanButtonClick -> CFullAutoAnalyz: preview, find the documents (or film
 * frames) and their type, then scan each */
- (void)startFullAuto
{
    if (self.working || self.pro.busy) return;
    self.working = YES; self.cancelled = NO; self.retried = NO;
    [self showState];
    [self setDocPicture:nil name:nil];
    [self status:ESS_UI_10003_11];
    [self syncToPro];
    [self previewFilm:[self filmChosen] negative:YES];
}

- (void)previewFilm:(BOOL)film negative:(BOOL)neg
{
    if (!self.pro.preview) self.pro.preview = [ESPreviewWindow new];
    ESPreviewWindow *pv = self.pro.preview;
    [pv.window orderOut:nil];
    pv.restoration = [self.state[@"restoration"] boolValue];
    pv.documentAE = NO;
    pv.backlight = 0;
    pv.thumbnailMode = film;
    pv.filmTFT = -1;                       /* DTR finds the film type */
    gDTRFoundFilmType = -1;
    __weak ESFullAutoWindow *weakSelf = self;
    pv.onPreviewDone = ^(BOOL ok) { [weakSelf previewDone:ok film:film negative:neg]; };
    [pv startPreviewFilm:film negative:film && neg targetDPI:300 bytesPerPixel:3];
}

- (void)fail:(NSString *)text
{
    [self finish];
    NSAlert *a = [NSAlert new];
    a.messageText = @"EPSON Scan";
    a.informativeText = text;
    a.alertStyle = NSAlertStyleWarning;
    [a beginSheetModalForWindow:self.window completionHandler:nil];
}

- (void)previewDone:(BOOL)ok film:(BOOL)film negative:(BOOL)neg
{
    ESPreviewWindow *pv = self.pro.preview;
    pv.onPreviewDone = nil;
    if (self.cancelled) return;
    if (!ok) { [self fail:[NSString stringWithUTF8String:es_last_error()] ?: @"The scanner couldn't complete the preview."]; return; }
    NSArray<NSValue *> *frames = pv.frames;
    NSString *art = @"ui_257.png", *name = @"Color Photo";
    if (film) {
        /* TWEP_TFT: 0 colour negative, 1 B&W negative, 2 positive. A positive previewed as a
         * negative is previewed again so its auto exposure is right */
        int tft = gDTRFoundFilmType;
        if (tft == 2 && neg && !self.retried) { self.retried = YES; [self previewFilm:YES negative:NO]; return; }
        if ((tft == 0 || tft == 1) && !neg && !self.retried) { self.retried = YES; [self previewFilm:YES negative:YES]; return; }
        [self pro:@"filmType" select:tft == 2 ? @"Positive Film" : tft == 1 ? @"B&W Negative Film" : @"Color Negative Film"];
        art = tft == 2 ? @"ui_259.png" : tft == 1 ? @"ui_261.png" : @"ui_260.png";
        name = tft == 2 ? @"Color Positive Film" : tft == 1 ? @"B&W Negative Film" : @"Color Negative Film";
        if (tft == 1) [self pro:@"imageType" select:@"8-bit Grayscale"];
    } else {
        /* no document type set: a film holder on the glass means film, previewed again with the
         * transparency unit's light (CDTR::CheckDocSource -> GetDocSrc 1) */
        if (![self.state[@"specifyDocument"] boolValue] &&
            ESDetectFilmHolderDTR(pv.raw16.bytes, pv.pw, pv.ph, pv.pdpi) == 1) {
            [self pro:@"documentType" select:@"Film (with Film Area Guide)"];
            BOOL dust = [self.state[@"dust"] boolValue];
            [self pro:@"ice" on:dust];
            [self pro:@"dust" on:NO];
            [self.pro relayout];
            [self.pro updateItemStatus];
            [self previewFilm:YES negative:YES];
            return;
        }
        /* the documents on the glass: Epson's DTR, then the outline finder, then Auto Locate */
        NSArray<NSNumber *> *kinds = nil;
        frames = ESDetectDocumentsDTR(pv.raw16.bytes, pv.pw, pv.ph, pv.pdpi, &kinds);
        /* CDTR::GetDocType for a colour original: photograph -> Color Photo (Photo auto exposure),
         * document -> Color Document, text -> Text/Line Art (Document auto exposure) */
        int kind = kinds.count ? kinds[0].intValue : 1;
        BOOL photo = NO;
        for (NSNumber *x in kinds) if (x.intValue == 1) photo = YES;
        if (!kinds.count) photo = YES;
        if (kind != 1 && !photo) {
            art = kind == 2 ? @"ui_264.png" : @"ui_262.png";
            name = kind == 2 ? @"Text/Line Art" : @"Color Document";
        }
        [self pro:@"aeType" select:photo ? @"Photo" : @"Document"];
        pv.documentAE = !photo;
        if (!frames.count) frames = ESLocateReflective(pv.pixels.bytes, pv.pw, pv.ph, pv.pdpi);
        if (!frames.count) frames = ESAutoLocateDTR(pv.raw16.bytes, pv.pw, pv.ph, pv.pdpi);
        if (frames.count) {
            pv.thumbnailMode = YES;
            [pv adoptFrames:frames];
        }
    }
    if (!frames.count) {
        [self fail:ESS_UI_10008_26];
        return;
    }
    [self setDocPicture:art name:name];
    /* resolution: the Customize setting, or CDTR::CalcFilmRes for film (the frame's long side at
     * 300 dpi on a 6-inch print) and 300 dpi for documents */
    int dpi;
    if ([self.state[@"specifyResolution"] boolValue])
        dpi = [self.state[film ? @"filmResolution" : @"reflectiveResolution"] intValue] ?: 300;
    else if (film) {
        NSRect f = frames[0].rectValue;
        double longIn = MAX(f.size.width, f.size.height) / (double)pv.pdpi;
        double print = [ESModeDefaults()[@"filmPrintLong"] doubleValue] ?: 6.0;
        dpi = longIn > 0 ? (int)lround(300.0 * print / longIn) : 1200;
    } else dpi = [self.state[@"reflectiveResolution"] intValue] ?: 300;
    dpi = MAX(50, MIN(film ? 6400 : 1200, dpi));
    [self setResolution:dpi];
    [pv checkAllFrames];
    if ([self.state[@"autoRotate"] boolValue]) [pv autoOrientFrames];
    ESLog(@"Full Auto: %@, %lu item(s), %d dpi", name, (unsigned long)frames.count, dpi);
    [self status:@"Scanning."];
    self.sawBusy = NO;
    self.scanStart = [NSDate date];
    [self.pro perform:@"scan"];
    [self.watch invalidate];
    self.watch = [NSTimer scheduledTimerWithTimeInterval:0.25 target:self selector:@selector(watchScan:) userInfo:nil repeats:YES];
}

/* the scan of every item has ended (or didn't start: a message, or Cancel in File Save Settings) */
- (void)watchScan:(NSTimer *)t
{
    ESProfessionalWindow *p = self.pro;
    if (p.busy || p.preview.scanning) { self.sawBusy = YES; return; }
    if (p.batchQueue.count) return;
    if (!self.sawBusy && -[self.scanStart timeIntervalSinceNow] < 1.0) return;
    [self finish];
}

- (void)finish
{
    [self.watch invalidate];
    self.watch = nil;
    self.working = NO;
    [self showState];
}

@end

/* ------------------------------------------------------------------------ */
#pragma mark - App

@interface ESAppDelegate : NSObject <NSApplicationDelegate>
@property (nonatomic, strong) ESProfessionalWindow *pro;
@property (nonatomic, strong) ESHomeWindow *home;
@property (nonatomic, strong) ESOfficeWindow *office;
@property (nonatomic, strong) ESFullAutoWindow *fullAuto;
@property (nonatomic, copy) NSString *mode;              /* the Mode list's current choice */
@property (nonatomic, strong) NSDictionary *proSettings;   /* Professional Mode's, while another mode drives it */
@property (nonatomic, strong) NSMenuItem *aquaItem, *nativeItem;
@end

@implementation ESAppDelegate

- (void)buildMenu
{
    NSMenu *bar = [NSMenu new];
    NSMenuItem *appItem = [bar addItemWithTitle:@"" action:nil keyEquivalent:@""];
    NSMenu *app = [[NSMenu alloc] initWithTitle:@"EPSON Scan"];
    [app addItemWithTitle:@"About EPSON Scan" action:@selector(orderFrontStandardAboutPanel:) keyEquivalent:@""];
    [app addItem:[NSMenuItem separatorItem]];
    [app addItemWithTitle:@"Hide EPSON Scan" action:@selector(hide:) keyEquivalent:@"h"];
    [app addItemWithTitle:@"Quit EPSON Scan" action:@selector(terminate:) keyEquivalent:@"q"];
    appItem.submenu = app;

    NSMenuItem *viewItem = [bar addItemWithTitle:@"" action:nil keyEquivalent:@""];
    NSMenu *view = [[NSMenu alloc] initWithTitle:@"View"];
    self.aquaItem = [view addItemWithTitle:@"Classic Aqua Controls" action:@selector(useAqua:) keyEquivalent:@"1"];
    self.nativeItem = [view addItemWithTitle:@"Native macOS Controls" action:@selector(useNative:) keyEquivalent:@"2"];
    self.aquaItem.target = self;
    self.nativeItem.target = self;
    viewItem.submenu = view;
    NSApp.mainMenu = bar;
    [self updateMenu];
}

- (void)updateMenu
{
    BOOL native = [[NSUserDefaults standardUserDefaults] boolForKey:kThemeDefault];
    self.aquaItem.state = native ? NSControlStateValueOff : NSControlStateValueOn;
    self.nativeItem.state = native ? NSControlStateValueOn : NSControlStateValueOff;
}

- (void)rebuildAll
{
    [self.pro rebuild];
    [self.pro.preview rebuild];
    [self.pro.imageAdjust rebuild];
    [self.pro.histogramAdjust rebuild];
    [self.pro.toneCorrection rebuild];
    [self.pro.colorPalette rebuild];
    [self.home rebuild];
    [self.home.adjust rebuild];
    [self.office rebuild];
    [self.fullAuto rebuild];
    /* the rebuilt Professional Mode controls take the driving mode's settings again */
    if (![self.mode isEqualToString:@"Professional Mode"]) {
        ESSelectItem(self.pro.builder.controls[@"mode"], self.mode);
        [[self modeWindow:self.mode create:NO] takeOver];
    }
}

- (void)useAqua:(id)sender
{
    [[NSUserDefaults standardUserDefaults] setBool:NO forKey:kThemeDefault];
    [self updateMenu];
    [self rebuildAll];
}

- (void)useNative:(id)sender
{
    [[NSUserDefaults standardUserDefaults] setBool:YES forKey:kThemeDefault];
    [self updateMenu];
    [self rebuildAll];
}

- (ESModeWindow *)modeWindow:(NSString *)mode create:(BOOL)create
{
    if ([mode isEqualToString:@"Home Mode"]) {
        if (!self.home && create) self.home = [[ESHomeWindow alloc] initWithPro:self.pro];
        return self.home;
    }
    if ([mode isEqualToString:@"Office Mode"]) {
        if (!self.office && create) self.office = [[ESOfficeWindow alloc] initWithPro:self.pro];
        return self.office;
    }
    if ([mode isEqualToString:@"Full Auto Mode"]) {
        if (!self.fullAuto && create) self.fullAuto = [[ESFullAutoWindow alloc] initWithPro:self.pro];
        return self.fullAuto;
    }
    return nil;
}

- (NSWindow *)windowFor:(NSString *)mode
{
    return [mode isEqualToString:@"Professional Mode"] ? self.pro.window : [self modeWindow:mode create:NO].window;
}

/* CMainDialog::DoUIModeMenuClick: the preview goes (STR# 10008 #4 asks first), the old mode's
 * window closes and the new one opens where it was */
- (void)modeChangeRequested:(NSNotification *)n
{
    NSString *to = n.object;
    if (![to isKindOfClass:[NSString class]] || [to isEqualToString:self.mode]) return;
    NSWindow *old = [self windowFor:self.mode];
    if (self.pro.busy || self.fullAuto.working) { NSBeep(); [self selectModeIn:self.mode]; return; }
    if (self.pro.preview.pw > 0 && self.pro.preview.window.isVisible) {
        NSAlert *a = [NSAlert new];
        a.messageText = @"EPSON Scan";
        a.informativeText = ESS_UI_10008_4;
        [a addButtonWithTitle:@"OK"];
        [a addButtonWithTitle:@"Cancel"];
        if ([a runModal] != NSAlertFirstButtonReturn) { [self selectModeIn:self.mode]; return; }
    }
    [self switchToMode:to from:old];
}

/* a cancelled change puts the old choice back in the Mode list */
- (void)selectModeIn:(NSString *)mode
{
    ESSelectItem(self.pro.builder.controls[@"mode"], [self.mode isEqualToString:@"Professional Mode"] ? @"Professional Mode" : mode);
    ESModeWindow *w = [self modeWindow:self.mode create:NO];
    if (w) ESSelectItem(w.k[@"mode"], w.modeName);
}

- (void)switchToMode:(NSString *)to from:(NSWindow *)old
{
    /* the preview and its dialogs close; the next preview starts fresh */
    for (NSWindow *w in @[ self.pro.preview.window ?: [NSNull null], self.pro.imageAdjust.window ?: [NSNull null],
                           self.pro.histogramAdjust.window ?: [NSNull null], self.pro.toneCorrection.window ?: [NSNull null],
                           self.pro.colorPalette.window ?: [NSNull null], self.home.adjust.window ?: [NSNull null] ])
        if ([w isKindOfClass:[NSWindow class]]) [w orderOut:nil];
    self.pro.preview.onPreviewDone = nil;
    self.pro.preview = nil;
    self.pro.imageAdjust = nil; self.pro.histogramAdjust = nil; self.pro.toneCorrection = nil; self.pro.colorPalette = nil;

    if ([self.mode isEqualToString:@"Professional Mode"]) {
        self.proSettings = [self.pro snapshotSettings];
        [self.pro saveSettings];
    } else [[self modeWindow:self.mode create:NO] saveState];

    NSString *from = self.mode;
    self.mode = to;
    [NSUserDefaults.standardUserDefaults setObject:to forKey:@"UIMode"];
    NSWindow *nw;
    if ([to isEqualToString:@"Professional Mode"]) {
        self.pro.hostWindow = nil;
        self.pro.fixedAreaMM = NSZeroRect;
        self.pro.forcedThumbnail = nil;
        if (self.proSettings) [self.pro applySettings:self.proSettings];
        ESSelectItem(self.pro.builder.controls[@"mode"], @"Professional Mode");
        nw = self.pro.window;
    } else {
        ESModeWindow *m = [self modeWindow:to create:YES];
        [m takeOver];
        nw = m.window;
    }
    if (old && old != nw) {
        NSRect of = old.frame, f = nw.frame;
        f.origin = NSMakePoint(of.origin.x, NSMaxY(of) - f.size.height);
        [nw setFrame:f display:NO];
    }
    [nw makeKeyAndOrderFront:nil];
    if (old != nw) [old orderOut:nil];
    ESLog(@"Mode: %@ -> %@", from, to);
}

- (void)applicationDidFinishLaunching:(NSNotification *)n
{
    /* defaults write local.epsonscan.rebuild ScanDebug -bool YES: the scanner's command trace goes to
     * ~/Library/Logs/EPSON Scan Driver.log (for diagnosing stalls) */
    if ([NSUserDefaults.standardUserDefaults boolForKey:@"ScanDebug"]) {
        NSString *dlog = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Logs/EPSON Scan Driver.log"];
        if (freopen(dlog.fileSystemRepresentation, "a", stderr)) {
            setvbuf(stderr, NULL, _IOLBF, 0);
            es_set_verbose(1);
            ESLog(@"Scanner trace on: %@", dlog);
        }
    }
    [self buildMenu];
    self.pro = [ESProfessionalWindow new];
    [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(modeChangeRequested:)
                                               name:ESModeChangeRequest object:nil];
    /* EPSON Scan opens in the mode it was closed in (CUIPrefsBase UI mode) */
    NSString *mode = [NSUserDefaults.standardUserDefaults stringForKey:@"UIMode"];
    if (![@[ @"Full Auto Mode", @"Home Mode", @"Office Mode", @"Professional Mode" ] containsObject:mode]) mode = @"Professional Mode";
    self.mode = @"Professional Mode";
    if ([mode isEqualToString:@"Professional Mode"]) [self.pro.window makeKeyAndOrderFront:nil];
    else [self switchToMode:mode from:nil];
    [NSApp activateIgnoringOtherApps:YES];
}

- (BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication *)app { return YES; }
- (void)applicationWillTerminate:(NSNotification *)n
{
    [self.pro.colorPalette savePrefs];
    if ([self.mode isEqualToString:@"Professional Mode"]) [self.pro saveSettings];
    else {
        [[self modeWindow:self.mode create:NO] saveState];
        if (self.proSettings) [self.pro applySettings:self.proSettings];
        [self.pro saveSettings];
    }
    es_close();
}

@end

int main(int argc, const char *argv[])
{
    @autoreleasepool {
        NSApplication *app = [NSApplication sharedApplication];
        ESAppDelegate *d = [ESAppDelegate new];
        app.delegate = d;
        [app setActivationPolicy:NSApplicationActivationPolicyRegular];
        [app run];
    }
    return 0;
}
